    public void analyze(SwccgGame game, String playerId, Side side) {
        LOG.warn("[ObjectiveAnalyzer] analyze() CALLED - game={}, player={}, side={}", game != null, playerId, side);
        if (game == null || playerId == null) return;

        GameState gameState = game.getGameState();
        if (gameState == null) return;

        try {
            PhysicalCard objectiveCard = findOurObjective(gameState, playerId);
            if (objectiveCard == null) {
                LOG.warn("[ObjectiveAnalyzer] No objective found for {}", playerId);
                reset();
                return;
            }

            ObjectiveSideBlueprints sides = ObjectiveSideBlueprints.resolve(objectiveCard);
            if (sides == null) return;

            String title = sides.front().getTitle();
            String gameText = sides.front().getGameText();
            String backGameText = sides.back() != null ? sides.back().getGameText() : null;

            if (gameText == null || gameText.isEmpty()) {
                LOG.warn("[ObjectiveAnalyzer] Objective '{}' has no game text", title);
                return;
            }

            String bpId = objectiveCard.getBlueprintId(true);
            if (analyzed && bpId != null && bpId.equals(objectiveBlueprintId)) {
                updateFlipStatus(
                        gameState, playerId, objectiveCard);
                return;
            }
            if (analyzed
                    && !Objects.equals(bpId, objectiveBlueprintId)) {
                resetFlipAgeObservation();
            }

            this.objectiveTitle = title;
            this.objectiveBlueprintId = bpId;
            // V86/V88/V121 CONSOLIDATED (2026-07-07): compute objective-identity flags from the
            // title HERE (before parseGameText's no-flip early return) so they are set for EVERY
            // objective, flip-parsed or not. Exact substring semantics preserved verbatim from the
            // old inline checks in Deploy/CardSelection (title.toLowerCase().contains(...)).
            String titleLowerId = (title != null) ? title.toLowerCase(Locale.ROOT) : "";
            this.isInvasion = titleLowerId.contains("invasion");
            this.isMyLord = titleLowerId.contains("my lord")
                    || titleLowerId.contains("make it legal")
                    || titleLowerId.contains("plead my case")
                    || titleLowerId.contains("sanity and compassion");
            this.isEndor = titleLowerId.contains("endor operations");
            this.isTdigwatt = titleLowerId.contains("this deal is getting worse all the time");
            this.isFirstOrderReigns =
                    titleLowerId.contains("the first order reigns")
                    || titleLowerId.contains(
                        "the resistance is doomed");
            // A loaderEnabled profile owns the active JSON playbook. Disabled or
            // missing profiles retain the compiled My Lord/Endor fallbacks.
            // Reuse this lookup after parsing for typed slot hydration.
            JsonProfile prof = findProfile(bpId, title);
            boolean loaderOn = prof != null && Boolean.TRUE.equals(prof.loaderEnabled);
            this.activePlaybook = loaderOn ? buildPlaybookFromProfile(prof)
                                : this.isMyLord ? MY_LORD_PLAYBOOK
                                : this.isEndor ? ENDOR_PLAYBOOK
                                : null;
            // V186 CONSOLIDATED (2026-07-07): I Want That Map identity + typed steer data (title-derived).
            this.isWantThatMap = titleLowerId.contains("i want that map");
            iwtmSystemBpIds.clear();
            iwtmSystemTitleFragment = null;
            iwtmPreferredStartingEffect = null;
            if (this.isWantThatMap) {
                iwtmSystemBpIds.add("208_51");
                iwtmSystemBpIds.add("208_051");
                iwtmSystemTitleFragment = "starkiller base";
                iwtmPreferredStartingEffect = "the first order was just the beginning";
            }
            // V29 UPDATED 2026-07-06: store raw text for objectiveForbidsDeployingExecutor()
            this.objectiveGameText = gameText;
            LOG.warn("\uD83C\uDFAF [ObjectiveAnalyzer] Analyzing objective: '{}'", title);
            LOG.warn("\uD83C\uDFAF [ObjectiveAnalyzer] Game text: {}", gameText);

            parseGameText(gameText, backGameText);
            // ObjectivePlaybook JSON hydration (2026-07-08): loader-enabled profiles own their
            // declared runtime slots. Most slots augment parser output; authoritative list slots may
            // replace it so stale parser-derived cards cannot survive. With no enabled profile, parser
            // output remains the hard fallback. Disabled profiles stay research-only.
            if (loaderOn) hydrateFromProfile(prof);
            updateFlipStatus(
                    gameState, playerId, objectiveCard);
            this.analyzed = true;

            logAnalysisResults();

        } catch (Exception e) {
            LOG.warn("[ObjectiveAnalyzer] Error analyzing objective: {}", e.getMessage());
        }
    }

    public boolean isObjectiveRelevantLocation(String locationTitle) {
        if (!analyzed || locationTitle == null) return false;
        if (isNoMoneyNoPartsObjectiveFamily()) {
            Boolean structuredMatch = exactStructuredTitleMatch(
                    locationTitle.toLowerCase(Locale.ROOT),
                    "preFlip", "flip");
            if (Boolean.TRUE.equals(structuredMatch)) return true;
        }
        if (hasPreFlipRuntimeActorRule()) {
            return false;
        }
        String titleLower = locationTitle.toLowerCase(Locale.ROOT);

        Boolean structuredMatch = exactStructuredTitleMatch(
                titleLower, "preFlip", "flip");
        if (structuredMatch != null) return structuredMatch;

        if (flipConditionLocations.contains(titleLower)) return true;

        for (String fragment : flipConditionLocationFragments) {
            if (titleLower.contains(fragment)) return true;
        }

        return false;
    }

    /**
     * Evaluates typed objective location conditions against current table state.
     * Unknown relations and filters fail closed.
     */
    public List<FlipLocationRuleState> assessFlipLocationRules(
            SwccgGame game, String playerId, String phase, String purpose) {
        if (!analyzed || game == null || playerId == null
                || phase == null || purpose == null
                || activeFlipLocationRules == null) {
            return Collections.emptyList();
        }

        List<FlipLocationRuleState> states = new ArrayList<>();
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (rule == null || !phase.equals(rule.phase)
                    || !purpose.equals(rule.purpose)
                    || rule.alternatives == null) {
                continue;
            }

            Set<String> satisfied = new LinkedHashSet<>();
            Set<String> missing = new LinkedHashSet<>();
            for (int i = 0; i < rule.alternatives.size(); i++) {
                FlipLocationAlternative alternative = rule.alternatives.get(i);
                String alternativeId = rule.id + ":" + (i + 1);
                boolean alternativeSatisfied =
                        isFirstOrderReignsRouteRule(rule)
                        ? isFirstOrderReignsHostControlled(
                            game, playerId)
                        : isFlipLocationAlternativeSatisfied(
                            game, playerId, alternative);
                if (alternativeSatisfied) {
                    satisfied.add(alternativeId);
                } else {
                    missing.add(alternativeId);
                }
            }

            boolean anyOf = "anyOf".equals(rule.mode);
            boolean conditionSatisfied =
                    isFirstOrderReignsRouteRule(rule)
                    ? isFirstOrderReignsHostControlled(
                        game, playerId)
                    : isShieldMainGeneratorRouteRule(rule)
                    ? isShieldMainGeneratorRouteRuleSatisfied(
                        game, playerId)
                    : anyOf
                        ? !satisfied.isEmpty()
                        : missing.isEmpty()
                            && !rule.alternatives.isEmpty();
            states.add(new FlipLocationRuleState(
                    rule.id,
                    rule.mode,
                    conditionSatisfied,
                    Collections.unmodifiableSet(satisfied),
                    Collections.unmodifiableSet(missing)));
        }
        return Collections.unmodifiableList(states);
    }

    public boolean hasCountedPreFlipActorRule() {
        if (!analyzed || isFlipped || activeFlipLocationRules == null) {
            return false;
        }
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (rule == null || !"preFlip".equals(rule.phase)
                    || !"flip".equals(rule.purpose)
                    || rule.alternatives == null) {
                continue;
            }
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (alternative != null && alternative.actorFilterKey != null
                        && alternative.count != null
                        && alternative.count.value != null
                        && alternative.count.value > 1) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * The Special Edition operative twins need three separate formations.
     * A matching operative is required at each site, but the operative rule
     * removes that operative's ability from control of its matching planet.
     * Each counted site therefore also needs another legal presence source;
     * the proactive hand planner prefers a non-operative character for that
     * second half of the formation.
     */
    public boolean hasCountedOperativeFormationRule() {
        return findCountedOperativeFormationAlternative() != null;
    }

    private static boolean isCountedOperativeFormationAlternative(
            FlipLocationAlternative alternative) {
        if (alternative == null
                || !"controlWith".equals(alternative.relation)
                || !"self".equals(alternative.controller)
                || alternative.count == null
                || alternative.count.value == null
                || alternative.count.value <= 1
                || alternative.locationFilterKey == null) {
            return false;
        }
        return "matchingOperativeToSubjugatedPlanet".equals(
                    alternative.actorFilterKey)
                || "matchingOperativeToRenegadePlanet".equals(
                    alternative.actorFilterKey);
    }

    private FlipLocationAlternative
            findCountedOperativeFormationAlternative() {
        if (isFlipped) return null;
        return findCountedOperativeSourceAlternative();
    }

    private FlipLocationAlternative
            findCountedOperativeSourceAlternative() {
        if (!analyzed || activeFlipLocationRules == null) {
            return null;
        }
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)) continue;
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (isCountedOperativeFormationAlternative(alternative)) {
                    return alternative;
                }
            }
        }
        return null;
    }

    public boolean isCountedOperativeFormationLocation(
            SwccgGame game, String playerId, PhysicalCard location) {
        FlipLocationAlternative alternative =
                findCountedOperativeFormationAlternative();
        return alternative != null && game != null && playerId != null
                && location != null && game.getGameState() != null
                && game.getModifiersQuerying() != null
                && locationMatchesAlternative(
                    game.getGameState(), game, playerId,
                    location, alternative);
    }

    public boolean matchesCountedOperativeFormationActor(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        FlipLocationAlternative alternative =
                findCountedOperativeFormationAlternative();
        return matchesCountedOperativeActor(
                game, playerId, candidate, alternative);
    }

    private boolean matchesCountedOperativeActor(
            SwccgGame game, String playerId, PhysicalCard candidate,
            FlipLocationAlternative alternative) {
        if (alternative == null || game == null || playerId == null
                || candidate == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            com.gempukku.swccgo.filters.Filter actorFilter =
                    resolveFilter(alternative.actorFilterKey);
            return actorFilter != null && actorFilter.accepts(
                    game.getGameState(), game.getModifiersQuerying(),
                    candidate);
        } catch (Exception e) {
            LOG.debug("Counted operative actor assessment failed: {}",
                    e.getMessage());
            return false;
        }
    }

    public boolean isCountedOperativeFormationCompanion(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        if (!hasCountedOperativeFormationRule() || game == null
                || playerId == null || candidate == null
                || !playerId.equals(candidate.getOwner())
                || candidate.isUndercover()
                || candidate.getBlueprint() == null
                || candidate.getBlueprint().getCardCategory()
                    != CardCategory.CHARACTER
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            return !Filters.operative.accepts(
                        game.getGameState(), game.getModifiersQuerying(),
                        candidate)
                    && candidateProvidesPresence(game, candidate);
        } catch (Exception e) {
            LOG.debug("Counted operative companion assessment failed: {}",
                    e.getMessage());
            return false;
        }
    }

    private boolean isCountedOperativeBoardControlCompanion(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        if (!hasCountedOperativeFormationRule() || game == null
                || playerId == null || candidate == null
                || !playerId.equals(candidate.getOwner())
                || candidate.isUndercover()
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            return !Filters.operativeOnMatchingPlanet.accepts(
                        game.getGameState(), game.getModifiersQuerying(),
                        candidate)
                    && candidateProvidesCountedOperativeControlPresence(
                        game, playerId, candidate);
        } catch (Exception e) {
            LOG.debug("Counted operative board companion assessment failed: {}",
                    e.getMessage());
            return false;
        }
    }

    public boolean hasCountedOperativeActorAtLocation(
            SwccgGame game, String playerId, PhysicalCard location) {
        return hasCountedOperativeFormationPieceAtLocation(
                game, playerId, location, null, true);
    }

    public boolean hasCountedOperativeCompanionAtLocation(
            SwccgGame game, String playerId, PhysicalCard location) {
        return hasCountedOperativeFormationPieceAtLocation(
                game, playerId, location, null, false);
    }

    public boolean isCountedOperativeFormationCompleteAt(
            SwccgGame game, String playerId, PhysicalCard location) {
        FlipLocationAlternative alternative =
                findCountedOperativeFormationAlternative();
        return alternative != null
                && isCountedOperativeFormationLocation(
                    game, playerId, location)
                && relationSatisfiedAt(
                    game, playerId, playerId, location,
                    alternative.relation,
                    alternative.actorFilterKey,
                    alternative.includeExcludedFromBattle,
                    alternative.spotOverride);
    }

    /**
     * Projects the ability that can qualify this operative formation for a
     * battle destiny. The engine excludes a matching operative's ability at
     * its planet, including when that operative is the prospective deploy.
     */
    public float getCountedOperativeProjectedBattleDestinyAbility(
            SwccgGame game, String playerId, PhysicalCard location,
            Collection<PhysicalCard> prospectiveCards) {
        if (!hasCountedOperativeFormationRule() || game == null
                || playerId == null || location == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0.0f;
        }
        try {
            float ability = game.getModifiersQuerying()
                    .getTotalAbilityAtLocation(
                        game.getGameState(), playerId, location,
                        false, true, false, null,
                        false, false, null);
            if (prospectiveCards == null) return ability;
            for (PhysicalCard card : prospectiveCards) {
                if (card == null
                        || matchesCountedOperativeFormationActor(
                            game, playerId, card)
                        || card.getBlueprint() == null
                        || !card.getBlueprint().hasAbilityAttribute()) {
                    continue;
                }
                Float cardAbility = card.getBlueprint().getAbility();
                if (cardAbility != null) ability += cardAbility;
            }
            return ability;
        } catch (Exception e) {
            LOG.debug("Counted operative battle-destiny projection failed: {}",
                    e.getMessage());
            return 0.0f;
        }
    }

    public int getCountedOperativeFormationsStillNeeded(
            SwccgGame game, String playerId) {
        FlipLocationAlternative alternative =
                findCountedOperativeFormationAlternative();
        if (alternative == null || game == null || playerId == null) {
            return 0;
        }
        return Math.max(0,
                expectedCount(game, playerId, alternative.count)
                - countAlternativeMatches(
                    game, playerId, playerId, alternative));
    }

    private boolean hasCountedOperativeFormationPieceAtLocation(
            SwccgGame game, String playerId, PhysicalCard location,
            PhysicalCard excluded, boolean actor) {
        if (!isCountedOperativeFormationLocation(
                    game, playerId, location)) {
            return false;
        }
        try {
            Collection<PhysicalCard> permanents =
                    game.getGameState().getAllPermanentCards();
            if (permanents == null) return false;
            for (PhysicalCard card : permanents) {
                if (card == null || card == excluded
                        || !playerId.equals(card.getOwner())
                        || !isActiveForSpot(game, card, true)) {
                    continue;
                }
                PhysicalCard cardLocation = presenceContributionLocation(
                        game, card);
                if (!samePhysicalLocation(cardLocation, location)) continue;
                if (actor
                        ? matchesCountedOperativeFormationActor(
                            game, playerId, card)
                        : isCountedOperativeBoardControlCompanion(
                            game, playerId, card)) {
                    return true;
                }
            }
        } catch (Exception e) {
            LOG.debug("Counted operative formation board assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    /** True when the active front has an actor-at-runtime-location flip leg. */
    public boolean hasPreFlipRuntimeActorRule() {
        if (!analyzed || isFlipped || activeFlipLocationRules == null) {
            return false;
        }
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)) continue;
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (isActorToRuntimeLocationAlternative(alternative)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Classifies a real candidate by whether it fills the next typed location
     * or actor leg of a counted pre-flip rule.
     */
    public ObjectiveProgressCandidateRole classifyPreFlipProgressCandidate(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || candidate == null || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return ObjectiveProgressCandidateRole.NONE;
        }

        try {
            GameState gameState = game.getGameState();
            if (isPreferredRequiredCardDeployCandidate(
                    game, playerId, candidate)) {
                return ObjectiveProgressCandidateRole
                        .REQUIRED_ON_TABLE_CARD;
            }
            if (isPreferredNamedRequiredCardCandidate(
                    game, playerId, candidate)) {
                return ObjectiveProgressCandidateRole
                        .REQUIRED_ON_TABLE_CARD;
            }
            if (isPreferredShieldRouteStageLocation(
                    game, playerId, candidate)) {
                return ObjectiveProgressCandidateRole
                        .REQUIRED_LOCATION;
            }
            if (isPreferredShieldRoutePackageCandidate(
                    game, playerId, candidate)) {
                return ObjectiveProgressCandidateRole
                        .REQUIRED_ACTOR;
            }
            ObjectiveProgressCandidateRole firstOrderRole =
                    classifyFirstOrderReignsProgressCandidate(
                            game, playerId, candidate);
            if (firstOrderRole
                    != ObjectiveProgressCandidateRole.NONE) {
                return firstOrderRole;
            }
            ObjectiveProgressCandidateRole operativeFormationRole =
                    classifyCountedOperativeFormationCandidate(
                            game, playerId, candidate);
            if (operativeFormationRole
                    != ObjectiveProgressCandidateRole.NONE) {
                return operativeFormationRole;
            }
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (!isActivePreFlipRule(rule) || isRuleSatisfied(
                        game, playerId, rule)) {
                    continue;
                }
                for (FlipLocationAlternative alternative : rule.alternatives) {
                    if (alternative == null || alternative.count == null
                            || alternative.count.value == null
                            || alternative.count.value <= 0) {
                        continue;
                    }
                    int required = expectedCount(
                            game, playerId, alternative.count);
                    String controller = resolveController(
                            gameState, playerId, alternative.controller);
                    int qualified = countAlternativeMatches(
                            game, playerId, controller, alternative);
                    if (qualified >= required) continue;

                    if ("onTable".equals(alternative.relation)) {
                        com.gempukku.swccgo.filters.Filter onTableFilter =
                                resolveFilter(alternative.actorFilterKey);
                        if (isISBOperations
                                && "ISB_agent".equals(
                                    alternative.actorFilterKey)
                                && isPreferredIsbOnTableAgentCandidate(
                                    game, playerId, candidate)) {
                            return ObjectiveProgressCandidateRole
                                    .REQUIRED_ON_TABLE_CARD;
                        }
                        if (onTableFilter != null
                                && playerId.equals(candidate.getOwner())
                                && onTableFilter.accepts(
                                        gameState,
                                        game.getModifiersQuerying(),
                                        candidate)
                                && !hasOtherReadyOnTableRequirementInHand(
                                        game, playerId, candidate,
                                        onTableFilter)) {
                            return ObjectiveProgressCandidateRole
                                    .REQUIRED_ON_TABLE_CARD;
                        }
                        continue;
                    }

                    com.gempukku.swccgo.filters.Filter locationFilter =
                            resolveLocationFilter(
                                    alternative.locationFilterKey, playerId);
                    if (locationFilter != null
                            && locationFilter.accepts(
                                    gameState, game.getModifiersQuerying(),
                                    candidate)
                            && countMatchingLocations(
                                    game, playerId, alternative) < required) {
                        return ObjectiveProgressCandidateRole
                                .REQUIRED_LOCATION;
                    }

                    com.gempukku.swccgo.filters.Filter actorFilter =
                            resolveFilter(alternative.actorFilterKey);
                    boolean duplicateCountOneActor = required <= 1
                            && (hasOtherMatchingActorInHand(
                                    game, playerId, candidate,
                                    actorFilter)
                                || isActorAtRelation(alternative)
                                    && hasOtherMatchingActorOnTable(
                                        game, playerId, candidate,
                                        actorFilter,
                                        alternative
                                                .includeExcludedFromBattle)
                                || !isActorAtRelation(alternative)
                                    && hasOtherMatchingActorOnPreFlipRoute(
                                        game, playerId, candidate,
                                        actorFilter,
                                        alternative
                                                .includeExcludedFromBattle));
                    if (actorFilter != null
                            && actorFilter.accepts(
                                    gameState, game.getModifiersQuerying(),
                                    candidate)
                            && !duplicateCountOneActor) {
                        List<PhysicalCard> locations =
                                gameState.getLocationsInOrder();
                        if (locations == null) continue;
                        for (PhysicalCard location : locations) {
                            if (advancesAlternativeAt(
                                    game, playerId, candidate, location,
                                    alternative)) {
                                return ObjectiveProgressCandidateRole
                                        .REQUIRED_ACTOR;
                            }
                        }
                    }
                    if (isPlainSelfPresenceAlternative(alternative)
                            && candidate.getZone() == Zone.HAND
                            && playerId.equals(candidate.getOwner())
                            && hasLegalPlainPresenceDestinationForAlternative(
                                    game, playerId, candidate,
                                    alternative)
                            && !hasOtherHandPlainPresenceCandidate(
                                    game, playerId, candidate,
                                    alternative)) {
                        return ObjectiveProgressCandidateRole
                                .REQUIRED_ACTOR;
                    }
                }
            }
            ObjectiveProgressCandidateRole deployEnablerRole =
                    classifyRequiredCardDeployEnablerCandidate(
                            game, playerId, candidate);
            if (deployEnablerRole
                    != ObjectiveProgressCandidateRole.NONE) {
                return deployEnablerRole;
            }
        } catch (Exception e) {
            LOG.debug("Objective progress candidate assessment failed: {}",
                    e.getMessage());
        }
        return ObjectiveProgressCandidateRole.NONE;
    }

    private ObjectiveProgressCandidateRole
            classifyCountedOperativeFormationCandidate(
                    SwccgGame game, String playerId,
                    PhysicalCard candidate) {
        FlipLocationAlternative alternative =
                findCountedOperativeFormationAlternative();
        if (alternative == null || candidate == null
                || !playerId.equals(candidate.getOwner())) {
            return ObjectiveProgressCandidateRole.NONE;
        }
        boolean actor = matchesCountedOperativeFormationActor(
                game, playerId, candidate);
        boolean companion = !actor
                && isCountedOperativeFormationCompanion(
                    game, playerId, candidate);
        if (!actor && !companion) {
            return ObjectiveProgressCandidateRole.NONE;
        }
        CountedOperativeFormationNeed need =
                countedOperativeFormationNeed(
                        game, playerId, alternative);
        int needed = actor ? need.actors() : need.companions();
        if (needed <= 0) return ObjectiveProgressCandidateRole.NONE;

        List<PhysicalCard> candidates = new ArrayList<>();
        for (PhysicalCard card : objectiveForceLossSurvivors(
                game.getGameState(), playerId)) {
            if (card == null || !playerId.equals(card.getOwner())) continue;
            boolean matches = actor
                    ? matchesCountedOperativeFormationActor(
                        game, playerId, card)
                    : isCountedOperativeFormationCompanion(
                        game, playerId, card);
            if (matches) candidates.add(card);
        }
        candidates.sort(Comparator
                .comparingInt((PhysicalCard card) ->
                    countedOperativeComponentZoneRank(card.getZone()))
                .thenComparingInt(
                    ObjectiveAnalyzer::printedDeployCost)
                .thenComparingInt(
                    PhysicalCard::getPermanentCardId));
        for (int i = 0; i < Math.min(needed, candidates.size()); i++) {
            if (candidates.get(i) == candidate) {
                return actor
                        ? ObjectiveProgressCandidateRole.REQUIRED_ACTOR
                        : ObjectiveProgressCandidateRole
                            .REQUIRED_COMPANION;
            }
        }
        return ObjectiveProgressCandidateRole.NONE;
    }

    private CountedOperativeFormationNeed countedOperativeFormationNeed(
            SwccgGame game, String playerId,
            FlipLocationAlternative alternative) {
        return countedOperativeFormationNeed(
                game, playerId, alternative, true);
    }

    private CountedOperativeFormationNeed countedOperativeFormationNeed(
            SwccgGame game, String playerId,
            FlipLocationAlternative alternative,
            boolean includeFutureSites) {
        int required = expectedCount(game, playerId, alternative.count);
        int qualified = countAlternativeMatches(
                game, playerId, playerId, alternative);
        int sitesNeeded = Math.max(0, required - qualified);
        if (sitesNeeded == 0) {
            return new CountedOperativeFormationNeed(0, 0);
        }

        List<PhysicalCard> incomplete = new ArrayList<>();
        for (PhysicalCard location
                : game.getGameState().getLocationsInOrder()) {
            if (!locationMatchesAlternative(
                        game.getGameState(), game, playerId,
                        location, alternative)
                    || relationSatisfiedAt(
                        game, playerId, playerId, location,
                        alternative.relation,
                        alternative.actorFilterKey,
                        alternative.includeExcludedFromBattle,
                        alternative.spotOverride)) {
                continue;
            }
            incomplete.add(location);
        }
        incomplete.sort(Comparator
                .comparingInt((PhysicalCard location) -> {
                    int missing = 0;
                    if (!hasCountedOperativeActorAtLocation(
                            game, playerId, location)) missing++;
                    if (!hasCountedOperativeCompanionAtLocation(
                            game, playerId, location)) missing++;
                    return missing;
                })
                .thenComparingInt(PhysicalCard::getPermanentCardId));

        int actors = 0;
        int companions = 0;
        int selectedSites = 0;
        for (PhysicalCard location : incomplete) {
            if (selectedSites >= sitesNeeded) break;
            boolean actorPresent = hasCountedOperativeActorAtLocation(
                    game, playerId, location);
            boolean companionPresent =
                    hasCountedOperativeCompanionAtLocation(
                        game, playerId, location);
            if (actorPresent && companionPresent) {
                continue;
            }
            if (!actorPresent) actors++;
            if (!companionPresent) companions++;
            selectedSites++;
        }
        int futureSites = includeFutureSites
                ? Math.max(0, sitesNeeded - selectedSites) : 0;
        return new CountedOperativeFormationNeed(
                actors + futureSites,
                companions + futureSites);
    }

    private static int countedOperativeComponentZoneRank(Zone zone) {
        if (zone == Zone.HAND) return 0;
        if (zone == Zone.RESERVE_DECK
                || zone == Zone.TOP_OF_RESERVE_DECK) return 1;
        return 2;
    }

    private static int printedDeployCost(PhysicalCard card) {
        if (card == null || card.getBlueprint() == null) {
            return Integer.MAX_VALUE;
        }
        try {
            Float cost = card.getBlueprint().getDeployCost();
            return cost != null
                    ? Math.max(0, (int) Math.ceil(cost))
                    : Integer.MAX_VALUE;
        } catch (Exception e) {
            return Integer.MAX_VALUE;
        }
    }

    private boolean hasOtherHandPlainPresenceCandidate(
            SwccgGame game, String playerId, PhysicalCard excluded,
            FlipLocationAlternative alternative) {
        List<PhysicalCard> hand = game.getGameState().getHand(playerId);
        if (hand == null) return false;
        for (PhysicalCard card : hand) {
            if (card == null || card == excluded
                    || !playerId.equals(card.getOwner())
                    || !hasLegalPlainPresenceDestinationForAlternative(
                            game, playerId, card, alternative)) {
                continue;
            }
            return true;
        }
        return false;
    }

    private boolean hasLegalPlainPresenceDestinationForAlternative(
            SwccgGame game, String playerId, PhysicalCard candidate,
            FlipLocationAlternative alternative) {
        List<PhysicalCard> locations =
                game.getGameState().getLocationsInOrder();
        if (locations == null) return false;
        for (PhysicalCard location : locations) {
            if (!advancesAlternativeAt(
                        game, playerId, candidate,
                        location, alternative)) {
                continue;
            }
            if (Filters.deployableToLocation(
                    candidate, Filters.sameCardId(location),
                    false, 0.0f).accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate)) {
                return true;
            }
        }
        return false;
    }

    private ObjectiveProgressCandidateRole
            classifyFirstOrderReignsProgressCandidate(
                    SwccgGame game, String playerId,
                    PhysicalCard candidate) {
        if (!isFirstOrderReignsRouteOpen(
                    game, playerId)
                || candidate == null
                || !playerId.equals(candidate.getOwner())) {
            return ObjectiveProgressCandidateRole.NONE;
        }
        PhysicalCard host =
                getFirstOrderReignsTrackedFleetHostSystem(
                    game, playerId);
        if (host == null) {
            return ObjectiveProgressCandidateRole.NONE;
        }
        List<PhysicalCard> chaseShips =
                getFirstOrderReignsAdvancingChaseShipsOnTable(
                        game, playerId, host);
        if (!chaseShips.isEmpty()) {
            for (PhysicalCard chaseShip : chaseShips) {
                if (isFirstOrderReignsReachableBridgeSystem(
                        game, playerId, host,
                        chaseShip, candidate)) {
                    return ObjectiveProgressCandidateRole
                            .REQUIRED_LOCATION;
                }
            }
            return ObjectiveProgressCandidateRole.NONE;
        }
        if (!hasFirstOrderReignsStagingSystem(
                    game, playerId, host)) {
            return isFirstOrderReignsStageSystem(
                        game, playerId, host,
                        candidate, true)
                    ? ObjectiveProgressCandidateRole
                        .REQUIRED_LOCATION
                    : ObjectiveProgressCandidateRole.NONE;
        }
        if (isFirstOrderReignsChaseShipCandidate(
                    game, playerId, candidate)
                && hasFirstOrderReignsStageForShip(
                    game, playerId, host, candidate)) {
            return ObjectiveProgressCandidateRole
                    .REQUIRED_ACTOR;
        }
        return ObjectiveProgressCandidateRole.NONE;
    }

    /**
     * Exact required-deploy rules own the initial pull before the later flip
     * destination is on table. Shield must acquire 222_13 while its legal
     * Ice Plains destination is ready; waiting for 3rd Marker would deadlock
     * the route before it started.
     */
    private boolean isPreferredRequiredCardDeployCandidate(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (activeRequiredCardDeployRules == null
                || candidate == null
                || !playerId.equals(candidate.getOwner())) {
            return false;
        }
        for (RequiredCardDeployRule rule
                : activeRequiredCardDeployRules) {
            if (!isRequiredCardDeployRuleActive(
                        game, playerId, rule)
                    || rule.blueprintIds == null
                    || !rule.blueprintIds.contains(
                        candidate.getBlueprintId(true))) {
                continue;
            }
            com.gempukku.swccgo.filters.Filter cardFilter =
                    resolveFilter(rule.requiredCardFilterKey);
            if (cardFilter != null
                    && cardFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate)
                    && isRequiredOnTableCardPullRouteReady(
                        game, playerId, candidate)
                    && !hasOtherReadyOnTableRequirementInHand(
                        game, playerId, candidate,
                        cardFilter)) {
                return true;
            }
        }
        return false;
    }

    private boolean isPreferredNamedRequiredCardCandidate(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        String requirement =
                matchingRequiredTitle(candidate);
        if (requirement == null
                || isRequiredCardActiveOnTable(
                    game, requirement)
                || !isRequiredOnTableCardPullRouteReady(
                    game, playerId, candidate)) {
            return false;
        }
        List<PhysicalCard> hand =
                game.getGameState().getHand(playerId);
        List<PhysicalCard> candidates = new ArrayList<>();
        if (hand != null) candidates.addAll(hand);
        List<PhysicalCard> reserve =
                game.getGameState().getReserveDeck(playerId);
        if (reserve != null) candidates.addAll(reserve);
        int candidateRank =
                requiredCardProgressZoneRank(candidate);
        Integer candidateCost =
                requiredOnTableCardDeployCost(
                    game, playerId, candidate);
        int candidateCostRank = candidateCost != null
                ? candidateCost : Integer.MAX_VALUE;
        for (PhysicalCard card : candidates) {
            if (card == null || card == candidate
                    || !playerId.equals(card.getOwner())
                    || !physicalCardMatchesRequirement(
                        card, requirement)
                    || !isRequiredOnTableCardPullRouteReady(
                        game, playerId, card)) {
                continue;
            }
            int rank = requiredCardProgressZoneRank(card);
            Integer cost =
                    requiredOnTableCardDeployCost(
                        game, playerId, card);
            int costRank = cost != null
                    ? cost : Integer.MAX_VALUE;
            if (rank < candidateRank
                    || rank == candidateRank
                        && (costRank < candidateCostRank
                            || costRank == candidateCostRank
                                && card.getCardId()
                                    < candidate.getCardId())) {
                return false;
            }
        }
        return true;
    }

    private static int requiredCardProgressZoneRank(
            PhysicalCard card) {
        if (card == null || card.getZone() == null) return 3;
        Zone zone = card.getZone();
        if (zone == Zone.HAND) return 0;
        if (zone == Zone.RESERVE_DECK
                || zone == Zone.TOP_OF_RESERVE_DECK) {
            return 1;
        }
        return 2;
    }

    private ObjectiveProgressCandidateRole
            classifyRequiredCardDeployEnablerCandidate(
                    SwccgGame game, String playerId,
                    PhysicalCard candidate) {
        if (activeRequiredCardDeployRules == null
                || candidate == null) {
            return ObjectiveProgressCandidateRole.NONE;
        }
        GameState gameState = game.getGameState();
        for (RequiredCardDeployRule rule
                : activeRequiredCardDeployRules) {
            FlipLocationAlternative prerequisite =
                    rule != null ? rule.prerequisite : null;
            if (!isRequiredCardDeployRuleActive(
                        game, playerId, rule)
                    || prerequisite == null
                    || prerequisite.count == null
                    || prerequisite.count.value == null
                    || prerequisite.count.value <= 0
                    || isFlipLocationAlternativeSatisfied(
                        game, playerId, prerequisite)
                    || isUpperBound(prerequisite.count)) {
                continue;
            }
            int required = expectedCount(
                    game, playerId, prerequisite.count);
            com.gempukku.swccgo.filters.Filter locationFilter =
                    resolveLocationFilter(
                            prerequisite.locationFilterKey,
                            playerId);
            if (locationFilter != null
                    && locationFilter.accepts(
                        gameState, game.getModifiersQuerying(),
                        candidate)
                    && countMatchingLocations(
                        game, playerId, prerequisite) < required) {
                return ObjectiveProgressCandidateRole
                        .REQUIRED_CARD_DEPLOY_ENABLER_LOCATION;
            }

            com.gempukku.swccgo.filters.Filter actorFilter =
                    resolveFilter(prerequisite.actorFilterKey);
            if (actorFilter == null
                    || !playerId.equals(candidate.getOwner())) {
                continue;
            }
            boolean directActor = actorFilter.accepts(
                    gameState, game.getModifiersQuerying(),
                    candidate);
            if (directActor) {
                List<PhysicalCard> locations =
                        gameState.getLocationsInOrder();
                if (locations == null) continue;
                for (PhysicalCard location : locations) {
                    if (advancesAlternativeAt(
                            game, playerId, candidate, location,
                            prerequisite)) {
                        return ObjectiveProgressCandidateRole
                                .REQUIRED_CARD_DEPLOY_ENABLER_ACTOR;
                    }
                }
            }
            if (matchesProspectiveActorPairComponent(
                        game, playerId, candidate,
                        prerequisite)
                    && hasOpenRequiredCardDeployActorLocation(
                        game, playerId, candidate,
                        prerequisite)) {
                    return ObjectiveProgressCandidateRole
                            .REQUIRED_CARD_DEPLOY_ENABLER_ACTOR;
            }
        }
        return ObjectiveProgressCandidateRole.NONE;
    }

    public boolean advancesRequiredCardDeployPrerequisiteAt(
            SwccgGame game, String playerId, PhysicalCard candidate,
            PhysicalCard destination) {
        if (!analyzed || isFlipped || game == null
                || playerId == null || candidate == null
                || destination == null
                || activeRequiredCardDeployRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        for (RequiredCardDeployRule rule
                : activeRequiredCardDeployRules) {
            FlipLocationAlternative prerequisite =
                    rule != null ? rule.prerequisite : null;
            if (isRequiredCardDeployRuleActive(
                        game, playerId, rule)
                    && prerequisite != null
                    && prerequisite.actorFilterKey != null
                    && !isUpperBound(prerequisite.count)
                    && !isFlipLocationAlternativeSatisfied(
                        game, playerId, prerequisite)
                    && (advancesAlternativeAt(
                            game, playerId, candidate, destination,
                            prerequisite)
                        || advancesProspectiveActorPairAt(
                            game, playerId, candidate, destination,
                            prerequisite))) {
                return true;
            }
        }
        return false;
    }

    public boolean advancesRequiredCardDeployPrerequisiteByMovingTo(
            SwccgGame game, String playerId, PhysicalCard candidate,
            PhysicalCard destination) {
        if (!analyzed || isFlipped || game == null
                || playerId == null || candidate == null
                || destination == null
                || activeRequiredCardDeployRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        PhysicalCard origin = game.getModifiersQuerying()
                .getLocationThatCardIsAt(
                        game.getGameState(), candidate);
        if (origin == null
                || samePhysicalLocation(origin, destination)) {
            return false;
        }
        for (RequiredCardDeployRule rule
                : activeRequiredCardDeployRules) {
            FlipLocationAlternative prerequisite =
                    rule != null ? rule.prerequisite : null;
            if (!isRequiredCardDeployRuleActive(
                        game, playerId, rule)
                    || prerequisite == null
                    || prerequisite.actorFilterKey == null
                    || prerequisite.count == null
                    || prerequisite.count.value == null
                    || prerequisite.count.value <= 0
                    || isUpperBound(prerequisite.count)
                    || isFlipLocationAlternativeSatisfied(
                        game, playerId, prerequisite)
                    || (!advancesAlternativeAt(
                            game, playerId, candidate,
                            destination, prerequisite)
                        && !advancesProspectiveActorPairAt(
                            game, playerId, candidate,
                            destination, prerequisite))) {
                continue;
            }

            boolean originQualified =
                    locationMatchesAlternative(
                        game.getGameState(), game, playerId,
                        origin, prerequisite)
                    && relationSatisfiedAt(
                        game, playerId, playerId, origin,
                        prerequisite.relation,
                        prerequisite.actorFilterKey,
                        prerequisite.includeExcludedFromBattle,
                        prerequisite.spotOverride);
            if (!originQualified) return true;

            com.gempukku.swccgo.filters.Filter actorFilter =
                    resolveFilter(prerequisite.actorFilterKey);
            PhysicalCard pairedActorLost =
                    prospectivePairActorLostWithPilot(
                        game, playerId, candidate,
                        prerequisite, actorFilter);
            boolean removesRequiredActor =
                    removedGroupContainsMatchingActor(
                        game, playerId, origin,
                        prerequisite, candidate,
                        pairedActorLost, actorFilter)
                    && !hasOtherMatchingActorOutsideRemovedGroup(
                        game, playerId, origin,
                        prerequisite, candidate,
                        pairedActorLost);
            boolean removesSolePresence =
                    isSolePresenceSourceAtLocation(
                        game, playerId, candidate, origin);
            if (!removesRequiredActor
                    && !removesSolePresence) {
                return true;
            }
        }
        return false;
    }

    public boolean
            preservesRequiredCardDeployPrerequisiteByMovingTo(
                    SwccgGame game, String playerId,
                    PhysicalCard candidate,
                    PhysicalCard destination) {
        if (!analyzed || isFlipped || game == null
                || playerId == null || candidate == null
                || destination == null
                || activeRequiredCardDeployRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        PhysicalCard origin = game.getModifiersQuerying()
                .getLocationThatCardIsAt(
                        game.getGameState(), candidate);
        if (origin == null
                || samePhysicalLocation(origin, destination)) {
            return false;
        }

        boolean criticalPrerequisiteSeen = false;
        for (RequiredCardDeployRule rule
                : activeRequiredCardDeployRules) {
            FlipLocationAlternative prerequisite =
                    rule != null ? rule.prerequisite : null;
            if (!isRequiredCardDeployRuleActive(
                        game, playerId, rule)
                    || prerequisite == null
                    || prerequisite.actorFilterKey == null
                    || prerequisite.count == null
                    || prerequisite.count.value == null
                    || prerequisite.count.value <= 0
                    || isUpperBound(prerequisite.count)
                    || !locationMatchesAlternative(
                        game.getGameState(), game, playerId,
                        origin, prerequisite)
                    || !relationSatisfiedAt(
                        game, playerId, playerId, origin,
                        prerequisite.relation,
                        prerequisite.actorFilterKey,
                        prerequisite.includeExcludedFromBattle,
                        prerequisite.spotOverride)) {
                continue;
            }

            int required = expectedCount(
                    game, playerId, prerequisite.count);
            int qualified = countAlternativeMatches(
                    game, playerId, playerId, prerequisite);
            if (qualified > required) {
                continue;
            }
            com.gempukku.swccgo.filters.Filter actorFilter =
                    resolveFilter(prerequisite.actorFilterKey);
            PhysicalCard dependentActor =
                    prospectivePairActorLostWithPilot(
                        game, playerId, candidate,
                        prerequisite, actorFilter);
            boolean removesRequiredActor =
                    removedGroupContainsMatchingActor(
                        game, playerId, origin,
                        prerequisite, candidate,
                        dependentActor, actorFilter)
                    && !hasOtherMatchingActorOutsideRemovedGroup(
                        game, playerId, origin,
                        prerequisite, candidate,
                        dependentActor);
            boolean removesSolePresence =
                    isSolePresenceSourceAtLocation(
                        game, playerId, candidate, origin);
            if (!removesRequiredActor
                    && !removesSolePresence) {
                continue;
            }

            criticalPrerequisiteSeen = true;
            if (relationSatisfiedAt(
                        game, playerId, playerId,
                        destination, prerequisite.relation,
                        prerequisite.actorFilterKey,
                        prerequisite.includeExcludedFromBattle,
                        prerequisite.spotOverride)
                    || !movedGroupCanSatisfyAlternativeAt(
                        game, playerId, candidate,
                        destination, prerequisite,
                        actorFilter)) {
                return false;
            }
        }
        return criticalPrerequisiteSeen;
    }

    public boolean
            hasSafeRequiredCardDeployActorLandspeedDestination(
                    SwccgGame game, String playerId,
                    PhysicalCard candidate) {
        if (game == null || playerId == null
                || candidate == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        PhysicalCard origin = game.getModifiersQuerying()
                .getLocationThatCardIsAt(
                        game.getGameState(), candidate);
        if (origin == null) return false;
        try {
            com.gempukku.swccgo.filters.Filter legalTarget =
                    Filters.canMoveToUsingLandspeed(
                        playerId, candidate,
                        false, false, false,
                        0.0f, null);
            for (PhysicalCard destination
                    : game.getGameState()
                        .getLocationsInOrder()) {
                if (destination != null
                        && legalTarget.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(),
                            destination)
                        && preservesRequiredCardDeployPrerequisiteByMovingTo(
                            game, playerId, candidate,
                            destination)
                        && FormationSafety
                            .vetoMoveDestination(
                                game, game.getGameState(),
                                playerId, candidate,
                                destination) == null
                        && FormationSafety
                            .vetoMoveOrigin(
                                game, game.getGameState(),
                                playerId, candidate,
                                origin) == null) {
                    return true;
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "Required-card actor relocation assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    private boolean movedGroupCanSatisfyAlternativeAt(
            SwccgGame game, String playerId,
            PhysicalCard movedRoot,
            PhysicalCard destination,
            FlipLocationAlternative alternative,
            com.gempukku.swccgo.filters.Filter actorFilter) {
        if (actorFilter == null
                || !locationMatchesAlternative(
                    game.getGameState(), game, playerId,
                    destination, alternative)) {
            return false;
        }
        Collection<PhysicalCard> cards =
                game.getGameState().getAllPermanentCards();
        if (cards == null) return false;
        boolean hasActor = false;
        boolean providesPresence = false;
        com.gempukku.swccgo.filters.Filter presenceSource =
                Filters.or(
                    Filters.hasAbilityOrHasPermanentPilotWithAbility,
                    com.gempukku.swccgo.common.Icon.PRESENCE);
        for (PhysicalCard card : cards) {
            if (!belongsToRemovedGroup(
                        card, movedRoot, null)
                    || !playerId.equals(card.getOwner())
                    || !isActiveForSpot(
                        game, card,
                        alternative.includeExcludedFromBattle)) {
                continue;
            }
            hasActor |= actorFilter.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), card);
            SwccgCardBlueprint blueprint =
                    card.getBlueprint();
            boolean cardProvidesPresence =
                    blueprint != null
                    && blueprint.hasAbilityAttribute()
                    && blueprint.getAbility() != null
                    && blueprint.getAbility() >= 1.0f;
            if (!cardProvidesPresence) {
                cardProvidesPresence =
                        presenceSource.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(),
                            card);
            }
            if (!cardProvidesPresence
                    && Filters.piloted.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        card)) {
                cardProvidesPresence =
                        game.getModifiersQuerying()
                            .getHighestAbilityPiloting(
                                game.getGameState(),
                                card, false, false)
                            >= 1.0f;
            }
            providesPresence |=
                    cardProvidesPresence;
        }
        if (!hasActor) return false;
        if (isActorAtRelation(alternative)) return true;

        Map<com.gempukku.swccgo.common.InactiveReason, Boolean>
                overrides = Boolean.TRUE.equals(
                    alternative.includeExcludedFromBattle)
                        ? SpotOverride
                            .INCLUDE_EXCLUDED_FROM_BATTLE
                        : null;
        if ("controlWith".equals(alternative.relation)) {
            if (game.getModifiersQuerying()
                    .controlsLocation(
                        game.getGameState(), destination,
                        playerId, overrides)) {
                return true;
            }
            String opponent =
                    game.getGameState()
                        .getOpponent(playerId);
            return providesPresence
                    && (opponent == null
                        || !game.getModifiersQuerying()
                            .occupiesLocation(
                                game.getGameState(),
                                destination, opponent,
                                overrides));
        }
        if ("occupyWith".equals(alternative.relation)) {
            return providesPresence
                    || game.getModifiersQuerying()
                        .occupiesLocation(
                            game.getGameState(),
                            destination, playerId,
                            overrides);
        }
        return false;
    }

    private boolean hasOpenRequiredCardDeployActorLocation(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            FlipLocationAlternative prerequisite) {
        ProspectiveActorPair pair =
                prerequisite != null
                        ? prerequisite.prospectiveActorPair : null;
        if (pair == null || candidate == null) return false;
        com.gempukku.swccgo.filters.Filter hostFilter =
                resolveFilter(pair.hostFilterKey);
        com.gempukku.swccgo.filters.Filter pilotFilter =
                resolveFilter(pair.pilotFilterKey);
        if (hostFilter == null || pilotFilter == null) return false;

        List<PhysicalCard> locations =
                game.getGameState().getLocationsInOrder();
        if (locations == null) return false;
        if (hostFilter.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), candidate)) {
            for (PhysicalCard location : locations) {
                if (canProspectivePairAdvanceAtTarget(
                            game, playerId, location,
                            prerequisite)
                        && hasUsablePilotForProspectiveHostAt(
                            game, playerId, candidate,
                            pilotFilter, location)) {
                    return true;
                }
            }
            return false;
        }
        if (!pilotFilter.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), candidate)) {
            return false;
        }

        List<PhysicalCard> hand =
                game.getGameState().getHand(playerId);
        if (hand != null) {
            for (PhysicalCard host : hand) {
                if (!isUsableProspectivePairCounterpart(
                            game, playerId, candidate, host,
                            hostFilter, true, false)) {
                    continue;
                }
                for (PhysicalCard location : locations) {
                    if (canProspectivePairAdvanceAtTarget(
                                game, playerId, location,
                                prerequisite)
                            && isProspectivePairRouteLegalAt(
                                game, playerId, host,
                                candidate, location)) {
                        return true;
                    }
                }
            }
        }
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents == null) return false;
        for (PhysicalCard host : permanents) {
            if (!isUsableProspectivePairCounterpart(
                        game, playerId, candidate, host,
                        hostFilter, true, true)) {
                continue;
            }
            PhysicalCard location =
                    game.getModifiersQuerying()
                        .getLocationThatCardIsAt(
                            game.getGameState(), host);
            if (canProspectivePairAdvanceAtTarget(
                        game, playerId, location,
                        prerequisite)
                    && isProspectivePairRouteLegalAt(
                        game, playerId, host,
                        candidate, location)) {
                return true;
            }
        }
        return false;
    }

    private boolean matchesProspectiveActorPairComponent(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            FlipLocationAlternative prerequisite) {
        ProspectiveActorPair pair =
                prerequisite != null
                        ? prerequisite.prospectiveActorPair : null;
        if (pair == null || pair.hostFilterKey == null
                || pair.pilotFilterKey == null
                || candidate == null
                || !playerId.equals(candidate.getOwner())) {
            return false;
        }
        com.gempukku.swccgo.filters.Filter hostFilter =
                resolveFilter(pair.hostFilterKey);
        com.gempukku.swccgo.filters.Filter pilotFilter =
                resolveFilter(pair.pilotFilterKey);
        if (hostFilter == null || pilotFilter == null) return false;
        boolean candidateIsHost = hostFilter.accepts(
                game.getGameState(),
                game.getModifiersQuerying(), candidate);
        boolean candidateIsPilot = pilotFilter.accepts(
                game.getGameState(),
                game.getModifiersQuerying(), candidate);
        return candidateIsHost
                && hasAccessibleProspectivePairCounterpart(
                    game, playerId, candidate,
                    pilotFilter, false)
                || candidateIsPilot
                && hasAccessibleProspectivePairCounterpart(
                    game, playerId, candidate,
                    hostFilter, true);
    }

    private boolean hasAccessibleProspectivePairCounterpart(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            com.gempukku.swccgo.filters.Filter counterpartFilter,
            boolean requireUnpiloted) {
        GameState gameState = game.getGameState();
        List<PhysicalCard> hand = gameState.getHand(playerId);
        if (hand != null) {
            for (PhysicalCard card : hand) {
                if (isUsableProspectivePairCounterpart(
                        game, playerId, candidate, card,
                        counterpartFilter, requireUnpiloted,
                        false)) {
                    return true;
                }
            }
        }
        Collection<PhysicalCard> permanents =
                gameState.getAllPermanentCards();
        if (permanents != null) {
            for (PhysicalCard card : permanents) {
                if (isUsableProspectivePairCounterpart(
                        game, playerId, candidate, card,
                        counterpartFilter, requireUnpiloted,
                        true)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isUsableProspectivePairCounterpart(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard counterpart,
            com.gempukku.swccgo.filters.Filter counterpartFilter,
            boolean requireUnpiloted, boolean requireActive) {
        if (counterpart == null || counterpart == candidate
                || !playerId.equals(counterpart.getOwner())
                || !counterpartFilter.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), counterpart)
                || requireActive
                    && !isActiveForSpot(
                        game, counterpart, false)
                || requireUnpiloted
                    && Filters.piloted.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), counterpart)
                || requireActive && !requireUnpiloted
                    && counterpart.getAttachedTo() != null) {
            return false;
        }
        PhysicalCard host = requireUnpiloted
                ? counterpart : candidate;
        PhysicalCard pilot = requireUnpiloted
                ? candidate : counterpart;
        return isLegalProspectivePilotForHost(
                game, playerId, host, pilot);
    }

    private boolean isLegalProspectivePilotForHost(
            SwccgGame game, String playerId,
            PhysicalCard host, PhysicalCard pilot) {
        if (game == null || playerId == null
                || host == null || pilot == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || !playerId.equals(host.getOwner())
                || !playerId.equals(pilot.getOwner())
                || host.getBlueprint() == null
                || pilot.getBlueprint() == null) {
            return false;
        }
        try {
            GameState gameState = game.getGameState();
            boolean hostInPlay = host.getZone() != null
                    && host.getZone().isInPlay();
            boolean pilotInPlay = pilot.getZone() != null
                    && pilot.getZone().isInPlay();
            if (hostInPlay
                    && (!isActiveForSpot(game, host, false)
                        || host.getAttachedTo() != null)) {
                return false;
            }
            boolean forDeployment = !pilotInPlay;
            return host.getBlueprint()
                        .getValidPilotFilter(
                                playerId, game, host,
                                forDeployment)
                        .accepts(
                                gameState,
                                game.getModifiersQuerying(),
                                pilot)
                    && Filters.hasAvailablePilotCapacity(pilot)
                        .accepts(
                                gameState,
                                game.getModifiersQuerying(),
                                host);
        } catch (Exception e) {
            LOG.debug(
                    "Prospective pilot-host legality unavailable: {}",
                    e.getMessage());
            return false;
        }
    }

    private boolean isProspectivePairRouteLegalAt(
            SwccgGame game, String playerId,
            PhysicalCard host, PhysicalCard pilot,
            PhysicalCard targetLocation) {
        if (!isLegalProspectivePilotForHost(
                    game, playerId, host, pilot)
                || targetLocation == null) {
            return false;
        }
        try {
            GameState gameState = game.getGameState();
            boolean hostInPlay = host.getZone() != null
                    && host.getZone().isInPlay();
            boolean pilotInPlay = pilot.getZone() != null
                    && pilot.getZone().isInPlay();
            if (hostInPlay) {
                PhysicalCard hostLocation =
                        game.getModifiersQuerying()
                            .getLocationThatCardIsAt(
                                    gameState, host);
                if (!samePhysicalLocation(
                            hostLocation, targetLocation)) {
                    return false;
                }
            }
            if (pilotInPlay) {
                PhysicalCard pilotLocation =
                        game.getModifiersQuerying()
                            .getLocationThatCardIsAt(
                                    gameState, pilot);
                if (!samePhysicalLocation(
                            pilotLocation, targetLocation)) {
                    return false;
                }
            }
            // These are route-shape probes. Free-cost mode deliberately
            // removes current Force affordability so the budget calculation
            // can reserve toward a legal route that is not affordable yet.
            if (!hostInPlay) {
                if (pilotInPlay) {
                    return Filters.deployableToLocation(
                                host,
                                Filters.sameCardId(targetLocation),
                                true, 0.0f)
                            .accepts(
                                gameState,
                                game.getModifiersQuerying(),
                                host);
                }
                return Filters
                        .deployableToLocationSimultaneouslyWith(
                            host, pilot, true, 0.0f,
                            Filters.sameCardId(targetLocation),
                            true, 0.0f)
                        .accepts(
                            gameState,
                            game.getModifiersQuerying(),
                            host);
            }
            if (!pilotInPlay) {
                return Filters.deployableToTarget(
                            pilot, Filters.sameCardId(host),
                            true, 0.0f)
                        .accepts(
                            gameState,
                            game.getModifiersQuerying(),
                            pilot);
            }
            return Filters.canEmbarkTo(
                        playerId, pilot, true, 0.0f)
                    .accepts(
                        gameState,
                        game.getModifiersQuerying(),
                        host);
        } catch (Exception e) {
            LOG.debug(
                    "Prospective pilot-host route unavailable: {}",
                    e.getMessage());
            return false;
        }
    }

    private boolean hasUsablePilotForProspectiveHostAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            com.gempukku.swccgo.filters.Filter pilotFilter,
            PhysicalCard targetLocation) {
        List<PhysicalCard> hand =
                game.getGameState().getHand(playerId);
        if (hand != null) {
            for (PhysicalCard card : hand) {
                if (isUsableProspectivePairCounterpart(
                        game, playerId, candidate, card,
                        pilotFilter, false, false)
                        && isProspectivePairRouteLegalAt(
                            game, playerId, candidate,
                            card, targetLocation)) {
                    return true;
                }
            }
        }
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents == null) return false;
        for (PhysicalCard card : permanents) {
            if (!isUsableProspectivePairCounterpart(
                        game, playerId, candidate, card,
                        pilotFilter, false, true)) {
                continue;
            }
            if (isProspectivePairRouteLegalAt(
                        game, playerId, candidate,
                        card, targetLocation)) {
                return true;
            }
        }
        return false;
    }

    private boolean advancesProspectiveActorPairAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard destination,
            FlipLocationAlternative prerequisite) {
        ProspectiveActorPair pair =
                prerequisite != null
                        ? prerequisite.prospectiveActorPair : null;
        if (pair == null || candidate == null || destination == null
                || !playerId.equals(candidate.getOwner())) {
            return false;
        }
        com.gempukku.swccgo.filters.Filter hostFilter =
                resolveFilter(pair.hostFilterKey);
        com.gempukku.swccgo.filters.Filter pilotFilter =
                resolveFilter(pair.pilotFilterKey);
        if (hostFilter == null || pilotFilter == null) return false;
        GameState gameState = game.getGameState();
        PhysicalCard targetLocation;
        if (hostFilter.accepts(
                    gameState, game.getModifiersQuerying(),
                    candidate)) {
            targetLocation = destination;
            if (!hasUsablePilotForProspectiveHostAt(
                        game, playerId, candidate,
                        pilotFilter, targetLocation)) {
                return false;
            }
        } else if (pilotFilter.accepts(
                    gameState, game.getModifiersQuerying(),
                    candidate)
                && playerId.equals(destination.getOwner())
                && hostFilter.accepts(
                    gameState, game.getModifiersQuerying(),
                    destination)
                && !Filters.piloted.accepts(
                    gameState, game.getModifiersQuerying(),
                    destination)
                && isLegalProspectivePilotForHost(
                    game, playerId, destination, candidate)) {
            targetLocation = game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                            gameState, destination);
            if (!isProspectivePairRouteLegalAt(
                        game, playerId, destination,
                        candidate, targetLocation)) {
                return false;
            }
        } else {
            return false;
        }
        return canProspectivePairAdvanceAtTarget(
                game, playerId, targetLocation, prerequisite);
    }

    private boolean canProspectivePairAdvanceAtTarget(
            SwccgGame game, String playerId,
            PhysicalCard targetLocation,
            FlipLocationAlternative prerequisite) {
        if (game == null || targetLocation == null
                || prerequisite == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        GameState gameState = game.getGameState();
        if (!locationMatchesAlternative(
                    gameState, game, playerId,
                    targetLocation, prerequisite)
                || relationSatisfiedAt(
                    game, playerId, playerId,
                    targetLocation, prerequisite.relation,
                    prerequisite.actorFilterKey,
                    prerequisite.includeExcludedFromBattle,
                    prerequisite.spotOverride)) {
            return false;
        }
        if ("controlWith".equals(
                    prerequisite.relation)) {
            Map<com.gempukku.swccgo.common.InactiveReason, Boolean>
                    overrides = resolveSpotOverride(
                        prerequisite.includeExcludedFromBattle,
                        prerequisite.spotOverride);
            String opponent =
                    gameState.getOpponent(playerId);
            if (opponent != null
                    && !game.getModifiersQuerying()
                        .controlsLocation(
                            gameState, targetLocation,
                            playerId, overrides)
                    && game.getModifiersQuerying()
                        .occupiesLocation(
                            gameState, targetLocation,
                            opponent, overrides)) {
                return false;
            }
        }
        int required = expectedCount(
                game, playerId, prerequisite.count);
        int qualified = countAlternativeMatches(
                game, playerId, playerId, prerequisite);
        return qualified < required;
    }

    public boolean isMissingRequiredCardDeployEnablerAt(
            SwccgGame game, String playerId,
            PhysicalCard location) {
        if (!analyzed || isFlipped || game == null
                || playerId == null || location == null
                || activeRequiredCardDeployRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        for (RequiredCardDeployRule rule
                : activeRequiredCardDeployRules) {
            FlipLocationAlternative prerequisite =
                    rule != null ? rule.prerequisite : null;
            if (!isRequiredCardDeployRuleActive(
                        game, playerId, rule)
                    || prerequisite == null
                    || isFlipLocationAlternativeSatisfied(
                        game, playerId, prerequisite)
                    || !locationMatchesAlternative(
                        game.getGameState(), game, playerId,
                        location, prerequisite)) {
                continue;
            }
            if (("controlWith".equals(
                        prerequisite.relation)
                    || "occupyWith".equals(
                        prerequisite.relation))
                    && !hasMatchingActorAtLocation(
                        game, playerId, location,
                        prerequisite.actorFilterKey,
                        prerequisite.includeExcludedFromBattle,
                        true)) {
                continue;
            }
            String controller = resolveController(
                    game.getGameState(), playerId,
                    prerequisite.controller);
            boolean relationHere = relationSatisfiedAt(
                    game, playerId, controller, location,
                    prerequisite.relation,
                    prerequisite.actorFilterKey,
                    prerequisite.includeExcludedFromBattle,
                    prerequisite.spotOverride);
            if (isUpperBound(prerequisite.count)
                    ? relationHere : !relationHere) {
                return true;
            }
        }
        return false;
    }

    public boolean hasActiveRequiredCardDeployActorRule(
            SwccgGame game, String playerId) {
        if (!analyzed || isFlipped
                || activeRequiredCardDeployRules == null) {
            return false;
        }
        for (RequiredCardDeployRule rule
                : activeRequiredCardDeployRules) {
            if (rule != null && rule.prerequisite != null
                    && rule.prerequisite.actorFilterKey != null
                    && isRequiredCardDeployRuleActive(
                        game, playerId, rule)) {
                return true;
            }
        }
        return false;
    }

    private boolean isRequiredCardDeployRuleActive(
            SwccgGame game, String playerId,
            RequiredCardDeployRule rule) {
        if (rule == null || rule.requiredCardFilterKey == null
                || rule.blueprintIds == null
                || rule.blueprintIds.isEmpty()
                || game == null || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        com.gempukku.swccgo.filters.Filter cardFilter =
                resolveFilter(rule.requiredCardFilterKey);
        if (cardFilter == null) return false;
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents != null) {
            for (PhysicalCard card : permanents) {
                if (card != null
                        && isActiveForSpot(game, card, true)
                        && cardFilter.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), card)) {
                    return false;
                }
            }
        }
        List<PhysicalCard> hand =
                game.getGameState().getHand(playerId);
        List<PhysicalCard> reserve =
                game.getGameState().getReserveDeck(playerId);
        boolean readyInHand = containsReadyRequiredCard(
                game, playerId, hand, cardFilter);
        boolean readyInReserve = containsReadyRequiredCard(
                game, playerId, reserve, cardFilter);
        boolean matchingInHand = containsRequiredCard(
                game, playerId, hand, cardFilter);
        List<PhysicalCard> preferredCards = readyInHand
                ? hand
                : readyInReserve ? reserve
                : matchingInHand ? hand : reserve;
        boolean requireReady = readyInHand || readyInReserve;
        if (preferredCards == null) return false;
        for (PhysicalCard card : preferredCards) {
            if (card != null
                    && playerId.equals(card.getOwner())
                    && rule.blueprintIds.contains(
                        card.getBlueprintId(true))
                    && (!requireReady
                        || isRequiredOnTableCardPullRouteReady(
                            game, playerId, card))) {
                return true;
            }
        }
        return false;
    }

    private boolean containsRequiredCard(
            SwccgGame game, String playerId,
            List<PhysicalCard> cards,
            com.gempukku.swccgo.filters.Filter cardFilter) {
        if (cards == null || cardFilter == null) return false;
        for (PhysicalCard card : cards) {
            if (card != null && playerId.equals(card.getOwner())
                    && cardFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), card)) {
                return true;
            }
        }
        return false;
    }

    private boolean containsReadyRequiredCard(
            SwccgGame game, String playerId,
            List<PhysicalCard> cards,
            com.gempukku.swccgo.filters.Filter cardFilter) {
        if (cards == null || cardFilter == null) return false;
        for (PhysicalCard card : cards) {
            if (card != null && playerId.equals(card.getOwner())
                    && cardFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), card)
                    && isRequiredOnTableCardPullRouteReady(
                        game, playerId, card)) {
                return true;
            }
        }
        return false;
    }

    /**
     * True when the virtual Hunt Down objective's exact once-per-deploy-phase
     * action has a legal Cloud City or Malachor battleground site in Reserve.
     */
    public boolean hasVirtualHuntDownLocationDownloadInReserve(
            SwccgGame game, String playerId) {
        if (!analyzed || isFlipped || !isVirtualHuntDownObjective()
                || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }

        try {
            GameState gameState = game.getGameState();
            PhysicalCard objective = findOurObjective(
                    gameState, playerId);
            if (objective == null) return false;
            List<PhysicalCard> reserve = gameState.getReserveDeck(playerId);
            if (reserve == null) return false;
            com.gempukku.swccgo.filters.Filter legalDownload = Filters.and(
                    Filters.battleground_site,
                    Filters.or(
                            Filters.partOfSystem(
                                    com.gempukku.swccgo.common.Title.Malachor),
                            Filters.icon(
                                    com.gempukku.swccgo.common.Icon.CLOUD_CITY)),
                    Filters.deployable(objective, null, false, 0.0f));
            for (PhysicalCard candidate : reserve) {
                if (candidate != null && legalDownload.accepts(
                        gameState, game.getModifiersQuerying(), candidate)) {
                    return true;
                }
            }
        } catch (Exception e) {
            LOG.debug("Virtual Hunt Down location download assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    /**
     * True only when the exact Vader's Castle source has a Vader in Reserve
     * that the engine currently considers deployable to that Castle at
     * ordinary cost.
     */
    public boolean hasLegalVaderCastleDeployInReserve(
            SwccgGame game, String playerId) {
        return hasLegalVaderCastleDeployInReserve(
                game, playerId, false);
    }

    /**
     * Uses the exact minimum prospective Castle move cost as extra deploy
     * reserve for the same Vader candidate.
     */
    public boolean hasVaderCastleDeployWithMoveReserve(
            SwccgGame game, String playerId) {
        return hasLegalVaderCastleDeployInReserve(
                game, playerId, true);
    }

    public record VaderCastleRouteAssessment(
            PhysicalCard mover,
            PhysicalCard origin,
            PhysicalCard destination,
            boolean outbound,
            boolean objectiveAdvance,
            boolean formationSafe,
            boolean returnHeld,
            int forceCost) {
        public boolean objectiveSafe() {
            return objectiveAdvance && formationSafe;
        }

        public boolean admissible() {
            return formationSafe && (outbound || !returnHeld);
        }
    }

    public record VaderCastleOutboundAssessment(
            boolean safeRoute,
            int minimumForce) {
        private static VaderCastleOutboundAssessment none() {
            return new VaderCastleOutboundAssessment(false, 0);
        }
    }

    public record VaderCastleDeployCandidateAssessment(
            boolean found,
            boolean legalDeploy,
            boolean preservesMoveCost) {
        private static VaderCastleDeployCandidateAssessment none() {
            return new VaderCastleDeployCandidateAssessment(
                    false, false, false);
        }
    }

    public record DockingBayTransitRouteAssessment(
            PhysicalCard mover,
            PhysicalCard origin,
            PhysicalCard destination,
            boolean objectiveAdvance,
            boolean blockerChase,
            boolean objectiveHold,
            String safetyVeto) {
        public boolean admissible() {
            return !objectiveHold && safetyVeto == null;
        }

        public boolean objectiveSafe() {
            return admissible()
                    && (objectiveAdvance || blockerChase);
        }
    }

    /**
     * Mirrors the stock DockingBayTransitAction candidate and destination
     * laws, then overlays the active runtime-actor hold and formation safety.
     */
    public List<DockingBayTransitRouteAssessment>
            assessDockingBayTransitRoutes(
                    SwccgGame game, String playerId,
                    PhysicalCard sourceDockingBay) {
        if (!analyzed || isFlipped
                || !hasPreFlipRuntimeActorRule()
                || game == null || playerId == null
                || sourceDockingBay == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return List.of();
        }
        try {
            GameState gameState = game.getGameState();
            if (!Filters.docking_bay.accepts(
                    gameState, game.getModifiersQuerying(),
                    sourceDockingBay)) {
                return List.of();
            }
            com.gempukku.swccgo.filters.Filter atFilter =
                    Filters.and(
                        Filters.your(playerId),
                        Filters.hasNotPerformedRegularMove,
                        Filters.or(
                            Filters.character,
                            Filters.vehicle,
                            Filters.movesLikeCharacter),
                        Filters.atLocation(sourceDockingBay));
            com.gempukku.swccgo.filters.Filter attachedArtilleryFilter =
                    Filters.and(
                        Filters.your(playerId),
                        Filters.hasNotPerformedRegularMove,
                        Filters.artillery_weapon_that_may_use_db_transit,
                        Filters.attachedTo(sourceDockingBay));
            com.gempukku.swccgo.filters.Filter moverFilter =
                    Filters.or(
                        atFilter, attachedArtilleryFilter);
            if (playerId.equals(
                    gameState.getCurrentPlayerId())) {
                moverFilter = Filters.and(
                        moverFilter,
                        Filters.not(Filters.or(
                            Filters.undercover_spy,
                            Filters
                                .deploysAndMovesLikeUndercoverSpy)));
            } else {
                moverFilter = Filters.and(
                        moverFilter,
                        Filters.or(
                            Filters.undercover_spy,
                            Filters
                                .deploysAndMovesLikeUndercoverSpy));
            }
            Collection<PhysicalCard> movers =
                    Filters.filterActive(
                        game, null,
                        SpotOverride.INCLUDE_UNDERCOVER,
                        moverFilter);
            List<PhysicalCard> destinations =
                    gameState.getTopLocations();
            if (movers == null || destinations == null) {
                return List.of();
            }
            String opponent =
                    gameState.getOpponent(playerId);
            List<DockingBayTransitRouteAssessment> routes =
                    new ArrayList<>();
            for (PhysicalCard mover : movers) {
                com.gempukku.swccgo.filters.Filter
                        legalDestination =
                        Filters.canMoveToUsingDockingBayTransit(
                                mover, false, 0.0f);
                for (PhysicalCard destination : destinations) {
                    if (destination == null
                            || !Filters.other(
                                sourceDockingBay).accepts(
                                    gameState,
                                    game.getModifiersQuerying(),
                                    destination)
                            || !Filters.docking_bay.accepts(
                                gameState,
                                game.getModifiersQuerying(),
                                destination)
                            || !legalDestination.accepts(
                                gameState,
                                game.getModifiersQuerying(),
                                destination)) {
                        continue;
                    }
                    boolean objectiveAdvance =
                            advancesPreFlipActorAtRuntimeLocation(
                                game, playerId, mover,
                                destination);
                    boolean preservesActor =
                            qualifiesPreFlipRuntimeActorAtLocation(
                                game, playerId, mover,
                                destination);
                    boolean blockerChase =
                            !objectiveAdvance
                            && preservesActor
                            && isPreFlipGlobalBlockerAt(
                                game, playerId,
                                destination);
                    boolean objectiveHold =
                            classifyGateFormationPieceIfRemoved(
                                game, playerId, mover)
                                == FlipGateFormationRole
                                    .LAST_REQUIRED_ACTOR
                            && !preservesActor
                            && !isRetreatableAt(
                                game, playerId, opponent,
                                sourceDockingBay);
                    String safetyVeto =
                            FormationSafety.vetoMoveDestination(
                                game, gameState, playerId,
                                mover, destination);
                    if (safetyVeto == null) {
                        safetyVeto =
                                FormationSafety.vetoMoveOrigin(
                                    game, gameState,
                                    playerId, mover,
                                    sourceDockingBay);
                    }
                    routes.add(
                        new DockingBayTransitRouteAssessment(
                            mover, sourceDockingBay,
                            destination,
                            objectiveAdvance,
                            blockerChase,
                            objectiveHold,
                            safetyVeto));
                }
            }
            return List.copyOf(routes);
        } catch (Exception e) {
            LOG.debug(
                    "Objective docking-bay transit assessment failed: {}",
                    e.getMessage());
            return List.of();
        }
    }

    /**
     * Candidate-specific child fact for Castle's Reserve Deck download.
     * Blueprint binding is exact because that mandatory prompt exposes
     * blueprint choices rather than physical card ids.
     */
    public VaderCastleDeployCandidateAssessment
            assessVaderCastleDeployCandidate(
                    SwccgGame game, String playerId,
                    String blueprintId) {
        if (!analyzed || !isHuntDownV()
                || game == null || playerId == null
                || blueprintId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return VaderCastleDeployCandidateAssessment.none();
        }
        try {
            PhysicalCard castle =
                    findActiveVaderCastle(game, playerId);
            List<PhysicalCard> reserve =
                    game.getGameState().getReserveDeck(playerId);
            if (castle == null || reserve == null) {
                return VaderCastleDeployCandidateAssessment.none();
            }
            boolean found = false;
            boolean legal = false;
            boolean preserves = false;
            for (PhysicalCard candidate : reserve) {
                if (candidate == null
                        || !blueprintId.equals(
                            candidate.getBlueprintId(true))
                        || !Filters.Vader.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(),
                            candidate)) {
                    continue;
                }
                found = true;
                legal |= vaderCastleDeployCandidateLegal(
                        game, playerId, candidate,
                        castle, false);
                preserves |= vaderCastleDeployCandidateLegal(
                        game, playerId, candidate,
                        castle, true);
            }
            return new VaderCastleDeployCandidateAssessment(
                    found, legal, preserves);
        } catch (Exception e) {
            LOG.debug(
                    "Vader's Castle deploy candidate assessment failed: {}",
                    e.getMessage());
            return VaderCastleDeployCandidateAssessment.none();
        }
    }

    /**
     * Returns the exact minimum Force needed for a currently legal Vader's
     * Castle outbound move that advances the active Hunt Down actor leg.
     * {@link VaderCastleOutboundAssessment#safeRoute()} distinguishes a free
     * route from no route.
     */
    public int getVaderCastleOutboundMoveReserve(
            SwccgGame game, String playerId) {
        return assessVaderCastleOutbound(
                game, playerId).minimumForce();
    }

    public boolean hasSafeVaderCastleOutboundRoute(
            SwccgGame game, String playerId) {
        return assessVaderCastleOutbound(
                game, playerId).safeRoute();
    }

    public VaderCastleOutboundAssessment assessVaderCastleOutbound(
            SwccgGame game, String playerId) {
        PhysicalCard castle = findActiveVaderCastle(game, playerId);
        if (castle == null) {
            return VaderCastleOutboundAssessment.none();
        }
        int minimumForce = Integer.MAX_VALUE;
        for (VaderCastleRouteAssessment route
                : assessVaderCastleRoutes(
                        game, playerId, castle, true)) {
            if (route.objectiveSafe()) {
                minimumForce = Math.min(
                        minimumForce, route.forceCost());
            }
        }
        return minimumForce == Integer.MAX_VALUE
                ? VaderCastleOutboundAssessment.none()
                : new VaderCastleOutboundAssessment(
                        true, minimumForce);
    }

    /**
     * Mirrors Vader's Castle's real location-text candidate set. Every
     * physical mover and destination remains separate, including duplicates.
     */
    public List<VaderCastleRouteAssessment> assessVaderCastleRoutes(
            SwccgGame game, String playerId, PhysicalCard castle,
            boolean outbound) {
        if (!analyzed || isFlipped || !isHuntDownV()
                || !hasPreFlipRuntimeActorRule()
                || game == null || playerId == null || castle == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || !playerId.equals(castle.getOwner())
                || !"209_50".equals(castle.getBlueprintId(true))
                || !isActiveForSpot(game, castle, false)) {
            return List.of();
        }
        try {
            GameState gameState = game.getGameState();
            Collection<PhysicalCard> permanents =
                    gameState.getAllPermanentCards();
            List<PhysicalCard> locations =
                    gameState.getLocationsInOrder();
            if (permanents == null || locations == null) {
                return List.of();
            }
            List<VaderCastleRouteAssessment> routes =
                    new ArrayList<>();
            String opponent = gameState.getOpponent(playerId);
            for (PhysicalCard mover : permanents) {
                if (mover == null
                        || !playerId.equals(mover.getOwner())
                        || !gameState.isCardInPlayActive(
                                mover,
                                false, true, false, false,
                                false, false, false, false)
                        || !Filters.Vader.accepts(
                                gameState,
                                game.getModifiersQuerying(),
                                mover)
                        || !Filters.hasNotPerformedRegularMove.accepts(
                                gameState,
                                game.getModifiersQuerying(),
                                mover)) {
                    continue;
                }
                PhysicalCard origin =
                        game.getModifiersQuerying()
                            .getLocationThatCardIsPresentAt(
                                    gameState, mover);
                if (origin == null
                        || outbound
                            != samePhysicalLocation(origin, castle)) {
                    continue;
                }
                if (!outbound
                        && (!isActiveForSpot(game, origin, false)
                            || !Filters.battleground_site.accepts(
                                gameState,
                                game.getModifiersQuerying(),
                                origin))) {
                    continue;
                }

                com.gempukku.swccgo.filters.Filter legalDestination =
                        Filters.canMoveToUsingLocationText(
                                mover, false, 1.0f, 0.0f);
                for (PhysicalCard destination : locations) {
                    if (destination == null
                            || !isActiveForSpot(
                                    game, destination, false)
                            || outbound
                                && (samePhysicalLocation(
                                        destination, castle)
                                    || !Filters.battleground_site
                                        .accepts(
                                            gameState,
                                            game.getModifiersQuerying(),
                                            destination))
                            || !outbound
                                && !samePhysicalLocation(
                                        destination, castle)
                            || !legalDestination.accepts(
                                gameState,
                                game.getModifiersQuerying(),
                                destination)) {
                        continue;
                    }

                    String veto =
                            FormationSafety.vetoMoveDestination(
                                game, gameState, playerId,
                                mover, destination);
                    if (veto == null) {
                        veto = FormationSafety.vetoMoveOrigin(
                                game, gameState, playerId,
                                mover, origin);
                    }
                    boolean objectiveAdvance = outbound
                            && advancesPreFlipActorAtRuntimeLocation(
                                game, playerId, mover, destination);
                    boolean returnHeld = !outbound
                            && classifyGateFormationPieceIfRemoved(
                                game, playerId, mover)
                                == FlipGateFormationRole
                                    .LAST_REQUIRED_ACTOR
                            && !isRetreatableAt(
                                game, playerId, opponent, origin);
                    float rawCost =
                            game.getModifiersQuerying()
                                .getMoveUsingLocationTextCost(
                                    gameState, mover, origin,
                                    destination, 1.0f, 0.0f);
                    routes.add(new VaderCastleRouteAssessment(
                            mover, origin, destination, outbound,
                            objectiveAdvance, veto == null,
                            returnHeld,
                            (int) Math.ceil(
                                    Math.max(0.0f, rawCost))));
                }
            }
            return List.copyOf(routes);
        } catch (Exception e) {
            LOG.debug(
                    "Vader's Castle route assessment failed: {}",
                    e.getMessage());
            return List.of();
        }
    }

    private PhysicalCard findActiveVaderCastle(
            SwccgGame game, String playerId) {
        if (game == null || playerId == null
                || game.getGameState() == null) {
            return null;
        }
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents == null) return null;
        for (PhysicalCard card : permanents) {
            if (card != null
                    && playerId.equals(card.getOwner())
                    && "209_50".equals(card.getBlueprintId(true))
                    && isActiveForSpot(game, card, false)) {
                return card;
            }
        }
        return null;
    }

    private boolean isRetreatableAt(
            SwccgGame game, String playerId, String opponent,
            PhysicalCard location) {
        if (opponent == null || location == null) return false;
        GameState gameState = game.getGameState();
        float friendlyPower =
                game.getModifiersQuerying()
                    .getTotalPowerAtLocation(
                        gameState, location, playerId,
                        false, false);
        float opponentPower =
                game.getModifiersQuerying()
                    .getTotalPowerAtLocation(
                        gameState, location, opponent,
                        false, false)
                + FormationSafety.weaponBonusAt(
                        gameState, location, opponent);
        return opponentPower > friendlyPower + 6.0f;
    }

    private boolean hasLegalVaderCastleDeployInReserve(
            SwccgGame game, String playerId, boolean reserveCastleMove) {
        if (!analyzed || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            GameState gameState = game.getGameState();
            PhysicalCard castle = null;
            Collection<PhysicalCard> permanents =
                    gameState.getAllPermanentCards();
            if (permanents == null) return false;
            for (PhysicalCard card : permanents) {
                if (card == null || !playerId.equals(card.getOwner())
                        || !"209_50".equals(card.getBlueprintId(true))
                        || !isActiveForSpot(game, card, false)) {
                    continue;
                }
                castle = card;
                break;
            }
            if (castle == null) return false;

            List<PhysicalCard> reserve =
                    gameState.getReserveDeck(playerId);
            if (reserve == null) return false;
            for (PhysicalCard candidate : reserve) {
                if (vaderCastleDeployCandidateLegal(
                        game, playerId, candidate,
                        castle, reserveCastleMove)) {
                    return true;
                }
            }
        } catch (Exception e) {
            LOG.debug("Vader's Castle deploy assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    private boolean vaderCastleDeployCandidateLegal(
            SwccgGame game, String playerId, PhysicalCard candidate,
            PhysicalCard castle, boolean reserveCastleMove) {
        if (candidate == null || !Filters.Vader.accepts(
                game.getGameState(),
                game.getModifiersQuerying(),
                candidate)) {
            return false;
        }
        int moveReserve = reserveCastleMove
                ? prospectiveVaderCastleOutboundMoveReserve(
                        game, playerId, candidate, castle)
                : 0;
        if (reserveCastleMove && moveReserve < 0) {
            return false;
        }
        return Filters.deployableToLocation(
                castle, Filters.here(castle),
                false, moveReserve).accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        candidate);
    }

    /**
     * Minimum ceiled engine cost for this Reserve Vader to move from Castle
     * to an active battleground site after deployment. Returns -1 when no
     * source-valid route exists.
     */
    private int prospectiveVaderCastleOutboundMoveReserve(
            SwccgGame game, String playerId, PhysicalCard candidate,
            PhysicalCard castle) {
        GameState gameState = game.getGameState();
        if (game.getModifiersQuerying().mayNotMove(
                gameState, candidate)) {
            return -1;
        }
        List<PhysicalCard> locations =
                gameState.getLocationsInOrder();
        if (locations == null) return -1;
        int minimumForce = Integer.MAX_VALUE;
        com.gempukku.swccgo.filters.Filter validMoveTarget =
                candidate.getBlueprint().getValidMoveTargetFilter(
                        playerId, game, candidate, false);
        for (PhysicalCard destination : locations) {
            if (destination == null
                    || samePhysicalLocation(destination, castle)
                    || !isActiveForSpot(game, destination, false)
                    || !Filters.battleground_site.accepts(
                            gameState,
                            game.getModifiersQuerying(),
                            destination)
                    || !validMoveTarget.accepts(
                            gameState,
                            game.getModifiersQuerying(),
                            destination)
                    || game.getModifiersQuerying()
                        .mayNotMoveFromLocationToLocationUsingLocationText(
                            gameState, candidate, castle,
                            destination)) {
                continue;
            }
            float rawCost = game.getModifiersQuerying()
                    .getMoveUsingLocationTextCost(
                            gameState, candidate, castle,
                            destination, 1.0f, 0.0f);
            minimumForce = Math.min(
                    minimumForce,
                    (int) Math.ceil(Math.max(0.0f, rawCost)));
        }
        return minimumForce == Integer.MAX_VALUE
                ? -1 : minimumForce;
    }

    /**
     * True when classic Hunt Down's exact move-phase recall action has at
     * least one legal Vader target whose removal does not dismantle the sole
     * actor currently satisfying the runtime battleground leg.
     */
    public boolean hasSafeClassicHuntDownVaderRecallTarget(
            SwccgGame game, String playerId) {
        return assessClassicHuntDownVaderRecall(
                game, playerId).safeTarget();
    }

    /**
     * The virtual objective offers a post-flip once-per-game Vader recall.
     * Its child target is any active Vader. A target is safe only while
     * another active Vader remains on table to keep the back side stable.
     */
    public boolean hasSafeVirtualHuntDownVaderRecallTarget(
            SwccgGame game, String playerId) {
        if (!analyzed || !isFlipped || !isVirtualHuntDownObjective()
                || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            GameState gameState = game.getGameState();
            Collection<PhysicalCard> permanents =
                    gameState.getAllPermanentCards();
            if (permanents == null) return false;
            for (PhysicalCard candidate : permanents) {
                HuntDownRecallTargetAssessment assessment =
                        assessVirtualHuntDownVaderRecallTarget(
                                game, playerId, candidate);
                if (assessment.applies()
                        && assessment.safeTarget()) {
                    return true;
                }
            }
        } catch (Exception e) {
            LOG.debug("Virtual Hunt Down recall assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    public record HuntDownRecallTargetAssessment(
            boolean applies,
            boolean safeTarget,
            boolean preservesRequiredVader,
            boolean remoteBlockerChase) {
        private static HuntDownRecallTargetAssessment none() {
            return new HuntDownRecallTargetAssessment(
                    false, false, false, false);
        }
    }

    /**
     * Candidate-level classic recall fact. The source can target any active
     * Vader at a location the player controls. Removing the sole battleground
     * Vader is allowed only when that exact Vader can be redeployed to chase a
     * remote Jedi or Luke blocker.
     */
    public HuntDownRecallTargetAssessment
            assessClassicHuntDownVaderRecallTarget(
                    SwccgGame game, String playerId,
                    PhysicalCard candidate) {
        if (!analyzed || isFlipped || !isClassicHuntDownObjective()
                || game == null || playerId == null || candidate == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return HuntDownRecallTargetAssessment.none();
        }
        try {
            GameState gameState = game.getGameState();
            com.gempukku.swccgo.filters.Filter legalTarget =
                    Filters.and(
                            Filters.Vader,
                            Filters.at(Filters.controls(playerId)));
            if (!isActiveForSpot(game, candidate, false)
                    || !legalTarget.accepts(
                            gameState, game.getModifiersQuerying(),
                            candidate)) {
                return HuntDownRecallTargetAssessment.none();
            }

            boolean ownedByPlayer =
                    playerId.equals(candidate.getOwner());
            boolean preservesRequiredVader =
                    ownedByPlayer
                    && classifyGateFormationPieceIfRemoved(
                            game, playerId, candidate)
                        != FlipGateFormationRole.LAST_REQUIRED_ACTOR;
            boolean remoteBlocker =
                    ownedByPlayer
                    && hasRemoteClassicHuntDownBlocker(
                            game, playerId, candidate);
            return new HuntDownRecallTargetAssessment(
                    true,
                    preservesRequiredVader || remoteBlocker,
                    preservesRequiredVader,
                    remoteBlocker);
        } catch (Exception e) {
            LOG.debug(
                    "Classic Hunt Down recall target assessment failed: {}",
                    e.getMessage());
            return HuntDownRecallTargetAssessment.none();
        }
    }

    /**
     * Candidate-level virtual recall fact. The real child target is any active
     * Vader, not only one at the controlled site that exposed the trigger. It
     * is safe exactly when another active Vader remains on table.
     */
    public HuntDownRecallTargetAssessment
            assessVirtualHuntDownVaderRecallTarget(
                    SwccgGame game, String playerId,
                    PhysicalCard candidate) {
        if (!analyzed || !isFlipped || !isVirtualHuntDownObjective()
                || game == null || playerId == null || candidate == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return HuntDownRecallTargetAssessment.none();
        }
        try {
            GameState gameState = game.getGameState();
            if (!isActiveForSpot(game, candidate, false)
                    || !Filters.Vader.accepts(
                            gameState, game.getModifiersQuerying(),
                            candidate)) {
                return HuntDownRecallTargetAssessment.none();
            }
            if (!playerId.equals(candidate.getOwner())) {
                return new HuntDownRecallTargetAssessment(
                        true, false, false, false);
            }
            Collection<PhysicalCard> permanents =
                    gameState.getAllPermanentCards();
            if (permanents == null) {
                return new HuntDownRecallTargetAssessment(
                        true, false, false, false);
            }
            for (PhysicalCard other : permanents) {
                if (other != null
                        && !samePhysicalLocation(other, candidate)
                        && isActiveForSpot(game, other, false)
                        && Filters.Vader.accepts(
                            gameState,
                            game.getModifiersQuerying(), other)) {
                    return new HuntDownRecallTargetAssessment(
                            true, true, true, false);
                }
            }
            return new HuntDownRecallTargetAssessment(
                    true, false, false, false);
        } catch (Exception e) {
            LOG.debug(
                    "Virtual Hunt Down recall target assessment failed: {}",
                    e.getMessage());
            return HuntDownRecallTargetAssessment.none();
        }
    }

    public record ClassicHuntDownRecallAssessment(
            boolean safeTarget,
            boolean remoteJediOrLukeBlocker) {
        private static ClassicHuntDownRecallAssessment none() {
            return new ClassicHuntDownRecallAssessment(false, false);
        }
    }

    public ClassicHuntDownRecallAssessment
            assessClassicHuntDownVaderRecall(
                    SwccgGame game, String playerId) {
        if (!analyzed || isFlipped || !isClassicHuntDownObjective()
                || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return ClassicHuntDownRecallAssessment.none();
        }
        try {
            GameState gameState = game.getGameState();
            Collection<PhysicalCard> permanents =
                    gameState.getAllPermanentCards();
            if (permanents == null) {
                return ClassicHuntDownRecallAssessment.none();
            }
            for (PhysicalCard candidate : permanents) {
                HuntDownRecallTargetAssessment assessment =
                        assessClassicHuntDownVaderRecallTarget(
                                game, playerId, candidate);
                if (assessment.applies()
                        && assessment.safeTarget()) {
                    return new ClassicHuntDownRecallAssessment(
                            true,
                            assessment.remoteBlockerChase());
                }
            }
            return ClassicHuntDownRecallAssessment.none();
        } catch (Exception e) {
            LOG.debug("Classic Hunt Down recall assessment failed: {}",
                    e.getMessage());
        }
        return ClassicHuntDownRecallAssessment.none();
    }

    private boolean hasRemoteClassicHuntDownBlocker(
            SwccgGame game, String playerId,
            PhysicalCard recallTarget) {
        GameState gameState = game.getGameState();
        Collection<PhysicalCard> permanents =
                gameState.getAllPermanentCards();
        if (permanents == null) return false;
        PhysicalCard targetLocation =
                game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                            gameState, recallTarget);
        String opponent = gameState.getOpponent(playerId);
        com.gempukku.swccgo.filters.Filter blocker =
                Filters.or(Filters.Jedi, Filters.Luke);
        for (PhysicalCard card : permanents) {
            if (card == null || opponent == null
                    || !opponent.equals(card.getOwner())
                    || !isActiveForSpot(game, card, true)
                    || !blocker.accepts(
                        gameState,
                        game.getModifiersQuerying(), card)) {
                continue;
            }
            PhysicalCard blockerLocation =
                    game.getModifiersQuerying()
                        .getLocationThatCardIsAt(
                                gameState, card);
            if (!samePhysicalLocation(
                        targetLocation, blockerLocation)
                    && Filters.battleground_site.accepts(
                        gameState,
                        game.getModifiersQuerying(),
                        blockerLocation)) {
                return true;
            }
        }
        return false;
    }

    private boolean hasOtherMatchingActorInHand(
            SwccgGame game,
            String playerId,
            PhysicalCard candidate,
            com.gempukku.swccgo.filters.Filter actorFilter) {
        GameState gameState = game.getGameState();
        if (gameState == null || actorFilter == null) return false;
        List<PhysicalCard> hand = gameState.getHand(playerId);
        if (hand == null) return false;
        for (PhysicalCard card : hand) {
            if (card != null && !samePhysicalLocation(card, candidate)
                    && playerId.equals(card.getOwner())
                    && actorFilter.accepts(
                            gameState, game.getModifiersQuerying(),
                            card)) {
                return true;
            }
        }
        return false;
    }

    private boolean hasOtherReadyOnTableRequirementInHand(
            SwccgGame game,
            String playerId,
            PhysicalCard candidate,
            com.gempukku.swccgo.filters.Filter actorFilter) {
        GameState gameState = game.getGameState();
        if (gameState == null || actorFilter == null) return false;
        List<PhysicalCard> hand = gameState.getHand(playerId);
        if (hand == null) return false;
        for (PhysicalCard card : hand) {
            if (card != null && card != candidate
                    && playerId.equals(card.getOwner())
                    && actorFilter.accepts(
                        gameState, game.getModifiersQuerying(), card)
                    && isRequiredOnTableCardPullRouteReady(
                        game, playerId, card)) {
                return true;
            }
        }
        return false;
    }

    private boolean hasOtherMatchingActorOnTable(
            SwccgGame game,
            String playerId,
            PhysicalCard candidate,
            com.gempukku.swccgo.filters.Filter actorFilter,
            Boolean includeExcludedFromBattle) {
        GameState gameState = game.getGameState();
        Collection<PhysicalCard> permanents =
                gameState != null ? gameState.getAllPermanentCards() : null;
        if (permanents == null || actorFilter == null) return false;
        for (PhysicalCard card : permanents) {
            if (card == null || samePhysicalLocation(card, candidate)
                    || !playerId.equals(card.getOwner())
                    || !isActiveForSpot(
                            game, card, includeExcludedFromBattle)
                    || !actorFilter.accepts(
                            gameState, game.getModifiersQuerying(),
                            card)) {
                continue;
            }
            return true;
        }
        return false;
    }

    /**
     * A count-one actor is already actionable only when it is in play on a
     * site route to the exact gate. A matching pilot aboard a starship or an
     * actor stranded in unrelated geography must not suppress another pull.
     */
    private boolean hasOtherMatchingActorOnPreFlipRoute(
            SwccgGame game,
            String playerId,
            PhysicalCard candidate,
            com.gempukku.swccgo.filters.Filter actorFilter,
            Boolean includeExcludedFromBattle) {
        GameState gameState = game.getGameState();
        if (gameState == null || actorFilter == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        List<PhysicalCard> locations = gameState.getLocationsInOrder();
        Collection<PhysicalCard> permanents =
                gameState.getAllPermanentCards();
        if (locations == null || permanents == null) return false;

        for (PhysicalCard gate : locations) {
            if (gate == null || !isFlipGateLocation(
                    game, playerId, gate)) {
                continue;
            }
            for (PhysicalCard card : permanents) {
                if (card == null || samePhysicalLocation(card, candidate)
                        || !playerId.equals(card.getOwner())
                        || !isActiveForSpot(
                                game, card,
                                includeExcludedFromBattle)
                        || !actorFilter.accepts(
                                gameState, game.getModifiersQuerying(),
                                card)) {
                    continue;
                }
                PhysicalCard actorLocation =
                        game.getModifiersQuerying()
                                .getLocationThatCardIsPresentAt(
                                        gameState, card);
                if (samePhysicalLocation(actorLocation, gate)) {
                    return true;
                }
                Integer distance = actorLocation != null
                        ? game.getModifiersQuerying()
                                .getDistanceBetweenSites(
                                        gameState, actorLocation, gate)
                        : null;
                if (distance != null && distance > 0) return true;
            }
        }
        return false;
    }

    /**
     * True when this typed candidate deployed to this exact location would add
     * one qualifying location to an unmet counted pre-flip alternative.
     */
    public boolean advancesPreFlipRequirementAt(
            SwccgGame game, String playerId, PhysicalCard candidate,
            PhysicalCard location) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || candidate == null || location == null
                || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        if (advancesShieldRoutePackageAt(
                game, playerId, candidate, location)) {
            return true;
        }
        if (advancesFirstOrderReignsChaseShipRouteAt(
                game, playerId, candidate, location)) {
            return true;
        }
        if (advancesOldAlliesFalconRouteAt(
                game, playerId, candidate, location)) {
            return true;
        }
        if (advancesOldAlliesGroundRouteAt(
                game, playerId, candidate, location)) {
            return true;
        }
        if (isISBOperations
                && isPreferredIsbOnTableAgentCandidate(
                    game, playerId, candidate)) {
            return true;
        }
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule) || isRuleSatisfied(
                    game, playerId, rule)) {
                continue;
            }
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (advancesAlternativeAt(
                        game, playerId, candidate, location, alternative)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * True when an owned actor would advance a structured actor-at-location
     * alternative such as Vader at any runtime battleground site.
     */
    public boolean advancesPreFlipActorAtRuntimeLocation(
            SwccgGame game, String playerId, PhysicalCard candidate,
            PhysicalCard location) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || candidate == null || location == null
                || !playerId.equals(candidate.getOwner())
                || activeFlipLocationRules == null) {
            return false;
        }
        PhysicalCard routeLocation =
                isIWantThatMapObjectiveFamily()
                    ? iWantThatMapRouteLocation(game, location)
                    : location;
        if (routeLocation == null) return false;
        if (advancesFirstOrderReignsChaseShipRouteAt(
                game, playerId, candidate, location)) {
            return true;
        }
        if (isRalltiirOperationsFamily()) {
            boolean movingProtectedPiece = candidate.getZone() != null
                    && candidate.getZone().isInPlay()
                    && classifyGateFormationPieceIfRemoved(
                        game, playerId, candidate)
                        != FlipGateFormationRole.NONE;
            if (movingProtectedPiece) return false;
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (!isActivePreFlipRule(rule)
                        || isRuleSatisfied(game, playerId, rule)) {
                    continue;
                }
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if (isRalltiirControlWithAlternative(alternative)
                            && advancesAlternativeAt(
                                game, playerId, candidate,
                                location, alternative)) {
                        return true;
                    }
                }
            }
            return false;
        }
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)
                    || isRuleSatisfied(game, playerId, rule)) {
                continue;
            }
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (isActorToRuntimeLocationAlternative(alternative)
                        && (isIWantThatMapObjectiveFamily()
                            ? iWantThatMapCandidateAddsQualifiedBattleground(
                                game, playerId, candidate,
                                routeLocation, alternative)
                            : advancesAlternativeAt(
                                game, playerId, candidate,
                                routeLocation, alternative)
                            || isAgentsOfBlackSunObjectiveFamily()
                                && !isFlipLocationAlternativeSatisfied(
                                    game, playerId, alternative)
                                && movedGroupCanSatisfyAlternativeAt(
                                    game, playerId, candidate,
                                    routeLocation, alternative,
                                    resolveFilter(
                                        alternative.actorFilterKey)))) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * True when this owned presence source would add one exact location to an
     * unmet plain control or occupy leg. This is deliberately separate from
     * actor-filter routes so generic bodies are never mistaken for a named
     * objective actor.
     */
    public boolean advancesPreFlipPlainPresenceAtRequiredLocation(
            SwccgGame game, String playerId, PhysicalCard candidate,
            PhysicalCard location) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || candidate == null || location == null
                || !playerId.equals(candidate.getOwner())
                || activeFlipLocationRules == null) {
            return false;
        }
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)
                    || isRuleSatisfied(game, playerId, rule)) {
                continue;
            }
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (isPlainSelfPresenceAlternative(alternative)
                        && advancesAlternativeAt(
                                game, playerId, candidate,
                                location, alternative)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * True when the candidate satisfies the typed actor-at-runtime-location
     * alternative at the supplied location. Unlike the advancement query,
     * this remains true when another actor already satisfies that leg, which
     * lets movement preserve a completed leg instead of freezing its actor.
     */
    public boolean qualifiesPreFlipRuntimeActorAtLocation(
            SwccgGame game, String playerId, PhysicalCard candidate,
            PhysicalCard location) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || candidate == null || location == null
                || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        if (isFirstOrderReignsChaseShipCandidate(
                    game, playerId, candidate)
                && samePhysicalLocation(
                    getFirstOrderReignsTrackedFleetHostSystem(
                        game, playerId),
                    location)) {
            return true;
        }
        GameState gameState = game.getGameState();
        PhysicalCard routeLocation =
                isIWantThatMapObjectiveFamily()
                    ? iWantThatMapRouteLocation(game, location)
                    : location;
        if (routeLocation == null) return false;
        if (isRalltiirOperationsFamily()) {
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (!isActivePreFlipRule(rule)) continue;
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if (!isRalltiirControlWithAlternative(alternative)
                            || !locationMatchesAlternative(
                                gameState, game, playerId,
                                location, alternative)) {
                        continue;
                    }
                    String controller = resolveController(
                            gameState, playerId,
                            alternative.controller);
                    if (controller != null
                            && !controller.equals(
                                candidate.getOwner())) {
                        continue;
                    }
                    if (candidate.getZone() != null
                            && candidate.getZone().isInPlay()
                            && !isActiveForSpot(
                                game, candidate,
                                alternative
                                    .includeExcludedFromBattle)) {
                        continue;
                    }
                    com.gempukku.swccgo.filters.Filter actorFilter =
                            resolveFilter(alternative.actorFilterKey);
                    return actorFilter != null
                            && actorFilter.accepts(
                                gameState,
                                game.getModifiersQuerying(), candidate);
                }
            }
            return false;
        }
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)) continue;
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (!isActorToRuntimeLocationAlternative(alternative)
                        || !locationMatchesAlternative(
                                gameState, game, playerId,
                                routeLocation, alternative)) {
                    continue;
                }
                String controller = resolveController(
                        gameState, playerId, alternative.controller);
                if (controller != null
                        && !controller.equals(candidate.getOwner())) {
                    continue;
                }
                if (candidate.getZone() != null
                        && candidate.getZone().isInPlay()
                        && !isActiveForSpot(
                                game, candidate,
                                alternative.includeExcludedFromBattle)) {
                    continue;
                }
                if (isCountedOperativeFormationAlternative(alternative)) {
                    if (candidateWouldCreateCountedOperativeFormationAt(
                            game, playerId, candidate, location,
                            alternative, controller)) {
                        return true;
                    }
                    continue;
                }
                com.gempukku.swccgo.filters.Filter actorFilter =
                        resolveFilter(alternative.actorFilterKey);
                if (actorFilter != null
                        && (actorFilter.accepts(
                                gameState,
                                game.getModifiersQuerying(), candidate)
                            || (isAgentsOfBlackSunObjectiveFamily()
                                || isIWantThatMapObjectiveFamily())
                                && movedGroupCanSatisfyAlternativeAt(
                                    game, playerId, candidate,
                                    routeLocation, alternative,
                                    actorFilter))) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean iWantThatMapCandidateAddsQualifiedBattleground(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard destination,
            FlipLocationAlternative alternative) {
        if (!isIWantThatMapObjectiveFamily()
                || !locationMatchesAlternative(
                    game.getGameState(), game, playerId,
                    destination, alternative)
                || isFlipLocationAlternativeSatisfied(
                    game, playerId, alternative)) {
            return false;
        }
        com.gempukku.swccgo.filters.Filter actorFilter =
                resolveFilter(alternative.actorFilterKey);
        boolean destinationQualifies = advancesAlternativeAt(
                game, playerId, candidate, destination, alternative)
                || movedGroupCanSatisfyAlternativeAt(
                    game, playerId, candidate, destination,
                    alternative, actorFilter);
        if (!destinationQualifies
                || candidate.getZone() == null
                || !candidate.getZone().isInPlay()) {
            return destinationQualifies;
        }
        PhysicalCard origin = actorLocationForAlternative(
                game, candidate, alternative);
        if (origin == null || samePhysicalLocation(origin, destination)
                || !locationMatchesAlternative(
                    game.getGameState(), game, playerId,
                    origin, alternative)
                || !relationSatisfiedAt(
                    game, playerId, playerId, origin,
                    alternative.relation,
                    alternative.actorFilterKey,
                    alternative.includeExcludedFromBattle,
                    alternative.spotOverride)) {
            return true;
        }
        return hasOtherMatchingActorOutsideRemovedGroup(
                game, playerId, origin, alternative,
                candidate, null);
    }

    private PhysicalCard iWantThatMapRouteLocation(
            SwccgGame game, PhysicalCard destination) {
        if (game == null || destination == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return null;
        }
        SwccgCardBlueprint blueprint = destination.getBlueprint();
        if (blueprint != null
                && blueprint.getCardCategory() == CardCategory.LOCATION) {
            return destination;
        }
        return game.getModifiersQuerying().getLocationThatCardIsAt(
                game.getGameState(), destination);
    }

    public boolean isSafePreFlipRuntimeActorLandspeedDestination(
            SwccgGame game, String playerId, PhysicalCard mover,
            PhysicalCard destination) {
        if (!qualifiesPreFlipRuntimeActorAtLocation(
                    game, playerId, mover, destination)) {
            return false;
        }
        try {
            GameState gameState = game.getGameState();
            PhysicalCard origin = game.getModifiersQuerying()
                    .getLocationThatCardIsPresentAt(
                            gameState, mover);
            if (origin == null
                    || samePhysicalLocation(origin, destination)
                    || !Filters.canMoveToUsingLandspeed(
                            playerId, mover,
                            false, false, false, 0.0f, null)
                        .accepts(
                            gameState,
                            game.getModifiersQuerying(),
                            destination)) {
                return false;
            }
            String veto = FormationSafety.vetoMoveDestination(
                    game, gameState, playerId,
                    mover, destination);
            if (veto == null) {
                veto = FormationSafety.vetoMoveOrigin(
                        game, gameState, playerId,
                        mover, origin);
            }
            return veto == null;
        } catch (Exception e) {
            LOG.debug(
                    "Objective runtime-actor landspeed destination failed: {}",
                    e.getMessage());
            return false;
        }
    }

    public boolean hasSafePreFlipRuntimeActorLandspeedDestination(
            SwccgGame game, String playerId, PhysicalCard mover) {
        if (game == null || game.getGameState() == null) return false;
        List<PhysicalCard> locations =
                game.getGameState().getLocationsInOrder();
        if (locations == null) return false;
        for (PhysicalCard destination : locations) {
            if (isSafePreFlipRuntimeActorLandspeedDestination(
                    game, playerId, mover, destination)) {
                return true;
            }
        }
        return false;
    }

    /** An ISB Route A agent remains on table after a landspeed move. */
    public boolean preservesIsbOnTableRouteAgentByMoving(
            SwccgGame game, String playerId, PhysicalCard mover) {
        if (!analyzed || !isISBOperations || isFlipped
                || game == null || playerId == null
                || mover == null || mover.getZone() == null
                || !mover.getZone().isInPlay()) {
            return false;
        }
        FlipLocationAlternative routeA =
                findIsbOnTableAgentAlternative();
        return routeA != null
                && candidateMatchesOnTableAlternative(
                    game, playerId, mover, routeA);
    }

    /**
     * Location-only fallback for a duplicate-blueprint actor whose exact
     * physical copy cannot be resolved at the child deploy prompt.
     */
    public boolean isUnmetPreFlipRuntimeActorLocation(
            SwccgGame game, String playerId, PhysicalCard location) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || location == null || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)
                    || isRuleSatisfied(game, playerId, rule)) {
                continue;
            }
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (!isActorToRuntimeLocationAlternative(alternative)
                        || !locationMatchesAlternative(
                            game.getGameState(), game, playerId,
                            location, alternative)) {
                    continue;
                }
                String controller = resolveController(
                        game.getGameState(), playerId,
                        alternative.controller);
                int required = expectedCount(
                        game, playerId, alternative.count);
                int qualified = countAlternativeMatches(
                        game, playerId, controller, alternative);
                if (qualified < required
                        && !relationSatisfiedAt(
                            game, playerId, controller, location,
                            alternative.relation,
                            alternative.actorFilterKey,
                            alternative.includeExcludedFromBattle,
                            alternative.spotOverride)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Parent deploy-action fact. It requires one engine-legal destination that
     * advances an unmet actor-at-runtime-location alternative.
     */
    public boolean hasLegalPreFlipActorLocationDestination(
            SwccgGame game, String playerId, PhysicalCard actor) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || actor == null || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            for (PhysicalCard location
                    : game.getGameState().getLocationsInOrder()) {
                if (!advancesPreFlipActorAtRuntimeLocation(
                            game, playerId, actor, location)
                        && !advancesPreFlipPlainPresenceAtRequiredLocation(
                            game, playerId, actor, location)) {
                    continue;
                }
                if (Filters.deployableToLocation(
                        actor, Filters.sameCardId(location),
                        false, 0.0f).accepts(
                                game.getGameState(),
                                game.getModifiersQuerying(), actor)) {
                    return true;
                }
            }
        } catch (Exception e) {
            LOG.debug("Objective actor-location deploy assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    /**
     * True when Castle has legal routes but every route is rejected by either
     * formation safety or the objective actor hold.
     */
    public boolean mustHoldVaderCastleRoutes(
            SwccgGame game, String playerId, PhysicalCard castle,
            boolean outbound) {
        List<VaderCastleRouteAssessment> routes =
                assessVaderCastleRoutes(
                        game, playerId, castle, outbound);
        return !routes.isEmpty()
                && routes.stream().noneMatch(
                        VaderCastleRouteAssessment::admissible);
    }

    /** Reverse-action compatibility wrapper. */
    public boolean mustHoldAllVaderCastleReturnMovers(
            SwccgGame game, String playerId, PhysicalCard castle) {
        return mustHoldVaderCastleRoutes(
                game, playerId, castle, false);
    }

    /** True when this location currently holds a global pre-flip blocker. */
    public boolean isPreFlipGlobalBlockerAt(
            SwccgGame game, String playerId, PhysicalCard location) {
        return isPreFlipGlobalBlockerAt(
                game, playerId, location, null);
    }

    /**
     * True when this location holds a blocker that can participate in the
     * current battle. Excluded blockers still prevent the flip, but battling
     * them cannot remove that blocker.
     */
    public boolean isPreFlipBattleRemovableGlobalBlockerAt(
            SwccgGame game, String playerId, PhysicalCard location) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || location == null || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        if (isRalltiirOperationsFamily()) {
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (!isActivePreFlipRule(rule)) continue;
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if (isRalltiirControlWithAlternative(alternative)
                            && isOpponentConstraintBlockingAt(
                                game, playerId, location,
                                alternative.opponentConstraint)
                            && hasOpponentBattleParticipantAt(
                                game, playerId, location)) {
                        return true;
                    }
                }
            }
        }
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)
                    || isRuleSatisfied(game, playerId, rule)) {
                continue;
            }
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (!"globalBlockerAbsent".equals(
                            alternative.scoreRole)
                        || isFlipLocationAlternativeSatisfied(
                            game, playerId, alternative)
                        || !locationMatchesAlternative(
                            game.getGameState(), game, playerId,
                            location, alternative)
                        || !hasBattleParticipantMatchingAlternativeAt(
                            game, playerId, location, alternative)) {
                    continue;
                }
                return true;
            }
        }
        return false;
    }

    private boolean hasOpponentBattleParticipantAt(
            SwccgGame game, String playerId,
            PhysicalCard location) {
        String opponent = game.getGameState().getOpponent(playerId);
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (opponent == null || permanents == null) return false;
        com.gempukku.swccgo.filters.Filter participant =
                Filters.canParticipateInBattleAt(location, playerId);
        for (PhysicalCard card : permanents) {
            if (card != null
                    && opponent.equals(card.getOwner())
                    && Filters.or(
                        Filters.character,
                        Filters.vehicle,
                        Filters.starship).accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), card)
                    && samePhysicalLocation(
                        presenceContributionLocation(game, card),
                        location)
                    && participant.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), card)) {
                return true;
            }
        }
        return false;
    }

    private boolean hasBattleParticipantMatchingAlternativeAt(
            SwccgGame game, String playerId, PhysicalCard location,
            FlipLocationAlternative alternative) {
        GameState gameState = game.getGameState();
        String controller = resolveController(
                gameState, playerId, alternative.controller);
        com.gempukku.swccgo.filters.Filter actorFilter =
                resolveFilter(alternative.actorFilterKey);
        Collection<PhysicalCard> permanents =
                gameState.getAllPermanentCards();
        if (actorFilter == null || permanents == null) return false;
        com.gempukku.swccgo.filters.Filter participant =
                Filters.canParticipateInBattleAt(location, playerId);
        for (PhysicalCard card : permanents) {
            if (card == null
                    || controller == null
                        && playerId.equals(card.getOwner())
                    || controller != null
                        && !controller.equals(card.getOwner())
                    || !isActiveForSpot(
                            game, card,
                            alternative.includeExcludedFromBattle)
                    || !actorFilter.accepts(
                            gameState, game.getModifiersQuerying(),
                            card)
                    || !participant.accepts(
                            gameState, game.getModifiersQuerying(),
                            card)) {
                continue;
            }
            return true;
        }
        return false;
    }

    private boolean isPreFlipGlobalBlockerAt(
            SwccgGame game, String playerId, PhysicalCard location,
            Boolean includeExcludedOverride) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || location == null || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        if (isRalltiirOperationsFamily()) {
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (!isActivePreFlipRule(rule)) continue;
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if (isRalltiirControlWithAlternative(alternative)
                            && isOpponentConstraintBlockingAt(
                                game, playerId, location,
                                alternative.opponentConstraint)) {
                        return true;
                    }
                }
            }
        }
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)
                    || isRuleSatisfied(game, playerId, rule)) {
                continue;
            }
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (!"globalBlockerAbsent".equals(
                            alternative.scoreRole)
                        || isFlipLocationAlternativeSatisfied(
                            game, playerId, alternative)
                        || !locationMatchesAlternative(
                            game.getGameState(), game, playerId,
                            location, alternative)) {
                    continue;
                }
                String controller = resolveController(
                        game.getGameState(), playerId,
                        alternative.controller);
                if (relationSatisfiedAt(
                        game, playerId, controller, location,
                        alternative.relation,
                        alternative.actorFilterKey,
                        includeExcludedOverride != null
                                ? includeExcludedOverride
                                : alternative
                                        .includeExcludedFromBattle,
                        alternative.spotOverride)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isActorToRuntimeLocationAlternative(
            FlipLocationAlternative alternative) {
        return alternative != null
                && (isActorAtRelation(alternative)
                    || "controlWith".equals(
                        alternative.relation)
                    || isHiddenPathObjectiveFamily()
                        && "occupyWith".equals(
                            alternative.relation))
                && ("actorToLocation".equals(alternative.scoreRole)
                    || isCountedOperativeFormationAlternative(
                        alternative)
                    || isHiddenPathObjectiveFamily()
                        && "flipProgress".equals(
                            alternative.scoreRole))
                && alternative.actorFilterKey != null
                && alternative.locationFilterKey != null
                && alternative.count != null
                && alternative.count.value != null
                && alternative.count.value > 0;
    }

    private static boolean isRalltiirControlWithAlternative(
            FlipLocationAlternative alternative) {
        return alternative != null
                && "controlWith".equals(alternative.relation)
                && "self".equals(alternative.controller)
                && "Ralltiir_site".equals(
                    alternative.locationFilterKey)
                && "Imperial".equals(alternative.actorFilterKey)
                && "flipProgress".equals(alternative.scoreRole)
                && alternative.count != null
                && alternative.count.value != null
                && alternative.count.value == 3;
    }

    private FlipLocationAlternative findRalltiirControlWithAlternative() {
        if (activeFlipLocationRules == null) return null;
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)) continue;
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (isRalltiirControlWithAlternative(alternative)) {
                    return alternative;
                }
            }
        }
        return null;
    }

    private PhysicalCard findRalltiirSoleSystemBlocker(
            SwccgGame game, String playerId) {
        if (!isRalltiirOperationsFamily() || isFlipped
                || !"7_300".equals(objectiveBlueprintId)
                || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return null;
        }
        FlipLocationAlternative alternative =
                findRalltiirControlWithAlternative();
        RuleOpponentConstraint constraint = alternative != null
                ? alternative.opponentConstraint : null;
        if (alternative == null || constraint == null
                || countAlternativeMatches(
                    game, playerId, playerId, alternative)
                    < expectedCount(game, playerId, alternative.count)
                || countOpponentConstraintMatches(
                    game, playerId, constraint) != 1) {
            return null;
        }
        for (PhysicalCard location
                : game.getGameState().getLocationsInOrder()) {
            if (location != null
                    && Filters.Ralltiir_system.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), location)
                    && isOpponentConstraintBlockingAt(
                        game, playerId, location, constraint)) {
                return location;
            }
        }
        return null;
    }

    /**
     * Exact terminal front-side projection. Once three Ralltiir sites already
     * satisfy control-with-Imperial, a presence-supplying starship arriving at
     * the sole opponent-controlled Ralltiir system removes the last blocker.
     */
    public boolean isRalltiirSoleSystemBlockerPresenceDestination(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard destination) {
        if (game == null || playerId == null
                || candidate == null || destination == null
                || !playerId.equals(candidate.getOwner())
                || candidate.getBlueprint() == null
                || candidate.getBlueprint().getCardCategory()
                    != CardCategory.STARSHIP
                || !candidateProvidesPresence(game, candidate)) {
            return false;
        }
        PhysicalCard blocker = findRalltiirSoleSystemBlocker(
                game, playerId);
        return samePhysicalLocation(blocker, destination);
    }

    /** A presence-supplying pilot can complete the same terminal route by
     * boarding an owned ship that is already at the blocked system. */
    public boolean isRalltiirSoleSystemBlockerPilotHost(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard host) {
        if (game == null || playerId == null
                || candidate == null || host == null
                || !playerId.equals(candidate.getOwner())
                || !playerId.equals(host.getOwner())
                || candidate.getBlueprint() == null
                || host.getBlueprint() == null
                || candidate.getBlueprint().getCardCategory()
                    != CardCategory.CHARACTER
                || host.getBlueprint().getCardCategory()
                    != CardCategory.STARSHIP
                || !candidateProvidesPresence(game, candidate)
                || !isLegalProspectivePilotForHost(
                    game, playerId, host, candidate)) {
            return false;
        }
        PhysicalCard blocker = findRalltiirSoleSystemBlocker(
                game, playerId);
        PhysicalCard hostLocation = presenceContributionLocation(
                game, host);
        return samePhysicalLocation(blocker, hostLocation);
    }

    private PhysicalCard findLegalRalltiirSoleSystemBlockerDeployTarget(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        PhysicalCard blocker = findRalltiirSoleSystemBlocker(
                game, playerId);
        if (blocker == null || candidate == null
                || candidate.getZone() != Zone.HAND) {
            return null;
        }
        try {
            if (isRalltiirSoleSystemBlockerPresenceDestination(
                        game, playerId, candidate, blocker)
                    && Filters.deployableToLocation(
                        candidate, Filters.sameCardId(blocker),
                        false, 0.0f).accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), candidate)) {
                return blocker;
            }
            Collection<PhysicalCard> permanents =
                    game.getGameState().getAllPermanentCards();
            if (permanents == null) return null;
            for (PhysicalCard host : permanents) {
                if (isRalltiirSoleSystemBlockerPilotHost(
                            game, playerId, candidate, host)
                        && isProspectivePairRouteLegalAt(
                            game, playerId, host,
                            candidate, blocker)) {
                    return host;
                }
            }
        } catch (Exception e) {
            return null;
        }
        return null;
    }

    public boolean hasLegalRalltiirSoleSystemBlockerDeployRoute(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        return findLegalRalltiirSoleSystemBlockerDeployTarget(
                game, playerId, candidate) != null;
    }

    private boolean hasLegalRalltiirSoleSystemBlockerHyperspeedRoute(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard destination) {
        if (!isRalltiirSoleSystemBlockerPresenceDestination(
                    game, playerId, candidate, destination)
                || candidate.getZone() == null
                || !candidate.getZone().isInPlay()) {
            return false;
        }
        try {
            PhysicalCard origin = presenceContributionLocation(
                    game, candidate);
            return origin != null
                    && !samePhysicalLocation(origin, destination)
                    && Filters.canMoveToUsingHyperspeed(
                        playerId, candidate,
                        false, false, 0.0f).accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), destination)
                    && FormationSafety.vetoMoveDestination(
                        game, game.getGameState(), playerId,
                        candidate, destination) == null
                    && FormationSafety.vetoMoveOrigin(
                        game, game.getGameState(), playerId,
                        candidate, origin) == null;
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Projects the exact Ralltiir control-with-Imperial result while the
     * engine is asking where to deploy the selected card. During that child
     * decision the card can be in a transient in-play state without a real
     * location, so the ordinary active-card spot query is not authoritative.
     */
    public boolean isRalltiirFrontProgressDeployDestination(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard location) {
        if (!isRalltiirOperationsFamily() || isFlipped
                || game == null || playerId == null
                || candidate == null || location == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || activeFlipLocationRules == null) {
            return false;
        }
        if (isRalltiirSoleSystemBlockerPresenceDestination(
                    game, playerId, candidate, location)
                || isRalltiirSoleSystemBlockerPilotHost(
                    game, playerId, candidate, location)) {
            return true;
        }
        try {
            GameState gameState = game.getGameState();
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (!isActivePreFlipRule(rule)) continue;
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if (!isRalltiirControlWithAlternative(alternative)
                            || !locationMatchesAlternative(
                                gameState, game, playerId,
                                location, alternative)) {
                        continue;
                    }
                    com.gempukku.swccgo.filters.Filter actorFilter =
                            resolveFilter(alternative.actorFilterKey);
                    if (actorFilter == null || !actorFilter.accepts(
                            gameState,
                            game.getModifiersQuerying(), candidate)) {
                        return false;
                    }
                    boolean suppliesPresence =
                            candidateProvidesPresence(game, candidate);
                    if (!suppliesPresence
                            && candidate.getBlueprint() != null
                            && candidate.getBlueprint()
                                .hasAbilityAttribute()
                            && candidate.getBlueprint().getAbility()
                                != null
                            && candidate.getBlueprint().getAbility()
                                >= 1.0f) {
                        suppliesPresence = true;
                    }
                    int required = expectedCount(
                            game, playerId, alternative.count);
                    int qualified = countAlternativeMatches(
                            game, playerId, playerId, alternative);
                    if (!suppliesPresence || qualified >= required
                            || relationSatisfiedAt(
                                game, playerId, playerId, location,
                                alternative.relation,
                                alternative.actorFilterKey,
                                alternative.includeExcludedFromBattle,
                                alternative.spotOverride)) {
                        return false;
                    }
                    Map<com.gempukku.swccgo.common.InactiveReason, Boolean>
                        overrides = resolveSpotOverride(
                            alternative.includeExcludedFromBattle,
                            alternative.spotOverride);
                    String opponent = gameState.getOpponent(playerId);
                    return opponent == null
                            || !game.getModifiersQuerying()
                                .occupiesLocation(
                                    gameState, location,
                                    opponent, overrides);
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "Ralltiir prospective deploy destination failed: {}",
                    e.getMessage());
        }
        return false;
    }

    public boolean wouldCompletePreFlipRequirementAt(
            SwccgGame game, String playerId, PhysicalCard candidate,
            PhysicalCard location) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || candidate == null || location == null
                || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        if (isRalltiirSoleSystemBlockerPresenceDestination(
                    game, playerId, candidate, location)
                || isRalltiirSoleSystemBlockerPilotHost(
                    game, playerId, candidate, location)) {
            return true;
        }
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)) continue;
            boolean advanced = false;
            boolean allSatisfiedAfter = true;
            for (FlipLocationAlternative alternative : rule.alternatives) {
                boolean advances = advancesAlternativeAt(
                        game, playerId, candidate, location, alternative);
                if (advances) advanced = true;
                boolean satisfiedAfter = advances
                        ? alternativeSatisfiedAfterCandidate(
                                game, playerId, alternative)
                        : isFlipLocationAlternativeSatisfied(
                                game, playerId, alternative);
                if ("anyOf".equals(rule.mode) && satisfiedAfter && advances) {
                    return true;
                }
                allSatisfiedAfter &= satisfiedAfter;
            }
            if (!"anyOf".equals(rule.mode)
                    && advanced && allSatisfiedAfter) {
                return true;
            }
        }
        return false;
    }

    /**
     * Stable cache key for typed pre-flip progress. It changes at each counted
     * location, actor, or opponent-blocker transition, not only at completion.
     */
    public String getPreFlipProgressFingerprint(
            SwccgGame game, String playerId) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return "";
        }
        StringBuilder fingerprint = new StringBuilder();
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)) continue;
            fingerprint.append(rule.id).append('=');
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (alternative == null) continue;
                String controller = resolveController(
                        game.getGameState(), playerId,
                        alternative.controller);
                fingerprint.append(countAlternativeMatches(
                        game, playerId, controller, alternative)).append('/');
                fingerprint.append(countMatchingLocations(
                        game, playerId, alternative)).append('/');
                RuleOpponentConstraint constraint =
                        alternative.opponentConstraint;
                fingerprint.append(countOpponentConstraintMatches(
                        game, playerId, constraint)).append(';');
            }
        }
        return fingerprint.toString();
    }

    /**
     * True when this exact location owns an unmet structured pre-flip condition.
     */
    public boolean isMissingPreFlipRequirementAt(
            SwccgGame game, String playerId, PhysicalCard location) {
        if (!analyzed || isFlipped || game == null
                || playerId == null || location == null) {
            return false;
        }

        GameState gameState = game.getGameState();
        if (gameState == null || game.getModifiersQuerying() == null) return false;

        if (isShieldMainGeneratorControlContestLocation(
                    game, playerId, location)) {
            return !game.getModifiersQuerying()
                    .controlsLocation(
                        gameState, location, playerId);
        }
        if (isShieldMainGeneratorFiringMarker(
                    game, location)) {
            boolean targetHere = hasActiveShieldTargetAt(
                    game, playerId, location);
            boolean packageHere =
                    hasActiveShieldFiringPackageAt(
                        game, playerId, location);
            if (targetHere != packageHere) return true;
        }
        if (activeFlipLocationRules == null) return false;

        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)
                    || isRuleSatisfied(game, playerId, rule)) {
                continue;
            }
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (alternative == null) {
                    continue;
                }
                if (isOpponentConstraintBlockingAt(
                        game, playerId, location,
                        alternative.opponentConstraint)) {
                    return true;
                }
                if (!locationMatchesAlternative(
                        gameState, game, playerId, location, alternative)) {
                    continue;
                }
                int required = expectedCount(
                        game, playerId, alternative.count);
                String controller = resolveController(
                        gameState, playerId, alternative.controller);
                int qualified = countAlternativeMatches(
                        game, playerId, controller, alternative);
                boolean relationHere = relationSatisfiedAt(
                        game, playerId, controller, location,
                        alternative.relation,
                        alternative.actorFilterKey,
                        alternative.includeExcludedFromBattle,
                        alternative.spotOverride);
                if (isUpperBound(alternative.count)) {
                    if (relationHere
                            && !isFlipLocationAlternativeSatisfied(
                                game, playerId, alternative)) {
                        return true;
                    }
                    continue;
                }
                if (qualified >= required || relationHere) continue;
                return true;
            }
        }
        return false;
    }

    private static boolean isUpperBound(RuleCount count) {
        if (count == null || count.comparator == null) return false;
        return "<".equals(count.comparator)
                || "<=".equals(count.comparator)
                || "=".equals(count.comparator)
                || "==".equals(count.comparator);
    }

    /**
     * True only for an exact typed pre-flip location whose relation is plain
     * self control. Actor-gated controlWith locations are handled separately.
     */
    public boolean isPreFlipPlainControlRequirementLocation(
            SwccgGame game, String playerId, PhysicalCard location) {
        return matchesStructuredRequirementLocation(
                game, playerId, location,
                "preFlip", "flip", "control", "self");
    }

    /** Exact location named by an active plain self-control or self-occupy leg. */
    public boolean isPreFlipPlainPresenceRequirementLocation(
            SwccgGame game, String playerId, PhysicalCard location) {
        return isPreFlipPlainControlRequirementLocation(
                    game, playerId, location)
                || matchesStructuredRequirementLocation(
                    game, playerId, location,
                    "preFlip", "flip", "occupy", "self");
    }

    /** Current relation truth for a plain control or occupy requirement here. */
    public boolean isPreFlipPlainPresenceRequirementSatisfiedAt(
            SwccgGame game, String playerId, PhysicalCard location) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || location == null || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)) continue;
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (!isPlainSelfPresenceAlternative(alternative)
                        || !locationMatchesAlternative(
                            game.getGameState(), game, playerId,
                            location, alternative)) {
                    continue;
                }
                if (relationSatisfiedAt(
                        game, playerId, playerId, location,
                        alternative.relation, null,
                        alternative.includeExcludedFromBattle,
                        alternative.spotOverride)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * True for any exact typed location named by the active pre-flip rule.
     */
    public boolean isPreFlipFlipRequirementLocation(
            SwccgGame game, String playerId, PhysicalCard location) {
        return isShieldMainGeneratorControlContestLocation(
                    game, playerId, location)
                || matchesStructuredRequirementLocation(
                game, playerId, location,
                "preFlip", "flip", null, null);
    }

    public boolean hasStructuredFlipBackLocationRules() {
        if (!analyzed || activeFlipLocationRules == null) return false;
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (rule != null && "postFlip".equals(rule.phase)
                    && isPostFlipProtectionPurpose(rule)
                    && rule.alternatives != null
                    && !rule.alternatives.isEmpty()) {
                return true;
            }
        }
        return false;
    }

    /**
     * Physical-card overload for exact post-flip protection. Structured rules
     * own the answer when present; parser fragments remain the legacy fallback.
     */
    public boolean isFlipBackProtectionLocation(
            PhysicalCard location, SwccgGame game, String playerId) {
        if (!analyzed || location == null) return false;
        if (isRequiredCardCancelPreventerDefenseLocation(
                game, playerId, location)) {
            return true;
        }
        RequiredCardRetentionRisk retentionRisk =
                assessRequiredCardRetentionRisk(
                        game, playerId, location);
        if (retentionRisk.applies()
                && retentionRisk.inScope()) {
            return retentionRisk.requiresProtection();
        }
        if (isNoMoneyNoPartsObjectiveFamily() && isFlipped
                && game != null && game.getGameState() != null
                && game.getModifiersQuerying() != null
                && Filters.Wattos_Junkyard.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), location)
                && hasNoMoneyNoPartsWattoAtJunkyardAfterMove(
                    game, location, null)) {
            return true;
        }
        if (hasStructuredFlipBackLocationRules()) {
            PostFlipLocationRisk risk = assessPostFlipLocationRisk(
                    game, playerId, location);
            if (risk.applies()) {
                return risk.requiresProtection();
            }
            return false;
        }
        return isFlipBackProtectionLocation(location.getTitle());
    }

    /**
     * Evaluates the enabled counted back-side shapes without confusing
     * regional geography with an immediate hold requirement.
     */
    public PostFlipLocationRisk assessPostFlipLocationRisk(
            SwccgGame game, String playerId, PhysicalCard location) {
        if (!analyzed || !isFlipped || game == null || playerId == null
                || location == null || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return PostFlipLocationRisk.none();
        }

        PostFlipLocationRisk supportedOutOfScope = null;
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (rule == null || !"postFlip".equals(rule.phase)
                    || !isPostFlipProtectionPurpose(rule)
                    || rule.alternatives == null) {
                continue;
            }
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (!isSupportedPostFlipAlternative(
                            rule, alternative)) {
                    continue;
                }
                PostFlipLocationRisk risk = assessPostFlipLocationRisk(
                        game, playerId, location, rule,
                        alternative);
                if (risk.inScope()) return risk;
                if (supportedOutOfScope == null) {
                    supportedOutOfScope = risk;
                }
            }
        }
        return supportedOutOfScope != null
                ? supportedOutOfScope : PostFlipLocationRisk.none();
    }

    /**
     * True only when this exact mover is the last friendly presence source and
     * its departure would immediately satisfy the counted flip-back predicate.
     */
    public boolean wouldDepartureTriggerFlipBack(
            SwccgGame game, String playerId, PhysicalCard mover) {
        if (!analyzed || !isFlipped || game == null || playerId == null
                || mover == null || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            if (isTheyHaveNoIdeaObjectiveFamily()) {
                return wouldTheyHaveNoIdeaDepartureTriggerFlipBack(
                        game, playerId, mover);
            }
            if (isIWantThatMapObjectiveFamily()) {
                return wouldIWantThatMapDepartureTriggerFlipBack(
                        game, playerId, mover);
            }
            // A location-scoped on-table actor stops matching when it leaves
            // that location. Global on-table actors, such as Vader for Hunt
            // Down, remain valid after ordinary movement.
            if (wouldDepartureTriggerOnTableFlipBack(
                    game, playerId, mover)) {
                return true;
            }
            GameState gameState = game.getGameState();
            PhysicalCard location = game.getModifiersQuerying()
                    .getLocationThatCardIsPresentAt(gameState, mover);
            PostFlipLocationRisk risk = assessPostFlipLocationRisk(
                    game, playerId, location);
            if (!risk.applies() || !risk.inScope() || risk.flipBackNow()) {
                return false;
            }

            FlipLocationAlternative alternative =
                    findSupportedPostFlipAlternative(
                            game, playerId, location);
            if (alternative == null) return false;
            if (isHiddenPathSelfOccupyWithFlipBackAlternative(
                    alternative)) {
                com.gempukku.swccgo.filters.Filter actorFilter =
                        resolveFilter(alternative.actorFilterKey);
                return risk.criticalIfSelfControlLost()
                        && removedGroupContainsMatchingActor(
                            game, playerId, location,
                            alternative, mover, null, actorFilter)
                        && !hasOtherMatchingActorOutsideRemovedGroup(
                            game, playerId, location,
                            alternative, mover, null);
            }
            if (!isSolePresenceSourceAtLocation(
                    game, playerId, mover, location)) {
                return false;
            }
            String opponent = gameState.getOpponent(playerId);
            if (opponent == null) return false;
            Map<com.gempukku.swccgo.common.InactiveReason, Boolean> overrides =
                    Boolean.TRUE.equals(
                            alternative.includeExcludedFromBattle)
                            ? SpotOverride.INCLUDE_EXCLUDED_FROM_BATTLE
                            : null;
            if (isSelfOccupyCountedFlipBackAlternative(alternative)) {
                return risk.criticalIfSelfControlLost();
            }
            boolean opponentOccupies =
                    game.getModifiersQuerying().occupiesLocation(
                            gameState, location, opponent, overrides);
            return opponentOccupies
                    ? risk.criticalIfOpponentGainsControl()
                    : risk.criticalIfSelfControlLost();
        } catch (Exception e) {
            LOG.debug("Objective flip-back departure assessment failed: {}",
                    e.getMessage());
            return false;
        }
    }

    /**
     * Evaluates THNI's compound back-side law as one counterfactual. Treating
     * its two allOf legs independently is incorrect because Rogue One at an
     * occupied Scarif site is the explicit exception to the occupation floor.
     */
    public boolean wouldTheyHaveNoIdeaDepartureTriggerFlipBack(
            SwccgGame game, String playerId, PhysicalCard mover) {
        if (!isTheyHaveNoIdeaObjectiveFamily() || !isFlipped
                || game == null || playerId == null || mover == null
                || !playerId.equals(mover.getOwner())
                || mover.getZone() == null || !mover.getZone().isInPlay()
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        TheyHaveNoIdeaBackState current =
                theyHaveNoIdeaBackStateAfterRemoval(
                    game, playerId, null);
        if (current.flipBackConditionMet()) return false;
        TheyHaveNoIdeaBackState after =
                theyHaveNoIdeaBackStateAfterRemoval(
                    game, playerId, mover);
        return after.flipBackConditionMet();
    }

    private record TheyHaveNoIdeaBackState(
            int occupiedScarifLocations,
            boolean rogueOneAtOccupiedScarifSite) {
        private boolean flipBackConditionMet() {
            return occupiedScarifLocations <= 1
                    && !rogueOneAtOccupiedScarifSite;
        }
    }

    private TheyHaveNoIdeaBackState
            theyHaveNoIdeaBackStateAfterRemoval(
                    SwccgGame game, String playerId,
                    PhysicalCard removedRoot) {
        GameState gameState = game.getGameState();
        Set<Integer> occupiedLocationIds = new HashSet<>();
        List<PhysicalCard> locations = gameState.getTopLocations();
        Collection<PhysicalCard> cards =
                gameState.getAllPermanentCards();
        if (locations != null && cards != null) {
            for (PhysicalCard location : locations) {
                if (location == null
                        || !Filters.Scarif_location.accepts(
                            gameState,
                            game.getModifiersQuerying(), location)) {
                    continue;
                }
                for (PhysicalCard card : cards) {
                    if (card == null
                            || !playerId.equals(card.getOwner())
                            || !candidateProvidesPresenceOutsideRemovedGroup(
                                game, card, removedRoot, null)) {
                        continue;
                    }
                    PhysicalCard contributionLocation =
                            presenceContributionLocation(game, card);
                    if (samePhysicalLocation(
                            contributionLocation, location)) {
                        occupiedLocationIds.add(
                                location.getPermanentCardId());
                        break;
                    }
                }
            }
        }

        boolean validRogueOneException = false;
        if (cards != null) {
            for (PhysicalCard card : cards) {
                if (!isExactOwnedCard(card, playerId, "206_7")
                        || belongsToRemovedGroup(
                            card, removedRoot, null)
                        || !isActiveForSpot(game, card, true)) {
                    continue;
                }
                PhysicalCard location = game.getModifiersQuerying()
                        .getLocationThatCardIsAt(gameState, card);
                if (location != null
                        && occupiedLocationIds.contains(
                            location.getPermanentCardId())
                        && Filters.Scarif_site.accepts(
                            gameState,
                            game.getModifiersQuerying(), location)) {
                    validRogueOneException = true;
                    break;
                }
            }
        }
        return new TheyHaveNoIdeaBackState(
                occupiedLocationIds.size(),
                validRogueOneException);
    }

    private boolean wouldIWantThatMapDepartureTriggerFlipBack(
            SwccgGame game, String playerId, PhysicalCard mover) {
        if (!isIWantThatMapObjectiveFamily() || !isFlipped
                || mover == null || !playerId.equals(mover.getOwner())
                || mover.getZone() == null || !mover.getZone().isInPlay()
                || hasIWantThatMapResistanceAgentAtBattlegroundSite(
                    game)) {
            return false;
        }
        int current = countIWantThatMapOccupiedBattlegroundsAfterRemoval(
                game, playerId, null);
        return current >= 2
                && countIWantThatMapOccupiedBattlegroundsAfterRemoval(
                    game, playerId, mover) < 2;
    }

    private int countIWantThatMapOccupiedBattlegroundsAfterRemoval(
            SwccgGame game, String playerId,
            PhysicalCard removedRoot) {
        List<PhysicalCard> locations =
                game.getGameState().getLocationsInOrder();
        Collection<PhysicalCard> cards =
                game.getGameState().getAllPermanentCards();
        if (locations == null || cards == null) return 0;

        int occupied = 0;
        for (PhysicalCard location : locations) {
            if (location == null || !Filters.battleground.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), location)) {
                continue;
            }
            for (PhysicalCard card : cards) {
                if (card == null || !playerId.equals(card.getOwner())
                        || !isActiveForSpot(game, card, true)
                        || !candidateProvidesPresenceOutsideRemovedGroup(
                            game, card, removedRoot, null)) {
                    continue;
                }
                if (samePhysicalLocation(
                        iWantThatMapPresenceContributionLocation(
                            game, card),
                        location)) {
                    occupied++;
                    break;
                }
            }
        }
        return occupied;
    }

    private boolean hasIWantThatMapResistanceAgentAtBattlegroundSite(
            SwccgGame game) {
        List<PhysicalCard> locations =
                game.getGameState().getLocationsInOrder();
        Collection<PhysicalCard> cards =
                game.getGameState().getAllPermanentCards();
        if (locations == null || cards == null) return false;
        for (PhysicalCard location : locations) {
            if (location == null || !Filters.battleground_site.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), location)) {
                continue;
            }
            for (PhysicalCard card : cards) {
                if (card == null || !isActiveForSpot(game, card, true)
                        || !Filters.Resistance_Agent.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), card)) {
                    continue;
                }
                PhysicalCard actorLocation = game.getModifiersQuerying()
                        .getLocationThatCardIsPresentAt(
                            game.getGameState(), card);
                if (samePhysicalLocation(actorLocation, location)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * True when moving or losing this exact card would violate a structured
     * stay-flipped survival law. This is deliberately separate from flip-back:
     * Shield's back side is placed out of play when its last qualifying Hoth
     * occupier disappears.
     */
    public boolean wouldDepartureTriggerStayFlippedFailure(
            SwccgGame game, String playerId, PhysicalCard mover) {
        if (!analyzed || !isFlipped || game == null || playerId == null
                || mover == null || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            GameState gameState = game.getGameState();
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (rule == null
                        || !"postFlip".equals(rule.phase)
                        || !"stayFlipped".equals(rule.purpose)
                        || rule.alternatives == null) {
                    continue;
                }
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if (!isSupportedPostFlipAlternative(
                                rule, alternative)) {
                        continue;
                    }
                    PhysicalCard location = actorLocationForAlternative(
                            game, mover, alternative);
                    if (location == null
                            || !locationMatchesAlternative(
                                gameState, game, playerId,
                                location, alternative)) {
                        continue;
                    }
                    PostFlipLocationRisk risk =
                            assessPostFlipLocationRisk(
                                game, playerId, location,
                                rule, alternative);
                    if (!risk.criticalIfSelfControlLost()) {
                        continue;
                    }

                    com.gempukku.swccgo.filters.Filter actorFilter =
                            resolveFilter(
                                alternative.actorFilterKey);
                    PhysicalCard pilotDependentHost =
                            findPilotedAtAtDependentOnPilot(
                                game, mover);
                    boolean removesQualifyingActor =
                            removedGroupContainsMatchingActor(
                                game, playerId, location,
                                alternative, mover,
                                pilotDependentHost, actorFilter);
                    if (!removesQualifyingActor
                            && pilotDependentHost != null
                            && actorFilter != null
                            && actorFilter.accepts(
                                gameState,
                                game.getModifiersQuerying(),
                                pilotDependentHost)) {
                        removesQualifyingActor = true;
                    }
                    if (removesQualifyingActor
                            && !hasOtherMatchingActorOutsideRemovedGroup(
                                game, playerId, location,
                                alternative, mover,
                                pilotDependentHost)) {
                        return true;
                    }
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "Objective stay-flipped departure assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    /**
     * A move is safe when the moved card group still satisfies the active
     * stay-flipped law at its destination. Shield may relocate its last
     * qualifying occupier between Hoth sites without losing the objective.
     */
    public boolean preservesStayFlippedRequirementByMovingTo(
            SwccgGame game, String playerId,
            PhysicalCard mover, PhysicalCard destination) {
        if (analyzed && isFlipped
                && CaptureObjectiveFacts.isCaptureObjective(this)) {
            return !CaptureObjectiveFacts
                    .wouldBreakStableBackByMovingTo(
                        game, playerId, this,
                        mover, destination);
        }
        if (!analyzed || !isFlipped || game == null
                || playerId == null || mover == null
                || destination == null
                || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        if (!wouldDepartureTriggerStayFlippedFailure(
                    game, playerId, mover)) {
            return true;
        }
        try {
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (rule == null
                        || !"postFlip".equals(rule.phase)
                        || !"stayFlipped".equals(rule.purpose)
                        || rule.alternatives == null) {
                    continue;
                }
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if (!isSupportedPostFlipAlternative(
                                rule, alternative)) {
                        continue;
                    }
                    com.gempukku.swccgo.filters.Filter actorFilter =
                            resolveFilter(
                                alternative.actorFilterKey);
                    if (movedGroupCanSatisfyAlternativeAt(
                                game, playerId, mover,
                                destination, alternative,
                                actorFilter)) {
                        return true;
                    }
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "Objective stay-flipped relocation assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    public boolean hasSafeStayFlippedLandspeedDestination(
            SwccgGame game, String playerId,
            PhysicalCard mover) {
        if (game == null || playerId == null || mover == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        PhysicalCard origin = game.getModifiersQuerying()
                .getLocationThatCardIsAt(
                    game.getGameState(), mover);
        if (origin == null) return false;
        try {
            com.gempukku.swccgo.filters.Filter legalTarget =
                    Filters.canMoveToUsingLandspeed(
                        playerId, mover,
                        false, false, false,
                        0.0f, null);
            for (PhysicalCard destination
                    : game.getGameState()
                        .getLocationsInOrder()) {
                if (destination != null
                        && legalTarget.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(),
                            destination)
                        && preservesStayFlippedRequirementByMovingTo(
                            game, playerId, mover,
                            destination)
                        && FormationSafety
                            .vetoMoveDestination(
                                game, game.getGameState(),
                                playerId, mover,
                                destination) == null
                        && FormationSafety
                            .vetoMoveOrigin(
                                game, game.getGameState(),
                                playerId, mover,
                                origin) == null) {
                    return true;
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "Objective stay-flipped landspeed assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    /**
     * Hoth repair #3 (2026-07-27): true when this location currently holds a
     * qualifying stay-flipped anchor (an actor matching the active profile's
     * stayFlipped actorFilterKey, owned by playerId). Keyed on the data rule
     * (today only 222_30's imperial-troops-back-hoth-site-survival), never a
     * title. Fails closed to false so uncertainty never gates a move.
     */
    public boolean holdsStayFlippedAnchor(
            SwccgGame game, String playerId, PhysicalCard location) {
        if (!analyzed || !isFlipped || game == null || playerId == null
                || location == null || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            GameState gameState = game.getGameState();
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (rule == null
                        || !"postFlip".equals(rule.phase)
                        || !"stayFlipped".equals(rule.purpose)
                        || rule.alternatives == null) {
                    continue;
                }
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if (isSupportedPostFlipAlternative(rule, alternative)
                            && locationMatchesAlternative(
                                gameState, game, playerId,
                                location, alternative)
                            && hasMatchingActorAtLocation(
                                game, playerId, location,
                                alternative.actorFilterKey)) {
                        return true;
                    }
                }
            }
        } catch (Exception e) {
            LOG.debug("Stay-flipped anchor check failed: {}",
                    e.getMessage());
        }
        return false;
    }

    /**
     * Hoth repair #3: true when no OTHER location besides this one holds a
     * qualifying stay-flipped anchor. Fails closed to false (never claims
     * soleness on error, so the concentration veto cannot fire falsely).
     */
    public boolean isSoleStayFlippedAnchorSite(
            SwccgGame game, String playerId, PhysicalCard site) {
        if (!holdsStayFlippedAnchor(game, playerId, site)) {
            return false;
        }
        try {
            for (PhysicalCard other
                    : game.getGameState().getLocationsInOrder()) {
                if (other != null && other != site
                        && holdsStayFlippedAnchor(
                            game, playerId, other)) {
                    return false;
                }
            }
            return true;
        } catch (Exception e) {
            LOG.debug("Sole anchor-site check failed: {}",
                    e.getMessage());
            return false;
        }
    }

    /**
     * Hoth repair #3: counts stay-flipped anchor sites that are SAFE
     * (opponent power + weapon bonus <= friendly power + the caller's
     * retreatable gap), excluding excludedSite (pass the move destination).
     * Returns 0 on any error; the veto also requires soleness so a failed
     * count cannot alone create a veto.
     */
    public int countSafeStayFlippedAnchorSites(
            SwccgGame game, String playerId, PhysicalCard excludedSite,
            float retreatablePowerGap) {
        if (!analyzed || !isFlipped || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        int count = 0;
        try {
            GameState gameState = game.getGameState();
            String opponent = gameState.getOpponent(playerId);
            for (PhysicalCard site
                    : gameState.getLocationsInOrder()) {
                if (site == null || site == excludedSite
                        || !holdsStayFlippedAnchor(
                            game, playerId, site)) {
                    continue;
                }
                float friendly = game.getModifiersQuerying()
                        .getTotalPowerAtLocation(
                            gameState, site, playerId, false, false);
                float opposing = opponent != null
                        ? game.getModifiersQuerying()
                            .getTotalPowerAtLocation(
                                gameState, site, opponent, false, false)
                            + FormationSafety.weaponBonusAt(
                                gameState, site, opponent)
                        : 0.0f;
                if (opposing <= friendly + retreatablePowerGap) {
                    count++;
                }
            }
        } catch (Exception e) {
            LOG.debug("Safe anchor-site count failed: {}",
                    e.getMessage());
            return 0;
        }
        return count;
    }

    /**
     * Returns the currently piloted AT-AT that would become unpiloted if this
     * exact assigned pilot left. Permanent pilots and a second assigned pilot
     * keep the vehicle valid and therefore return no dependency.
     */
    private PhysicalCard findPilotedAtAtDependentOnPilot(
            SwccgGame game, PhysicalCard candidate) {
        GameState gameState = game.getGameState();
        PhysicalCard host = game.getModifiersQuerying()
                .getIsPilotOf(gameState, candidate);
        if (host == null
                || !Filters.AT_AT.accepts(
                    gameState, game.getModifiersQuerying(), host)
                || !Filters.piloted.accepts(
                    gameState, game.getModifiersQuerying(), host)
                || game.getModifiersQuerying()
                    .hasPermanentPilot(gameState, host)) {
            return null;
        }
        Collection<PhysicalCard> cards =
                gameState.getAllPermanentCards();
        if (cards == null) return null;
        for (PhysicalCard card : cards) {
            if (card == null || card == candidate
                    || !isActiveForSpot(game, card, true)) {
                continue;
            }
            PhysicalCard otherHost = game.getModifiersQuerying()
                    .getIsPilotOf(gameState, card);
            if (otherHost == host) {
                return null;
            }
        }
        return host;
    }

    private PostFlipLocationRisk assessPostFlipLocationRisk(
            SwccgGame game, String playerId, PhysicalCard location,
            FlipLocationRule rule,
            FlipLocationAlternative alternative) {
        GameState gameState = game.getGameState();
        String opponent = gameState.getOpponent(playerId);
        if (opponent == null) return PostFlipLocationRisk.none();

        int selfCount = countAlternativeMatches(
                game, playerId, playerId, alternative);
        boolean inScope = locationMatchesAlternative(
                gameState, game, playerId, location, alternative);
        boolean selfQualifiesHere = inScope && relationSatisfiedAt(
                game, playerId, playerId, location,
                alternative.relation, alternative.actorFilterKey,
                alternative.includeExcludedFromBattle,
                alternative.spotOverride);

        if ((isCountedOperativeObjectiveFamily()
                    || isOldAlliesObjectiveFamily()
                    || isNoMoneyNoPartsObjectiveFamily()
                    || isIWantThatMapObjectiveFamily())
                    && isSelfOccupyCountedFlipBackAlternative(alternative)
                || isHiddenPathSelfOccupyWithFlipBackAlternative(
                    alternative)) {
            int required = expectedCount(
                    game, playerId, alternative.count);
            String comparator = alternative.count.comparator;
            boolean flipBackNow = compareCounts(
                    selfCount, required, comparator);
            boolean selfLossTriggers = selfQualifiesHere
                    && compareCounts(
                        Math.max(0, selfCount - 1),
                        required, comparator);
            int adverseSteps = 0;
            while (adverseSteps < 100
                    && !compareCounts(
                        Math.max(0, selfCount - adverseSteps),
                        required, comparator)) {
                adverseSteps++;
            }
            return new PostFlipLocationRisk(
                    true, inScope, flipBackNow, false,
                    selfLossTriggers, false,
                    selfCount, 0, adverseSteps);
        }

        if ("stayFlipped".equals(rule.purpose)) {
            int required = expectedCount(
                    game, playerId, alternative.count);
            String comparator = alternative.count.comparator;
            boolean protectionFailedNow = !compareCounts(
                    selfCount, required, comparator);
            boolean selfLossTriggers = selfQualifiesHere
                    && !compareCounts(
                        Math.max(0, selfCount - 1),
                        required, comparator);
            int adverseSteps = 0;
            while (adverseSteps < 100
                    && compareCounts(
                        Math.max(0, selfCount - adverseSteps),
                        required, comparator)) {
                adverseSteps++;
            }
            return new PostFlipLocationRisk(
                    true, inScope, protectionFailedNow, false,
                    selfLossTriggers, false,
                    selfCount, 0, adverseSteps);
        }

        int opponentCount = countAlternativeMatches(
                game, playerId, opponent, alternative);
        boolean opponentControlsHere = inScope && relationSatisfiedAt(
                game, playerId, opponent, location,
                alternative.relation, alternative.actorFilterKey,
                alternative.includeExcludedFromBattle,
                alternative.spotOverride);

        boolean flipBackNow = postFlipCountTriggered(
                game, playerId, alternative,
                opponentCount, selfCount);
        boolean selfLossTriggers = selfQualifiesHere
                && postFlipCountTriggered(
                        game, playerId, alternative,
                        opponentCount, Math.max(0, selfCount - 1));
        boolean opponentGainTriggers = inScope && !opponentControlsHere
                && postFlipCountTriggered(
                        game, playerId, alternative,
                        opponentCount + 1,
                        Math.max(0, selfCount
                                - (selfQualifiesHere ? 1 : 0)));

        int adverseSteps = 0;
        while (adverseSteps < 100
                && !postFlipCountTriggered(
                        game, playerId, alternative,
                        opponentCount + adverseSteps, selfCount)) {
            adverseSteps++;
        }
        return new PostFlipLocationRisk(
                true, inScope, flipBackNow, opponentControlsHere,
                selfLossTriggers, opponentGainTriggers,
                selfCount, opponentCount, adverseSteps);
    }

    private static boolean isPostFlipProtectionPurpose(
            FlipLocationRule rule) {
        return rule != null
                && ("flipBack".equals(rule.purpose)
                    || "stayFlipped".equals(rule.purpose));
    }

    private boolean isSupportedPostFlipAlternative(
            FlipLocationRule rule,
            FlipLocationAlternative alternative) {
        if (rule == null || alternative == null) return false;
        if ("flipBack".equals(rule.purpose)) {
            return isSupportedCountedFlipBackAlternative(alternative);
        }
        return "stayFlipped".equals(rule.purpose)
                && "self".equals(alternative.controller)
                && ("occupyWith".equals(alternative.relation)
                    || "controlWith".equals(alternative.relation)
                    || "at".equals(alternative.relation))
                && alternative.locationFilterKey != null
                && alternative.actorFilterKey != null
                && alternative.count != null
                && alternative.count.value != null;
    }

    private boolean postFlipCountTriggered(
            SwccgGame game, String playerId,
            FlipLocationAlternative alternative,
            int opponentCount, int selfCount) {
        RuleCount count = alternative.count;
        if (count.referenceController != null) {
            return compareCounts(
                    opponentCount, selfCount, count.comparator);
        }
        return compareCounts(
                opponentCount, expectedCount(game, playerId, count),
                count.comparator);
    }

    private boolean isSupportedCountedFlipBackAlternative(
            FlipLocationAlternative alternative) {
        if (alternative == null || alternative.locationFilterKey == null
                || alternative.count == null) {
            return false;
        }
        boolean opponentControl = "control".equals(alternative.relation)
                && "opponent".equals(alternative.controller)
                && (alternative.count.value != null
                    || "self".equals(
                        alternative.count.referenceController));
        return opponentControl
                || (isCountedOperativeObjectiveFamily()
                    || isOldAlliesObjectiveFamily()
                    || isNoMoneyNoPartsObjectiveFamily()
                    || isIWantThatMapObjectiveFamily())
                    && isSelfOccupyCountedFlipBackAlternative(alternative)
                || isHiddenPathSelfOccupyWithFlipBackAlternative(
                    alternative);
    }

    private static boolean isSelfOccupyCountedFlipBackAlternative(
            FlipLocationAlternative alternative) {
        return alternative != null
                && "occupy".equals(alternative.relation)
                && "self".equals(alternative.controller)
                && alternative.count != null
                && alternative.count.value != null
                && ("<".equals(alternative.count.comparator)
                    || "<=".equals(alternative.count.comparator));
    }

    private boolean isHiddenPathSelfOccupyWithFlipBackAlternative(
            FlipLocationAlternative alternative) {
        return isHiddenPathObjectiveFamily()
                && alternative != null
                && "occupyWith".equals(alternative.relation)
                && "self".equals(alternative.controller)
                && "Jedi".equals(alternative.actorFilterKey)
                && "non_Mapuzo_site".equals(
                    alternative.locationFilterKey)
                && alternative.count != null
                && alternative.count.value != null
                && ("<".equals(alternative.count.comparator)
                    || "<=".equals(alternative.count.comparator));
    }

    private FlipLocationAlternative findSupportedPostFlipAlternative(
            SwccgGame game, String playerId, PhysicalCard location) {
        if (activeFlipLocationRules == null) return null;
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (rule == null || !"postFlip".equals(rule.phase)
                    || !"flipBack".equals(rule.purpose)
                    || rule.alternatives == null) {
                continue;
            }
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (isSupportedCountedFlipBackAlternative(alternative)
                        && locationMatchesAlternative(
                                game.getGameState(), game, playerId,
                                location, alternative)) {
                    return alternative;
                }
            }
        }
        return null;
    }

    /**
     * Counterfactual fact for moving a card from a required-control location.
     * It returns true only when the mover is a proven presence source and no
     * independent friendly presence source remains.
     */
    public boolean isSoleControlSourceAtRequiredLocation(
            SwccgGame game, String playerId, PhysicalCard mover,
            PhysicalCard location) {
        if (!isPreFlipPlainControlRequirementLocation(
                    game, playerId, location)
                || mover == null || game == null) {
            return false;
        }

        return isSolePresenceSourceAtRequiredLocation(
                game, playerId, mover, location);
    }

    /**
     * Count-aware counterfactual for a plain control or occupy location. It is
     * true only when this card's departure would erase needed objective
     * progress, not merely because the location appears in the playbook.
     */
    public boolean isSolePresenceSourceAtRequiredLocation(
            SwccgGame game, String playerId, PhysicalCard mover,
            PhysicalCard location) {
        if (!isPreFlipPlainPresenceRequirementLocation(
                    game, playerId, location)
                || mover == null || game == null) {
            return false;
        }

        try {
            GameState gameState = game.getGameState();
            if (gameState == null || game.getModifiersQuerying() == null) {
                return false;
            }
            if (!playerId.equals(mover.getOwner())
                    || mover.isUndercover()
                    || !candidateProvidesPresence(game, mover)) {
                return false;
            }
            PhysicalCard moverLocation = presenceContributionLocation(
                    game, mover);
            if (!samePhysicalLocation(moverLocation, location)) return false;

            return classifyPlainPresenceIfRemoved(
                    game, playerId, mover)
                    == FlipGateFormationRole.LAST_REQUIRED_ACTOR;
        } catch (Exception e) {
            LOG.debug("Objective required-presence source assessment failed: {}",
                    e.getMessage());
            return false;
        }
    }

    private boolean matchesStructuredRequirementLocation(
            SwccgGame game, String playerId, PhysicalCard location,
            String phase, String purpose, String relation,
            String controller) {
        if (!analyzed || game == null || playerId == null || location == null
                || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (rule == null || !phase.equals(rule.phase)
                    || !purpose.equals(rule.purpose)
                    || rule.alternatives == null) {
                continue;
            }
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (alternative == null
                        || relation != null
                            && !relation.equals(alternative.relation)
                        || controller != null
                            && !controller.equals(alternative.controller)) {
                    continue;
                }
                if (locationMatchesAlternative(
                        game.getGameState(), game, playerId,
                        location, alternative)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean attachedToOrAboard(
            PhysicalCard card, PhysicalCard possibleHost) {
        PhysicalCard host = card.getAttachedTo();
        Set<PhysicalCard> seen = Collections.newSetFromMap(
                new IdentityHashMap<>());
        while (host != null && seen.add(host)) {
            if (host == possibleHost) return true;
            host = host.getAttachedTo();
        }
        return false;
    }

    private boolean isFlipLocationAlternativeSatisfied(
            SwccgGame game, String playerId,
            FlipLocationAlternative alternative) {
        if (alternative == null
                || (!"onTable".equals(alternative.relation)
                    && !"utinniEffectCompleted".equals(alternative.relation)
                    && alternative.locationFilterKey == null)) {
            return false;
        }

        try {
            GameState gameState = game.getGameState();
            if (gameState == null || game.getModifiersQuerying() == null) {
                return false;
            }
            if (!isSupportedSpotOverride(alternative.spotOverride)) {
                LOG.warn("[ObjectiveAnalyzer] unknown spotOverride '{}' in"
                        + " objective_playbooks.json; fail-closed.",
                        alternative.spotOverride);
                return false;
            }

            String controller = resolveController(
                    gameState, playerId, alternative.controller);
            if (controller == null
                    && !"any".equals(alternative.controller)) {
                return false;
            }

            // Extension batch (2026-07-29): phase-window gate (Rebel Strike
            // Team's move-phase-only routes). Outside the window the
            // alternative is simply unsatisfied; unknown values fail closed.
            if (alternative.gamePhase != null) {
                com.gempukku.swccgo.common.Phase windowPhase;
                try {
                    windowPhase = com.gempukku.swccgo.common.Phase.valueOf(
                            alternative.gamePhase);
                } catch (IllegalArgumentException badPhase) {
                    LOG.warn("[ObjectiveAnalyzer] unknown gamePhase '{}' in"
                            + " objective_playbooks.json — fail-closed.",
                            alternative.gamePhase);
                    return false;
                }
                if (gameState.getCurrentPhase() != windowPhase) {
                    return false;
                }
                if (alternative.whosePhase != null) {
                    String phaseOwner = gameState.getCurrentPlayerId();
                    if ("self".equals(alternative.whosePhase)) {
                        if (!playerId.equals(phaseOwner)) return false;
                    } else if ("opponent".equals(alternative.whosePhase)) {
                        if (playerId.equals(phaseOwner)) return false;
                    } else {
                        LOG.warn("[ObjectiveAnalyzer] unknown whosePhase '{}'"
                                + " in objective_playbooks.json — fail-closed.",
                                alternative.whosePhase);
                        return false;
                    }
                }
            }

            // Batch Seventeen (2026-07-27): persistent-counter relation for
            // Watch Your Step's Kessel Run route. Reads the engine's
            // completed-Utinni-effect record; the counter survives the cards
            // leaving the table, exactly like the card law. Supports >= and
            // < comparators only; anything else fails closed with a warn.
            if ("utinniEffectCompleted".equals(alternative.relation)) {
                com.gempukku.swccgo.filters.Filter utinniFilter =
                        resolveFilter(alternative.actorFilterKey);
                if (utinniFilter == null || alternative.count == null
                        || controller == null) {
                    return false;
                }
                String comparator = alternative.count.comparator != null
                        ? alternative.count.comparator : ">=";
                boolean atLeast = game.getModifiersQuerying()
                        .hasCompletedUtinniEffect(gameState, controller,
                                alternative.count.value, utinniFilter);
                if (">=".equals(comparator)) {
                    return atLeast;
                }
                if ("<".equals(comparator)) {
                    return !atLeast;
                }
                LOG.warn("[ObjectiveAnalyzer] utinniEffectCompleted supports"
                        + " only >= and < comparators; got '{}' — fail-closed.",
                        comparator);
                return false;
            }

            // Extension batch (2026-07-29): blown-away relation (Rebel
            // Strike Team's Bunker routes). Reads the engine's SNAPSHOT
            // record (ModifiersLogic._blownAwayCards) — latched for the
            // rest of the game exactly like the card law, and immune to the
            // blown-away card later leaving the table. The snapshots carry
            // the pre-flag state, so both tolerant and one-arg title
            // filters match; profiles still pair this with a tolerant key
            // for clarity. Supports >= 1 and < 1 only; fail-closed warn
            // otherwise.
            if ("blownAway".equals(alternative.relation)) {
                com.gempukku.swccgo.filters.Filter blownFilter =
                        resolveLocationFilter(
                                alternative.locationFilterKey, playerId);
                if (blownFilter == null || alternative.count == null
                        || alternative.count.value == null
                        || alternative.count.value != 1) {
                    LOG.warn("[ObjectiveAnalyzer] blownAway needs a"
                            + " resolvable locationFilterKey and count value"
                            + " 1 — fail-closed.");
                    return false;
                }
                String blownComparator =
                        alternative.count.comparator != null
                                ? alternative.count.comparator : ">=";
                boolean anyBlown = game.getModifiersQuerying()
                        .isBlownAway(gameState, blownFilter);
                if (">=".equals(blownComparator)) {
                    return anyBlown;
                }
                if ("<".equals(blownComparator)) {
                    return !anyBlown;
                }
                LOG.warn("[ObjectiveAnalyzer] blownAway supports only >= and"
                        + " < comparators; got '{}' — fail-closed.",
                        blownComparator);
                return false;
            }

            int matchingLocations = countAlternativeMatches(
                    game, playerId, controller, alternative);
            boolean countSatisfied;
            RuleCount count = alternative.count;
            if (count != null && count.referenceController != null) {
                String referenceController =
                        "opponent".equals(count.referenceController)
                                ? gameState.getOpponent(playerId) : playerId;
                int referenceCount = referenceController == null ? 0
                        : countAlternativeMatches(
                                game, playerId, referenceController,
                                alternative);
                countSatisfied = compareCounts(
                        matchingLocations, referenceCount, count.comparator);
            } else {
                countSatisfied = compareCounts(
                        matchingLocations,
                        expectedCount(game, playerId, count),
                        count != null ? count.comparator : null);
            }
            return countSatisfied && opponentConstraintSatisfied(
                    game, playerId, alternative.opponentConstraint);
        } catch (Exception e) {
            LOG.debug("Structured objective location assessment failed: {}",
                    e.getMessage());
            return false;
        }
    }

    private int countAlternativeMatches(
            SwccgGame game, String playerId, String controller,
            FlipLocationAlternative alternative) {
        GameState gameState = game.getGameState();
        if ("onTable".equals(alternative.relation)) {
            com.gempukku.swccgo.filters.Filter actorFilter =
                    resolveFilter(alternative.actorFilterKey);
            Collection<PhysicalCard> permanents =
                    gameState.getAllPermanentCards();
            if (actorFilter == null || permanents == null) return 0;
            int matchingActors = 0;
            for (PhysicalCard card : permanents) {
                if (card == null
                        || controller != null
                            && !controller.equals(card.getOwner())
                        || !isActiveForSpot(
                                game, card,
                                alternative.includeExcludedFromBattle)
                        || !actorFilter.accepts(
                                gameState, game.getModifiersQuerying(),
                                card)) {
                    continue;
                }
                matchingActors++;
            }
            return matchingActors;
        }
        List<PhysicalCard> locations = gameState.getLocationsInOrder();
        if (locations == null) return 0;
        int matchingLocations = 0;
        for (PhysicalCard location : locations) {
            if (locationMatchesAlternative(
                    gameState, game, playerId, location, alternative)
                    && relationSatisfiedAt(
                            game, playerId, controller, location,
                            alternative.relation,
                            alternative.actorFilterKey,
                            alternative.includeExcludedFromBattle,
                            alternative.spotOverride)
                    && meetsPerLocationActorFloor(
                            game, controller, location, alternative)) {
                matchingLocations++;
            }
        }
        return matchingLocations;
    }

    /**
     * Extension batch (2026-07-29): per-location actor-count floor (Rebel
     * Strike Team's two-scouts-per-site law). A location only counts when
     * the controller has at least minActorsPerLocation matching actors
     * there. Mirrors the card law's spotting asymmetry: the first actor may
     * ride the alternative's spot override, but every actor beyond the
     * first must be FULLY ACTIVE because the source's inner with() takes no
     * SpotOverride.
     */
    private boolean meetsPerLocationActorFloor(
            SwccgGame game, String controller, PhysicalCard location,
            FlipLocationAlternative alternative) {
        if (alternative.minActorsPerLocation == null
                || alternative.minActorsPerLocation <= 1
                || alternative.actorFilterKey == null) {
            return true;
        }
        com.gempukku.swccgo.filters.Filter actorFilter =
                resolveFilter(alternative.actorFilterKey);
        if (actorFilter == null) return false;
        GameState gameState = game.getGameState();
        Collection<PhysicalCard> permanents = gameState.getAllPermanentCards();
        if (permanents == null) return false;
        int totalWithOverride = 0;
        int fullyActive = 0;
        for (PhysicalCard card : permanents) {
            if (card == null
                    || controller != null
                        && !controller.equals(card.getOwner())
                    || !actorFilter.accepts(
                            gameState, game.getModifiersQuerying(), card)) {
                continue;
            }
            PhysicalCard at = game.getModifiersQuerying()
                    .getLocationThatCardIsAt(gameState, card);
            if (at != location) continue;
            if (isActiveForSpot(
                    game, card, alternative.includeExcludedFromBattle)) {
                totalWithOverride++;
            }
            if (isActiveForSpot(game, card, Boolean.FALSE)) {
                fullyActive++;
            }
        }
        return totalWithOverride >= alternative.minActorsPerLocation
                && fullyActive >= alternative.minActorsPerLocation - 1;
    }

    private static String resolveController(
            GameState gameState, String playerId, String scope) {
        if ("any".equals(scope)) return null;
        if ("opponent".equals(scope)) {
            return gameState.getOpponent(playerId);
        }
        return playerId;
    }

    private static boolean isActivePreFlipRule(FlipLocationRule rule) {
        return rule != null && "preFlip".equals(rule.phase)
                && "flip".equals(rule.purpose)
                && rule.alternatives != null
                && !rule.alternatives.isEmpty();
    }

    private boolean isRuleSatisfied(
            SwccgGame game, String playerId, FlipLocationRule rule) {
        if (rule == null || rule.alternatives == null
                || rule.alternatives.isEmpty()) {
            return false;
        }
        if (isShieldMainGeneratorRouteRule(rule)) {
            return isShieldMainGeneratorRouteRuleSatisfied(
                    game, playerId);
        }
        if (isFirstOrderReignsRouteRule(rule)) {
            return isFirstOrderReignsHostControlled(
                    game, playerId);
        }
        if ("anyOf".equals(rule.mode)) {
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (isFlipLocationAlternativeSatisfied(
                        game, playerId, alternative)) {
                    return true;
                }
            }
            return false;
        }
        for (FlipLocationAlternative alternative : rule.alternatives) {
            if (!isFlipLocationAlternativeSatisfied(
                    game, playerId, alternative)) {
                return false;
            }
        }
        return true;
    }

    private static boolean isFirstOrderReignsRouteRule(
            FlipLocationRule rule) {
        return rule != null
                && "first-order-reigns-tracked-fleet-control"
                    .equals(rule.id);
    }

    public PhysicalCard
            getFirstOrderReignsTrackedFleetHostSystem(
                    SwccgGame game, String playerId) {
        if (!analyzed || !isFirstOrderReigns
                || isFlipped
                || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return null;
        }
        com.gempukku.swccgo.filters.Filter fleetFilter =
                resolveFilter("Tracked_Fleet");
        Collection<PhysicalCard> permanents =
                game.getGameState()
                    .getAllPermanentCards();
        if (fleetFilter == null || permanents == null) {
            return null;
        }
        for (PhysicalCard fleet : permanents) {
            if (fleet == null
                    || !playerId.equals(fleet.getOwner())
                    || fleet.getZone() == null
                    || !fleet.getZone().isInPlay()
                    || !isActiveForSpot(
                        game, fleet, true)
                    || !fleetFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        fleet)) {
                continue;
            }
            PhysicalCard host = fleet.getAttachedTo();
            if (host == null) {
                host = game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                        game.getGameState(), fleet);
            }
            if (host != null) return host;
        }
        return null;
    }

    public boolean isFirstOrderReignsHostControlled(
            SwccgGame game, String playerId) {
        PhysicalCard host =
                getFirstOrderReignsTrackedFleetHostSystem(
                    game, playerId);
        return host != null
                && game.getModifiersQuerying()
                    .controlsLocation(
                        game.getGameState(), host,
                        playerId);
    }

    public boolean isFirstOrderReignsSolePendingTriggerControlSource(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (!analyzed || isFlipped || !isFirstOrderReigns
                || game == null || playerId == null
                || candidate == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || !playerId.equals(candidate.getOwner())) {
            return false;
        }
        try {
            PhysicalCard host =
                    getFirstOrderReignsTrackedFleetHostSystem(
                        game, playerId);
            if (host == null
                    || !isFirstOrderReignsHostControlled(
                        game, playerId)) {
                return false;
            }
            PhysicalCard candidateLocation =
                    game.getModifiersQuerying()
                        .getLocationThatCardIsPresentAt(
                            game.getGameState(), candidate);
            return samePhysicalLocation(
                        candidateLocation, host)
                    && isSolePresenceSourceAtLocation(
                        game, playerId, candidate, host);
        } catch (Exception e) {
            LOG.debug(
                    "First Order Reigns pending control-source assessment failed: {}",
                    e.getMessage());
            return false;
        }
    }

    public boolean isFirstOrderReignsRouteOpen(
            SwccgGame game, String playerId) {
        return analyzed && isFirstOrderReigns
                && !isFlipped
                && getFirstOrderReignsTrackedFleetHostSystem(
                    game, playerId) != null
                && !isFirstOrderReignsHostControlled(
                    game, playerId);
    }

    public boolean isFirstOrderReignsNavyRouteAction(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText) {
        return FIRST_ORDER_NAVY_ROUTE_ACTION.equals(actionText)
                && isFirstOrderReignsNavySource(
                    game, playerId, sourceCard)
                && selectFirstOrderReignsNavyPackage(
                    game, playerId, sourceCard,
                    null, null, true) != null;
    }

    public boolean isFirstOrderReignsNavyRouteSelectionPrompt(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String decisionText) {
        if (decisionText == null
                || !FIRST_ORDER_NAVY_HAND_PROMPT.equals(
                        decisionText.trim())
                && !decisionText.toLowerCase(Locale.ROOT)
                    .startsWith(FIRST_ORDER_NAVY_RESERVE_PROMPT)) {
            return false;
        }
        return isFirstOrderReignsNavySource(
                    game, playerId, sourceCard)
                && selectFirstOrderReignsNavyPackage(
                    game, playerId, sourceCard,
                    null, null, true) != null;
    }

    public boolean isFirstOrderReignsNavyHandRouteCandidate(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String decisionText,
            PhysicalCard candidate) {
        if (!FIRST_ORDER_NAVY_HAND_PROMPT.equals(
                    decisionText)
                || !isFirstOrderReignsNavySource(
                    game, playerId, sourceCard)
                || candidate == null
                || candidate.getZone() != Zone.HAND) {
            return false;
        }
        FirstOrderReignsNavyPackage preferred =
                selectFirstOrderReignsNavyPackage(
                    game, playerId, sourceCard,
                    null, null, true);
        return preferred != null
                && preferred.handCard == candidate;
    }

    public boolean isFirstOrderReignsNavyReserveRouteCandidate(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String decisionText,
            PhysicalCard candidate) {
        if (decisionText == null
                || !decisionText.toLowerCase(Locale.ROOT)
                    .startsWith(FIRST_ORDER_NAVY_RESERVE_PROMPT)
                || !isFirstOrderReignsNavySource(
                    game, playerId, sourceCard)
                || candidate == null
                || candidate.getZone() != Zone.RESERVE_DECK) {
            return false;
        }
        String selectedHandBlueprint = null;
        Matcher matcher =
                CARD_HINT_BLUEPRINT_PATTERN.matcher(
                    decisionText);
        if (matcher.find()) {
            selectedHandBlueprint =
                    matcher.group(1);
        }
        List<PhysicalCard> hand =
                game.getGameState().getHand(playerId);
        if (hand == null) return false;
        for (PhysicalCard handCard : hand) {
            if (handCard == null
                    || selectedHandBlueprint != null
                    && !selectedHandBlueprint.equals(
                        handCard.getBlueprintId(true))) {
                continue;
            }
            FirstOrderReignsNavyPackage preferred =
                    selectFirstOrderReignsNavyPackage(
                    game, playerId, sourceCard,
                    handCard, null, true);
            if (preferred != null
                    && preferred.reserveCard
                        == candidate) {
                return true;
            }
        }
        return false;
    }

    public boolean isFirstOrderReignsNavyRouteDestinationCandidate(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String decisionText,
            PhysicalCard candidate) {
        if (decisionText == null
                || candidate == null
                || !decisionText.toLowerCase(Locale.ROOT)
                    .startsWith("choose where to deploy ")
                || !decisionText.toLowerCase(Locale.ROOT)
                    .contains(" simultaneously")
                || !isFirstOrderReignsNavySource(
                    game, playerId, sourceCard)) {
            return false;
        }
        FirstOrderReignsNavyPackage preferred =
                selectFirstOrderReignsNavyPackage(
                    game, playerId, sourceCard,
                    null, null, true);
        if (preferred == null
                || !samePhysicalLocation(
                    preferred.stage, candidate)) {
            return false;
        }
        List<String> hintedBlueprints =
                new ArrayList<>();
        Matcher matcher =
                CARD_HINT_BLUEPRINT_PATTERN.matcher(
                    decisionText);
        while (matcher.find()) {
            hintedBlueprints.add(
                    matcher.group(1));
        }
        return hintedBlueprints.contains(
                    preferred.handCard
                        .getBlueprintId(true))
                && hintedBlueprints.contains(
                    preferred.reserveCard
                        .getBlueprintId(true));
    }

    public boolean isFirstOrderReignsDownloadAction(
            PhysicalCard sourceCard, String actionText) {
        if (!analyzed || !isFirstOrderReigns
                || sourceCard == null
                || actionText == null
                || !"Deploy Supremacy card or battleground"
                    .equals(actionText)) {
            return false;
        }
        String blueprintId =
                sourceCard.getBlueprintId(true);
        return "225_32".equals(blueprintId)
                || "225_32_BACK".equals(blueprintId)
                || "501_60".equals(blueprintId)
                || "501_60_BACK".equals(blueprintId);
    }

    public boolean isFirstOrderReignsLostPileDeployAction(
            PhysicalCard sourceCard, String actionText) {
        if (!analyzed || !isFlipped || !isFirstOrderReigns
                || sourceCard == null
                || !"Deploy card from Lost Pile"
                    .equals(actionText)) {
            return false;
        }
        String blueprintId =
                sourceCard.getBlueprintId(true);
        return "225_32".equals(blueprintId)
                || "225_32_BACK".equals(blueprintId)
                || "501_60".equals(blueprintId)
                || "501_60_BACK".equals(blueprintId);
    }

    public boolean hasLegalFirstOrderReignsLostPileDeployCandidate(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard) {
        if (!isFirstOrderReignsLostPileDeployAction(
                    sourceCard,
                    "Deploy card from Lost Pile")
                || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        List<PhysicalCard> lostPile =
                game.getGameState()
                    .getLostPile(playerId);
        if (lostPile == null) return false;
        com.gempukku.swccgo.filters.Filter objectiveFilter =
                Filters.or(
                    Filters.and(
                        Filters.non_unique,
                        Filters.trooper),
                    Filters.and(
                        Filters.non_unique,
                        Icon.FIRST_ORDER,
                        Filters.vehicle));
        com.gempukku.swccgo.filters.Filter deployable =
                Filters.deployable(
                    sourceCard, null, false, 0.0f);
        for (PhysicalCard candidate : lostPile) {
            if (candidate != null
                    && playerId.equals(candidate.getOwner())
                    && objectiveFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        candidate)
                    && deployable.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        candidate)) {
                return true;
            }
        }
        return false;
    }

    public boolean hasFirstOrderReignsKyloCraitPayoff(
            SwccgGame game, String playerId) {
        if (!analyzed || !isFirstOrderReigns || !isFlipped
                || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        com.gempukku.swccgo.filters.Filter craitLocation =
                resolveLocationFilter("Crait_location", playerId);
        List<PhysicalCard> locations =
                game.getGameState().getLocationsInOrder();
        if (craitLocation == null || locations == null) {
            return false;
        }
        for (PhysicalCard location : locations) {
            if (location != null
                    && craitLocation.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), location)
                    && relationSatisfiedAt(
                        game, playerId, playerId, location,
                        "occupyWith", "Kylo", false)) {
                return true;
            }
        }
        return false;
    }

    public boolean advancesFirstOrderReignsDrainPairAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            PhysicalCard destination) {
        return isFirstOrderReignsDrainPairCandidate(
                    game, playerId, candidate, destination)
                && countActiveFirstOrderCharactersAt(
                    game, playerId, destination, candidate) == 1;
    }

    public boolean breaksFirstOrderReignsDrainPairIfMoved(
            SwccgGame game, String playerId,
            PhysicalCard mover,
            PhysicalCard destination) {
        if (!isFirstOrderReignsDrainPairMemberAtExactPair(
                    game, playerId, mover)
                || destination == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        PhysicalCard origin =
                game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                        game.getGameState(), mover);
        return origin != null
                && !samePhysicalLocation(origin, destination);
    }

    public boolean isFirstOrderReignsDrainPairMemberAtExactPair(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (!hasFirstOrderReignsKyloCraitPayoff(
                    game, playerId)
                || candidate == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || !isActiveForSpot(game, candidate, false)
                || !Filters.First_Order_character.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), candidate)) {
            return false;
        }
        PhysicalCard origin =
                game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                        game.getGameState(), candidate);
        return origin != null
                && Filters.battleground.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), origin)
                && countActiveFirstOrderCharactersAt(
                    game, playerId, origin, null) == 2;
    }

    private boolean isFirstOrderReignsDrainPairCandidate(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            PhysicalCard destination) {
        if (!hasFirstOrderReignsKyloCraitPayoff(
                    game, playerId)
                || candidate == null || destination == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || !Filters.First_Order_character.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), candidate)
                || !Filters.battleground.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), destination)) {
            return false;
        }
        return candidate.getZone() == null
                || !candidate.getZone().isInPlay()
                || isActiveForSpot(game, candidate, false);
    }

    private int countActiveFirstOrderCharactersAt(
            SwccgGame game, String playerId,
            PhysicalCard location,
            PhysicalCard excluded) {
        if (game == null || playerId == null || location == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents == null) return 0;
        int count = 0;
        for (PhysicalCard card : permanents) {
            if (card == null || card == excluded
                    || !playerId.equals(card.getOwner())
                    || !isActiveForSpot(game, card, false)
                    || !Filters.First_Order_character.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), card)) {
                continue;
            }
            PhysicalCard cardLocation =
                    game.getModifiersQuerying()
                        .getLocationThatCardIsAt(
                            game.getGameState(), card);
            if (samePhysicalLocation(
                    cardLocation, location)) {
                count++;
            }
        }
        return count;
    }

    public boolean hasFirstOrderReignsRouteProgressCandidateInReserve(
            SwccgGame game, String playerId) {
        if (!isFirstOrderReignsRouteOpen(
                    game, playerId)
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            GameState gameState = game.getGameState();
            PhysicalCard objective =
                    findOurObjective(gameState, playerId);
            if (objective == null) return false;
            List<PhysicalCard> reserve =
                    gameState.getReserveDeck(playerId);
            if (reserve == null) return false;
            com.gempukku.swccgo.filters.Filter deployable =
                    Filters.deployable(
                        objective, null, false, 0.0f);
            for (PhysicalCard candidate : reserve) {
                ObjectiveProgressCandidateRole role =
                        classifyFirstOrderReignsProgressCandidate(
                            game, playerId, candidate);
                if ((role
                        == ObjectiveProgressCandidateRole
                            .REQUIRED_LOCATION
                        || role
                        == ObjectiveProgressCandidateRole
                            .REQUIRED_ACTOR)
                        && deployable.accepts(
                            gameState,
                            game.getModifiersQuerying(),
                            candidate)) {
                    return true;
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "First Order Reigns route candidate assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    private boolean isFirstOrderReignsSupremacy(
            SwccgGame game, PhysicalCard card) {
        if (game == null || card == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || card.getBlueprint() == null
                || card.getBlueprint().getCardCategory()
                    != CardCategory.STARSHIP) {
            return false;
        }
        com.gempukku.swccgo.filters.Filter filter =
                resolveFilter("Supremacy");
        return filter != null && filter.accepts(
                game.getGameState(),
                game.getModifiersQuerying(), card);
    }

    private boolean isFirstOrderReignsChaseShipCandidate(
            SwccgGame game, String playerId,
            PhysicalCard card) {
        if (game == null || playerId == null
                || card == null
                || !playerId.equals(card.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || card.getBlueprint() == null
                || card.getBlueprint().getCardCategory()
                    != CardCategory.STARSHIP) {
            return false;
        }
        if (isFirstOrderReignsSupremacy(
                game, card)) {
            return true;
        }
        try {
            boolean inPlay = card.getZone() != null
                    && card.getZone().isInPlay();
            if (!inPlay
                    && !card.getBlueprint()
                        .hasIcon(Icon.EPISODE_VII)) {
                return false;
            }
            boolean piloted = inPlay
                    ? game.getModifiersQuerying()
                        .isPiloted(
                            game.getGameState(),
                            card, false)
                    : game.getModifiersQuerying()
                        .getHighestAbilityPiloting(
                            game.getGameState(),
                            card, true, false) >= 1.0f;
            return piloted
                    && game.getModifiersQuerying()
                        .hasAstromechOrNavComputer(
                            game.getGameState(), card);
        } catch (Exception e) {
            LOG.debug(
                    "First Order Reigns chase-ship assessment failed: {}",
                    e.getMessage());
            return false;
        }
    }

    private boolean isFirstOrderReignsNavySource(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard) {
        return isFirstOrderReignsRouteOpen(
                    game, playerId)
                && sourceCard != null
                && playerId.equals(
                    sourceCard.getOwner())
                && FIRST_ORDER_NAVY_BLUEPRINT_ID.equals(
                    sourceCard.getBlueprintId(true))
                && sourceCard.getZone() != null
                && sourceCard.getZone().isInPlay()
                && isActiveForSpot(
                    game, sourceCard, true);
    }

    private boolean isFirstOrderReignsNavyPair(
            SwccgGame game,
            PhysicalCard handCard,
            PhysicalCard reserveCard) {
        if (game == null || handCard == null
                || reserveCard == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        boolean handPilot =
                Filters.First_Order_pilot.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(),
                    handCard);
        boolean handStarship =
                Filters.First_Order_starship.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(),
                    handCard);
        boolean reservePilot =
                Filters.First_Order_pilot.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(),
                    reserveCard);
        boolean reserveStarship =
                Filters.First_Order_starship.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(),
                    reserveCard);
        return handPilot && reserveStarship
                || handStarship && reservePilot;
    }

    private boolean canFirstOrderReignsNavyShipReachHost(
            SwccgGame game, PhysicalCard starship,
            PhysicalCard stage, PhysicalCard host) {
        if (game == null || starship == null
                || stage == null || host == null
                || samePhysicalLocation(stage, host)
                || !isFirstOrderReignsEpisodeSevenSystem(
                    game, stage, false)
                || starship.getBlueprint() == null
                || !starship.getBlueprint()
                    .hasIcon(Icon.EPISODE_VII)
                || !game.getModifiersQuerying()
                    .hasAstromechOrNavComputer(
                        game.getGameState(), starship)) {
            return false;
        }
        try {
            if (game.getModifiersQuerying()
                    .hasNoHyperdrive(
                        game.getGameState(), starship)
                    || game.getModifiersQuerying()
                        .mayNotMoveUsingHyperspeed(
                            game.getGameState(), starship)
                    || game.getModifiersQuerying()
                        .mayNotMoveFromLocationToLocationUsingHyperspeed(
                            game.getGameState(), starship,
                            stage, host, false)) {
                return false;
            }
            return game.getModifiersQuerying()
                    .getHyperspeed(
                        game.getGameState(), starship,
                        stage, host)
                    >= Math.abs(
                        stage.getParsec()
                            - host.getParsec());
        } catch (Exception e) {
            LOG.debug(
                    "First Order Navy chase-range assessment failed: {}",
                    e.getMessage());
            return false;
        }
    }

    private FirstOrderReignsNavyPackage
            selectFirstOrderReignsNavyPackage(
                    SwccgGame game, String playerId,
                    PhysicalCard sourceCard,
                    PhysicalCard requiredHandCard,
                    PhysicalCard requiredReserveCard,
                    boolean requireAffordable) {
        if (!isFirstOrderReignsNavySource(
                    game, playerId, sourceCard)
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return null;
        }
        List<PhysicalCard> hand =
                game.getGameState().getHand(playerId);
        List<PhysicalCard> reserve =
                game.getGameState()
                    .getReserveDeck(playerId);
        List<PhysicalCard> locations =
                game.getGameState()
                    .getLocationsInOrder();
        PhysicalCard host =
                getFirstOrderReignsTrackedFleetHostSystem(
                    game, playerId);
        if (hand == null || reserve == null
                || locations == null || host == null) {
            return null;
        }
        float availableForce =
                game.getModifiersQuerying()
                    .getForceAvailableToUse(
                        game.getGameState(), playerId);
        FirstOrderReignsNavyPackage best = null;
        for (PhysicalCard handCard : hand) {
            if (handCard == null
                    || handCard.getZone() != Zone.HAND
                    || requiredHandCard != null
                    && handCard != requiredHandCard) {
                continue;
            }
            for (PhysicalCard reserveCard : reserve) {
                if (reserveCard == null
                        || reserveCard.getZone()
                            != Zone.RESERVE_DECK
                        || requiredReserveCard != null
                        && reserveCard
                            != requiredReserveCard
                        || !isFirstOrderReignsNavyPair(
                            game, handCard,
                            reserveCard)) {
                    continue;
                }
                PhysicalCard starship =
                        Filters.First_Order_starship
                            .accepts(
                                game.getGameState(),
                                game.getModifiersQuerying(),
                                handCard)
                        ? handCard : reserveCard;
                PhysicalCard pilot =
                        starship == handCard
                        ? reserveCard : handCard;
                for (PhysicalCard stage : locations) {
                    if (!canFirstOrderReignsNavyShipReachHost(
                            game, starship,
                            stage, host)) {
                        continue;
                    }
                    try {
                        boolean legalShape =
                                Filters
                                    .deployableToLocationSimultaneouslyWith(
                                        sourceCard,
                                        handCard,
                                        false, 0.0f,
                                        Filters.sameCardId(
                                            stage),
                                        false, 0.0f)
                                    .accepts(
                                        game.getGameState(),
                                        game.getModifiersQuerying(),
                                        reserveCard);
                        if (!legalShape) continue;
                        float exactCost =
                                game.getModifiersQuerying()
                                    .getSimultaneousDeployCost(
                                        game.getGameState(),
                                        sourceCard,
                                        starship,
                                        false, 0.0f,
                                        pilot,
                                        false, 0.0f,
                                        stage, null, true);
                        if (requireAffordable
                                && exactCost
                                    > availableForce) {
                            continue;
                        }
                        int cost = (int) Math.ceil(
                                Math.max(0.0f,
                                    exactCost));
                        FirstOrderReignsNavyPackage
                                candidate =
                                    new FirstOrderReignsNavyPackage(
                                        handCard,
                                        reserveCard,
                                        starship,
                                        pilot,
                                        stage,
                                        cost,
                                        firstOrderReignsPrintedDeployCost(
                                            starship));
                        if (best == null
                                || candidate.cost
                                    < best.cost
                                || candidate.cost
                                    == best.cost
                                && candidate
                                    .starshipPrintedDeployCost
                                    < best
                                        .starshipPrintedDeployCost
                                || candidate.cost
                                    == best.cost
                                && candidate
                                    .starshipPrintedDeployCost
                                    == best
                                        .starshipPrintedDeployCost
                                && candidate.reserveCard
                                    .getPermanentCardId()
                                    < best.reserveCard
                                        .getPermanentCardId()) {
                            best = candidate;
                        }
                    } catch (Exception e) {
                        LOG.debug(
                                "First Order Navy package assessment failed: {}",
                                e.getMessage());
                    }
                }
            }
        }
        return best;
    }

    private float firstOrderReignsPrintedDeployCost(
            PhysicalCard card) {
        if (card == null
                || card.getBlueprint() == null) {
            return Float.MAX_VALUE;
        }
        try {
            Float cost =
                    card.getBlueprint()
                        .getDeployCost();
            return cost != null
                    ? cost : Float.MAX_VALUE;
        } catch (UnsupportedOperationException e) {
            return Float.MAX_VALUE;
        }
    }

    private int getFirstOrderReignsNavyPackageReserve(
            SwccgGame game, String playerId) {
        PhysicalCard navy =
                findFirstOrderReignsNavySource(
                    game, playerId);
        FirstOrderReignsNavyPackage route =
                selectFirstOrderReignsNavyPackage(
                    game, playerId, navy,
                    null, null, false);
        return route == null ? 0 : route.cost;
    }

    private boolean hasFirstOrderReignsNavyPackage(
            SwccgGame game, String playerId) {
        PhysicalCard navy =
                findFirstOrderReignsNavySource(
                    game, playerId);
        return selectFirstOrderReignsNavyPackage(
                    game, playerId, navy,
                    null, null, false) != null;
    }

    private PhysicalCard findFirstOrderReignsNavySource(
            SwccgGame game, String playerId) {
        if (game == null
                || game.getGameState() == null) {
            return null;
        }
        Collection<PhysicalCard> permanents =
                game.getGameState()
                    .getAllPermanentCards();
        if (permanents == null) return null;
        for (PhysicalCard card : permanents) {
            if (isFirstOrderReignsNavySource(
                    game, playerId, card)) {
                return card;
            }
        }
        return null;
    }

    private static final class
            FirstOrderReignsNavyPackage {
        private final PhysicalCard handCard;
        private final PhysicalCard reserveCard;
        private final PhysicalCard starship;
        private final PhysicalCard pilot;
        private final PhysicalCard stage;
        private final int cost;
        private final float starshipPrintedDeployCost;

        private FirstOrderReignsNavyPackage(
                PhysicalCard handCard,
                PhysicalCard reserveCard,
                PhysicalCard starship,
                PhysicalCard pilot,
                PhysicalCard stage,
                int cost,
                float starshipPrintedDeployCost) {
            this.handCard = handCard;
            this.reserveCard = reserveCard;
            this.starship = starship;
            this.pilot = pilot;
            this.stage = stage;
            this.cost = cost;
            this.starshipPrintedDeployCost =
                    starshipPrintedDeployCost;
        }
    }

    private boolean canFirstOrderReignsShipStageAt(
            SwccgGame game, String playerId,
            PhysicalCard host, PhysicalCard stage,
            PhysicalCard chaseShip,
            boolean requireBattleground) {
        if (game == null || playerId == null
                || host == null || stage == null
                || chaseShip == null
                || samePhysicalLocation(host, stage)
                || !isFirstOrderReignsEpisodeSevenSystem(
                    game, stage, requireBattleground)
                || !isFirstOrderReignsChaseShipCandidate(
                    game, playerId, chaseShip)) {
            return false;
        }
        try {
            if (game.getModifiersQuerying()
                    .hasNoHyperdrive(
                        game.getGameState(), chaseShip)
                    || game.getModifiersQuerying()
                        .mayNotMoveUsingHyperspeed(
                            game.getGameState(), chaseShip)
                    || game.getModifiersQuerying()
                        .mayNotMoveFromLocationToLocationUsingHyperspeed(
                            game.getGameState(), chaseShip,
                            stage, host, false)) {
                return false;
            }
            float hyperspeed =
                    game.getModifiersQuerying()
                        .getHyperspeed(
                            game.getGameState(), chaseShip,
                            stage, host);
            if (hyperspeed <= 0
                    && isFirstOrderReignsSupremacy(
                        game, chaseShip)) {
                hyperspeed = 2.0f;
            }
            return hyperspeed >= Math.abs(
                    stage.getParsec() - host.getParsec());
        } catch (Exception e) {
            LOG.debug(
                    "First Order Reigns staging-range assessment failed: {}",
                    e.getMessage());
            return false;
        }
    }

    private boolean isFirstOrderReignsStageSystem(
            SwccgGame game, String playerId,
            PhysicalCard host,
            PhysicalCard candidate,
            boolean requireBattleground) {
        if (game == null || playerId == null
                || host == null
                || candidate == null
                || samePhysicalLocation(host, candidate)
                || !isFirstOrderReignsEpisodeSevenSystem(
                    game, candidate, requireBattleground)) {
            return false;
        }
        for (PhysicalCard chaseShip
                : getFirstOrderReignsAccessibleChaseShipCards(
                    game, playerId)) {
            if (canFirstOrderReignsShipStageAt(
                    game, playerId, host,
                    candidate, chaseShip,
                    requireBattleground)) {
                return true;
            }
        }
        // The objective can always download Supremacy. Its printed
        // hyperspeed 2 remains the source-backed fallback when no physical
        // copy is visible in a searchable pile.
        return Math.abs(
                candidate.getParsec() - host.getParsec())
                <= 2;
    }

    private boolean isFirstOrderReignsEpisodeSevenSystem(
            SwccgGame game, PhysicalCard candidate,
            boolean requireBattleground) {
        if (game == null || candidate == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        com.gempukku.swccgo.filters.Filter filter =
                resolveLocationFilter(
                    requireBattleground
                        ? "Episode_VII_battleground_system"
                        : "Episode_VII_system",
                    null);
        if (filter == null || !filter.accepts(
                game.getGameState(),
                game.getModifiersQuerying(),
                candidate)) {
            return false;
        }
        return true;
    }

    private boolean isFirstOrderReignsReachableBridgeSystem(
            SwccgGame game, String playerId,
            PhysicalCard host, PhysicalCard chaseShip,
            PhysicalCard candidate) {
        if (game == null || playerId == null
                || host == null || chaseShip == null
                || candidate == null
                || !isFirstOrderReignsEpisodeSevenSystem(
                    game, candidate, true)
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        PhysicalCard origin =
                game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                        game.getGameState(), chaseShip);
        if (origin == null
                || Math.abs(candidate.getParsec()
                        - host.getParsec())
                    >= Math.abs(origin.getParsec()
                        - host.getParsec())) {
            return false;
        }
        return Filters.canMoveToUsingHyperspeed(
                playerId, chaseShip,
                false, true, 0.0f).accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(),
                    candidate);
    }

    private boolean hasFirstOrderReignsStagingSystem(
            SwccgGame game, String playerId,
            PhysicalCard host) {
        if (game == null || playerId == null
                || host == null
                || game.getGameState() == null) {
            return false;
        }
        List<PhysicalCard> locations =
                game.getGameState()
                    .getLocationsInOrder();
        if (locations == null) return false;
        for (PhysicalCard location : locations) {
            if (isFirstOrderReignsStageSystem(
                    game, playerId, host,
                    location, false)) {
                return true;
            }
        }
        return false;
    }

    private boolean hasFirstOrderReignsStageForShip(
            SwccgGame game, String playerId,
            PhysicalCard host,
            PhysicalCard chaseShip) {
        if (game == null || playerId == null
                || host == null || chaseShip == null
                || game.getGameState() == null) {
            return false;
        }
        List<PhysicalCard> locations =
                game.getGameState()
                    .getLocationsInOrder();
        if (locations == null) return false;
        for (PhysicalCard location : locations) {
            if (canFirstOrderReignsShipStageAt(
                    game, playerId, host,
                    location, chaseShip, false)
                    && canFirstOrderReignsShipDeployAt(
                        game, playerId,
                        chaseShip, location)) {
                return true;
            }
        }
        return false;
    }

    private boolean canFirstOrderReignsShipDeployAt(
            SwccgGame game, String playerId,
            PhysicalCard chaseShip,
            PhysicalCard stage) {
        if (game == null || playerId == null
                || chaseShip == null || stage == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            PhysicalCard source = chaseShip;
            if (chaseShip.getZone()
                    == Zone.RESERVE_DECK
                    && isFirstOrderReignsSupremacy(
                        game, chaseShip)) {
                source = findOurObjective(
                        game.getGameState(), playerId);
            }
            return source != null
                    && Filters.deployableToLocation(
                        source,
                        Filters.sameCardId(stage),
                        true, 0.0f).accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(),
                            chaseShip);
        } catch (Exception e) {
            LOG.debug(
                    "First Order Reigns ship-deploy assessment failed: {}",
                    e.getMessage());
            return false;
        }
    }

    private List<PhysicalCard>
            getFirstOrderReignsChaseShipsOnTable(
            SwccgGame game, String playerId) {
        if (game == null || playerId == null
                || game.getGameState() == null) {
            return List.of();
        }
        Collection<PhysicalCard> permanents =
                game.getGameState()
                    .getAllPermanentCards();
        if (permanents == null) return List.of();
        List<PhysicalCard> result =
                new ArrayList<>();
        for (PhysicalCard card : permanents) {
            if (card != null
                    && playerId.equals(card.getOwner())
                    && card.getZone() != null
                    && card.getZone().isInPlay()
                    && isActiveForSpot(
                        game, card, true)
                    && isFirstOrderReignsChaseShipCandidate(
                        game, playerId, card)) {
                result.add(card);
            }
        }
        return result;
    }

    private List<PhysicalCard>
            getFirstOrderReignsAdvancingChaseShipsOnTable(
                    SwccgGame game, String playerId,
                    PhysicalCard host) {
        List<PhysicalCard> result =
                new ArrayList<>();
        for (PhysicalCard chaseShip
                : getFirstOrderReignsChaseShipsOnTable(
                    game, playerId)) {
            if (getFirstOrderReignsNextMoveForceReserve(
                    game, playerId,
                    chaseShip, host) >= 0) {
                result.add(chaseShip);
            }
        }
        return result;
    }

    private List<PhysicalCard>
            getFirstOrderReignsAccessibleChaseShipCards(
                    SwccgGame game, String playerId) {
        if (game == null || playerId == null
                || game.getGameState() == null) {
            return List.of();
        }
        List<PhysicalCard> result =
                new ArrayList<>();
        List<PhysicalCard> hand =
                game.getGameState().getHand(playerId);
        if (hand != null) result.addAll(hand);
        List<PhysicalCard> reserve =
                game.getGameState()
                    .getReserveDeck(playerId);
        if (reserve != null) {
            for (PhysicalCard card : reserve) {
                if (isFirstOrderReignsSupremacy(
                        game, card)) {
                    result.add(card);
                }
            }
        }
        return result;
    }

    private boolean hasFirstOrderReignsChaseShipIn(
            SwccgGame game, String playerId,
            Iterable<PhysicalCard> cards,
            PhysicalCard excluded,
            PhysicalCard host) {
        if (cards == null) return false;
        for (PhysicalCard card : cards) {
            if (card != null && card != excluded
                    && playerId.equals(card.getOwner())
                    && isFirstOrderReignsChaseShipCandidate(
                        game, playerId, card)
                    && hasFirstOrderReignsStageForShip(
                        game, playerId, host, card)) {
                return true;
            }
        }
        return false;
    }

    private int getFirstOrderReignsChaseShipDeployReserve(
            SwccgGame game, String playerId,
            PhysicalCard host,
            PhysicalCard excluded) {
        if (game == null || playerId == null
                || host == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        int minimum = Integer.MAX_VALUE;
        for (PhysicalCard candidate
                : getFirstOrderReignsAccessibleChaseShipCards(
                    game, playerId)) {
            if (candidate == null || candidate == excluded
                    || !isFirstOrderReignsChaseShipCandidate(
                        game, playerId, candidate)
                    || !hasFirstOrderReignsStageForShip(
                        game, playerId, host, candidate)) {
                continue;
            }
            float cost = isFirstOrderReignsSupremacy(
                    game, candidate)
                    ? 7.0f
                    : game.getModifiersQuerying()
                        .getDeployCost(
                            game.getGameState(), candidate);
            minimum = Math.min(
                    minimum,
                    (int) Math.ceil(Math.max(0.0f, cost)));
        }
        return minimum == Integer.MAX_VALUE
                ? 0 : minimum;
    }

    private boolean isFirstOrderReignsCrewCandidate(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (game == null || playerId == null
                || candidate == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || candidate.getBlueprint() == null
                || candidate.getBlueprint().getCardCategory()
                    != CardCategory.CHARACTER
                || !Filters.First_Order_character.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(),
                    candidate)) {
            return false;
        }
        return true;
    }

    private boolean canFirstOrderReignsCrewBoard(
            SwccgGame game, PhysicalCard crew,
            PhysicalCard chaseShip) {
        if (game == null || crew == null
                || chaseShip == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            boolean hasCapacity =
                    game.getGameState()
                        .getAvailablePilotCapacity(
                            game.getModifiersQuerying(),
                            chaseShip, crew) > 0
                    || game.getGameState()
                        .getAvailablePassengerCapacity(
                            game.getModifiersQuerying(),
                            chaseShip, crew) > 0;
            if (!hasCapacity
                    || !Filters.deployableToTarget(
                        crew,
                        Filters.sameCardId(chaseShip),
                        true, 0.0f).accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(),
                            crew)) {
                return false;
            }
            return getFirstOrderReignsCrewDeployCost(
                    game, crew, chaseShip) <= 3.0f;
        } catch (Exception e) {
            LOG.debug(
                    "First Order Reigns crew-boarding assessment failed: {}",
                    e.getMessage());
            return false;
        }
    }

    private float getFirstOrderReignsCrewDeployCost(
            SwccgGame game, PhysicalCard crew,
            PhysicalCard chaseShip) {
        return game.getModifiersQuerying()
                .getDeployCost(
                    game.getGameState(),
                    crew, crew, chaseShip,
                    false, null, false,
                    0.0f, null, true);
    }

    public boolean advancesFirstOrderReignsRouteCrewAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            PhysicalCard destination) {
        if (!isFirstOrderReignsRouteOpen(
                    game, playerId)
                || !isFirstOrderReignsCrewCandidate(
                    game, playerId, candidate)
                || destination == null
                || !getFirstOrderReignsAdvancingChaseShipsOnTable(
                    game, playerId,
                    getFirstOrderReignsTrackedFleetHostSystem(
                        game, playerId))
                    .contains(destination)) {
            return false;
        }
        return canFirstOrderReignsCrewBoard(
                game, candidate, destination);
    }

    private boolean hasFirstOrderReignsCrewAboard(
            SwccgGame game, String playerId,
            List<PhysicalCard> chaseShips) {
        if (game == null || playerId == null
                || chaseShips == null
                || chaseShips.isEmpty()
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        Collection<PhysicalCard> permanents =
                game.getGameState()
                    .getAllPermanentCards();
        if (permanents == null) return false;
        for (PhysicalCard card : permanents) {
            if (card == null
                    || !playerId.equals(card.getOwner())
                    || card.getZone() == null
                    || !card.getZone().isInPlay()
                    || !Filters.First_Order_character.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        card)) {
                continue;
            }
            for (PhysicalCard chaseShip : chaseShips) {
                if (samePhysicalLocation(
                        card.getAttachedTo(), chaseShip)) {
                    return true;
                }
            }
        }
        return false;
    }

    private int getFirstOrderReignsCrewReserve(
            SwccgGame game, String playerId,
            List<PhysicalCard> chaseShips,
            PhysicalCard currentDeployCandidate) {
        if (chaseShips == null || chaseShips.isEmpty()
                || hasFirstOrderReignsCrewAboard(
                    game, playerId, chaseShips)) {
            return 0;
        }
        if (isFirstOrderReignsCrewCandidate(
                game, playerId, currentDeployCandidate)) {
            for (PhysicalCard chaseShip : chaseShips) {
                if (canFirstOrderReignsCrewBoard(
                        game, currentDeployCandidate,
                        chaseShip)) {
                    return 0;
                }
            }
        }
        int minimum = Integer.MAX_VALUE;
        List<PhysicalCard> hand =
                game.getGameState().getHand(playerId);
        if (hand == null) return 0;
        for (PhysicalCard candidate : hand) {
            if (!isFirstOrderReignsCrewCandidate(
                    game, playerId, candidate)) {
                continue;
            }
            int candidateMinimum = Integer.MAX_VALUE;
            for (PhysicalCard chaseShip : chaseShips) {
                if (canFirstOrderReignsCrewBoard(
                        game, candidate, chaseShip)) {
                    candidateMinimum = Math.min(
                            candidateMinimum,
                            (int) Math.ceil(
                                getFirstOrderReignsCrewDeployCost(
                                    game, candidate,
                                    chaseShip)));
                }
            }
            if (candidateMinimum
                    == Integer.MAX_VALUE) continue;
            minimum = Math.min(
                    minimum,
                    Math.max(0, candidateMinimum));
        }
        return minimum == Integer.MAX_VALUE
                ? 0 : minimum;
    }

    public boolean
            isFirstOrderReignsPrematureGroundDeploymentAt(
                    SwccgGame game, String playerId,
                    PhysicalCard candidate,
                    PhysicalCard destination) {
        if (!isFirstOrderReignsRouteOpen(
                    game, playerId)
                || candidate == null
                || destination == null
                || !playerId.equals(candidate.getOwner())
                || candidate.getBlueprint() == null
                || candidate.getBlueprint().getCardCategory()
                    != CardCategory.CHARACTER
                || destination.getBlueprint() == null
                || destination.getBlueprint()
                    .getCardCategory()
                    != CardCategory.LOCATION
                || destination.getBlueprint()
                    .getCardSubtype()
                    != com.gempukku.swccgo.common.CardSubtype
                        .SITE
                || advancesFirstOrderReignsRouteCrewAt(
                    game, playerId,
                    candidate, destination)) {
            return false;
        }
        PhysicalCard host =
                getFirstOrderReignsTrackedFleetHostSystem(
                    game, playerId);
        return !getFirstOrderReignsAdvancingChaseShipsOnTable(
                    game, playerId, host).isEmpty()
                || hasFirstOrderReignsChaseShipIn(
                    game, playerId,
                    getFirstOrderReignsAccessibleChaseShipCards(
                        game, playerId),
                    null, host)
                || hasFirstOrderReignsNavyPackage(
                    game, playerId);
    }

    public boolean
            isFirstOrderReignsPrematureCraitGroundDeploymentAt(
                    SwccgGame game, String playerId,
                    PhysicalCard candidate,
                    PhysicalCard destination) {
        return isFirstOrderReignsPrematureGroundDeploymentAt(
                game, playerId, candidate, destination);
    }

    public int getFirstOrderReignsRouteForceReserve(
            SwccgGame game, String playerId,
            PhysicalCard currentDeployCandidate) {
        if (!isFirstOrderReignsRouteOpen(
                    game, playerId)
                || game.getGameState() == null) {
            return 0;
        }
        PhysicalCard host =
                getFirstOrderReignsTrackedFleetHostSystem(
                    game, playerId);
        List<PhysicalCard> chaseShips =
                getFirstOrderReignsAdvancingChaseShipsOnTable(
                        game, playerId, host);
        if (!chaseShips.isEmpty()) {
            return getFirstOrderReignsCurrentMoveForceReserve(
                        game, playerId)
                    + getFirstOrderReignsCrewReserve(
                        game, playerId, chaseShips,
                        currentDeployCandidate);
        }
        if (isFirstOrderReignsChaseShipCandidate(
                    game, playerId,
                    currentDeployCandidate)
                && hasFirstOrderReignsStageForShip(
                    game, playerId, host,
                    currentDeployCandidate)) {
            return 0;
        }
        int directRouteReserve =
                getFirstOrderReignsChaseShipDeployReserve(
                game, playerId, host,
                currentDeployCandidate);
        int navyRouteReserve =
                getFirstOrderReignsNavyPackageReserve(
                    game, playerId);
        if (directRouteReserve <= 0) {
            return navyRouteReserve;
        }
        if (navyRouteReserve <= 0) {
            return directRouteReserve;
        }
        return Math.min(
                directRouteReserve,
                navyRouteReserve);
    }

    public int getFirstOrderReignsCurrentMoveForceReserve(
            SwccgGame game, String playerId) {
        if (!isFirstOrderReignsRouteOpen(
                    game, playerId)) {
            return 0;
        }
        PhysicalCard host =
                getFirstOrderReignsTrackedFleetHostSystem(
                    game, playerId);
        int minimum = Integer.MAX_VALUE;
        for (PhysicalCard chaseShip
                : getFirstOrderReignsAdvancingChaseShipsOnTable(
                    game, playerId, host)) {
            int reserve =
                    getFirstOrderReignsNextMoveForceReserve(
                        game, playerId,
                        chaseShip, host);
            if (reserve >= 0) {
                minimum = Math.min(
                        minimum, reserve);
            }
        }
        return minimum == Integer.MAX_VALUE
                ? 0 : minimum;
    }

    private int getFirstOrderReignsNextMoveForceReserve(
            SwccgGame game, String playerId,
            PhysicalCard chaseShip, PhysicalCard host) {
        if (game == null || playerId == null
                || chaseShip == null || host == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return -1;
        }
        PhysicalCard origin =
                game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                        game.getGameState(), chaseShip);
        if (origin == null) {
            return -1;
        }
        if (samePhysicalLocation(
                origin, host)) {
            return 0;
        }
        List<PhysicalCard> locations =
                game.getGameState()
                    .getLocationsInOrder();
        if (locations == null) {
            return -1;
        }
        com.gempukku.swccgo.filters.Filter structuralMove =
                Filters.canMoveToUsingHyperspeed(
                    playerId, chaseShip,
                    false, true, 0.0f);
        int originDistance = Math.abs(
                origin.getParsec() - host.getParsec());
        int minimum = Integer.MAX_VALUE;
        for (PhysicalCard destination : locations) {
            boolean completesRoute =
                    samePhysicalLocation(
                        destination, host);
            if (destination == null
                    || !completesRoute
                    && Math.abs(
                        destination.getParsec()
                            - host.getParsec())
                        >= originDistance
                    || !structuralMove.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        destination)) {
                continue;
            }
            float cost = game.getModifiersQuerying()
                    .getMoveUsingHyperspeedCost(
                        game.getGameState(), chaseShip,
                        origin, destination,
                        false, 0.0f);
            minimum = Math.min(
                    minimum,
                    (int) Math.ceil(cost));
        }
        return minimum == Integer.MAX_VALUE
                ? -1 : minimum;
    }

    public boolean
            isPreferredFirstOrderReignsRouteForceLossCandidate(
                    SwccgGame game, String playerId,
                    PhysicalCard candidate) {
        if (!isFirstOrderReignsRouteOpen(
                    game, playerId)
                || candidate == null
                || !playerId.equals(candidate.getOwner())
                || !isFirstOrderReignsChaseShipCandidate(
                    game, playerId, candidate)
                || game.getGameState() == null) {
            return false;
        }
        PhysicalCard host =
                getFirstOrderReignsTrackedFleetHostSystem(
                    game, playerId);
        if (candidate.getZone() != null
                && candidate.getZone().isInPlay()) {
            List<PhysicalCard> advancingShips =
                    getFirstOrderReignsAdvancingChaseShipsOnTable(
                        game, playerId, host);
            return isActiveForSpot(
                    game, candidate, true)
                    && advancingShips.size() == 1
                    && advancingShips.contains(candidate);
        }
        if (!hasFirstOrderReignsStageForShip(
                game, playerId, host, candidate)) {
            return false;
        }
        if (!getFirstOrderReignsAdvancingChaseShipsOnTable(
                    game, playerId, host).isEmpty()) {
            return false;
        }
        return !hasFirstOrderReignsChaseShipIn(
                    game, playerId,
                    getFirstOrderReignsAccessibleChaseShipCards(
                        game, playerId),
                    candidate, host);
    }

    public boolean isFirstOrderReignsRouteShipCandidate(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (!isFirstOrderReignsRouteOpen(
                    game, playerId)
                || !isFirstOrderReignsChaseShipCandidate(
                    game, playerId, candidate)) {
            return false;
        }
        PhysicalCard host =
                getFirstOrderReignsTrackedFleetHostSystem(
                    game, playerId);
        if (candidate.getZone() != null
                && candidate.getZone().isInPlay()) {
            return getFirstOrderReignsAdvancingChaseShipsOnTable(
                    game, playerId, host)
                    .contains(candidate);
        }
        return hasFirstOrderReignsStageForShip(
                game, playerId, host, candidate);
    }

    private boolean advancesFirstOrderReignsChaseShipRouteAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            PhysicalCard destination) {
        if (!isFirstOrderReignsRouteOpen(
                    game, playerId)
                || candidate == null
                || destination == null
                || !playerId.equals(candidate.getOwner())
                || !isFirstOrderReignsChaseShipCandidate(
                    game, playerId, candidate)) {
            return false;
        }
        PhysicalCard host =
                getFirstOrderReignsTrackedFleetHostSystem(
                    game, playerId);
        if (host == null) return false;

        PhysicalCard origin =
                game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                        game.getGameState(), candidate);
        if (origin == null) {
            return canFirstOrderReignsShipStageAt(
                    game, playerId, host,
                    destination, candidate, false);
        }

        com.gempukku.swccgo.filters.Filter legalMove =
                Filters.canMoveToUsingHyperspeed(
                    playerId, candidate,
                    false, false, 0.0f);
        if (!legalMove.accepts(
                game.getGameState(),
                game.getModifiersQuerying(),
                destination)) {
            return false;
        }
        if (samePhysicalLocation(
                destination, host)) {
            return true;
        }
        int originDistance = Math.abs(
                origin.getParsec() - host.getParsec());
        int destinationDistance = Math.abs(
                destination.getParsec()
                    - host.getParsec());
        return destinationDistance < originDistance;
    }

    private boolean isShieldMainGeneratorRouteRule(
            FlipLocationRule rule) {
        return isShieldWillBeDown
                && rule != null
                && "shield-will-be-down-virtual-in-range-route"
                    .equals(rule.id);
    }

    private boolean isShieldMainGeneratorRouteRuleSatisfied(
            SwccgGame game, String playerId) {
        if (game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        List<PhysicalCard> locations =
                game.getGameState().getLocationsInOrder();
        if (locations == null) return false;
        for (PhysicalCard location : locations) {
            if (isShieldMainGeneratorFiringMarker(
                        game, location)
                    && hasActiveShieldTargetAt(
                        game, playerId, location)
                    && hasActiveShieldFiringPackageAt(
                        game, playerId, location)) {
                return true;
            }
        }
        return false;
    }

    private int countMatchingLocations(
            SwccgGame game, String playerId,
            FlipLocationAlternative alternative) {
        com.gempukku.swccgo.filters.Filter filter =
                resolveLocationFilter(
                        alternative.locationFilterKey, playerId);
        List<PhysicalCard> locations =
                game.getGameState().getLocationsInOrder();
        if (filter == null || locations == null) return 0;
        int count = 0;
        for (PhysicalCard location : locations) {
            if (filter.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), location)) {
                count++;
            }
        }
        return count;
    }

    private boolean advancesAlternativeAt(
            SwccgGame game, String playerId, PhysicalCard candidate,
            PhysicalCard location,
            FlipLocationAlternative alternative) {
        if (alternative == null || alternative.count == null
                || isUpperBound(alternative.count)
                || alternative.count.value == null
                || alternative.count.value <= 0
                || alternative.actorFilterKey == null
                    && !isPlainSelfPresenceAlternative(alternative)
                || candidate == null || location == null
                || !locationMatchesAlternative(
                        game.getGameState(), game, playerId,
                        location, alternative)
                || candidate.getZone() != null
                    && candidate.getZone().isInPlay()
                    && !isActiveForSpot(
                            game, candidate,
                            alternative.includeExcludedFromBattle)) {
            return false;
        }
        int required = expectedCount(game, playerId, alternative.count);
        String controller = resolveController(
                game.getGameState(), playerId, alternative.controller);
        int qualified = countAlternativeMatches(
                game, playerId, controller, alternative);
        if (qualified >= required
                || relationSatisfiedAt(
                        game, playerId, controller, location,
                        alternative.relation,
                        alternative.actorFilterKey,
                        alternative.includeExcludedFromBattle,
                        alternative.spotOverride)) {
            return false;
        }

        return candidateWouldSatisfyAlternativeAt(
                game, playerId, candidate, location, alternative);
    }

    private boolean candidateWouldSatisfyAlternativeAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard location,
            FlipLocationAlternative alternative) {
        if (game == null || playerId == null
                || candidate == null || location == null
                || alternative == null
                || alternative.actorFilterKey == null
                    && !isPlainSelfPresenceAlternative(alternative)
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || !locationMatchesAlternative(
                    game.getGameState(), game, playerId,
                    location, alternative)
                || candidate.getZone() != null
                    && candidate.getZone().isInPlay()
                    && !isActiveForSpot(
                        game, candidate,
                        alternative.includeExcludedFromBattle)) {
            return false;
        }
        String controller = resolveController(
                game.getGameState(), playerId,
                alternative.controller);
        if ((controller != null
                && !controller.equals(candidate.getOwner()))
                || (controller == null
                    && alternative.controller != null
                    && !"any".equals(alternative.controller))) {
            return false;
        }
        if (isCountedOperativeFormationAlternative(alternative)) {
            return candidateWouldCompleteCountedOperativeFormationAt(
                    game, playerId, candidate, location,
                    alternative, controller);
        }
        com.gempukku.swccgo.filters.Filter actorFilter =
                resolveFilter(alternative.actorFilterKey);
        if (alternative.actorFilterKey != null) {
            boolean prospectiveIsbAgent =
                    isIsbRebelBaseAgentAlternative(alternative)
                    && (candidate.getZone() == null
                        || !candidate.getZone().isInPlay())
                    && !candidate.isUndercover()
                    && isIsbLoreAgentCandidate(
                        game, playerId, candidate);
            if (!prospectiveIsbAgent
                    && (actorFilter == null || !actorFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate))) {
                return false;
            }
        }
        if (isActorAtRelation(alternative)) {
            return true;
        }
        if (!isSupportedSpotOverride(alternative.spotOverride)) {
            return false;
        }
        Map<com.gempukku.swccgo.common.InactiveReason, Boolean> overrides =
                resolveSpotOverride(
                        alternative.includeExcludedFromBattle,
                        alternative.spotOverride);
        if ("controlWith".equals(alternative.relation)
                && controller != null
                && game.getModifiersQuerying().controlsLocation(
                        game.getGameState(), location, controller,
                        overrides)) {
            return true;
        }
        if ("occupyWith".equals(alternative.relation)
                && controller != null
                && game.getModifiersQuerying().occupiesLocation(
                        game.getGameState(), location, controller,
                        overrides)) {
            return true;
        }
        if (!candidateProvidesPresence(game, candidate)) return false;

        if ("controlWith".equals(alternative.relation)) {
            String opponent =
                    game.getGameState().getOpponent(controller);
            return opponent == null
                    || !game.getModifiersQuerying().occupiesLocation(
                            game.getGameState(), location,
                            opponent, overrides);
        }
        if ("occupyWith".equals(alternative.relation)) {
            return true;
        }
        if ("control".equals(alternative.relation)) {
            String opponent =
                    game.getGameState().getOpponent(controller);
            return opponent == null
                    || !game.getModifiersQuerying().occupiesLocation(
                            game.getGameState(), location,
                            opponent, overrides);
        }
        return "occupy".equals(alternative.relation);
    }

    private boolean candidateWouldCompleteCountedOperativeFormationAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard location,
            FlipLocationAlternative alternative, String controller) {
        if (!candidateWouldCreateCountedOperativeFormationAt(
                    game, playerId, candidate, location,
                    alternative, controller)) {
            return false;
        }
        return !wouldMoveBreakCountedOperativeFormationAtOrigin(
                game, playerId, candidate, location);
    }

    private boolean candidateWouldCreateCountedOperativeFormationAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard location,
            FlipLocationAlternative alternative, String controller) {
        if (controller == null || !controller.equals(playerId)
                || relationSatisfiedAt(
                    game, playerId, controller, location,
                    alternative.relation,
                    alternative.actorFilterKey,
                    alternative.includeExcludedFromBattle,
                    alternative.spotOverride)) {
            return false;
        }
        Map<com.gempukku.swccgo.common.InactiveReason, Boolean> overrides =
                resolveSpotOverride(
                    alternative.includeExcludedFromBattle,
                    alternative.spotOverride);
        String opponent = game.getGameState().getOpponent(controller);
        if (opponent != null
                && game.getModifiersQuerying().occupiesLocation(
                    game.getGameState(), location,
                    opponent, overrides)) {
            return false;
        }

        boolean actor = matchesCountedOperativeFormationActor(
                game, playerId, candidate);
        if (actor) {
            return !hasCountedOperativeActorAtLocation(
                        game, playerId, location)
                    && hasCountedOperativeCompanionAtLocation(
                        game, playerId, location);
        }
        boolean companion = candidate.getZone() != null
                && candidate.getZone().isInPlay()
                    ? isCountedOperativeBoardControlCompanion(
                        game, playerId, candidate)
                    : isCountedOperativeFormationCompanion(
                        game, playerId, candidate);
        return companion
                && !hasCountedOperativeCompanionAtLocation(
                    game, playerId, location)
                && hasCountedOperativeActorAtLocation(
                    game, playerId, location);
    }

    private boolean wouldMoveBreakCountedOperativeFormationAtOrigin(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard destination) {
        if (candidate.getZone() == null
                || !candidate.getZone().isInPlay()) {
            return false;
        }
        PhysicalCard origin = presenceContributionLocation(
                game, candidate);
        if (origin == null || samePhysicalLocation(origin, destination)
                || !isCountedOperativeFormationCompleteAt(
                    game, playerId, origin)) {
            return false;
        }
        boolean actor = matchesCountedOperativeFormationActor(
                game, playerId, candidate);
        return actor
                ? !hasCountedOperativeFormationPieceAtLocation(
                    game, playerId, origin, candidate, true)
                : isCountedOperativeBoardControlCompanion(
                    game, playerId, candidate)
                    && !hasCountedOperativeFormationPieceAtLocation(
                        game, playerId, origin, candidate, false);
    }

    private static boolean isPlainSelfPresenceAlternative(
            FlipLocationAlternative alternative) {
        return alternative != null
                && alternative.actorFilterKey == null
                && "self".equals(alternative.controller)
                && ("control".equals(alternative.relation)
                    || "occupy".equals(alternative.relation))
                && alternative.count != null
                && alternative.count.value != null
                && alternative.count.value > 0
                && !isUpperBound(alternative.count);
    }

    private boolean candidateProvidesPresence(
            SwccgGame game, PhysicalCard candidate) {
        if (game == null || candidate == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || candidate.isUndercover()) {
            return false;
        }
        boolean providesPresence = Filters.or(
                Filters.hasAbilityOrHasPermanentPilotWithAbility,
                com.gempukku.swccgo.common.Icon.PRESENCE).accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate);
        boolean inPlay = candidate.getZone() != null
                && candidate.getZone().isInPlay();
        if (!providesPresence && !inPlay) {
            SwccgCardBlueprint blueprint = candidate.getBlueprint();
            providesPresence = blueprint != null
                    && blueprint.hasAbilityAttribute()
                    && blueprint.getAbility() != null
                    && blueprint.getAbility() >= 1.0f;
        }
        if (!providesPresence
                && Filters.piloted.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), candidate)) {
            providesPresence = game.getModifiersQuerying()
                    .getHighestAbilityPiloting(
                        game.getGameState(), candidate,
                        false, false) >= 1.0f;
        }
        return providesPresence;
    }

    /**
     * Mirrors the control query's operative exclusion for a carrier. A
     * vehicle's permanent pilot may supply ability, but an attached matching
     * operative cannot turn that same excluded ability into a second control
     * source merely by occupying a pilot slot.
     */
    private boolean candidateProvidesCountedOperativeControlPresence(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (!candidateProvidesPresence(game, candidate)) return false;
        if (Filters.or(
                Filters.hasAbilityOrHasPermanentPilotWithAbility,
                com.gempukku.swccgo.common.Icon.PRESENCE).accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), candidate)) {
            return true;
        }
        for (PhysicalCard pilot : game.getGameState()
                .getPilotCardsAboard(
                    game.getModifiersQuerying(), candidate, true)) {
            if (pilot != null
                    && playerId.equals(pilot.getOwner())
                    && isActiveForSpot(game, pilot, true)
                    && !Filters.operativeOnMatchingPlanet.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), pilot)
                    && candidateProvidesPresence(game, pilot)) {
                return true;
            }
        }
        return false;
    }

    private boolean candidateProvidesPresenceOutsideRemovedGroup(
            SwccgGame game, PhysicalCard candidate,
            PhysicalCard removedRoot, PhysicalCard dependentActor) {
        if (belongsToRemovedGroup(
                    candidate, removedRoot, dependentActor)
                || !candidateProvidesPresence(game, candidate)) {
            return false;
        }
        boolean intrinsicOrPermanentPresence = Filters.or(
                Filters.hasAbilityOrHasPermanentPilotWithAbility,
                com.gempukku.swccgo.common.Icon.PRESENCE).accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate);
        if (intrinsicOrPermanentPresence
                || !Filters.piloted.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), candidate)) {
            return true;
        }
        for (PhysicalCard pilot : game.getGameState()
                .getPilotCardsAboard(
                    game.getModifiersQuerying(), candidate, true)) {
            if (!belongsToRemovedGroup(
                        pilot, removedRoot, dependentActor)
                    && candidateProvidesPresence(game, pilot)) {
                return true;
            }
        }
        return false;
    }

    private PhysicalCard presenceContributionLocation(
            SwccgGame game, PhysicalCard candidate) {
        PhysicalCard location = game.getModifiersQuerying()
                .getLocationThatCardIsPresentAt(
                        game.getGameState(), candidate);
        return location != null ? location
                : game.getModifiersQuerying().getLocationThatCardIsAt(
                        game.getGameState(), candidate);
    }

    private boolean alternativeSatisfiedAfterCandidate(
            SwccgGame game, String playerId,
            FlipLocationAlternative alternative) {
        int required = expectedCount(game, playerId, alternative.count);
        String controller = resolveController(
                game.getGameState(), playerId, alternative.controller);
        int qualified = countAlternativeMatches(
                game, playerId, controller, alternative);
        return qualified + 1 >= required
                && opponentConstraintSatisfied(
                        game, playerId,
                        alternative.opponentConstraint);
    }

    private boolean relationSatisfiedAt(
            SwccgGame game, String playerId, String controller,
            PhysicalCard location, String relation, String actorFilterKey,
            Boolean includeExcludedFromBattle) {
        return relationSatisfiedAt(
                game, playerId, controller, location, relation,
                actorFilterKey, includeExcludedFromBattle, null);
    }

    private boolean relationSatisfiedAt(
            SwccgGame game, String playerId, String controller,
            PhysicalCard location, String relation, String actorFilterKey,
            Boolean includeExcludedFromBattle, String spotOverride) {
        if (location == null || relation == null) {
            return false;
        }
        if (!isSupportedSpotOverride(spotOverride)) {
            LOG.warn("[ObjectiveAnalyzer] unknown spotOverride '{}' in"
                    + " objective_playbooks.json; fail-closed.",
                    spotOverride);
            return false;
        }
        GameState gameState = game.getGameState();
        Map<com.gempukku.swccgo.common.InactiveReason, Boolean> overrides =
                resolveSpotOverride(
                        includeExcludedFromBattle, spotOverride);
        if ("control".equals(relation)) {
            if (controller == null) return false;
            return game.getModifiersQuerying().controlsLocation(
                    gameState, location, controller, overrides);
        }
        if ("occupy".equals(relation)) {
            if (controller == null) return false;
            return game.getModifiersQuerying().occupiesLocation(
                    gameState, location, controller, overrides);
        }
        if ("controlWith".equals(relation)
                || "occupyWith".equals(relation)) {
            if (controller == null) return false;
            boolean relationSatisfied = "controlWith".equals(relation)
                    ? game.getModifiersQuerying().controlsLocation(
                            gameState, location, controller, overrides)
                    : game.getModifiersQuerying().occupiesLocation(
                            gameState, location, controller, overrides);
            if (isHiddenPathObjectiveFamily()
                    && "occupyWith".equals(relation)
                    && "Jedi".equals(actorFilterKey)) {
                return relationSatisfied
                        && hasOwnedActiveJediAt(
                            game, controller, location, null,
                            Boolean.TRUE.equals(
                                includeExcludedFromBattle));
            }
            return relationSatisfied && hasMatchingActorAtLocation(
                    game, controller, location, actorFilterKey,
                    includeExcludedFromBattle, true);
        }
        if ("presentAt".equals(relation)) {
            return hasMatchingActorAtLocation(
                    game, controller, location, actorFilterKey,
                    includeExcludedFromBattle);
        }
        if ("at".equals(relation)) {
            return hasMatchingActorAtLocation(
                    game, controller, location, actorFilterKey,
                    includeExcludedFromBattle, true);
        }
        return false;
    }

    private static boolean isSupportedSpotOverride(String spotOverride) {
        return spotOverride == null
                || "INCLUDE_EXCLUDED_FROM_BATTLE".equals(spotOverride)
                || "INCLUDE_CAPTIVE_AND_EXCLUDED_FROM_BATTLE"
                    .equals(spotOverride);
    }

    private static Map<com.gempukku.swccgo.common.InactiveReason, Boolean>
            resolveSpotOverride(
                    Boolean includeExcludedFromBattle,
                    String spotOverride) {
        if ("INCLUDE_CAPTIVE_AND_EXCLUDED_FROM_BATTLE"
                .equals(spotOverride)) {
            return SpotOverride.INCLUDE_CAPTIVE_AND_EXCLUDED_FROM_BATTLE;
        }
        if ("INCLUDE_EXCLUDED_FROM_BATTLE".equals(spotOverride)
                || Boolean.TRUE.equals(includeExcludedFromBattle)) {
            return SpotOverride.INCLUDE_EXCLUDED_FROM_BATTLE;
        }
        return null;
    }

    private boolean opponentConstraintSatisfied(
            SwccgGame game, String playerId,
            RuleOpponentConstraint constraint) {
        if (constraint == null) return true;
        if (!isSupportedSpotOverride(constraint.spotOverride)) {
            LOG.warn("[ObjectiveAnalyzer] unknown opponent-constraint"
                    + " spotOverride '{}' in objective_playbooks.json;"
                    + " fail-closed.", constraint.spotOverride);
            return false;
        }
        int actual = countOpponentConstraintMatches(
                game, playerId, constraint);
        return compareCounts(
                actual, expectedCount(game, playerId, constraint.count),
                constraint.count != null
                        ? constraint.count.comparator : null);
    }

    private int countOpponentConstraintMatches(
            SwccgGame game, String playerId,
            RuleOpponentConstraint constraint) {
        if (constraint == null || game == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        GameState gameState = game.getGameState();
        String opponent = gameState.getOpponent(playerId);
        com.gempukku.swccgo.filters.Filter locationFilter =
                resolveLocationFilter(
                        constraint.locationFilterKey, playerId);
        List<PhysicalCard> locations = gameState.getLocationsInOrder();
        if (opponent == null || locationFilter == null || locations == null) {
            return 0;
        }
        int actual = 0;
        for (PhysicalCard location : locations) {
            if (locationFilter.accepts(
                    gameState, game.getModifiersQuerying(), location)
                    && relationSatisfiedAt(
                            game, playerId, opponent, location,
                            constraint.relation, null,
                            constraint.includeExcludedFromBattle,
                            constraint.spotOverride)) {
                actual++;
            }
        }
        return actual;
    }

    private boolean isOpponentConstraintBlockingAt(
            SwccgGame game, String playerId, PhysicalCard location,
            RuleOpponentConstraint constraint) {
        if (constraint == null || opponentConstraintSatisfied(
                game, playerId, constraint)) {
            return false;
        }
        com.gempukku.swccgo.filters.Filter locationFilter =
                resolveLocationFilter(
                        constraint.locationFilterKey, playerId);
        String opponent =
                game.getGameState().getOpponent(playerId);
        return locationFilter != null && opponent != null
                && locationFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), location)
                && relationSatisfiedAt(
                        game, playerId, opponent, location,
                        constraint.relation, null,
                        constraint.includeExcludedFromBattle,
                        constraint.spotOverride);
    }

    private boolean locationMatchesAlternative(
            GameState gameState, SwccgGame game, String playerId,
            PhysicalCard location, FlipLocationAlternative alternative) {
        if (location == null || alternative == null) return false;
        com.gempukku.swccgo.filters.Filter filter =
                resolveLocationFilter(alternative.locationFilterKey, playerId);
        return filter != null && filter.accepts(
                gameState, game.getModifiersQuerying(), location);
    }

    private boolean hasMatchingActorAtLocation(
            SwccgGame game, String controller, PhysicalCard location,
            String actorFilterKey) {
        return hasMatchingActorAtLocation(
                game, controller, location, actorFilterKey, true);
    }

    private boolean hasMatchingActorAtLocation(
            SwccgGame game, String controller, PhysicalCard location,
            String actorFilterKey, Boolean includeExcludedFromBattle) {
        return hasMatchingActorAtLocation(
                game, controller, location, actorFilterKey,
                includeExcludedFromBattle, false);
    }

    private boolean hasMatchingActorAtLocation(
            SwccgGame game, String controller, PhysicalCard location,
            String actorFilterKey, Boolean includeExcludedFromBattle,
            boolean rulesAt) {
        com.gempukku.swccgo.filters.Filter actorFilter =
                resolveFilter(actorFilterKey);
        if (actorFilter == null) return false;

        GameState gameState = game.getGameState();
        Collection<PhysicalCard> cards = gameState.getAllPermanentCards();
        if (cards == null) return false;
        for (PhysicalCard card : cards) {
            if (card == null
                    || controller != null
                        && !controller.equals(card.getOwner())
                    || !isActiveForSpot(
                            game, card, includeExcludedFromBattle)
                    || !actorFilter.accepts(
                            gameState, game.getModifiersQuerying(), card)) {
                continue;
            }
            PhysicalCard actorLocation = rulesAt
                    ? game.getModifiersQuerying()
                        .getLocationThatCardIsAt(
                                gameState, card)
                    : game.getModifiersQuerying()
                        .getLocationThatCardIsPresentAt(
                                gameState, card);
            if (samePhysicalLocation(actorLocation, location)) return true;
        }
        return false;
    }

    private static boolean isActorAtRelation(
            FlipLocationAlternative alternative) {
        return alternative != null
                && ("presentAt".equals(alternative.relation)
                    || "at".equals(alternative.relation));
    }

    private PhysicalCard actorLocationForAlternative(
            SwccgGame game, PhysicalCard actor,
            FlipLocationAlternative alternative) {
        if (game == null || actor == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return null;
        }
        boolean rulesAt = alternative != null
                && ("at".equals(alternative.relation)
                    || "controlWith".equals(
                        alternative.relation)
                    || "occupyWith".equals(
                        alternative.relation));
        return rulesAt
                ? game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                            game.getGameState(), actor)
                : game.getModifiersQuerying()
                    .getLocationThatCardIsPresentAt(
                            game.getGameState(), actor);
    }

    /**
     * Mirrors the engine's ordinary active-card spotting semantics while
     * allowing only the exact structured-rule override for exclusion from
     * battle. Captive Fury's explicit participation modifier remains honored.
     */
    private boolean isActiveForSpot(
            SwccgGame game, PhysicalCard card,
            Boolean includeExcludedFromBattle) {
        if (game == null || card == null || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            GameState gameState = game.getGameState();
            boolean captiveMayParticipate =
                    game.getModifiersQuerying()
                            .captiveMayParticipateInBattle(
                                    gameState, card);
            return gameState.isCardInPlayActive(
                    card,
                    Boolean.TRUE.equals(includeExcludedFromBattle),
                    false,
                    captiveMayParticipate,
                    false,
                    false,
                    false,
                    false,
                    false);
        } catch (Exception e) {
            return false;
        }
    }

    private int expectedCount(
            SwccgGame game, String playerId, RuleCount count) {
        int expected = count != null && count.value != null ? count.value : 1;
        if (count == null || count.gameTextModification == null
                || count.modifiedValue == null || game == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return expected;
        }
        try {
            PhysicalCard objective =
                    findOurObjective(game.getGameState(), playerId);
            ModifyGameTextType type = ModifyGameTextType.valueOf(
                    count.gameTextModification);
            if (objective != null
                    && game.getModifiersQuerying().hasGameTextModification(
                            game.getGameState(), objective, type)) {
                return count.modifiedValue;
            }
        } catch (Exception e) {
            LOG.debug("Objective count modifier assessment failed: {}",
                    e.getMessage());
        }
        return expected;
    }

    private static boolean compareCounts(
            int actual, int expected, String comparator) {
        String effectiveComparator =
                comparator != null ? comparator : ">=";
        return switch (effectiveComparator) {
            case ">" -> actual > expected;
            case "<" -> actual < expected;
            case "<=" -> actual <= expected;
            case "=", "==" -> actual == expected;
            default -> actual >= expected;
        };
    }

    /**
     * Exact named typed rules override the legacy substring parser. null means
     * the rule set is not exact-title authoritative and legacy matching applies.
     */
    private Boolean exactStructuredTitleMatch(
            String titleLower, String phase, String purpose) {
        if (activeFlipLocationRules == null) return null;

        boolean foundRule = false;
        boolean matched = false;
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (rule == null || !phase.equals(rule.phase)
                    || !purpose.equals(rule.purpose)
                    || rule.alternatives == null) {
                continue;
            }
            foundRule = true;
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (alternative == null
                        || !isExactNamedLocationFilter(
                                alternative.locationFilterKey)
                        || alternative.locationFragments == null
                        || alternative.locationFragments.isEmpty()) {
                    return null;
                }
                for (String fragment : alternative.locationFragments) {
                    if (fragment != null
                            && titleLower.equals(
                                    fragment.toLowerCase(Locale.ROOT).trim())) {
                        matched = true;
                    }
                }
            }
        }
        return foundRule ? matched : null;
    }

    private static boolean isExactNamedLocationFilter(String key) {
        return "Bunker".equals(key)
                || "Bespin_system".equals(key)
                || "Theed_Palace_Throne_Room".equals(key)
                || "Naboo_system".equals(key)
                || "Galactic_Senate".equals(key)
                || "Wattos_Junkyard".equals(key)
                || "Mos_Espa".equals(key);
    }

    // Loader-extension step 3b (2026-07-10): FILTER-based objective-relevance. Returns true if the location
    // matches the existing title/fragment path OR any of the active objective's flipLocationRules/
    // actorLocationRules resolved location filters (via the fail-closed resolveLocationFilter registry). This
    // is what count-refine/relation objectives whose relevant geography is NOT a simple title fragment
    // (generic battlegrounds, ownership-scoped, composite sites) need. Behavior-neutral for objectives with
    // no rules (activeFlipLocationRules/activeActorLocationRules null → same result as the title overload).
    public boolean isObjectiveRelevantLocation(PhysicalCard loc, SwccgGame game, String playerId) {
        if (!analyzed || loc == null) return false;
        // Local Uprising / Imperial Occupation choose their planet at runtime,
        // so title-only relevance cannot identify their three operative sites.
        // Preserve the general runtime-actor guard below, but recognize the
        // exact typed counted-operative geography first. This lets the normal
        // objective-site exemptions evaluate a funded operative-plus-companion
        // plan as objective work instead of a generic unsupported solo deploy.
        if (hasCountedOperativeFormationRule()
                && game != null && playerId != null
                && isCountedOperativeFormationLocation(
                    game, playerId, loc)) {
            return true;
        }
        if (isNoMoneyNoPartsObjectiveFamily()
                && game != null
                && Filters.or(
                        Filters.Wattos_Junkyard,
                        Filters.Mos_Espa).accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), loc)) {
            return true;
        }
        if (isIWantThatMapObjectiveFamily() && game != null) {
            try {
                if (game.getModifiersQuerying()
                        .isBattleground(game.getGameState(), loc, null)) {
                    return true;
                }
            } catch (Exception ignored) {
                // An unresolved modifier state must not invent relevance.
            }
        }
        if (hasPreFlipRuntimeActorRule()) return false;
        if (loc.getTitle() != null && isObjectiveRelevantLocation(loc.getTitle())) return true;
        if (game == null) return false;
        GameState gs = game.getGameState();
        if (gs == null) return false;
        if (activeFlipLocationRules != null) {
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (rule == null || rule.alternatives == null
                        || !(isFlipped ? "postFlip" : "preFlip")
                            .equals(rule.phase)) continue;
                for (FlipLocationAlternative alt : rule.alternatives) {
                    if (alt == null || alt.locationFilterKey == null) continue;
                    if ("opponent".equals(alt.controller)
                            && alt.actorFilterKey != null) {
                        continue;
                    }
                    com.gempukku.swccgo.filters.Filter f = resolveLocationFilter(alt.locationFilterKey, playerId);
                    if (f != null && f.accepts(gs, game.getModifiersQuerying(), loc)) return true;
                }
            }
        }
        if (activeActorLocationRules != null) {
            for (ActorLocationRule rule : activeActorLocationRules) {
                if (rule == null || rule.locationFilterKey == null) continue;
                com.gempukku.swccgo.filters.Filter f = resolveLocationFilter(rule.locationFilterKey, playerId);
                if (f != null && f.accepts(gs, game.getModifiersQuerying(), loc)) return true;
            }
        }
        return false;
    }

    public boolean isRequiredCardForFlip(String cardTitle) {
        if (!analyzed || cardTitle == null) return false;
        String titleLower = cardTitle.toLowerCase(Locale.ROOT);
        for (String required : requiredCardsOnTable) {
            if (titleLower.startsWith(required) || titleLower.equals(required)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Printing-aware required-card fact. Shield's playable route is the
     * virtual Epic Event 222_13; the classic card shares its title but cannot
     * legally execute this objective's route.
     */
    public boolean isRequiredCardForFlip(PhysicalCard card) {
        if (card == null
                || !isRequiredCardForFlip(card.getTitle())) {
            return false;
        }
        return !isShieldMainGeneratorRequirement(
                    card.getTitle())
                || "222_13".equals(
                    card.getBlueprintId(true));
    }

    /**
     * Source-accurate active spotting for one named required card.
     * Endor Operations includes cards excluded from battle, but not suspended
     * or otherwise inactive cards.
     */
    public boolean isRequiredCardActiveOnTable(
            SwccgGame game, String cardTitle) {
        if (!analyzed || game == null || cardTitle == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || !isRequiredCardForFlip(cardTitle)) {
            return false;
        }
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents == null) return false;
        for (PhysicalCard card : permanents) {
            if (physicalCardMatchesRequirement(
                        card, cardTitle)
                    && isActiveForSpot(game, card, true)
                    && (!isShieldCannonRequirement(
                            cardTitle)
                        || isActiveShieldCannonOnRoute(
                            game, card))) {
                return true;
            }
        }
        return false;
    }

    private boolean isActiveShieldCannonOnRoute(
            SwccgGame game, PhysicalCard cannon) {
        if (cannon == null || cannon.getOwner() == null
                || cannon.getAttachedTo() == null) {
            return false;
        }
        PhysicalCard staging = shieldRouteStagingLocation(
                game, cannon.getOwner());
        return staging != null
                && isCompleteShieldRouteHost(
                    game, cannon.getOwner(),
                    cannon.getAttachedTo(), staging);
    }

    /**
     * Protects one still-needed physical copy of a required on-table card
     * during Force loss. Ready hand and Reserve routes dominate blocked
     * printings; an active table copy closes protection for all duplicates.
     */
    public boolean isPreferredRequiredCardForceLossCandidate(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (!analyzed || game == null || playerId == null
                || candidate == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || isShieldWillBeDown && isFlipped) {
            return false;
        }
        GameState gameState = game.getGameState();
        String requirement =
                matchingRequiredTitle(candidate);
        if (requirement == null
                || isRequiredCardActiveOnTable(
                    game, requirement)) {
            return false;
        }
        PhysicalCard preferred = null;
        int preferredRank = Integer.MAX_VALUE;
        int preferredCost = Integer.MAX_VALUE;
        List<PhysicalCard> survivingCopies =
                new ArrayList<>();
        survivingCopies.addAll(
                gameState.getHand(playerId));
        survivingCopies.addAll(
                gameState.getReserveDeck(playerId));
        survivingCopies.addAll(
                gameState.getForcePile(playerId));
        survivingCopies.addAll(
                gameState.getUsedPile(playerId));
        survivingCopies.addAll(
                gameState.getUnresolvedDestinyDraw(playerId));
        survivingCopies.addAll(
                gameState.getSabaccHand(playerId));
        for (PhysicalCard card : survivingCopies) {
            if (card == null
                    || !playerId.equals(card.getOwner())
                    || !physicalCardMatchesRequirement(
                        card, requirement)) {
                continue;
            }
            int rank = requiredCardForceLossRank(
                    game, playerId, card);
            Integer liveCost =
                    requiredCardDeployCost(game, card);
            int cost = liveCost != null
                    ? liveCost : Integer.MAX_VALUE;
            if (preferred == null || rank < preferredRank
                    || rank == preferredRank
                        && cost < preferredCost) {
                preferred = card;
                preferredRank = rank;
                preferredCost = cost;
            }
        }
        return preferred == candidate;
    }

    /**
     * Protects the exact executable Shield package from Force loss without
     * making a pilot deploy before its selected host.
     */
    public boolean isPreferredShieldRoutePackageForceLossCandidate(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (!hasShieldMainGeneratorFormationRule()
                || game == null || playerId == null
                || candidate == null
                || !playerId.equals(candidate.getOwner())) {
            return false;
        }
        ShieldRoutePackage packagePlan =
                selectShieldRoutePackage(
                        game, playerId);
        return packagePlan != null
                && (candidate == packagePlan.host
                    || candidate == packagePlan.pilot
                    || candidate == packagePlan.cannon);
    }

    /**
     * Hoth repair #1 (2026-07-27): protects exactly ONE cheapest affordable
     * ship+pilot pair in hand from generic Force-loss ranking while the
     * objective's own named battleground SYSTEM is on table and we occupy
     * zero battleground systems. Data-scoped: the hook is
     * Filters.and(battleground_system, resolved named-location filter) from
     * the active profile's flip/actor location rules — no 222_x title check.
     * Fails closed: no named-system fact, no protection. Reuses the
     * ShieldFacts Invasion Naboo exclusion so a Naboo pair is never protected
     * while Invasion says Naboo is not a battleground.
     */
    public boolean isPreferredObjectiveTheaterPackageForceLossCandidate(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (!analyzed || game == null || playerId == null
                || candidate == null
                || !playerId.equals(candidate.getOwner())) {
            return false;
        }
        PhysicalCard[] pair =
                selectObjectiveTheaterPackage(game, playerId);
        return pair != null
                && (candidate == pair[0] || candidate == pair[1]);
    }

    /** Returns {ship, pilot} or null. See the public predicate for the law. */
    private PhysicalCard[] selectObjectiveTheaterPackage(
            SwccgGame game, String playerId) {
        GameState gameState = game.getGameState();
        if (gameState == null
                || game.getModifiersQuerying() == null) {
            return null;
        }
        try {
            com.gempukku.swccgo.filters.Filter systemFilter =
                    com.gempukku.swccgo.filters.Filters.battleground_system;
            if (ShieldFacts.isInvasionOnTable(gameState)) {
                systemFilter = com.gempukku.swccgo.filters.Filters.and(
                        systemFilter,
                        com.gempukku.swccgo.filters.Filters.not(
                                com.gempukku.swccgo.filters.Filters
                                        .Naboo_system));
            }

            // Leg 1: an objective-named battleground system is on table.
            boolean namedSystemOnTable = false;
            java.util.LinkedHashSet<String> filterKeys =
                    new java.util.LinkedHashSet<>();
            if (activeFlipLocationRules != null) {
                for (FlipLocationRule rule : activeFlipLocationRules) {
                    if (rule == null || rule.alternatives == null) continue;
                    for (FlipLocationAlternative alt : rule.alternatives) {
                        if (alt != null && alt.locationFilterKey != null) {
                            filterKeys.add(alt.locationFilterKey);
                        }
                    }
                }
            }
            if (activeActorLocationRules != null) {
                for (ActorLocationRule rule : activeActorLocationRules) {
                    if (rule != null && rule.locationFilterKey != null) {
                        filterKeys.add(rule.locationFilterKey);
                    }
                }
            }
            for (String key : filterKeys) {
                com.gempukku.swccgo.filters.Filter named =
                        resolveLocationFilter(key, playerId);
                if (named == null) continue;
                if (com.gempukku.swccgo.filters.Filters.canSpot(game, null,
                        com.gempukku.swccgo.filters.Filters.and(
                                systemFilter, named))) {
                    namedSystemOnTable = true;
                    break;
                }
            }
            if (!namedSystemOnTable) return null;

            // Leg 2: we occupy ZERO battleground systems.
            if (com.gempukku.swccgo.filters.Filters.canSpot(game, null,
                    com.gempukku.swccgo.filters.Filters.and(
                            com.gempukku.swccgo.filters.Filters
                                    .occupies(playerId),
                            systemFilter))) {
                return null;
            }

            // Leg 3: cheapest affordable ship+pilot pair in hand,
            // tiebreak cost, then ship cardId, then pilot cardId.
            List<PhysicalCard> hand = gameState.getHand(playerId);
            if (hand == null || hand.isEmpty()) return null;
            int forceAvailable =
                    gameState.getForcePile(playerId) != null
                            ? gameState.getForcePile(playerId).size() : 0;
            PhysicalCard bestShip = null, bestPilot = null;
            int bestCost = Integer.MAX_VALUE;
            for (PhysicalCard ship : hand) {
                if (ship == null
                        || !playerId.equals(ship.getOwner())
                        || !com.gempukku.swccgo.filters.Filters.starship
                                .accepts(gameState,
                                        game.getModifiersQuerying(), ship)) {
                    continue;
                }
                Integer shipCost = requiredCardDeployCost(game, ship);
                if (shipCost == null) continue;
                for (PhysicalCard pilot : hand) {
                    if (pilot == null || pilot == ship
                            || !isLegalProspectivePilotForHost(
                                    game, playerId, ship, pilot)) {
                        continue;
                    }
                    Integer pilotCost =
                            requiredCardDeployCost(game, pilot);
                    if (pilotCost == null) continue;
                    int total = shipCost + pilotCost;
                    if (total > forceAvailable) continue;
                    boolean better;
                    if (bestShip == null) {
                        better = true;
                    } else if (total != bestCost) {
                        better = total < bestCost;
                    } else if (ship.getCardId()
                            != bestShip.getCardId()) {
                        better = ship.getCardId()
                                < bestShip.getCardId();
                    } else {
                        better = bestPilot != null
                                && pilot.getCardId()
                                    < bestPilot.getCardId();
                    }
                    if (better) {
                        bestShip = ship;
                        bestPilot = pilot;
                        bestCost = total;
                    }
                }
            }
            return bestShip != null
                    ? new PhysicalCard[]{bestShip, bestPilot} : null;
        } catch (Exception e) {
            LOG.debug("Theater-package selection error: {}",
                    e.getMessage());
            return null;
        }
    }

    private int requiredCardForceLossRank(
            SwccgGame game, String playerId,
            PhysicalCard card) {
        Zone zone = card.getZone();
        boolean ready = (zone == Zone.HAND
                    || zone == Zone.RESERVE_DECK
                    || zone == Zone.TOP_OF_RESERVE_DECK)
                && isRequiredOnTableCardPullRouteReady(
                    game, playerId, card);
        if (zone == Zone.HAND) {
            return ready ? 0 : 2;
        }
        if (zone == Zone.RESERVE_DECK
                || zone == Zone.TOP_OF_RESERVE_DECK) {
            return ready ? 1 : 3;
        }
        if (zone == Zone.FORCE_PILE
                || zone == Zone.TOP_OF_FORCE_PILE
                || zone == Zone.USED_PILE
                || zone == Zone.TOP_OF_USED_PILE
                || zone == Zone.UNRESOLVED_DESTINY_DRAW
                || zone == Zone.TOP_OF_UNRESOLVED_DESTINY_DRAW
                || zone == Zone.SABACC_HAND
                || zone == Zone.REVEALED_SABACC_HAND) {
            return 4;
        }
        return 5;
    }

    /**
     * True only when the active objective itself can acquire a still-missing
     * required on-table card from Reserve Deck. A copy already in hand closes
     * the parent pull bonus so Rando does not upload duplicates.
     */
    public boolean objectivePullAdvancesRequiredOnTableCard(
            SwccgGame game, String playerId, String sourceTitle) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || sourceTitle == null || objectiveTitle == null
                || !objectiveTitle.equalsIgnoreCase(sourceTitle)
                || game.getGameState() == null
                || requiredCardsOnTable.isEmpty()) {
            return false;
        }
        return hasMissingReadyRequiredCardInReserve(
                game, playerId);
    }

    /**
     * Physical-source overload for tutors outside the objective itself.
     * Virtual Prepare For A Surface Attack 209_42 is the Shield route's exact
     * source. The classic printing shares its title and must not inherit this
     * objective priority.
     */
    public boolean objectivePullAdvancesRequiredOnTableCard(
            SwccgGame game, String playerId,
            PhysicalCard source) {
        if (source == null) return false;
        if (objectiveTitle != null
                && objectiveTitle.equalsIgnoreCase(
                    source.getTitle())) {
            if (isShieldWillBeDown) {
                return false;
            }
            return objectivePullAdvancesRequiredOnTableCard(
                    game, playerId, source.getTitle());
        }
        return analyzed && !isFlipped && isShieldWillBeDown
                && "209_42".equals(
                    source.getBlueprintId(true))
                && hasMissingReadyRequiredCardInReserve(
                    game, playerId);
    }

    private boolean hasMissingReadyRequiredCardInReserve(
            SwccgGame game, String playerId) {
        if (game == null || playerId == null
                || game.getGameState() == null
                || requiredCardsOnTable.isEmpty()) {
            return false;
        }
        List<PhysicalCard> reserve =
                game.getGameState().getReserveDeck(playerId);
        if (reserve == null || reserve.isEmpty()) return false;
        List<PhysicalCard> hand = game.getGameState().getHand(playerId);
        for (String required : requiredCardsOnTable) {
            if (isRequiredCardActiveOnTable(game, required)
                    || containsReadyRequiredTitle(
                        game, playerId, hand, required)) {
                continue;
            }
                for (PhysicalCard card : reserve) {
                    if (card != null && playerId.equals(card.getOwner())
                        && physicalCardMatchesRequirement(
                                card, required)
                        && isRequiredOnTableCardPullRouteReady(
                            game, playerId, card)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean containsReadyRequiredTitle(
            SwccgGame game, String playerId,
            List<PhysicalCard> cards, String required) {
        if (cards == null) return false;
        for (PhysicalCard card : cards) {
            if (card != null
                    && playerId.equals(card.getOwner())
                    && physicalCardMatchesRequirement(
                        card, required)
                    && isRequiredOnTableCardPullRouteReady(
                        game, playerId, card)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Printing-aware route readiness for a required-card tutor choice.
     * A direct route is ready when its typed destination is on table. A gated
     * route also requires its exact source-defined prerequisite.
     */
    public boolean isRequiredOnTableCardPullRouteReady(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (!analyzed || isFlipped || game == null
                || playerId == null || candidate == null
                || !playerId.equals(candidate.getOwner())
                || activeRequiredCardDeployRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || matchingRequiredTitle(candidate) == null) {
            return false;
        }
        if (isShieldCannonRequirement(
                candidate.getTitle())) {
            ShieldRoutePackage packagePlan =
                    selectShieldRoutePackage(
                            game, playerId);
            return packagePlan != null
                    && packagePlan.cannon == candidate;
        }
        boolean matchingTitleHasStructuredRoutes = false;
        String blueprintId = candidate.getBlueprintId(true);
        for (RequiredCardDeployRule rule
                : activeRequiredCardDeployRules) {
            if (rule == null
                    || rule.requiredCardFilterKey == null
                    || rule.blueprintIds == null) {
                continue;
            }
            com.gempukku.swccgo.filters.Filter requiredFilter =
                    resolveFilter(
                            rule.requiredCardFilterKey);
            if (requiredFilter == null
                    || !requiredFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        candidate)) {
                continue;
            }
            matchingTitleHasStructuredRoutes = true;
            if (!rule.blueprintIds.contains(blueprintId)
                    || !hasRequiredCardDeployDestination(
                        game, playerId, rule)) {
                continue;
            }
            if (rule.prerequisite == null
                    || isFlipLocationAlternativeSatisfied(
                        game, playerId,
                        rule.prerequisite)) {
                return true;
            }
        }
        return !isShieldMainGeneratorRequirement(
                    candidate.getTitle())
                && !matchingTitleHasStructuredRoutes;
    }

    private boolean hasRequiredCardDeployDestination(
            SwccgGame game, String playerId,
            RequiredCardDeployRule rule) {
        com.gempukku.swccgo.filters.Filter destinationFilter =
                resolveLocationFilter(
                        rule.destinationLocationFilterKey,
                        playerId);
        if (destinationFilter == null) return false;
        List<PhysicalCard> locations =
                game.getGameState().getLocationsInOrder();
        if (locations == null) return false;
        for (PhysicalCard location : locations) {
            if (location != null
                    && destinationFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        location)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Force that must remain available to deploy missing required cards
     * already in hand. Uses the live modifier query, so Ominous Rumors'
     * source-defined 2 Force cost is honored.
     */
    public int getRequiredOnTableCardForceReserve(
            SwccgGame game, String playerId) {
        return getRequiredOnTableCardForceReserve(
                game, playerId, null);
    }

    public int getRequiredOnTableCardForceReserve(
            SwccgGame game, String playerId,
            PhysicalCard deployingCandidate) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        List<PhysicalCard> hand = game.getGameState().getHand(playerId);
        if (hand == null || hand.isEmpty()) return 0;
        String deployingRequirement = deployingCandidate != null
                ? matchingRequiredTitle(
                    deployingCandidate)
                : null;
        Map<String, Integer> minimumCosts = new HashMap<>();
        for (PhysicalCard card : hand) {
            if (card == null || card == deployingCandidate
                    || !playerId.equals(card.getOwner())
                    || card.getTitle() == null) {
                continue;
            }
            String requirement =
                    matchingRequiredTitle(card);
            if (requirement == null
                    || requirement.equals(deployingRequirement)
                    || isRequiredCardActiveOnTable(game, requirement)) {
                continue;
            }
            if (!isRequiredOnTableCardPullRouteReady(
                        game, playerId, card)) {
                continue;
            }
            if (isShieldWillBeDown
                    && titleMatchesRequired(
                        card.getTitle(), "at-at cannon")) {
                continue;
            }
            try {
                Integer cost = requiredOnTableCardDeployCost(
                        game, playerId, card);
                if (cost != null) {
                    minimumCosts.merge(
                            requirement, cost, Math::min);
                }
            } catch (Exception e) {
                LOG.debug(
                        "Required on-table card Force reserve unavailable: {}",
                        e.getMessage());
            }
        }
        int reserve = 0;
        for (int cost : minimumCosts.values()) {
            reserve += cost;
        }
        reserve += getShieldRoutePackageForceReserve(
                game, playerId, deployingCandidate);
        return reserve;
    }

    private Integer requiredOnTableCardDeployCost(
            SwccgGame game, String playerId,
            PhysicalCard card) {
        if (!isShieldWillBeDown
                || card == null
                || card.getTitle() == null
                || !titleMatchesRequired(
                    card.getTitle(), "at-at cannon")) {
            return requiredCardDeployCost(game, card);
        }

        Integer minimum = null;
        Collection<PhysicalCard> cards =
                game.getGameState().getAllPermanentCards();
        if (cards != null) {
            for (PhysicalCard host : cards) {
                if (host == null
                        || !playerId.equals(host.getOwner())
                        || !isActiveForSpot(game, host, true)
                        || !Filters.AT_AT.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), host)
                        || !shieldCannonCanDeployOnHost(
                            game, card, host)) {
                    continue;
                }
                Integer cost =
                        requiredCardDeployCostAt(
                            game, card, host);
                if (cost != null
                        && (minimum == null || cost < minimum)) {
                    minimum = cost;
                }
            }
        }
        ShieldRoutePackage packagePlan =
                selectShieldRoutePackage(
                        game, playerId);
        if (packagePlan != null
                && packagePlan.host != null
                && shieldCannonCanDeployOnHost(
                    game, card, packagePlan.host)) {
            Integer plannedCost = requiredCardDeployCostAt(
                    game, card, packagePlan.host);
            if (plannedCost != null
                    && (minimum == null
                        || plannedCost < minimum)) {
                minimum = plannedCost;
            }
        }
        return minimum;
    }

    public int getRequiredCardDeployEnablerForceReserve(
            SwccgGame game, String playerId,
            PhysicalCard deployingCandidate) {
        if (!analyzed || isFlipped || game == null
                || playerId == null
                || activeRequiredCardDeployRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        int reserve = 0;
        for (RequiredCardDeployRule rule
                : activeRequiredCardDeployRules) {
            FlipLocationAlternative prerequisite =
                    rule != null ? rule.prerequisite : null;
            if (!isRequiredCardDeployRuleActive(
                        game, playerId, rule)
                    || prerequisite == null
                    || prerequisite.actorFilterKey == null
                    || prerequisite.count == null
                    || prerequisite.count.value == null
                    || prerequisite.count.value <= 0
                    || isUpperBound(prerequisite.count)) {
                continue;
            }
            int required = expectedCount(
                    game, playerId, prerequisite.count);
            int qualified = countAlternativeMatches(
                    game, playerId, playerId,
                    prerequisite);
            int missing = Math.max(0, required - qualified);
            com.gempukku.swccgo.filters.Filter actorFilter =
                    resolveFilter(prerequisite.actorFilterKey);
            ProspectiveActorPair pair =
                    prerequisite.prospectiveActorPair;
            com.gempukku.swccgo.filters.Filter pairHostFilter =
                    pair != null
                            ? resolveFilter(pair.hostFilterKey) : null;
            com.gempukku.swccgo.filters.Filter pairPilotFilter =
                    pair != null
                            ? resolveFilter(pair.pilotFilterKey) : null;
            if (missing == 0 || actorFilter == null) continue;

            List<DeployCostedCard> directActors =
                    new ArrayList<>();
            List<DeployCostedCard> pairHosts = new ArrayList<>();
            List<DeployCostedCard> pairPilots = new ArrayList<>();
            if (deployingCandidate != null) {
                if (actorFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        deployingCandidate)) {
                    directActors.add(new DeployCostedCard(
                            deployingCandidate, true));
                }
                if (pairHostFilter != null
                        && pairPilotFilter != null
                        && pairHostFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        deployingCandidate)) {
                    pairHosts.add(new DeployCostedCard(
                            deployingCandidate, true));
                }
                if (pairPilotFilter != null
                        && pairPilotFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        deployingCandidate)) {
                    pairPilots.add(new DeployCostedCard(
                            deployingCandidate, true));
                }
            }
            List<PhysicalCard> hand =
                    game.getGameState().getHand(playerId);
            if (hand != null) {
                for (PhysicalCard card : hand) {
                    if (card == null || card == deployingCandidate
                            || !playerId.equals(card.getOwner())) {
                        continue;
                    }
                    if (actorFilter.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), card)) {
                        directActors.add(new DeployCostedCard(
                                card, false));
                    }
                    if (pairHostFilter != null
                            && pairHostFilter.accepts(
                                game.getGameState(),
                                game.getModifiersQuerying(), card)) {
                        pairHosts.add(new DeployCostedCard(
                                card, false));
                    }
                    if (pairPilotFilter != null
                            && pairPilotFilter.accepts(
                                game.getGameState(),
                                game.getModifiersQuerying(), card)) {
                        pairPilots.add(new DeployCostedCard(
                                card, false));
                    }
                }
            }
            if (pairHostFilter != null
                    && pairPilotFilter != null) {
                Collection<PhysicalCard> permanents =
                        game.getGameState().getAllPermanentCards();
                if (permanents != null) {
                    for (PhysicalCard card : permanents) {
                        if (card == null
                                || !playerId.equals(card.getOwner())
                                || !isActiveForSpot(game, card, false)
                                || card.getAttachedTo() != null) {
                            continue;
                        }
                        PhysicalCard location =
                                game.getModifiersQuerying()
                                    .getLocationThatCardIsAt(
                                        game.getGameState(), card);
                        if (!canProspectivePairAdvanceAtTarget(
                                    game, playerId, location,
                                    prerequisite)) {
                            continue;
                        }
                        if (pairHostFilter.accepts(
                                    game.getGameState(),
                                    game.getModifiersQuerying(), card)
                                && !Filters.piloted.accepts(
                                    game.getGameState(),
                                    game.getModifiersQuerying(), card)) {
                            pairHosts.add(new DeployCostedCard(
                                    card, true));
                        }
                        if (pairPilotFilter.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), card)) {
                            pairPilots.add(new DeployCostedCard(
                                    card, true));
                        }
                    }
                }
            }
            reserve += minimumRequiredDeployContributionCost(
                    game, playerId, prerequisite, missing,
                    directActors, pairHosts, pairPilots);
        }
        return reserve;
    }

    private int minimumRequiredDeployContributionCost(
            SwccgGame game, String playerId,
            FlipLocationAlternative prerequisite, int missing,
            List<DeployCostedCard> directActors,
            List<DeployCostedCard> pairHosts,
            List<DeployCostedCard> pairPilots) {
        List<PhysicalCard> locations =
                game.getGameState().getLocationsInOrder();
        if (locations == null || locations.isEmpty()) return 0;
        List<List<DeployContributionOption>> optionsByTarget =
                new ArrayList<>();
        for (PhysicalCard location : locations) {
            List<DeployContributionOption> options =
                    new ArrayList<>();
            for (DeployCostedCard actor : directActors) {
                if (!advancesAlternativeAt(
                            game, playerId, actor.card,
                            location, prerequisite)
                        || !isDirectActorRouteLegalAt(
                            game, actor.card, location)) {
                    continue;
                }
                Integer cost = actor.alreadyCovered
                        ? 0
                        : requiredCardDeployCostAt(
                            game, actor.card, location);
                if (cost != null) {
                    options.add(new DeployContributionOption(
                            actor.card, null, cost));
                }
            }
            if (canProspectivePairAdvanceAtTarget(
                        game, playerId, location,
                        prerequisite)) {
                for (DeployCostedCard host : pairHosts) {
                    for (DeployCostedCard pilot : pairPilots) {
                        if (!isProspectivePairRouteLegalAt(
                                    game, playerId,
                                    host.card, pilot.card,
                                    location)) {
                            continue;
                        }
                        Integer cost =
                                requiredProspectivePairCostAt(
                                    game, host, pilot,
                                    location);
                        if (cost != null) {
                            options.add(
                                    new DeployContributionOption(
                                        host.card, pilot.card,
                                        cost));
                        }
                    }
                }
            }
            if (!options.isEmpty()) {
                options.sort(
                        Comparator.comparingInt(
                            option -> option.cost));
                optionsByTarget.add(options);
            }
        }
        optionsByTarget.sort(
                Comparator.comparingInt(List::size));

        int maxUnits = Math.min(
                missing, optionsByTarget.size());
        for (int units = maxUnits; units > 0; units--) {
            int[] best = {Integer.MAX_VALUE};
            minimumDistinctContributionCost(
                    optionsByTarget, 0, units, 0,
                    Collections.newSetFromMap(
                            new IdentityHashMap<>()),
                    best);
            if (best[0] != Integer.MAX_VALUE) {
                return best[0];
            }
        }
        return 0;
    }

    private void minimumDistinctContributionCost(
            List<List<DeployContributionOption>> optionsByTarget,
            int targetIndex, int unitsNeeded, int costSoFar,
            Set<PhysicalCard> usedCards, int[] best) {
        if (unitsNeeded == 0) {
            best[0] = Math.min(best[0], costSoFar);
            return;
        }
        int remainingTargets =
                optionsByTarget.size() - targetIndex;
        if (remainingTargets < unitsNeeded
                || costSoFar >= best[0]) {
            return;
        }
        int lowerBound = minimumRemainingTargetCost(
                optionsByTarget, targetIndex, unitsNeeded);
        if (lowerBound == Integer.MAX_VALUE
                || costSoFar + lowerBound >= best[0]) {
            return;
        }

        List<DeployContributionOption> options =
                optionsByTarget.get(targetIndex);
        for (DeployContributionOption option : options) {
            if (usedCards.contains(option.primary)
                    || option.secondary != null
                        && usedCards.contains(
                            option.secondary)) {
                continue;
            }
            usedCards.add(option.primary);
            if (option.secondary != null) {
                usedCards.add(option.secondary);
            }
            minimumDistinctContributionCost(
                    optionsByTarget, targetIndex + 1,
                    unitsNeeded - 1,
                    costSoFar + option.cost,
                    usedCards, best);
            usedCards.remove(option.primary);
            if (option.secondary != null) {
                usedCards.remove(option.secondary);
            }
        }
        minimumDistinctContributionCost(
                optionsByTarget, targetIndex + 1,
                unitsNeeded, costSoFar, usedCards, best);
    }

    private static int minimumRemainingTargetCost(
            List<List<DeployContributionOption>> optionsByTarget,
            int targetIndex, int unitsNeeded) {
        List<Integer> minimums = new ArrayList<>();
        for (int index = targetIndex;
                index < optionsByTarget.size(); index++) {
            List<DeployContributionOption> options =
                    optionsByTarget.get(index);
            if (!options.isEmpty()) {
                minimums.add(options.get(0).cost);
            }
        }
        if (minimums.size() < unitsNeeded) {
            return Integer.MAX_VALUE;
        }
        Collections.sort(minimums);
        int result = 0;
        for (int index = 0; index < unitsNeeded; index++) {
            result += minimums.get(index);
        }
        return result;
    }

    private boolean isDirectActorRouteLegalAt(
            SwccgGame game, PhysicalCard actor,
            PhysicalCard targetLocation) {
        if (actor == null || targetLocation == null
                || actor.getZone() != null
                    && actor.getZone().isInPlay()) {
            return false;
        }
        try {
            return Filters.deployableToLocation(
                        actor,
                        Filters.sameCardId(targetLocation),
                        true, 0.0f)
                    .accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), actor);
        } catch (Exception e) {
            LOG.debug(
                    "Required-card actor deploy route unavailable: {}",
                    e.getMessage());
            return false;
        }
    }

    private Integer requiredProspectivePairCostAt(
            SwccgGame game, DeployCostedCard host,
            DeployCostedCard pilot,
            PhysicalCard targetLocation) {
        if (host.alreadyCovered && pilot.alreadyCovered) {
            try {
                float cost = game.getModifiersQuerying()
                        .getEmbarkingCost(
                            game.getGameState(),
                            pilot.card, host.card, 0.0f);
                return (int) Math.ceil(
                        Math.max(0.0f, cost));
            } catch (Exception e) {
                LOG.debug(
                    "Required-card embark cost unavailable: {}",
                    e.getMessage());
                return null;
            }
        }
        if (!host.alreadyCovered && !pilot.alreadyCovered) {
            try {
                float cost = game.getModifiersQuerying()
                        .getSimultaneousDeployCost(
                            game.getGameState(),
                            host.card, host.card,
                            false, 0.0f,
                            pilot.card, false, 0.0f,
                            targetLocation, null, true);
                return (int) Math.ceil(
                        Math.max(0.0f, cost));
            } catch (Exception e) {
                LOG.debug(
                        "Required-card pair deploy cost unavailable: {}",
                        e.getMessage());
                return null;
            }
        }
        PhysicalCard unpaid = host.alreadyCovered
                ? pilot.card : host.card;
        PhysicalCard target = host.alreadyCovered
                ? host.card : targetLocation;
        return requiredCardDeployCostAt(
                game, unpaid, target);
    }

    private static final class DeployCostedCard {
        private final PhysicalCard card;
        private final boolean alreadyCovered;

        private DeployCostedCard(
                PhysicalCard card, boolean alreadyCovered) {
            this.card = card;
            this.alreadyCovered = alreadyCovered;
        }
    }

    private static final class DeployContributionOption {
        private final PhysicalCard primary;
        private final PhysicalCard secondary;
        private final int cost;

        private DeployContributionOption(
                PhysicalCard primary,
                PhysicalCard secondary, int cost) {
            this.primary = primary;
            this.secondary = secondary;
            this.cost = cost;
        }
    }

    private Integer requiredCardDeployCost(
            SwccgGame game, PhysicalCard card) {
        try {
            float cost = game.getModifiersQuerying()
                    .getDeployCost(game.getGameState(), card);
            return (int) Math.ceil(Math.max(0.0f, cost));
        } catch (Exception e) {
            LOG.debug(
                    "Required-card deploy cost unavailable: {}",
                    e.getMessage());
            return null;
        }
    }

    private Integer requiredCardDeployCostAt(
            SwccgGame game, PhysicalCard card,
            PhysicalCard target) {
        return requiredCardDeployCostAt(
                game, card, card, target);
    }

    private Integer requiredCardDeployCostAt(
            SwccgGame game, PhysicalCard sourceCard,
            PhysicalCard card, PhysicalCard target) {
        try {
            float cost = game.getModifiersQuerying()
                    .getDeployCost(
                        game.getGameState(), sourceCard, card,
                        target, false, null, false,
                        0.0f, null, true);
            return (int) Math.ceil(Math.max(0.0f, cost));
        } catch (Exception e) {
            LOG.debug(
                    "Required-card enabler Force reserve unavailable: {}",
                    e.getMessage());
            return null;
        }
    }

    /**
     * The Bunker control requirement belongs only to the V and Legacy
     * Establish Secret Base printings. It is a deploy enabler, not the
     * objective's flip condition.
     */
    public boolean isActiveRequiredCardControlEnablerLocation(
            SwccgGame game, String playerId, PhysicalCard location) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || location == null || flipCriticalControlSite == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || isRequiredCardActiveOnTable(
                        game, flipCriticalControlCard)
                || !flipCriticalControlSite.equalsIgnoreCase(
                        location.getTitle())) {
            return false;
        }
        List<List<PhysicalCard>> accessible = Arrays.asList(
                game.getGameState().getHand(playerId),
                game.getGameState().getReserveDeck(playerId));
        for (List<PhysicalCard> cards : accessible) {
            if (cards == null) continue;
            for (PhysicalCard card : cards) {
                if (card != null && playerId.equals(card.getOwner())
                        && flipCriticalControlCardIds.contains(
                                card.getBlueprintId(true))) {
                    return true;
                }
            }
        }
        return false;
    }

    public boolean isSoleControlSourceAtRequiredCardEnabler(
            SwccgGame game, String playerId, PhysicalCard mover,
            PhysicalCard location) {
        if (!isActiveRequiredCardControlEnablerLocation(
                    game, playerId, location)
                || mover == null || !playerId.equals(mover.getOwner())
                || !samePhysicalLocation(
                        game.getModifiersQuerying()
                            .getLocationThatCardIsPresentAt(
                                game.getGameState(), mover),
                        location)) {
            return false;
        }
        return isSolePresenceSourceAtLocation(
                game, playerId, mover, location);
    }

    public RequiredCardRetentionRisk assessRequiredCardRetentionRisk(
            SwccgGame game, String playerId, PhysicalCard location) {
        if (!analyzed || game == null || playerId == null
                || location == null
                || activeRequiredCardRetentionRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return RequiredCardRetentionRisk.none();
        }
        RequiredCardRetentionRisk best = null;
        for (RequiredCardRetentionRule rule
                : activeRequiredCardRetentionRules) {
            if (!isRequiredCardRetentionRuleActive(
                        game, playerId, rule)
                    || rule.removalCondition == null
                    || !isSupportedRequiredCardRetentionCondition(
                        rule.removalCondition)) {
                continue;
            }
            RequiredCardRetentionRisk risk =
                    assessRequiredCardRetentionRisk(
                            game, playerId, location,
                            rule.removalCondition);
            if (!risk.inScope()) {
                if (best == null) best = risk;
                continue;
            }
            if (best == null || !best.inScope()
                    || risk.removalNow() && !best.removalNow()
                    || risk.removalNow() == best.removalNow()
                        && risk.adverseStepsRemaining()
                            < best.adverseStepsRemaining()) {
                best = risk;
            }
        }
        return best != null
                ? best : RequiredCardRetentionRisk.none();
    }

    public boolean isRequiredCardRetentionProtectionLocation(
            SwccgGame game, String playerId, PhysicalCard location) {
        return assessRequiredCardRetentionRisk(
                    game, playerId, location).requiresProtection()
                || isRequiredCardCancelPreventerDefenseLocation(
                    game, playerId, location);
    }

    public boolean isRequiredCardRetentionBattleLocation(
            SwccgGame game, String playerId, PhysicalCard location) {
        RequiredCardRetentionRisk risk =
                assessRequiredCardRetentionRisk(
                        game, playerId, location);
        return (risk.applies() && risk.inScope()
                    && !risk.removalNow()
                    && risk.adverseStepsRemaining() <= 1)
                || isRequiredCardCancelPreventerDefenseLocation(
                    game, playerId, location);
    }

    public boolean advancesRequiredCardRetentionDefenseAt(
            SwccgGame game, String playerId, PhysicalCard candidate,
            PhysicalCard destination) {
        if (!isRequiredCardRetentionBattleLocation(
                    game, playerId, destination)
                || candidate == null
                || !playerId.equals(candidate.getOwner())) {
            return false;
        }
        com.gempukku.swccgo.filters.Filter presenceSource = Filters.or(
                Filters.hasAbilityOrHasPermanentPilotWithAbility,
                com.gempukku.swccgo.common.Icon.PRESENCE);
        return presenceSource.accepts(
                game.getGameState(),
                game.getModifiersQuerying(), candidate);
    }

    public boolean wouldDepartureTriggerRequiredCardRemoval(
            SwccgGame game, String playerId, PhysicalCard mover) {
        if (!analyzed || game == null || playerId == null
                || mover == null || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || !playerId.equals(mover.getOwner())) {
            return false;
        }
        try {
            GameState gameState = game.getGameState();
            PhysicalCard location = game.getModifiersQuerying()
                    .getLocationThatCardIsPresentAt(
                            gameState, mover);
            RequiredCardRetentionRisk risk =
                    assessRequiredCardRetentionRisk(
                            game, playerId, location);
            if (!risk.applies() || !risk.inScope()
                    || risk.removalNow()
                    || !risk.criticalIfOpponentGainsControl()
                    || !isSolePresenceSourceAtLocation(
                            game, playerId, mover, location)) {
                return false;
            }
            String opponent = gameState.getOpponent(playerId);
            if (opponent == null) return false;
            return game.getModifiersQuerying().occupiesLocation(
                    gameState, location, opponent,
                    SpotOverride.INCLUDE_EXCLUDED_FROM_BATTLE);
        } catch (Exception e) {
            LOG.debug(
                    "Required-card retention departure assessment failed: {}",
                    e.getMessage());
            return false;
        }
    }

    /**
     * True when deploying this exact source would prevent a required card
     * from ever counting as active while the objective remains on table.
     */
    public boolean wouldDeployPreventRequiredCardActivity(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        if (!analyzed || game == null || playerId == null
                || candidate == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || (candidate.getZone() != null
                    && candidate.getZone().isInPlay())
                || activeRequiredCardInactivationRules == null) {
            return false;
        }
        String candidateBlueprint = candidate.getBlueprintId(true);
        for (RequiredCardInactivationRule rule
                : activeRequiredCardInactivationRules) {
            if (rule == null || rule.sourceBlueprintIds == null
                    || !rule.sourceBlueprintIds.contains(
                            candidateBlueprint)
                    || rule.requiredCardFilterKey == null
                    || !"suspend".equals(rule.outcome)) {
                continue;
            }
            String requiredTitle =
                    requiredTitleForFilterKey(
                            rule.requiredCardFilterKey);
            if (requiredTitle != null
                    && isRequiredCardForFlip(requiredTitle)
                    && findOurObjective(
                        game.getGameState(), playerId) != null) {
                return true;
            }
        }
        return false;
    }

    private RequiredCardRetentionRisk
            assessRequiredCardRetentionRisk(
                    SwccgGame game, String playerId,
                    PhysicalCard location,
                    FlipLocationAlternative condition) {
        GameState gameState = game.getGameState();
        String opponent = gameState.getOpponent(playerId);
        if (opponent == null) {
            return RequiredCardRetentionRisk.none();
        }
        int opponentCount = countAlternativeMatches(
                game, playerId, opponent, condition);
        boolean inScope = locationMatchesAlternative(
                gameState, game, playerId, location,
                condition);
        boolean opponentControlsHere = inScope
                && relationSatisfiedAt(
                    game, playerId, opponent, location,
                    condition.relation,
                    condition.actorFilterKey,
                    condition.includeExcludedFromBattle,
                    condition.spotOverride);
        int required = expectedCount(
                game, playerId, condition.count);
        boolean removalNow = compareCounts(
                opponentCount, required,
                condition.count.comparator);
        boolean opponentGainTriggers = inScope
                && !opponentControlsHere
                && compareCounts(
                    opponentCount + 1, required,
                    condition.count.comparator);
        int adverseSteps = 0;
        while (adverseSteps < 100
                && !compareCounts(
                    opponentCount + adverseSteps,
                    required, condition.count.comparator)) {
            adverseSteps++;
        }
        return new RequiredCardRetentionRisk(
                true, inScope, removalNow,
                opponentControlsHere,
                opponentGainTriggers,
                opponentCount, adverseSteps);
    }

    private boolean isRequiredCardRetentionRuleActive(
            SwccgGame game, String playerId,
            RequiredCardRetentionRule rule) {
        if (rule == null || rule.requiredCardFilterKey == null
                || rule.blueprintIds == null
                || rule.blueprintIds.isEmpty()
                || !"tableChangedOpponentControl".equals(
                    rule.trigger)
                || (!"cancel".equals(rule.outcome)
                    && !"usedPile".equals(rule.outcome))) {
            return false;
        }
        com.gempukku.swccgo.filters.Filter requiredFilter =
                resolveFilter(rule.requiredCardFilterKey);
        if (requiredFilter == null) return false;
        try {
            PhysicalCard requiredCard =
                    findActiveRequiredCardForRetention(
                            game, playerId, rule,
                            requiredFilter);
            return requiredCard != null
                    && (!Boolean.TRUE.equals(
                            rule.requiresCancelable)
                        || com.gempukku.swccgo.cards
                            .GameConditions.canBeCanceled(
                                game, requiredCard));
        } catch (Exception e) {
            LOG.debug(
                    "Required-card retention active-state assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    private PhysicalCard findActiveRequiredCardForRetention(
            SwccgGame game, String playerId,
            RequiredCardRetentionRule rule,
            com.gempukku.swccgo.filters.Filter requiredFilter) {
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents == null) return null;
        for (PhysicalCard card : permanents) {
            if (card != null
                    && playerId.equals(card.getOwner())
                    && rule.blueprintIds.contains(
                        card.getBlueprintId(true))
                    && isActiveForSpot(game, card, true)
                    && requiredFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), card)) {
                return card;
            }
        }
        return null;
    }

    private boolean isSoleRequiredCardCancelPreventerIfRemoved(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (activeRequiredCardRetentionRules == null
                || game == null || playerId == null
                || candidate == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            GameState gameState = game.getGameState();
            for (RequiredCardRetentionRule rule
                    : activeRequiredCardRetentionRules) {
                RequiredCardCancelPrevention prevention =
                        rule != null ? rule.cancelPrevention : null;
                if (!Boolean.TRUE.equals(
                            rule != null
                                ? rule.requiresCancelable : null)
                        || prevention == null
                        || prevention.actorFilterKey == null
                        || prevention.locationFilterKey == null
                        || rule.removalCondition == null) {
                    continue;
                }
                com.gempukku.swccgo.filters.Filter requiredFilter =
                        resolveFilter(
                                rule.requiredCardFilterKey);
                PhysicalCard requiredCard =
                        requiredFilter != null
                            ? findActiveRequiredCardForRetention(
                                game, playerId, rule,
                                requiredFilter)
                            : null;
                if (requiredCard == null
                        || com.gempukku.swccgo.cards
                            .GameConditions.canBeCanceled(
                                game, requiredCard)) {
                    continue;
                }
                com.gempukku.swccgo.filters.Filter actorFilter =
                        resolveFilter(
                                prevention.actorFilterKey);
                com.gempukku.swccgo.filters.Filter locationFilter =
                        resolveLocationFilter(
                                prevention.locationFilterKey,
                                playerId);
                Collection<PhysicalCard> permanents =
                        gameState.getAllPermanentCards();
                if (actorFilter == null || locationFilter == null
                        || permanents == null) {
                    continue;
                }
                PhysicalCard affectedPreventer = null;
                PhysicalCard candidateLocation = null;
                for (PhysicalCard card : permanents) {
                    if (card == null
                            || !playerId.equals(card.getOwner())
                            || !isActiveForSpot(game, card, true)
                            || !actorFilter.accepts(
                                gameState,
                                game.getModifiersQuerying(), card)
                            || card != candidate
                                && !attachedToOrAboard(
                                    card, candidate)) {
                        continue;
                    }
                    PhysicalCard preventerLocation =
                            game.getModifiersQuerying()
                                .getLocationThatCardIsAt(
                                    gameState, card);
                    if (preventerLocation != null
                            && locationFilter.accepts(
                                gameState,
                                game.getModifiersQuerying(),
                                preventerLocation)) {
                        affectedPreventer = card;
                        candidateLocation = preventerLocation;
                        break;
                    }
                }
                if (affectedPreventer == null
                        || candidateLocation == null) {
                    continue;
                }
                boolean removalConditionAlreadyMet =
                        isFlipLocationAlternativeSatisfied(
                                game, playerId,
                                rule.removalCondition);
                RequiredCardRetentionRisk transitionRisk =
                        assessRequiredCardRetentionRisk(
                                game, playerId,
                                candidateLocation,
                                rule.removalCondition);
                if (!removalConditionAlreadyMet
                        && (!transitionRisk.applies()
                            || !transitionRisk.inScope()
                            || transitionRisk
                                .adverseStepsRemaining() > 1)) {
                    continue;
                }
                boolean otherPreventer = false;
                for (PhysicalCard card : permanents) {
                    if (card == null || card == affectedPreventer
                            || card == candidate
                            || attachedToOrAboard(
                                card, candidate)
                            || !playerId.equals(card.getOwner())
                            || !isActiveForSpot(game, card, true)
                            || !actorFilter.accepts(
                                gameState,
                                game.getModifiersQuerying(),
                                card)) {
                        continue;
                    }
                    PhysicalCard otherLocation =
                            game.getModifiersQuerying()
                                .getLocationThatCardIsAt(
                                    gameState, card);
                    if (otherLocation != null
                            && locationFilter.accepts(
                                gameState,
                                game.getModifiersQuerying(),
                                otherLocation)) {
                        otherPreventer = true;
                        break;
                    }
                }
                if (!otherPreventer) return true;
            }
        } catch (Exception e) {
            LOG.debug(
                    "Required-card cancel-preventer assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    public boolean isRequiredCardCancelPreventerDefenseLocation(
            SwccgGame game, String playerId,
            PhysicalCard location) {
        if (!analyzed || game == null || playerId == null
                || location == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents == null) return false;
        for (PhysicalCard card : permanents) {
            if (card == null || !playerId.equals(card.getOwner())) {
                continue;
            }
            PhysicalCard cardLocation =
                    game.getModifiersQuerying()
                        .getLocationThatCardIsAt(
                            game.getGameState(), card);
            if (samePhysicalLocation(cardLocation, location)
                    && isSoleRequiredCardCancelPreventerIfRemoved(
                        game, playerId, card)) {
                return true;
            }
        }
        return false;
    }

    public boolean preservesRequiredCardCancelPreventionAt(
            SwccgGame game, String playerId,
            PhysicalCard mover, PhysicalCard destination) {
        if (!analyzed || game == null || playerId == null
                || mover == null || destination == null
                || activeRequiredCardRetentionRules == null
                || !isSoleRequiredCardCancelPreventerIfRemoved(
                    game, playerId, mover)) {
            return false;
        }
        try {
            GameState gameState = game.getGameState();
            Collection<PhysicalCard> permanents =
                    gameState.getAllPermanentCards();
            if (permanents == null) return false;
            for (RequiredCardRetentionRule rule
                    : activeRequiredCardRetentionRules) {
                RequiredCardCancelPrevention prevention =
                        rule != null ? rule.cancelPrevention : null;
                com.gempukku.swccgo.filters.Filter actorFilter =
                        prevention != null
                            ? resolveFilter(
                                prevention.actorFilterKey)
                            : null;
                com.gempukku.swccgo.filters.Filter locationFilter =
                        prevention != null
                            ? resolveLocationFilter(
                                prevention.locationFilterKey,
                                playerId)
                            : null;
                if (actorFilter == null || locationFilter == null
                        || !locationFilter.accepts(
                            gameState,
                            game.getModifiersQuerying(),
                            destination)) {
                    continue;
                }
                for (PhysicalCard card : permanents) {
                    if (card != null
                            && playerId.equals(card.getOwner())
                            && isActiveForSpot(game, card, true)
                            && actorFilter.accepts(
                                gameState,
                                game.getModifiersQuerying(),
                                card)
                            && (card == mover
                                || attachedToOrAboard(
                                    card, mover))) {
                        return true;
                    }
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "Required-card cancel-preventer relocation failed: {}",
                    e.getMessage());
        }
        return false;
    }

    private static boolean
            isSupportedRequiredCardRetentionCondition(
                    FlipLocationAlternative condition) {
        return condition != null
                && "control".equals(condition.relation)
                && "opponent".equals(condition.controller)
                && condition.locationFilterKey != null
                && condition.count != null
                && condition.count.value != null;
    }

    private static String requiredTitleForFilterKey(
            String filterKey) {
        if ("Ominous_Rumors".equals(filterKey)) {
            return "ominous rumors";
        }
        if ("Establish_Secret_Base".equals(filterKey)) {
            return "establish secret base";
        }
        return null;
    }

    public boolean isObjectiveHardLossLocation(
            SwccgGame game, String playerId, PhysicalCard location) {
        if (!analyzed || game == null || playerId == null
                || location == null
                || activeHardLossLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            for (HardLossLocationRule rule
                    : activeHardLossLocationRules) {
                com.gempukku.swccgo.filters.Filter locationFilter =
                        !isActiveHardLossLocationRule(rule)
                                || !"blownAwayLastStep".equals(
                                    rule.trigger)
                                || !"objectiveOutOfPlay".equals(
                                    rule.outcome)
                            ? null
                            : resolveLocationFilter(
                                rule.locationFilterKey, playerId);
                if (locationFilter != null
                        && locationFilter.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), location)) {
                    return true;
                }
            }
        } catch (Exception e) {
            LOG.debug("Objective hard-loss location assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    public boolean isObjectiveHardLossDefenseLocation(
            SwccgGame game, String playerId, PhysicalCard location) {
        if (isFirstOrderReignsTerminalBattleHazardAt(
                game, playerId, location)) {
            return true;
        }
        if (!isObjectiveHardLossLocation(
                    game, playerId, location)) {
            return false;
        }
        try {
            for (HardLossLocationRule rule
                    : activeHardLossLocationRules) {
                if (!isActiveHardLossLocationRule(rule)) {
                    continue;
                }
                com.gempukku.swccgo.filters.Filter defenseFilter =
                        rule == null ? null
                            : resolveLocationFilter(
                                rule.defenseLocationFilterKey,
                                playerId);
                com.gempukku.swccgo.filters.Filter threatFilter =
                        rule == null ? null
                            : resolveFilter(
                                rule.threatCardFilterKey);
                if (defenseFilter == null || threatFilter == null
                        || !defenseFilter.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), location)) {
                    continue;
                }
                Collection<PhysicalCard> permanents =
                        game.getGameState().getAllPermanentCards();
                if (permanents == null) continue;
                for (PhysicalCard threat : permanents) {
                    if (threat == null
                            || playerId.equals(threat.getOwner())
                            || !isActiveForSpot(game, threat, true)
                            || !threatFilter.accepts(
                                game.getGameState(),
                                game.getModifiersQuerying(), threat)) {
                        continue;
                    }
                    PhysicalCard threatLocation =
                            threat.getAttachedTo();
                    if (threatLocation == null) {
                        threatLocation = game.getModifiersQuerying()
                                .getLocationThatCardIsAt(
                            game.getGameState(), threat);
                    }
                    if (isMassassiBaseOperationsFamily()
                            && "Death_Star_system".equals(
                                rule.threatCardFilterKey)) {
                        if (isMassassiYavinBlowAwayThreat(
                                game, playerId, location, threat)) {
                            return true;
                        }
                        continue;
                    }
                    if (samePhysicalLocation(
                            threatLocation, location)) {
                        return true;
                    }
                    if ("onTable".equals(rule.threatRelation)) {
                        return true;
                    }
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "Objective hard-loss defense assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    private boolean isMassassiYavinBlowAwayThreat(
            SwccgGame game, String playerId,
            PhysicalCard yavinSystem, PhysicalCard deathStar) {
        if (!isMassassiBaseOperationsFamily() || isFlipped
                || game == null || playerId == null
                || yavinSystem == null || deathStar == null
                || playerId.equals(deathStar.getOwner())
                || !Filters.Yavin_4_system.accepts(
                    game.getGameState(), game.getModifiersQuerying(),
                    yavinSystem)
                || !Filters.Death_Star_system.accepts(
                    game.getGameState(), game.getModifiersQuerying(),
                    deathStar)
                || !Title.Yavin_4.equals(deathStar.getSystemOrbited())) {
            return false;
        }
        Collection<PhysicalCard> permanents = game.getGameState()
                .getAllPermanentCards();
        if (permanents == null) return false;
        com.gempukku.swccgo.filters.Filter potentialSuperlaser =
                Filters.superlaserThatCanFireAtPlanetSystem(
                    yavinSystem);
        for (PhysicalCard card : permanents) {
            if (card != null && deathStar.getOwner().equals(card.getOwner())
                    && isActiveForSpot(game, card, true)
                    && card.getAttachedTo() == deathStar
                    && potentialSuperlaser.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), card)) {
                return true;
            }
        }
        return false;
    }

    private boolean isActiveHardLossLocationRule(
            HardLossLocationRule rule) {
        if (rule == null || rule.phase == null
                || rule.phase.isBlank()) {
            return rule != null;
        }
        return "preFlip".equals(rule.phase)
                ? !isFlipped
                : "postFlip".equals(rule.phase) && isFlipped;
    }

    public boolean advancesObjectiveHardLossDefenseAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard destination) {
        if (game == null || playerId == null
                || candidate == null || destination == null
                || !playerId.equals(candidate.getOwner())
                || !isObjectiveHardLossDefenseLocation(
                    game, playerId, destination)) {
            return false;
        }
        com.gempukku.swccgo.filters.Filter presenceSource =
                Filters.or(
                    Filters.hasAbilityOrHasPermanentPilotWithAbility,
                    com.gempukku.swccgo.common.Icon.PRESENCE);
        return presenceSource.accepts(
                game.getGameState(),
                game.getModifiersQuerying(), candidate);
    }

    public boolean isFirstOrderReignsTerminalBattleHazardAt(
            SwccgGame game, String playerId,
            PhysicalCard location) {
        if (!analyzed || !isFirstOrderReigns
                || !isFlipped || game == null
                || playerId == null || location == null
                || activeTerminalForfeitRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        Collection<PhysicalCard> permanents =
                game.getGameState()
                    .getAllPermanentCards();
        if (permanents == null) return false;
        for (TerminalForfeitRule rule
                : activeTerminalForfeitRules) {
            if (!isActiveTerminalForfeitRule(rule)) {
                continue;
            }
            com.gempukku.swccgo.filters.Filter locationFilter =
                    resolveLocationFilter(
                        rule.locationFilterKey, playerId);
            com.gempukku.swccgo.filters.Filter actorFilter =
                    resolveFilter(rule.actorFilterKey);
            com.gempukku.swccgo.filters.Filter threatFilter =
                    resolveFilter(rule.threatCardFilterKey);
            if (locationFilter == null || actorFilter == null
                    || threatFilter == null
                    || !locationFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        location)) {
                continue;
            }
            boolean actorHere = false;
            boolean threatHere = false;
            for (PhysicalCard card : permanents) {
                if (card == null || card.getZone() == null
                        || !card.getZone().isInPlay()
                        || !isActiveForSpot(
                            game, card, true)) {
                    continue;
                }
                PhysicalCard cardLocation =
                        game.getModifiersQuerying()
                            .getLocationThatCardIsPresentAt(
                                game.getGameState(), card);
                if (!samePhysicalLocation(
                        cardLocation, location)) {
                    continue;
                }
                if (playerId.equals(card.getOwner())
                        && actorFilter.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(),
                            card)) {
                    actorHere = true;
                } else if (!playerId.equals(card.getOwner())
                        && threatFilter.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(),
                            card)) {
                    threatHere = true;
                }
            }
            if (actorHere && threatHere) return true;
        }
        return false;
    }

    /**
     * Classifies the payoff this actor would actively provide at one location.
     * Unlike classifyPostFlipPayoffAt, this remains true when the payoff is
     * already satisfied so movement can preserve rather than re-score it.
     */
    private AgentsOfBlackSunPayoffProjection
            projectAgentsOfBlackSunPayoff(
                    SwccgGame game, String playerId,
                    PhysicalCard candidate,
                    PhysicalCard destination) {
        AgentsOfBlackSunPayoffProjection none =
                new AgentsOfBlackSunPayoffProjection(
                        false, 0, 0, 0);
        if (!isAgentsOfBlackSunObjectiveFamily() || !isFlipped
                || game == null || playerId == null
                || candidate == null || destination == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return none;
        }
        FlipLocationAlternative payoff =
                agentsOfBlackSunPayoffAlternative();
        if (payoff == null || payoff.count == null) return none;

        try {
            GameState gameState = game.getGameState();
            com.gempukku.swccgo.filters.Filter actorFilter =
                    resolveFilter(payoff.actorFilterKey);
            PhysicalCard payoffDestination =
                    objectivePayoffLocation(game, destination);
            if (actorFilter == null || payoffDestination == null
                    || !locationMatchesAlternative(
                        gameState, game, playerId,
                        payoffDestination, payoff)) {
                return none;
            }

            Set<PhysicalCard> movingGroup =
                    Collections.newSetFromMap(
                            new IdentityHashMap<>());
            movingGroup.add(candidate);
            if (candidate.getZone() != null
                    && candidate.getZone().isInPlay()) {
                movingGroup.addAll(
                        gameState.getAboardCards(candidate, true));
                Collection<PhysicalCard> permanents =
                        gameState.getAllPermanentCards();
                if (permanents != null) {
                    for (PhysicalCard card : permanents) {
                        if (card != null
                                && game.getModifiersQuerying()
                                    .isAboard(
                                        gameState, card,
                                        candidate, true, true)) {
                            movingGroup.add(card);
                        }
                    }
                }
            }

            boolean qualifyingMover = false;
            for (PhysicalCard card : movingGroup) {
                if (card != null
                        && playerId.equals(card.getOwner())
                        && actorFilter.accepts(
                            gameState,
                            game.getModifiersQuerying(), card)
                        && (card.getZone() == null
                            || !card.getZone().isInPlay()
                            || isActiveForSpot(
                                game, card,
                                payoff.includeExcludedFromBattle))) {
                    qualifyingMover = true;
                    break;
                }
            }
            if (!qualifyingMover) return none;

            Set<PhysicalCard> currentActorLocations =
                    Collections.newSetFromMap(
                            new IdentityHashMap<>());
            Set<PhysicalCard> projectedActorLocations =
                    Collections.newSetFromMap(
                            new IdentityHashMap<>());
            PhysicalCard candidateCurrentLocation =
                    candidate.getZone() != null
                            && candidate.getZone().isInPlay()
                        ? game.getModifiersQuerying()
                            .getLocationThatCardIsAt(
                                gameState, candidate)
                        : null;
            Collection<PhysicalCard> permanents =
                    gameState.getAllPermanentCards();
            if (permanents == null) return none;
            for (PhysicalCard card : permanents) {
                if (card == null
                        || !playerId.equals(card.getOwner())
                        || card.getZone() == null
                        || !card.getZone().isInPlay()
                        || !isActiveForSpot(
                            game, card,
                            payoff.includeExcludedFromBattle)
                        || !actorFilter.accepts(
                            gameState,
                            game.getModifiersQuerying(), card)) {
                    continue;
                }
                PhysicalCard currentLocation =
                        game.getModifiersQuerying()
                            .getLocationThatCardIsAt(
                                gameState, card);
                if (currentLocation != null) {
                    currentActorLocations.add(currentLocation);
                    projectedActorLocations.add(
                            movingGroup.contains(card)
                                && samePhysicalLocation(
                                    currentLocation,
                                    candidateCurrentLocation)
                                ? payoffDestination
                                : currentLocation);
                }
            }
            if ((candidate.getZone() == null
                    || !candidate.getZone().isInPlay())
                    && actorFilter.accepts(
                        gameState,
                        game.getModifiersQuerying(), candidate)) {
                projectedActorLocations.add(payoffDestination);
            }

            int current = countAgentsOfBlackSunPayoffLocations(
                    game, playerId, currentActorLocations,
                    null, false);
            boolean projectedGroupProvidesPresence = false;
            for (PhysicalCard card : movingGroup) {
                if (card != null
                        && playerId.equals(card.getOwner())
                        && actorFilter.accepts(
                            gameState,
                            game.getModifiersQuerying(), card)
                        && candidateWouldSatisfyAlternativeAt(
                            game, playerId, card,
                            payoffDestination, payoff)) {
                    projectedGroupProvidesPresence = true;
                    break;
                }
            }
            int projected = countAgentsOfBlackSunPayoffLocations(
                    game, playerId, projectedActorLocations,
                    payoffDestination,
                    projectedGroupProvidesPresence);
            return new AgentsOfBlackSunPayoffProjection(
                    true,
                    expectedCount(game, playerId, payoff.count),
                    current, projected);
        } catch (Exception e) {
            LOG.debug(
                    "Agents of Black Sun payoff projection failed: {}",
                    e.getMessage());
            return none;
        }
    }

    private FlipLocationAlternative
            agentsOfBlackSunPayoffAlternative() {
        if (activeFlipLocationRules == null) return null;
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (rule == null
                    || !"agents-black-sun-back-payoff".equals(rule.id)
                    || rule.alternatives == null) {
                continue;
            }
            for (FlipLocationAlternative alternative
                    : rule.alternatives) {
                if (alternative != null
                        && "postFlipPrimary".equals(
                            alternative.scoreRole)) {
                    return alternative;
                }
            }
        }
        return null;
    }

    private PhysicalCard objectivePayoffLocation(
            SwccgGame game, PhysicalCard destination) {
        if (Filters.location.accepts(
                game.getGameState(),
                game.getModifiersQuerying(), destination)) {
            return destination;
        }
        return game.getModifiersQuerying()
                .getLocationThatCardIsAt(
                    game.getGameState(), destination);
    }

    private int countAgentsOfBlackSunPayoffLocations(
            SwccgGame game, String playerId,
            Set<PhysicalCard> actorLocations,
            PhysicalCard projectedDestination,
            boolean candidateProvidesDestinationPresence) {
        int count = 0;
        for (PhysicalCard location : actorLocations) {
            if (location == null
                    || !Filters.battleground.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), location)) {
                continue;
            }
            boolean occupied = game.getModifiersQuerying()
                    .occupiesLocation(
                        game.getGameState(), location,
                        playerId, null);
            if (!occupied
                    && projectedDestination != null
                    && samePhysicalLocation(
                        location, projectedDestination)
                    && candidateProvidesDestinationPresence) {
                occupied = true;
            }
            if (occupied) count++;
        }
        return count;
    }

    public ObjectivePostFlipPayoffRole classifyPostFlipPayoffRoleAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            PhysicalCard destination) {
        ObjectivePostFlipPayoffRole captureRole =
                CaptureObjectiveFacts.bhbmDuelPayoffRoleAt(
                    game, playerId, this,
                    candidate, destination);
        if (captureRole
                != ObjectivePostFlipPayoffRole.NONE) {
            return captureRole;
        }
        if (qualifiesMassassiAttackRunCarrierAt(
                game, playerId, candidate, destination)) {
            return ObjectivePostFlipPayoffRole.PRIMARY;
        }
        AgentsOfBlackSunPayoffProjection agentsOfBlackSun =
                projectAgentsOfBlackSunPayoff(
                        game, playerId, candidate, destination);
        if (agentsOfBlackSun.qualifyingMover()) {
            return agentsOfBlackSun.projectedLocations() > 0
                    && agentsOfBlackSun.projectedLocations()
                        >= agentsOfBlackSun.currentLocations()
                        ? ObjectivePostFlipPayoffRole.PRIMARY
                        : ObjectivePostFlipPayoffRole.NONE;
        }
        if (!analyzed || !isFlipped || game == null
                || playerId == null || candidate == null
                || destination == null
                || activeFlipLocationRules == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || isFirstOrderReignsTerminalExposureAt(
                    game, playerId, candidate, destination)) {
            return ObjectivePostFlipPayoffRole.NONE;
        }
        if (!canNabooDuelBackTargetOwnActor(
                game, playerId, candidate)) {
            return ObjectivePostFlipPayoffRole.NONE;
        }
        ObjectivePostFlipPayoffRole secondary =
                ObjectivePostFlipPayoffRole.NONE;
        try {
            for (FlipLocationRule rule
                    : activeFlipLocationRules) {
                if (rule == null
                        || !"postFlip".equals(rule.phase)
                        || !"payoff".equals(rule.purpose)
                        || rule.alternatives == null) {
                    continue;
                }
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if (!candidateWouldSatisfyAlternativeAt(
                            game, playerId, candidate,
                            destination, alternative)) {
                        continue;
                    }
                    if ("postFlipPrimary".equals(
                            alternative.scoreRole)) {
                        return ObjectivePostFlipPayoffRole.PRIMARY;
                    }
                    if ("postFlipSecondary".equals(
                            alternative.scoreRole)) {
                        secondary =
                                ObjectivePostFlipPayoffRole.SECONDARY;
                    }
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "Post-flip objective payoff-role assessment failed: {}",
                    e.getMessage());
        }
        return secondary;
    }

    public boolean wouldDowngradePostFlipPayoffIfMoved(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            PhysicalCard destination) {
        if (game == null || candidate == null
                || destination == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        PhysicalCard origin =
                game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                        game.getGameState(), candidate);
        ObjectivePostFlipPayoffRole current =
                classifyPostFlipPayoffRoleAt(
                    game, playerId, candidate, origin);
        ObjectivePostFlipPayoffRole next =
                classifyPostFlipPayoffRoleAt(
                    game, playerId, candidate, destination);
        return postFlipPayoffRank(next)
                < postFlipPayoffRank(current);
    }

    private static int postFlipPayoffRank(
            ObjectivePostFlipPayoffRole role) {
        if (role == ObjectivePostFlipPayoffRole.PRIMARY) {
            return 2;
        }
        return role == ObjectivePostFlipPayoffRole.SECONDARY
                ? 1 : 0;
    }

    public boolean advancesNabooDuelFrontTargetRouteAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            PhysicalCard destination) {
        if (!isNabooDuelObjectiveFamily() || isFlipped
                || game == null || playerId == null
                || candidate == null || destination == null
                || activeFlipLocationRules == null
                || !playerId.equals(candidate.getOwner())) {
            return false;
        }
        try {
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (!isNabooDuelFrontPayoffRule(rule)) continue;
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if ("preFlipPrimary".equals(
                                alternative.scoreRole)
                            && advancesAlternativeAt(
                                game, playerId, candidate,
                                destination, alternative)) {
                        return true;
                    }
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "Naboo duel front target-route assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    public boolean qualifiesNabooDuelFrontTargetRouteAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            PhysicalCard destination) {
        if (!isNabooDuelObjectiveFamily() || isFlipped
                || game == null || playerId == null
                || candidate == null || destination == null
                || activeFlipLocationRules == null
                || !playerId.equals(candidate.getOwner())) {
            return false;
        }
        try {
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (!isNabooDuelFrontPayoffRule(rule)) continue;
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if ("preFlipPrimary".equals(
                                alternative.scoreRole)
                            && candidateWouldSatisfyAlternativeAt(
                                game, playerId, candidate,
                                destination, alternative)) {
                        return true;
                    }
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "Naboo duel front target-route role failed: {}",
                    e.getMessage());
        }
        return false;
    }

    public boolean wouldDowngradeNabooDuelFrontTargetRouteIfMoved(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            PhysicalCard destination) {
        if (game == null || candidate == null
                || destination == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        PhysicalCard origin = game.getModifiersQuerying()
                .getLocationThatCardIsPresentAt(
                    game.getGameState(), candidate);
        return qualifiesNabooDuelFrontTargetRouteAt(
                    game, playerId, candidate, origin)
                && !qualifiesNabooDuelFrontTargetRouteAt(
                    game, playerId, candidate, destination);
    }

    private static boolean isNabooDuelFrontPayoffRule(
            FlipLocationRule rule) {
        return rule != null
                && "preFlip".equals(rule.phase)
                && "payoff".equals(rule.purpose)
                && rule.alternatives != null
                && !rule.alternatives.isEmpty();
    }

    public ObjectivePostFlipPayoffRole classifyPostFlipPayoffAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            PhysicalCard destination) {
        ObjectivePostFlipPayoffRole captureRole =
                CaptureObjectiveFacts.advancesBhhmDuelPayoffAt(
                    game, playerId, this,
                    candidate, destination);
        if (captureRole
                != ObjectivePostFlipPayoffRole.NONE) {
            return captureRole;
        }
        if (qualifiesMassassiAttackRunCarrierAt(
                game, playerId, candidate, destination)) {
            PhysicalCard origin = game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                        game.getGameState(), candidate);
            if (!samePhysicalLocation(origin, destination)) {
                return ObjectivePostFlipPayoffRole.PRIMARY;
            }
        }
        AgentsOfBlackSunPayoffProjection agentsOfBlackSun =
                projectAgentsOfBlackSunPayoff(
                        game, playerId, candidate, destination);
        if (agentsOfBlackSun.qualifyingMover()) {
            return agentsOfBlackSun.currentLocations()
                        < agentsOfBlackSun.requiredLocations()
                    && agentsOfBlackSun.projectedLocations()
                        > agentsOfBlackSun.currentLocations()
                        ? ObjectivePostFlipPayoffRole.PRIMARY
                        : ObjectivePostFlipPayoffRole.NONE;
        }
        if (!analyzed || !isFlipped || game == null
                || playerId == null || candidate == null
                || destination == null
                || activeFlipLocationRules == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || isFirstOrderReignsTerminalExposureAt(
                    game, playerId, candidate, destination)) {
            return ObjectivePostFlipPayoffRole.NONE;
        }
        if (!canNabooDuelBackTargetOwnActor(
                game, playerId, candidate)) {
            return ObjectivePostFlipPayoffRole.NONE;
        }
        ObjectivePostFlipPayoffRole secondary =
                ObjectivePostFlipPayoffRole.NONE;
        try {
            for (FlipLocationRule rule
                    : activeFlipLocationRules) {
                if (rule == null
                        || !"postFlip".equals(rule.phase)
                        || !"payoff".equals(rule.purpose)
                        || rule.alternatives == null) {
                    continue;
                }
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if (!advancesAlternativeAt(
                            game, playerId, candidate,
                            destination, alternative)) {
                        continue;
                    }
                    if ("postFlipPrimary".equals(
                            alternative.scoreRole)) {
                        return ObjectivePostFlipPayoffRole.PRIMARY;
                    }
                    if ("postFlipSecondary".equals(
                            alternative.scoreRole)) {
                        secondary =
                                ObjectivePostFlipPayoffRole.SECONDARY;
                    }
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "Post-flip objective payoff assessment failed: {}",
                    e.getMessage());
        }
        return secondary;
    }

    public boolean isTerminalObjectiveForfeitActor(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (game == null || playerId == null
                || candidate == null
                || game.getGameState() == null
                || game.getGameState().getBattleState() == null
                || !game.getGameState().getBattleState()
                    .isLoser(playerId)
                || !playerId.equals(candidate.getOwner())) {
            return false;
        }
        PhysicalCard battleLocation =
                game.getGameState().getBattleState()
                    .getBattleLocation();
        if (!isFirstOrderReignsTerminalBattleHazardAt(
                game, playerId, battleLocation)) {
            return false;
        }
        for (TerminalForfeitRule rule
                : activeTerminalForfeitRules) {
            if (!isActiveTerminalForfeitRule(rule)) {
                continue;
            }
            com.gempukku.swccgo.filters.Filter actorFilter =
                    resolveFilter(rule.actorFilterKey);
            if (actorFilter != null
                    && actorFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        candidate)) {
                PhysicalCard candidateLocation =
                        game.getModifiersQuerying()
                            .getLocationThatCardIsPresentAt(
                                game.getGameState(),
                                candidate);
                return samePhysicalLocation(
                        candidateLocation, battleLocation);
            }
        }
        return false;
    }

    public boolean isFirstOrderReignsTerminalExposureAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            PhysicalCard destination) {
        if (!analyzed || !isFirstOrderReigns
                || !isFlipped || game == null
                || playerId == null || candidate == null
                || destination == null
                || activeTerminalForfeitRules == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        String opponent =
                game.getGameState().getOpponent(playerId);
        for (TerminalForfeitRule rule
                : activeTerminalForfeitRules) {
            if (!isActiveTerminalForfeitRule(rule)) {
                continue;
            }
            com.gempukku.swccgo.filters.Filter actorFilter =
                    resolveFilter(rule.actorFilterKey);
            com.gempukku.swccgo.filters.Filter locationFilter =
                    resolveLocationFilter(
                        rule.locationFilterKey, playerId);
            com.gempukku.swccgo.filters.Filter threatFilter =
                    resolveFilter(rule.threatCardFilterKey);
            PhysicalCard terminalLocation = destination;
            if (locationFilter != null
                    && !locationFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        terminalLocation)) {
                PhysicalCard destinationHost =
                        game.getModifiersQuerying()
                            .getLocationThatCardIsAt(
                                game.getGameState(),
                                destination);
                if (destinationHost != null) {
                    terminalLocation = destinationHost;
                }
            }
            if (actorFilter != null
                    && locationFilter != null
                    && threatFilter != null
                    && actorFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        candidate)
                    && locationFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(),
                        terminalLocation)) {
                return hasMatchingActorAtLocation(
                        game, opponent, terminalLocation,
                        rule.threatCardFilterKey);
            }
        }
        return false;
    }

    public boolean isFirstOrderReignsTerminalDeploymentHazardAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            PhysicalCard destination) {
        return isFirstOrderReignsTerminalExposureAt(
                game, playerId, candidate, destination);
    }

    private static boolean isActiveTerminalForfeitRule(
            TerminalForfeitRule rule) {
        return rule != null
                && "postFlip".equals(rule.phase)
                && "LOST_PILE".equals(rule.destinationZone)
                && Boolean.TRUE.equals(
                    rule.requiresBattleLost)
                && "objectiveOutOfPlay".equals(
                    rule.outcome);
    }

    public boolean isSolePresenceSourceAtObjectiveHardLossLocation(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        if (game == null || playerId == null || candidate == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || !playerId.equals(candidate.getOwner())) {
            return false;
        }
        PhysicalCard location = game.getModifiersQuerying()
                .getLocationThatCardIsPresentAt(
                        game.getGameState(), candidate);
        return isObjectiveHardLossDefenseLocation(
                    game, playerId, location)
                && isSolePresenceSourceAtLocation(
                    game, playerId, candidate, location);
    }

    public boolean isPullableCard(String cardTitle) {
        if (!analyzed || cardTitle == null) return false;
        String titleLower = cardTitle.toLowerCase(Locale.ROOT);
        for (String pullable : pullableCards) {
            if (titleLower.startsWith(pullable) || titleLower.equals(pullable)) {
                return true;
            }
        }
        return false;
    }

    public boolean isPullableCard(PhysicalCard card) {
        if (card == null || !isPullableCard(card.getTitle())) {
            return false;
        }
        if (isShieldWillBeDown && isFlipped) {
            return false;
        }
        if (isShieldMainGeneratorRequirement(card.getTitle())) {
            return "222_13".equals(
                    card.getBlueprintId(true));
        }
        if (isShieldWillBeDown
                && titleMatchesRequired(
                    card.getTitle(),
                    "prepare for a surface attack")) {
            return "209_42".equals(
                    card.getBlueprintId(true));
        }
        return true;
    }

    private String matchingRequiredTitle(String cardTitle) {
        if (cardTitle == null) return null;
        for (String required : requiredCardsOnTable) {
            if (titleMatchesRequired(cardTitle, required)) return required;
        }
        return null;
    }

    private String matchingRequiredTitle(PhysicalCard card) {
        if (card == null) return null;
        String requirement =
                matchingRequiredTitle(card.getTitle());
        return requirement != null
                && physicalCardMatchesRequirement(
                    card, requirement)
                ? requirement : null;
    }

    private boolean physicalCardMatchesRequirement(
            PhysicalCard card, String requirement) {
        if (card == null
                || !titleMatchesRequired(
                    card.getTitle(), requirement)) {
            return false;
        }
        return !isShieldMainGeneratorRequirement(requirement)
                || "222_13".equals(
                    card.getBlueprintId(true));
    }

    private boolean isShieldMainGeneratorRequirement(
            String titleOrRequirement) {
        return isShieldWillBeDown
                && titleOrRequirement != null
                && titleMatchesRequired(
                    titleOrRequirement,
                    "target the main generator");
    }

    private boolean isShieldCannonRequirement(
            String titleOrRequirement) {
        return isShieldWillBeDown
                && titleOrRequirement != null
                && titleMatchesRequired(
                    titleOrRequirement,
                    "at-at cannon");
    }

    private static boolean containsRequiredTitle(
            Iterable<PhysicalCard> cards, String required) {
        if (cards == null) return false;
        for (PhysicalCard card : cards) {
            if (card != null
                    && titleMatchesRequired(
                            card.getTitle(), required)) {
                return true;
            }
        }
        return false;
    }

    private static boolean titleMatchesRequired(
            String cardTitle, String required) {
        if (cardTitle == null || required == null) return false;
        String titleLower = cardTitle.toLowerCase(Locale.ROOT);
        String requiredLower = required.toLowerCase(Locale.ROOT);
        return titleLower.equals(requiredLower)
                || titleLower.startsWith(requiredLower);
    }

    public float getLocationObjectiveBonus(String locationTitle) {
        if (!analyzed) return 0.0f;

        if (isFlipped) {
            // V22.2: POST-FLIP — protecting locations is MORE important, not less!
            // Returning 0 here was a critical bug: after flipping, Rando stopped caring
            // about objective locations and deployed elsewhere. Now we return a HIGHER
            // bonus because losing these locations means the objective flips BACK.
            if (isFlipBackProtectionLocation(locationTitle)) {
                return 200.0f;  // Higher than pre-flip 150 — defense is critical
            }
            return 0.0f;
        }

        // Pre-flip: standard objective location bonus
        if (isObjectiveRelevantLocation(locationTitle)) {
            return 150.0f;
        }
        return 0.0f;
    }

    /**
     * Game-aware objective bonus. Counted post-flip rules award defense only
     * to current recovery or one-transition risk locations.
     */
    public float getLocationObjectiveBonus(
            PhysicalCard location, SwccgGame game, String playerId) {
        if (!analyzed || location == null) return 0.0f;
        if (isRequiredCardCancelPreventerDefenseLocation(
                game, playerId, location)) {
            return isFlipped ? 200.0f : 150.0f;
        }
        RequiredCardRetentionRisk retentionRisk =
                assessRequiredCardRetentionRisk(
                        game, playerId, location);
        if (retentionRisk.applies()
                && retentionRisk.inScope()
                && retentionRisk.requiresProtection()) {
            return isFlipped ? 200.0f : 150.0f;
        }
        if (isFlipped && hasStructuredFlipBackLocationRules()) {
            PostFlipLocationRisk risk = assessPostFlipLocationRisk(
                    game, playerId, location);
            if (risk.applies()) {
                return risk.requiresProtection() ? 200.0f : 0.0f;
            }
        }
        if (!isFlipped && isObjectiveRelevantLocation(
                location, game, playerId)) {
            return 150.0f;
        }
        return getLocationObjectiveBonus(location.getTitle());
    }

