    public boolean hasObjectiveLocationRouteCandidateInReserve(
            SwccgGame game, String playerId) {
        PhysicalCard objectiveCard = game != null
                && game.getGameState() != null
                ? findOurObjective(game.getGameState(), playerId)
                : null;
        return hasObjectiveLocationRouteCandidateInReserve(
                game, playerId, objectiveCard);
    }

    public boolean hasObjectiveLocationRouteCandidateInReserve(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard) {
        if (!usesObjectiveLocationPullSequence()) return false;
        if (isIWantThatMapObjectiveFamily()) {
            return hasIWantThatMapBattlegroundRouteCandidateInReserve(
                    game, playerId, sourceCard);
        }
        if (isHiddenPathObjectiveFamily()) {
            List<PhysicalCard> reserve = game.getGameState()
                    .getReserveDeck(playerId);
            if (reserve == null) return false;
            for (PhysicalCard card : reserve) {
                if (isNativeObjectiveLocationRouteCandidate(
                        game, playerId, sourceCard, card)) {
                    return true;
                }
            }
            return false;
        }
        if (isCountedOperativeObjectiveFamily()) {
            int routeSiteTarget = getCountedOperativeRouteSiteTarget();
            if (routeSiteTarget <= 0) return false;
            if (countCountedOperativeUsableRouteSites(
                    game, playerId) >= routeSiteTarget) {
                return false;
            }
            List<PhysicalCard> reserve = game.getGameState()
                    .getReserveDeck(playerId);
            if (reserve == null) return false;
            for (PhysicalCard card : reserve) {
                if (isNativeObjectiveLocationRouteCandidate(
                        game, playerId, sourceCard, card)) {
                    return true;
                }
            }
            return false;
        }
        if (isTwinSunsObjectiveFamily() && !isFlipped) {
            if (countTwinSunsUsableRouteSites(
                    game, playerId) >= 2) {
                return false;
            }
            List<PhysicalCard> reserve = game.getGameState()
                    .getReserveDeck(playerId);
            if (reserve == null) return false;
            for (PhysicalCard card : reserve) {
                if (isNativeObjectiveLocationRouteCandidate(
                        game, playerId, sourceCard, card)) {
                    return true;
                }
            }
            return false;
        }
        if (!isFlipped) {
            return hasMissingPreFlipRequiredLocationInReserve(
                    game, playerId);
        }
        if (!needsImperialEntanglementsBackSiteExpansion(
                game, playerId)) {
            return false;
        }
        List<PhysicalCard> reserve = game.getGameState()
                .getCardPile(playerId, Zone.RESERVE_DECK);
        if (reserve == null) return false;
        for (PhysicalCard card : reserve) {
            if (isNativeObjectiveLocationRouteCandidate(
                    game, playerId, card)) {
                return true;
            }
        }
        return false;
    }

    /**
     * True when Reserve Deck still contains a location card that fills an
     * actually missing pre-flip location leg. This lets the deploy script fire
     * objective location actions first while they matter, then stop spending
     * Force on decorative geography after only presence remains missing.
     */
    public boolean hasMissingPreFlipRequiredLocationInReserve(
            SwccgGame game, String playerId) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || game.getGameState() == null) {
            return false;
        }
        try {
            if (isIWantThatMapObjectiveFamily()) {
                Collection<PhysicalCard> permanents =
                        game.getGameState().getAllPermanentCards();
                if (permanents == null) return false;
                for (PhysicalCard source : permanents) {
                    if (isIWantThatMapRouteSource(source, playerId)
                            && isActiveForSpot(game, source, true)
                            && hasIWantThatMapBattlegroundRouteCandidateInReserve(
                                game, playerId, source)) {
                        return true;
                    }
                }
                return false;
            }
            if (isCountedOperativeObjectiveFamily()) {
                return hasObjectiveLocationRouteCandidateInReserve(
                        game, playerId,
                        findOurObjective(
                            game.getGameState(), playerId));
            }
            if (isTwinSunsObjectiveFamily()) {
                return hasObjectiveLocationRouteCandidateInReserve(
                        game, playerId,
                        findOurObjective(
                            game.getGameState(), playerId));
            }
            List<PhysicalCard> reserve = game.getGameState()
                    .getReserveDeck(playerId);
            if (reserve == null) return false;
            for (PhysicalCard card : reserve) {
                if (classifyPreFlipProgressCandidate(
                        game, playerId, card)
                        == ObjectiveProgressCandidateRole
                            .REQUIRED_LOCATION
                        && isNativeObjectiveLocationRouteCandidate(
                            game, playerId, card)) {
                    return true;
                }
            }
        } catch (Exception e) {
            LOG.debug("Objective Reserve location assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

