    public int getSetYourCourseDeathStarSitePullPriority(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        Zone candidateZone = candidate != null
                ? candidate.getZone() : null;
        if (!"111_6".equals(objectiveBlueprintId)
                || isFlipped || game == null || candidate == null
                || !playerId.equals(candidate.getOwner())
                || candidateZone != Zone.RESERVE_DECK
                    && candidateZone != Zone.TOP_OF_RESERVE_DECK
                || !Filters.Death_Star_site.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), candidate)) {
            return 0;
        }
        return exactBlueprint(candidate, "1_283") ? 2 : 1;
    }

    private boolean hasSetYourCourseDeathStarSitePullCandidate(
            SwccgGame game, String playerId) {
        if (game == null || playerId == null
                || game.getGameState() == null) {
            return false;
        }
        List<PhysicalCard> reserve = game.getGameState()
                .getCardPile(playerId, Zone.RESERVE_DECK);
        if (reserve == null) return false;
        for (PhysicalCard card : reserve) {
            if (getSetYourCourseDeathStarSitePullPriority(
                    game, playerId, card) > 0) {
                return true;
            }
        }
        return false;
    }

    public boolean isPreferredSetYourCourseForceLossCandidate(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        if (!"111_6".equals(objectiveBlueprintId)
                || isFlipped || game == null || playerId == null
                || candidate == null
                || !playerId.equals(candidate.getOwner())) {
            return false;
        }
        String protectedRoutePiece =
                isSetYourCourseCompatibleSuperlaser(candidate)
                    ? "SUPERLASER"
                    : exactBlueprint(candidate, "2_130")
                        ? "2_130"
                        : exactBlueprint(candidate, "1_283")
                            ? "1_283" : null;
        if (protectedRoutePiece == null) return false;
        SetYourCourseObjectivePolicy.RouteFacts facts =
                getSetYourCourseRouteFacts(game, playerId);
        if (!facts.classicPackageSupported()) return false;
        if ("SUPERLASER".equals(protectedRoutePiece)
                && facts.compatibleSuperlaserAttached()) {
            return false;
        }
        if ("1_283".equals(protectedRoutePiece)
                && findSetYourCourseLocationOnTable(
                    game.getGameState(), "1_283") != null) {
            return false;
        }
        PhysicalCard preferred = null;
        int preferredRank = Integer.MAX_VALUE;
        for (PhysicalCard card : objectiveForceLossSurvivors(
                game.getGameState(), playerId)) {
            if ("SUPERLASER".equals(protectedRoutePiece)
                    ? !isSetYourCourseCompatibleSuperlaser(card)
                    : !exactBlueprint(card, protectedRoutePiece)) {
                continue;
            }
            int rank = setYourCourseForceLossZoneRank(card.getZone());
            if (preferred == null || rank < preferredRank
                    || rank == preferredRank
                        && card.getCardId() < preferred.getCardId()) {
                preferred = card;
                preferredRank = rank;
            }
        }
        return candidate == preferred;
    }

    public boolean isSetYourCourseMovementForceLossReserveCandidate(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        if (!"111_6".equals(objectiveBlueprintId)
                || isFlipped || game == null || playerId == null
                || candidate == null
                || !playerId.equals(candidate.getOwner())
                || candidate.getZone() != Zone.FORCE_PILE
                    && candidate.getZone() != Zone.TOP_OF_FORCE_PILE) {
            return false;
        }
        int requiredMoveForce =
                getSetYourCourseNextRouteForceReserve(game, playerId);
        return requiredMoveForce > 0
                && game.getGameState().getForcePileSize(playerId)
                    <= requiredMoveForce;
    }

    private PhysicalCard findOwnedSetYourCourseCardInPlay(
            GameState gameState, String playerId, String blueprintId) {
        Collection<PhysicalCard> permanents =
                gameState.getAllPermanentCards();
        if (permanents == null) return null;
        for (PhysicalCard card : permanents) {
            if (isExactOwnedCard(card, playerId, blueprintId)
                    && card.getZone() != null
                    && card.getZone().isInPlay()) {
                return card;
            }
        }
        return null;
    }

    private PhysicalCard findSetYourCourseLocationOnTable(
            GameState gameState, String blueprintId) {
        List<PhysicalCard> locations = gameState.getTopLocations();
        if (locations == null) return null;
        for (PhysicalCard location : locations) {
            if (exactBlueprint(location, blueprintId)) return location;
        }
        return null;
    }

    private PhysicalCard findSetYourCourseSystemOnTable(
            GameState gameState, String title) {
        List<PhysicalCard> locations = gameState.getTopLocations();
        if (locations == null) return null;
        for (PhysicalCard location : locations) {
            if (isNamedSystem(location, title)) return location;
        }
        return null;
    }

    private boolean isNamedSystem(PhysicalCard card, String title) {
        return card != null && card.getBlueprint() != null
                && card.getBlueprint().getCardSubtype()
                    == CardSubtype.SYSTEM
                && title.equals(card.getTitle());
    }

    private boolean hasExactAttachedCard(
            GameState gameState, PhysicalCard host,
            String blueprintId) {
        List<PhysicalCard> attached = gameState.getAttachedCards(host);
        if (attached == null) return false;
        for (PhysicalCard card : attached) {
            if (exactBlueprint(card, blueprintId)) return true;
        }
        return false;
    }

    private boolean isSetYourCourseCompatibleSuperlaser(
            PhysicalCard card) {
        return exactBlueprint(card, "2_161")
                || exactBlueprint(card, "216_19");
    }

    private boolean hasAccessibleSetYourCourseCard(
            GameState gameState, String playerId,
            String blueprintId) {
        return hasExactBlueprint(
                objectiveForceLossSurvivors(gameState, playerId),
                blueprintId);
    }

    private boolean hasExactBlueprint(
            Collection<PhysicalCard> cards, String blueprintId) {
        if (cards == null) return false;
        for (PhysicalCard card : cards) {
            if (exactBlueprint(card, blueprintId)) return true;
        }
        return false;
    }

    private boolean isExactOwnedCard(
            PhysicalCard card, String playerId,
            String blueprintId) {
        return card != null && playerId != null
                && playerId.equals(card.getOwner())
                && exactBlueprint(card, blueprintId);
    }

    private boolean exactBlueprint(
            PhysicalCard card, String blueprintId) {
        try {
            return card != null && blueprintId.equals(
                    card.getBlueprintId(true));
        } catch (Exception e) {
            return false;
        }
    }

    private int setYourCourseForceLossZoneRank(Zone zone) {
        if (zone == Zone.HAND) return 0;
        if (zone == Zone.RESERVE_DECK
                || zone == Zone.TOP_OF_RESERVE_DECK) return 1;
        return 2;
    }

    public boolean isHiddenPathJabiimRouteAction(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText) {
        return isHiddenPathObjectiveFamily()
                && isExactCurrentObjectiveSourceCard(
                    game, playerId, sourceCard)
                && "Deploy a Jabiim location".equals(actionText);
    }

    public boolean isExhaustedHiddenPathJabiimRouteAction(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText) {
        return isHiddenPathJabiimRouteAction(
                    game, playerId, sourceCard, actionText)
                && !hasObjectiveLocationRouteCandidateInReserve(
                    game, playerId, sourceCard);
    }

    public boolean isHiddenPathHolocronAction(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText) {
        return "226_28".equals(objectiveBlueprintId)
                && isExactCurrentObjectiveSourceCard(
                    game, playerId, sourceCard)
                && "Deploy a holocron from Reserve Deck".equals(
                    actionText);
    }

    public boolean isHiddenPathSurvivorRouteAction(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText) {
        return "226_28".equals(objectiveBlueprintId)
                && !isFlipped
                && isHiddenPathStackedSurvivorDeployAction(
                    game, playerId, sourceCard, actionText);
    }

    public boolean isHiddenPathStackedSurvivorDeployAction(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText) {
        if (!isHiddenPathObjectiveFamily()
                || game == null || playerId == null
                || sourceCard == null
                || !playerId.equals(sourceCard.getOwner())
                || !"Deploy a Jedi Survivor stacked here".equals(
                    actionText)) {
            return false;
        }
        try {
            return "226_14".equals(
                    sourceCard.getBlueprintId(true));
        } catch (Exception e) {
            return false;
        }
    }

    public boolean isHiddenPathBackRelocateAction(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText) {
        return isHiddenPathObjectiveFamily() && isFlipped
                && isExactCurrentObjectiveSourceCard(
                    game, playerId, sourceCard)
                && "Relocate a Jedi".equals(actionText);
    }

    public record HiddenPathRelocationAssessment(
            boolean applies,
            boolean legal,
            boolean preservesHold,
            int holdSitesAfter,
            int battlegroundSitesBefore,
            int battlegroundSitesAfter) {
        private static HiddenPathRelocationAssessment none() {
            return new HiddenPathRelocationAssessment(
                    false, false, false, 0, 0, 0);
        }

        public int battlegroundGain() {
            return battlegroundSitesAfter
                    - battlegroundSitesBefore;
        }
    }

    /**
     * Simulates the back-side relocation before the bot commits its two Force.
     * The mover is removed from its origin and added at the destination, so a
     * lone Jedi may not collapse two qualifying hold sites into one.
     */
    public HiddenPathRelocationAssessment assessHiddenPathRelocation(
            SwccgGame game, String playerId,
            PhysicalCard mover, PhysicalCard destination) {
        if (!isHiddenPathObjectiveFamily() || !isFlipped
                || game == null || playerId == null
                || mover == null || destination == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return HiddenPathRelocationAssessment.none();
        }
        try {
            GameState gameState = game.getGameState();
            if (!playerId.equals(mover.getOwner())
                    || mover.isUndercover()
                    || !isActiveForSpot(game, mover, true)
                    || !Filters.Jedi.accepts(
                        gameState, game.getModifiersQuerying(), mover)
                    || !Filters.hasNotPerformedRegularMove.accepts(
                        gameState, game.getModifiersQuerying(), mover)) {
                return new HiddenPathRelocationAssessment(
                        true, false, false, 0, 0, 0);
            }
            PhysicalCard origin = game.getModifiersQuerying()
                    .getLocationThatCardIsPresentAt(
                        gameState, mover);
            if (origin == null
                    || samePhysicalLocation(origin, destination)) {
                return new HiddenPathRelocationAssessment(
                        true, false, false, 0, 0, 0);
            }

            boolean originBattleground = Filters.battleground_site
                    .accepts(gameState, game.getModifiersQuerying(), origin);
            boolean originJabiim = Filters.Jabiim_site
                    .accepts(gameState, game.getModifiersQuerying(), origin);
            boolean destinationBattleground = Filters.battleground_site
                    .accepts(
                        gameState, game.getModifiersQuerying(), destination);
            boolean destinationJabiim = Filters.Jabiim_site
                    .accepts(
                        gameState, game.getModifiersQuerying(), destination);
            boolean routeMatchesCardText =
                    originBattleground && destinationJabiim
                    || originJabiim && destinationBattleground;
            boolean legal = routeMatchesCardText
                    && Filters.locationCanBeRelocatedTo(
                        mover, true, 0).accepts(
                            gameState,
                            game.getModifiersQuerying(), destination);
            if (!legal) {
                return new HiddenPathRelocationAssessment(
                        true, false, false, 0, 0, 0);
            }

            int holdSitesAfter = 0;
            int battlegroundSitesBefore = 0;
            int battlegroundSitesAfter = 0;
            List<PhysicalCard> locations = gameState.getTopLocations();
            if (locations == null) {
                return new HiddenPathRelocationAssessment(
                        true, true, false, 0, 0, 0);
            }
            for (PhysicalCard location : locations) {
                if (location == null) continue;
                boolean battleground = Filters.battleground_site
                        .accepts(
                            gameState,
                            game.getModifiersQuerying(), location);
                boolean holdOccupiedAfter = hasOwnedActiveJediAt(
                        game, playerId, location, mover, true)
                        || samePhysicalLocation(
                            location, destination);
                boolean battlegroundOccupiedBefore =
                        hasOwnedActiveJediAt(
                            game, playerId, location, null, false);
                boolean battlegroundOccupiedAfter =
                        hasOwnedActiveJediAt(
                            game, playerId, location, mover, false)
                        || samePhysicalLocation(location, destination)
                            && isActiveForSpot(game, mover, false);
                if (isHiddenPathHoldLocation(
                        game, playerId, location)
                        && holdOccupiedAfter) {
                    holdSitesAfter++;
                }
                if (battleground && battlegroundOccupiedBefore) {
                    battlegroundSitesBefore++;
                }
                if (battleground && battlegroundOccupiedAfter) {
                    battlegroundSitesAfter++;
                }
            }
            return new HiddenPathRelocationAssessment(
                    true, true, holdSitesAfter >= 2,
                    holdSitesAfter, battlegroundSitesBefore,
                    battlegroundSitesAfter);
        } catch (Exception e) {
            LOG.debug("Hidden Path relocation assessment failed: {}",
                    e.getMessage());
            return HiddenPathRelocationAssessment.none();
        }
    }

    /** Integer.MIN_VALUE means the mover has no legal hold-safe route. */
    public int getBestHiddenPathRelocationBattlegroundGain(
            SwccgGame game, String playerId, PhysicalCard mover) {
        if (game == null || game.getGameState() == null) {
            return Integer.MIN_VALUE;
        }
        int best = Integer.MIN_VALUE;
        List<PhysicalCard> locations =
                game.getGameState().getTopLocations();
        if (locations == null) return best;
        for (PhysicalCard destination : locations) {
            HiddenPathRelocationAssessment assessment =
                    assessHiddenPathRelocation(
                        game, playerId, mover, destination);
            if (assessment.legal()
                    && assessment.preservesHold()
                    && assessment.battlegroundSitesBefore() < 2
                    && isHiddenPathRelocationFormationSafe(
                        game, playerId, mover, destination)) {
                best = Math.max(
                        best, assessment.battlegroundGain());
            }
        }
        return best;
    }

    public boolean hasUsefulHiddenPathRelocation(
            SwccgGame game, String playerId) {
        if (!isHiddenPathObjectiveFamily() || !isFlipped
                || game == null || game.getGameState() == null) {
            return false;
        }
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents == null) return false;
        for (PhysicalCard card : permanents) {
            if (getBestHiddenPathRelocationBattlegroundGain(
                    game, playerId, card) > 0) {
                return true;
            }
        }
        return false;
    }

    public boolean isHiddenPathRelocationFormationSafe(
            SwccgGame game, String playerId,
            PhysicalCard mover, PhysicalCard destination) {
        if (game == null || playerId == null || mover == null
                || destination == null || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            GameState gameState = game.getGameState();
            PhysicalCard origin = game.getModifiersQuerying()
                    .getLocationThatCardIsAt(gameState, mover);
            return origin != null
                    && FormationSafety.vetoMoveDestination(
                        game, gameState, playerId,
                        mover, destination) == null
                    && FormationSafety.vetoMoveOrigin(
                        game, gameState, playerId,
                        mover, origin) == null;
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Exact V67z reserve for the Hidden Path's Underground Corridor action.
     * The card action can move only an active Jedi Survivor that has not made
     * a regular move, and each such move costs one Force. Reserve only the
     * exits that can currently add distinct non-Mapuzo Jedi sites toward the
     * two-site flip gate.
     */
    public int getHiddenPathCorridorTransitForceReserve(
            SwccgGame game, String playerId) {
        if (!"226_28".equals(objectiveBlueprintId)
                || isFlipped || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        try {
            GameState gameState = game.getGameState();
            List<PhysicalCard> locations =
                    gameState.getLocationsInOrder();
            Collection<PhysicalCard> permanents =
                    gameState.getAllPermanentCards();
            if (locations == null || permanents == null) return 0;

            PhysicalCard corridor = null;
            int occupiedHoldSites = 0;
            Set<Integer> occupiedLocationIds = new HashSet<>();
            for (PhysicalCard location : locations) {
                if (location == null) continue;
                if ("226_23".equals(location.getBlueprintId(true))) {
                    corridor = location;
                }
                if (hasHiddenPathJediAt(
                        game, playerId, location, null)) {
                    occupiedHoldSites++;
                    occupiedLocationIds.add(
                            location.getPermanentCardId());
                }
            }
            int sitesStillNeeded = Math.max(
                    0, 2 - occupiedHoldSites);
            if (corridor == null || sitesStillNeeded == 0) return 0;

            Collection<PhysicalCard> survivors =
                    Filters.filterActive(
                        game, null,
                        SpotOverride.INCLUDE_UNDERCOVER,
                        Filters.and(
                            Filters.owner(playerId),
                            Filters.Jedi_Survivor,
                            Filters.hasNotPerformedRegularMove,
                            Filters.here(corridor)));
            if (survivors == null || survivors.isEmpty()) return 0;

            Set<Integer> legalUnfilledDestinationIds =
                    new HashSet<>();
            Set<Integer> legalSurvivorIds =
                    new HashSet<>();
            for (PhysicalCard destination : locations) {
                if (destination == null
                        || occupiedLocationIds.contains(
                            destination.getPermanentCardId())
                        || !isHiddenPathHoldLocation(
                            game, playerId, destination)
                        || !Filters.or(
                                Filters.Jabiim_site,
                                Filters.and(
                                    Filters.opponents(playerId),
                                    Filters.battleground_site))
                            .accepts(
                                gameState,
                                game.getModifiersQuerying(),
                                destination)) {
                    continue;
                }
                for (PhysicalCard survivor : survivors) {
                    if (Filters.canMoveToUsingLocationText(
                            survivor, true, 1.0f, 0.0f)
                            .accepts(
                                gameState,
                                game.getModifiersQuerying(), destination)
                            && isHiddenPathCorridorTransitFormationSafe(
                                game, playerId,
                                survivor, destination)) {
                        legalUnfilledDestinationIds.add(
                                destination.getPermanentCardId());
                        legalSurvivorIds.add(
                                survivor.getPermanentCardId());
                    }
                }
            }
            return Math.min(
                    sitesStillNeeded,
                    Math.min(
                        legalSurvivorIds.size(),
                        legalUnfilledDestinationIds.size()));
        } catch (Exception e) {
            LOG.debug(
                    "Hidden Path Corridor transit reserve unavailable: {}",
                    e.getMessage());
            return 0;
        }
    }

    public boolean isHiddenPathCorridorTransitFormationSafe(
            SwccgGame game, String playerId,
            PhysicalCard survivor, PhysicalCard destination) {
        if (!"226_28".equals(objectiveBlueprintId)
                || isFlipped || game == null || playerId == null
                || survivor == null || destination == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || !isHiddenPathCorridorTransitCandidate(
                    game, playerId, survivor)) {
            return false;
        }
        try {
            GameState gameState = game.getGameState();
            if (!Filters.canMoveToUsingLocationText(
                        survivor, true, 1.0f, 0.0f)
                    .accepts(
                        gameState,
                        game.getModifiersQuerying(), destination)) {
                return false;
            }
            PhysicalCard origin = game.getModifiersQuerying()
                    .getLocationThatCardIsAt(gameState, survivor);
            String opponent = gameState.getOpponent(playerId);
            float nonSpyOpponentPower = 0.0f;
            if (opponent != null) {
                for (PhysicalCard card :
                        gameState.getCardsAtLocation(destination)) {
                    if (card == null || card.isUndercover()
                            || !opponent.equals(card.getOwner())
                            || card.getBlueprint() == null
                            || !card.getBlueprint()
                                .hasPowerAttribute()) {
                        continue;
                    }
                    Float power = card.getBlueprint().getPower();
                    if (power != null) {
                        nonSpyOpponentPower += power;
                    }
                }
            }
            float ourPower = game.getModifiersQuerying()
                    .getTotalPowerAtLocation(
                        gameState, destination,
                        playerId, false, false);
            return origin != null
                    && !MoveDestinationPolicy
                        .hiddenPathPreFlipSuicide(
                            true, destination.getTitle(),
                            nonSpyOpponentPower, ourPower)
                        .applies()
                    && FormationSafety.vetoMoveDestination(
                        game, gameState, playerId,
                        survivor, destination) == null
                    && FormationSafety.vetoMoveOrigin(
                        game, gameState, playerId,
                        survivor, origin) == null;
        } catch (Exception e) {
            return false;
        }
    }

    public boolean hasFormationSafeHiddenPathCorridorTransitTo(
            SwccgGame game, String playerId,
            PhysicalCard destination) {
        if (!"226_28".equals(objectiveBlueprintId)
                || isFlipped || game == null || playerId == null
                || destination == null
                || game.getGameState() == null) {
            return false;
        }
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents == null) return false;
        for (PhysicalCard survivor : permanents) {
            if (isHiddenPathCorridorTransitFormationSafe(
                    game, playerId, survivor, destination)) {
                return true;
            }
        }
        return false;
    }

    public boolean hasUsefulHiddenPathCorridorTransit(
            SwccgGame game, String playerId) {
        return getHiddenPathCorridorTransitForceReserve(
                game, playerId) > 0;
    }

    public int getHiddenPathBackRelocationForceReserve(
            SwccgGame game, String playerId) {
        return hasUsefulHiddenPathRelocation(game, playerId)
                ? 2 : 0;
    }

    public int getHiddenPathMoveForceReserve(
            SwccgGame game, String playerId) {
        return Math.max(
                getHiddenPathCorridorTransitForceReserve(
                    game, playerId),
                getHiddenPathBackRelocationForceReserve(
                    game, playerId));
    }

    /** Exact parent-action payment hidden by the objective/effect source. */
    public int getHiddenPathRouteActionForcePayment(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText) {
        if (isHiddenPathHolocronAction(
                game, playerId, sourceCard, actionText)) {
            return 2;
        }
        if (isHiddenPathStackedSurvivorDeployAction(
                game, playerId, sourceCard, actionText)) {
            return isFlipped ? 7 : 3;
        }
        if (isHiddenPathBackRelocateAction(
                game, playerId, sourceCard, actionText)) {
            return 2;
        }
        return 0;
    }

    public boolean wouldHiddenPathRouteActionConsumeTransitReserve(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText,
            int availableForce) {
        int payment = getHiddenPathRouteActionForcePayment(
                game, playerId, sourceCard, actionText);
        int reserve = getHiddenPathMoveForceReserve(
                game, playerId);
        return payment > 0 && reserve > 0
                && availableForce - payment < reserve;
    }

    public boolean isHiddenPathCorridorTransitCandidate(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (!isHiddenPathObjectiveFamily()
                || game == null || playerId == null
                || candidate == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            if (!isActiveForSpot(game, candidate, true)
                    || !Filters.Jedi_Survivor.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate)
                    || !Filters.hasNotPerformedRegularMove.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate)) {
                return false;
            }
            PhysicalCard location = game.getModifiersQuerying()
                    .getLocationThatCardIsPresentAt(
                        game.getGameState(), candidate);
            return location != null
                    && "226_23".equals(
                        location.getBlueprintId(true));
        } catch (Exception e) {
            return false;
        }
    }

    public boolean isHiddenPathFlipSite(
            SwccgGame game, String playerId,
            PhysicalCard location) {
        return isHiddenPathObjectiveFamily()
                && isHiddenPathHoldLocation(
                    game, playerId, location);
    }

    public boolean advancesHiddenPathDistinctHoldSiteByMovingTo(
            SwccgGame game, String playerId,
            PhysicalCard mover, PhysicalCard destination) {
        return "226_28".equals(objectiveBlueprintId)
                && !isFlipped
                && advancesPreFlipActorAtRuntimeLocation(
                    game, playerId, mover, destination)
                && classifyGateFormationPieceIfRemoved(
                    game, playerId, mover)
                    != FlipGateFormationRole.LAST_REQUIRED_ACTOR;
    }

    public boolean isHiddenPathJediHoldSiteOccupied(
            SwccgGame game, String playerId,
            PhysicalCard location) {
        return isHiddenPathObjectiveFamily()
                && hasHiddenPathJediAt(
                    game, playerId, location, null);
    }

    private boolean isHiddenPathHoldLocation(
            SwccgGame game, String playerId,
            PhysicalCard location) {
        if (game == null || playerId == null || location == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        com.gempukku.swccgo.filters.Filter filter =
                resolveLocationFilter(
                    "non_Mapuzo_site", playerId);
        return filter != null && filter.accepts(
                game.getGameState(),
                game.getModifiersQuerying(), location);
    }

    private boolean hasHiddenPathJediAt(
            SwccgGame game, String playerId,
            PhysicalCard location,
            PhysicalCard ignoredJedi) {
        if (!isHiddenPathHoldLocation(
                game, playerId, location)) {
            return false;
        }
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents == null) return false;
        for (PhysicalCard card : permanents) {
            if (card == null || card == ignoredJedi
                    || !playerId.equals(card.getOwner())
                    || card.isUndercover()
                    || !isActiveForSpot(game, card, true)
                    || !Filters.Jedi.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), card)) {
                continue;
            }
            PhysicalCard actorLocation =
                    game.getModifiersQuerying()
                        .getLocationThatCardIsAt(
                            game.getGameState(), card);
            if (samePhysicalLocation(
                    actorLocation, location)) {
                return true;
            }
        }
        return false;
    }

    private boolean hasOwnedActiveJediAt(
            SwccgGame game, String playerId,
            PhysicalCard location,
            PhysicalCard ignoredJedi,
            boolean includeExcludedFromBattle) {
        if (game == null || playerId == null || location == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents == null) return false;
        for (PhysicalCard card : permanents) {
            if (card == null || card == ignoredJedi
                    || !playerId.equals(card.getOwner())
                    || card.isUndercover()
                    || !isActiveForSpot(
                        game, card, includeExcludedFromBattle)
                    || !Filters.Jedi.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), card)) {
                continue;
            }
            PhysicalCard actorLocation = game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                        game.getGameState(), card);
            if (samePhysicalLocation(actorLocation, location)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Preserves the ordinary one-Force battle payment when a selected-planet
     * battleground contains an exposed friendly force that already has a
     * strict power edge over an opposing card. This remains useful on either
     * objective face, because the flip may occur as soon as the final pair
     * lands while the contested battle is still pending.
     */
    public int getCountedOperativeBattleForceReserve(
            SwccgGame game, String playerId) {
        if (!isCountedOperativeObjectiveFamily() || game == null
                || playerId == null || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        String opponent = game.getGameState().getOpponent(playerId);
        if (opponent == null) return 0;
        for (PhysicalCard location :
                game.getGameState().getTopLocations()) {
            if (!isCountedOperativeChosenPlanetSite(
                    game, location, true)) {
                continue;
            }
            boolean ours = false;
            boolean theirs = false;
            for (PhysicalCard card :
                    game.getGameState().getCardsAtLocation(location)) {
                if (card == null) continue;
                if (playerId.equals(card.getOwner())
                        && !card.isUndercover()) {
                    ours = true;
                } else if (opponent.equals(card.getOwner())) {
                    theirs = true;
                }
            }
            if (!ours || !theirs) continue;
            float ourPower = game.getModifiersQuerying()
                    .getTotalPowerAtLocation(
                        game.getGameState(), location,
                        playerId, false, false);
            float theirPower = game.getModifiersQuerying()
                    .getTotalPowerAtLocation(
                        game.getGameState(), location,
                        opponent, false, false);
            if (ourPower > theirPower) return 1;
        }
        return 0;
    }

    public int getIsbRebelBaseBattleForceReserve(
            SwccgGame game, String playerId) {
        return getIsbRebelBaseBattleForceReserve(
                game, playerId, null);
    }

    public int getIsbRebelBaseBattleForceReserve(
            SwccgGame game, String playerId,
            PhysicalCard deployingCandidate) {
        FlipLocationAlternative alternative =
                findIsbRebelBaseAgentAlternative();
        if (alternative == null || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        if (deployingCandidate != null
                && isIsbFlipCompletionDeployCandidate(
                    game, playerId, deployingCandidate)) {
            return 0;
        }
        String opponent = game.getGameState().getOpponent(playerId);
        if (opponent == null) return 0;
        int required = expectedCount(
                game, playerId, alternative.count);
        int qualified = countAlternativeMatches(
                game, playerId, playerId, alternative);
        if (qualified >= required) return 0;

        int cheapest = Integer.MAX_VALUE;
        for (PhysicalCard location
                : game.getGameState().getLocationsInOrder()) {
            if (!locationMatchesAlternative(
                        game.getGameState(), game, playerId,
                        location, alternative)
                    || relationSatisfiedAt(
                        game, playerId, playerId, location,
                        alternative.relation,
                        alternative.actorFilterKey,
                        alternative.includeExcludedFromBattle,
                        alternative.spotOverride)
                    || !hasMatchingActorAtLocation(
                        game, playerId, location,
                        alternative.actorFilterKey,
                        alternative.includeExcludedFromBattle, true)
                    || qualified + 1 < required
                    || !com.gempukku.swccgo.cards.GameConditions
                        .canInitiateBattleAtLocation(
                            playerId, game, location,
                            false, true)
                    || FormationSafety.vetoInitiateBattle(
                        game, game.getGameState(), playerId,
                        location) != null) {
                continue;
            }
            boolean opponentPresent = false;
            for (PhysicalCard card
                    : game.getGameState().getCardsAtLocation(location)) {
                if (card != null
                        && opponent.equals(card.getOwner())
                        && !card.isUndercover()) {
                    opponentPresent = true;
                    break;
                }
            }
            if (!opponentPresent) continue;
            float ourPower = game.getModifiersQuerying()
                    .getTotalPowerAtLocation(
                        game.getGameState(), location,
                        playerId, false, false);
            float theirPower = game.getModifiersQuerying()
                    .getTotalPowerAtLocation(
                        game.getGameState(), location,
                        opponent, false, false);
            if (ourPower <= theirPower) continue;
            try {
                float cost = game.getModifiersQuerying()
                        .getInitiateBattleCost(
                            game.getGameState(), location,
                            playerId, true);
                cheapest = Math.min(cheapest,
                        Math.max(0, (int) Math.ceil(cost)));
            } catch (Exception ignored) {
            }
        }
        return cheapest == Integer.MAX_VALUE ? 0 : cheapest;
    }

    private boolean isCountedOperativeChosenPlanetSite(
            SwccgGame game, PhysicalCard location,
            boolean requireBattleground) {
        if (!isCountedOperativeObjectiveFamily() || game == null
                || location == null || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || !Filters.site.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), location)) {
            return false;
        }
        String chosenPlanet = "7_137".equals(objectiveBlueprintId)
                || "7_137_BACK".equals(objectiveBlueprintId)
                    ? game.getGameState().getSubjugatedPlanet()
                    : game.getGameState().getRenegadePlanet();
        return chosenPlanet != null
                && chosenPlanet.equals(location.getPartOfSystem())
                && (!requireBattleground
                    || Filters.battleground.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), location));
    }

    public boolean isCountedOperativeSetupSystemChoiceOpen(
            SwccgGame game) {
        if (!isCountedOperativeObjectiveFamily() || isFlipped
                || game == null || game.getGameState() == null) {
            return false;
        }
        return "7_137".equals(objectiveBlueprintId)
                ? game.getGameState().getSubjugatedPlanet() == null
                : "7_298".equals(objectiveBlueprintId)
                    && game.getGameState().getRenegadePlanet() == null;
    }

    public boolean hasRalltiirFrontRouteCandidateInReserve(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard) {
        if (!isRalltiirOperationsFamily() || isFlipped
                || game == null || playerId == null
                || sourceCard == null
                || !isExactCurrentObjectiveSourceCard(
                    game, playerId, sourceCard)
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        List<PhysicalCard> reserve = game.getGameState()
                .getReserveDeck(playerId);
        if (reserve == null) return false;
        for (PhysicalCard candidate : reserve) {
            if (getRalltiirFrontPullCandidatePriority(
                    game, playerId, sourceCard, candidate) > 0) {
                return true;
            }
        }
        return false;
    }

    /**
     * Stages the mixed native route. A legal site wins until three usable
     * control lanes exist. Once an existing site can accept a progressing
     * Imperial, the cheapest legal non-unique Imperial wins instead.
     */
    public int getRalltiirFrontPullCandidatePriority(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, PhysicalCard candidate) {
        if (!isRalltiirOperationsFamily() || isFlipped
                || game == null || playerId == null
                || sourceCard == null || candidate == null
                || !isExactCurrentObjectiveSourceCard(
                    game, playerId, sourceCard)) {
            return 0;
        }
        if (isRalltiirFrontSiteRouteCandidate(
                game, playerId, sourceCard, candidate)) {
            return 3;
        }
        if (hasRalltiirFrontSiteRouteCandidateInReserve(
                    game, playerId, sourceCard)) {
            return 0;
        }
        return isRalltiirFrontImperialRouteCandidate(
                game, playerId, sourceCard, candidate) ? 2 : 0;
    }

    public boolean hasRalltiirFrontSiteRouteCandidateInReserve(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard) {
        if (!isRalltiirOperationsFamily() || isFlipped
                || game == null || playerId == null
                || sourceCard == null
                || !isExactCurrentObjectiveSourceCard(
                    game, playerId, sourceCard)
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        List<PhysicalCard> reserve = game.getGameState()
                .getReserveDeck(playerId);
        if (reserve == null) return false;
        for (PhysicalCard candidate : reserve) {
            if (isRalltiirFrontSiteRouteCandidate(
                    game, playerId, sourceCard, candidate)) {
                return true;
            }
        }
        return false;
    }

    private boolean isRalltiirFrontSiteRouteCandidate(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, PhysicalCard candidate) {
        if (candidate == null
                || !playerId.equals(candidate.getOwner())) {
            return false;
        }
        try {
            return Filters.site.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate)
                    && needsRalltiirFrontSiteRoute(
                        game, playerId, sourceCard)
                    && Filters.deployableToSystem(
                        sourceCard, Title.Ralltiir,
                        null, false, 0.0f).accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), candidate);
        } catch (Exception e) {
            return false;
        }
    }

    private boolean needsRalltiirFrontSiteRoute(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard) {
        return sourceCard != null
                && countRalltiirUsableRouteSites(
                    game, playerId) < 3;
    }

    private boolean isRalltiirFrontImperialRouteCandidate(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, PhysicalCard candidate) {
        if (sourceCard == null || candidate == null
                || !playerId.equals(candidate.getOwner())) {
            return false;
        }
        try {
            if (!Filters.and(Filters.non_unique, Filters.Imperial)
                    .accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate)) {
                return false;
            }
            if (!Filters.deployableToSystem(
                        sourceCard, Title.Ralltiir,
                        null, false, 0.0f).accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), candidate)) {
                return false;
            }
            for (PhysicalCard location
                    : game.getGameState().getLocationsInOrder()) {
                if (advancesPreFlipRequirementAt(
                            game, playerId, candidate, location)
                        && Filters.deployableToLocation(
                            sourceCard, Filters.sameCardId(location),
                            false, 0.0f).accepts(
                                game.getGameState(),
                                game.getModifiersQuerying(), candidate)) {
                    return true;
                }
            }
        } catch (Exception e) {
            return false;
        }
        return false;
    }

    private int countRalltiirSitesOnTable(SwccgGame game) {
        if (game == null || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        int count = 0;
        for (PhysicalCard location
                : game.getGameState().getLocationsInOrder()) {
            if (location != null && Filters.Ralltiir_site.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), location)) {
                count++;
            }
        }
        return count;
    }

    private int countRalltiirQualifiedSites(
            SwccgGame game, String playerId) {
        if (game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        int count = 0;
        for (PhysicalCard location
                : game.getGameState().getLocationsInOrder()) {
            if (location != null
                    && Filters.Ralltiir_site.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), location)
                    && relationSatisfiedAt(
                        game, playerId, playerId, location,
                        "controlWith", "Imperial", true, null)) {
                count++;
            }
        }
        return count;
    }

    private int countRalltiirUsableRouteSites(
            SwccgGame game, String playerId) {
        if (game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        FlipLocationAlternative alternative =
                findRalltiirControlWithAlternative();
        if (alternative == null) return 0;
        Map<com.gempukku.swccgo.common.InactiveReason, Boolean> overrides =
                resolveSpotOverride(
                    alternative.includeExcludedFromBattle,
                    alternative.spotOverride);
        String opponent = game.getGameState().getOpponent(playerId);
        int count = 0;
        for (PhysicalCard location
                : game.getGameState().getLocationsInOrder()) {
            if (location == null
                    || !Filters.Ralltiir_site.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), location)) {
                continue;
            }
            if (relationSatisfiedAt(
                        game, playerId, playerId, location,
                        alternative.relation,
                        alternative.actorFilterKey,
                        alternative.includeExcludedFromBattle,
                        alternative.spotOverride)
                    || opponent == null
                    || !game.getModifiersQuerying().occupiesLocation(
                            game.getGameState(), location,
                            opponent, overrides)) {
                count++;
            }
        }
        return count;
    }

    private Integer cheapestRalltiirImperialDeployCost(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, PhysicalCard candidate) {
        Integer cheapest = null;
        for (PhysicalCard location
                : game.getGameState().getLocationsInOrder()) {
            if (!advancesPreFlipRequirementAt(
                        game, playerId, candidate, location)
                    || !Filters.deployableToLocation(
                        sourceCard, Filters.sameCardId(location),
                        false, 0.0f).accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), candidate)) {
                continue;
            }
            Integer cost = requiredCardDeployCostAt(
                    game, sourceCard, candidate, location);
            if (cost != null
                    && (cheapest == null || cost < cheapest)) {
                cheapest = cost;
            }
        }
        return cheapest;
    }

    /**
     * Projects an objective's initial generic-site choice at the already
     * chosen operative planet. Arbitrary-card setup decisions expose blueprint
     * ids rather than stable physical ids, so resolve the offered printing
     * against Reserve Deck and apply the same source-defined deploy law and
     * battleground test used by the later native site pull.
     */
    public boolean isCountedOperativeSetupSiteRouteCandidate(
            SwccgGame game, String playerId,
            String blueprintId) {
        if (!isCountedOperativeObjectiveFamily() || isFlipped
                || game == null || playerId == null
                || blueprintId == null || blueprintId.isBlank()
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        PhysicalCard objectiveCard = findOurObjective(
                game.getGameState(), playerId);
        List<PhysicalCard> reserve = game.getGameState()
                .getReserveDeck(playerId);
        if (objectiveCard == null || reserve == null) return false;
        for (PhysicalCard candidate : reserve) {
            if (candidate != null
                    && blueprintId.equals(
                            candidate.getBlueprintId(true))) {
                String chosenPlanet = "7_137".equals(objectiveBlueprintId)
                        ? game.getGameState().getSubjugatedPlanet()
                        : game.getGameState().getRenegadePlanet();
                if (chosenPlanet != null
                        && Filters.generic.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), candidate)
                        && Filters.site.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), candidate)
                        && Filters.deployableToSystem(
                            objectiveCard, chosenPlanet,
                            Filters.battleground, true, 0.0f).accepts(
                                game.getGameState(),
                                game.getModifiersQuerying(), candidate)) {
                    return true;
                }
            }
        }
        return false;
    }

    public int countMatchingOperativesAvailableForSetupSystem(
            SwccgGame game, String playerId,
            SwccgCardBlueprint systemBlueprint) {
        if (!isCountedOperativeSetupSystemChoiceOpen(game)
                || playerId == null || systemBlueprint == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        String systemName;
        try {
            systemName = systemBlueprint.getSystemName();
        } catch (Exception e) {
            return 0;
        }
        if (systemName == null) return 0;

        List<PhysicalCard> candidates = new ArrayList<>();
        candidates.addAll(game.getGameState().getReserveDeck(playerId));
        candidates.addAll(game.getGameState().getHand(playerId));
        int count = 0;
        for (PhysicalCard card : candidates) {
            if (card == null || !playerId.equals(card.getOwner())
                    || card.getBlueprint() == null) {
                continue;
            }
            try {
                if (Filters.operative.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), card)
                        && systemName.equals(
                            card.getBlueprint().getMatchingSystem())) {
                    count++;
                }
            } catch (Exception ignored) {
                // Non-operative blueprints do not expose matchingSystem.
            }
        }
        return count;
    }

    /**
     * Separates the broad location law from the exact native download route.
     * Imperial Entanglements counts every Tatooine site after it reaches the
     * table, but its action can deploy only a currently legal battleground
     * site and its permanent restriction forbids Jabba's Palace sites.
     */
    public boolean isNativeObjectiveLocationRouteCandidate(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        PhysicalCard objectiveCard = game != null
                && game.getGameState() != null
                ? findOurObjective(game.getGameState(), playerId)
                : null;
        return isNativeObjectiveLocationRouteCandidate(
                game, playerId, objectiveCard, candidate);
    }

    public boolean isNativeObjectiveLocationRouteCandidate(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, PhysicalCard candidate) {
        if ((!isMassassiBaseOperationsFamily()
                    && !isImperialEntanglementsFamily()
                    && !isOldAlliesObjectiveFamily()
                    && !isCountedOperativeObjectiveFamily()
                    && !isHiddenPathObjectiveFamily()
                    && !isTwinSunsObjectiveFamily()
                    && !isIWantThatMapObjectiveFamily())
                || isFlipped && !isImperialEntanglementsFamily()
                    && !isCountedOperativeObjectiveFamily()
                    && !isHiddenPathObjectiveFamily()
                || game == null || playerId == null
                || candidate == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        PhysicalCard objectiveCard = findOurObjective(
                game.getGameState(), playerId);
        if (objectiveCard == null
                || !isCurrentObjectiveSourceCard(objectiveCard)) {
            return false;
        }
        if (isIWantThatMapObjectiveFamily()) {
            return isIWantThatMapNativeBattlegroundRouteCandidate(
                    game, playerId, sourceCard, candidate);
        }
        if (isCountedOperativeObjectiveFamily()) {
            int routeSiteTarget = getCountedOperativeRouteSiteTarget();
            if (sourceCard == null
                    || routeSiteTarget <= 0
                    || countCountedOperativeUsableRouteSites(
                        game, playerId) >= routeSiteTarget
                    || !isCountedOperativeSiteRouteSource(
                        game, playerId, sourceCard)
                    || !Filters.site.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), candidate)) {
                return false;
            }
            boolean objectiveSource =
                    isCurrentObjectiveSourceCard(sourceCard);
            String chosenPlanet = "7_137".equals(objectiveBlueprintId)
                    || "7_137_BACK".equals(objectiveBlueprintId)
                    ? game.getGameState().getSubjugatedPlanet()
                    : game.getGameState().getRenegadePlanet();
            boolean routeSite = objectiveSource
                    ? Filters.generic.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate)
                    : chosenPlanet != null
                        && (Filters.generic.accepts(
                                game.getGameState(),
                                game.getModifiersQuerying(), candidate)
                            || chosenPlanet.equals(
                                candidate.getPartOfSystem()));
            // Generic sites acquire their planet relation only while the
            // engine projects a placement. Check both legality and the
            // battleground flip condition at that exact chosen planet.
            // An unprojected Jungle appears to be a battleground in Reserve,
            // but it is barred from Tatooine and becomes a non-battleground
            // on Dagobah, so neither route advances this objective.
            return routeSite && chosenPlanet != null
                    && Filters.deployableToSystem(
                        sourceCard, chosenPlanet,
                        Filters.battleground, false, 0.0f).accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate);
        }
        if (isHiddenPathObjectiveFamily()) {
            return sourceCard != null
                    && isExactCurrentObjectiveSourceCard(
                        game, playerId, sourceCard)
                    && Filters.Jabiim_location.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate)
                    && Filters.deployable(
                        objectiveCard, null,
                        false, 0.0f).accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), candidate);
        }
        if (isTwinSunsObjectiveFamily()) {
            return !isFlipped
                    && sourceCard != null
                    && isExactCurrentObjectiveSourceCard(
                        game, playerId, sourceCard)
                    && countTwinSunsUsableRouteSites(
                        game, playerId) < 2
                    && Filters.Tatooine_battleground_site.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate)
                    && Filters.deployable(
                        objectiveCard, Filters.battleground,
                        false, 0.0f).accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), candidate);
        }
        com.gempukku.swccgo.filters.Filter printedFilter =
                isMassassiBaseOperationsFamily()
                    ? Filters.Yavin_4_site
                    : isOldAlliesObjectiveFamily()
                    ? Filters.Jakku_battleground_site
                    : Filters.Tatooine_site;
        com.gempukku.swccgo.filters.Filter specialLocationConditions =
                isImperialEntanglementsFamily()
                    ? Filters.battleground : null;
        return printedFilter.accepts(
                    game.getGameState(), game.getModifiersQuerying(),
                    candidate)
                && Filters.deployable(
                    objectiveCard, specialLocationConditions,
                    false, 0.0f).accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate);
    }

    public boolean isCountedOperativeSiteRouteAction(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText) {
        return isCountedOperativeObjectiveFamily()
                && actionText != null
                && "deploy site from reserve deck".equals(
                    actionText.trim().toLowerCase(Locale.ROOT))
                && isCountedOperativeSiteRouteSource(
                    game, playerId, sourceCard)
                && hasObjectiveLocationRouteCandidateInReserve(
                    game, playerId, sourceCard);
    }

    /**
     * True when the native operative-objective site action is still offered by
     * the engine after its three-site route is complete, or when no legal
     * battleground candidate remains. The deploy script omits this action from
     * its location bucket; callers must also hard-block it so the generic
     * non-bucket epilogue cannot resurrect the strategically exhausted pull.
     */
    public boolean isExhaustedCountedOperativeSiteRouteAction(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText) {
        return isCountedOperativeObjectiveFamily()
                && actionText != null
                && "deploy site from reserve deck".equals(
                    actionText.trim().toLowerCase(Locale.ROOT))
                && isCountedOperativeSiteRouteSource(
                    game, playerId, sourceCard)
                && !hasObjectiveLocationRouteCandidateInReserve(
                    game, playerId, sourceCard);
    }

    public boolean isCountedOperativeSiteRouteSource(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard) {
        if (!isCountedOperativeObjectiveFamily()
                || game == null || playerId == null
                || sourceCard == null
                || !playerId.equals(sourceCard.getOwner())) {
            return false;
        }
        if (isCurrentObjectiveSourceCard(sourceCard)) return !isFlipped;
        if (!matchesCountedOperativeActor(
                    game, playerId, sourceCard,
                    findCountedOperativeSourceAlternative())) {
            return false;
        }
        PhysicalCard sourceLocation = presenceContributionLocation(
                game, sourceCard);
        return isCountedOperativeChosenPlanetSite(
                game, sourceLocation, false);
    }

    private int getCountedOperativeRouteSiteTarget() {
        FlipLocationAlternative alternative =
                findCountedOperativeSourceAlternative();
        return alternative != null && alternative.count != null
                && alternative.count.value != null
                ? alternative.count.value : 0;
    }

    private int countCountedOperativeUsableRouteSites(
            SwccgGame game, String playerId) {
        FlipLocationAlternative alternative =
                findCountedOperativeSourceAlternative();
        if (alternative == null || game == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        List<PhysicalCard> locations =
                game.getGameState().getLocationsInOrder();
        if (locations == null) return 0;
        String opponent = game.getGameState().getOpponent(playerId);
        Map<com.gempukku.swccgo.common.InactiveReason, Boolean> overrides =
                resolveSpotOverride(
                    alternative.includeExcludedFromBattle,
                    alternative.spotOverride);
        int usable = 0;
        for (PhysicalCard location : locations) {
            if (!isCountedOperativeChosenPlanetSite(
                    game, location, true)) {
                continue;
            }
            boolean complete = relationSatisfiedAt(
                    game, playerId, playerId, location,
                    alternative.relation,
                    alternative.actorFilterKey,
                    alternative.includeExcludedFromBattle,
                    alternative.spotOverride);
            boolean contested = opponent != null
                    && game.getModifiersQuerying().occupiesLocation(
                        game.getGameState(), location,
                        opponent, overrides);
            if (complete || !contested) usable++;
        }
        return usable;
    }

    private int countTwinSunsUsableRouteSites(
            SwccgGame game, String playerId) {
        if (!isTwinSunsObjectiveFamily() || isFlipped
                || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        List<PhysicalCard> locations =
                game.getGameState().getLocationsInOrder();
        if (locations == null) return 0;
        String opponent = game.getGameState().getOpponent(playerId);
        Map<com.gempukku.swccgo.common.InactiveReason, Boolean> overrides =
                resolveSpotOverride(true, null);
        int usable = 0;
        for (PhysicalCard location : locations) {
            if (location == null
                    || !Filters.Tatooine_battleground_site.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), location)) {
                continue;
            }
            boolean selfControls = game.getModifiersQuerying()
                    .controlsLocation(
                        game.getGameState(), location,
                        playerId, overrides);
            boolean opponentControls = opponent != null
                    && game.getModifiersQuerying().controlsLocation(
                        game.getGameState(), location,
                        opponent, overrides);
            if (selfControls || !opponentControls) usable++;
        }
        return usable;
    }

    public boolean isImperialEntanglementsBackSiteExpansionCandidate(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        return isImperialEntanglementsFamily() && isFlipped
                && needsImperialEntanglementsBackSiteExpansion(
                    game, playerId)
                && isNativeObjectiveLocationRouteCandidate(
                    game, playerId, candidate);
    }

    public boolean isImperialEntanglementsBackSiteRouteAction(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText) {
        return isImperialEntanglementsFamily() && isFlipped
                && game != null && playerId != null
                && sourceCard != null
                && isExactCurrentObjectiveSourceCard(
                    game, playerId, sourceCard)
                && actionText != null
                && "deploy tatooine battleground site from reserve deck"
                    .equals(actionText.trim().toLowerCase(Locale.ROOT))
                && needsImperialEntanglementsBackSiteExpansion(
                    game, playerId)
                && hasObjectiveLocationRouteCandidateInReserve(
                    game, playerId);
    }

    public boolean isMassassiFrontSiteRouteAction(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText) {
        return isMassassiBaseOperationsFamily() && !isFlipped
                && game != null && playerId != null
                && sourceCard != null
                && isExactCurrentObjectiveSourceCard(
                    game, playerId, sourceCard)
                && actionText != null
                && "deploy yavin 4 site from reserve deck"
                    .equals(actionText.trim().toLowerCase(Locale.ROOT))
                && hasObjectiveLocationRouteCandidateInReserve(
                    game, playerId);
    }

    public boolean isOldAlliesFrontLocationRouteAction(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText) {
        return isOldAlliesObjectiveFamily() && !isFlipped
                && game != null && playerId != null
                && sourceCard != null
                && isExactCurrentObjectiveSourceCard(
                    game, playerId, sourceCard)
                && actionText != null
                && "deploy jakku location from reserve deck"
                    .equals(actionText.trim().toLowerCase(Locale.ROOT))
                && hasObjectiveLocationRouteCandidateInReserve(
                    game, playerId);
    }

    public boolean isISBBackAgentRetrievalAction(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText) {
        if (!analyzed || !isISBOperations || !isFlipped
                || game == null || playerId == null
                || sourceCard == null
                || !isExactCurrentObjectiveSourceCard(
                    game, playerId, sourceCard)
                || actionText == null
                || !"retrieve an isb agent".equals(
                    actionText.trim().toLowerCase(Locale.ROOT))
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        List<PhysicalCard> lostPile =
                game.getGameState().getLostPile(playerId);
        if (lostPile == null) return false;
        for (PhysicalCard card : lostPile) {
            if (card != null && playerId.equals(card.getOwner())
                    && Filters.ISB_agent.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), card)) {
                return true;
            }
        }
        return false;
    }

    private boolean isExactCurrentObjectiveSourceCard(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard) {
        return game != null && game.getGameState() != null
                && playerId != null && sourceCard != null
                && sourceCard == findOurObjective(
                    game.getGameState(), playerId);
    }

    private boolean needsImperialEntanglementsBackSiteExpansion(
            SwccgGame game, String playerId) {
        if (!isImperialEntanglementsFamily() || !isFlipped
                || game == null || playerId == null
                || activeFlipLocationRules == null
                || game.getGameState() == null) {
            return false;
        }
        String opponent = game.getGameState().getOpponent(playerId);
        if (opponent == null) return false;
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (rule == null || !"postFlip".equals(rule.phase)
                    || !"flipBack".equals(rule.purpose)
                    || rule.alternatives == null) {
                continue;
            }
            for (FlipLocationAlternative alternative
                    : rule.alternatives) {
                if (!isSupportedCountedFlipBackAlternative(
                        alternative)) {
                    continue;
                }
                int selfCount = countAlternativeMatches(
                        game, playerId, playerId, alternative);
                int opponentCount = countAlternativeMatches(
                        game, playerId, opponent, alternative);
                return selfCount <= opponentCount + 1;
            }
        }
        return false;
    }

    /**
     * The permanent Massassi back is an assembly line, not a generic card
     * draw. Rebel Tech must lead so it can fetch the Trench during the next
     * control phase, followed by Death Star, Attack Run, and Torpedoes.
     */
    public int getMassassiAttackRunPackagePullPriority(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        int rank = massassiAttackRunPackageRank(
                game, playerId, candidate);
        if (!isMassassiBaseOperationsFamily() || !isFlipped
                || rank == 0 || game == null || playerId == null
                || candidate == null
                || candidate.getZone() != Zone.RESERVE_DECK
                    && candidate.getZone() != Zone.TOP_OF_RESERVE_DECK
                || !playerId.equals(candidate.getOwner())
                || rank != massassiPackagePullFrontierRank(
                        game, playerId)) {
            return 0;
        }
        return rank;
    }

    public boolean isPreferredMassassiWarRoomPullCandidate(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        return isMassassiBaseOperationsFamily() && !isFlipped
                && game != null && playerId != null && candidate != null
                && playerId.equals(candidate.getOwner())
                && Filters.Massassi_War_Room.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate);
    }

    public boolean isMassassiAttackRunPackageUploadAction(
            SwccgGame game, String playerId,
            PhysicalCard sourceCard, String actionText) {
        if (!isMassassiBaseOperationsFamily() || !isFlipped
                || game == null || playerId == null || sourceCard == null
                || !isExactCurrentObjectiveSourceCard(
                    game, playerId, sourceCard)
                || actionText == null) {
            return false;
        }
        String text = actionText.toLowerCase(Locale.ROOT);
        if (!text.contains("into hand")
                || !text.contains("reserve deck")) {
            return false;
        }
        List<PhysicalCard> reserve = game.getGameState()
                .getReserveDeck(playerId);
        if (reserve == null) return false;
        for (PhysicalCard card : reserve) {
            if (getMassassiAttackRunPackagePullPriority(
                    game, playerId, card) > 0) {
                return true;
            }
        }
        return false;
    }

    public boolean isPreferredMassassiAttackRunPackageForceLossCandidate(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        if (!isMassassiBaseOperationsFamily() || !isFlipped
                || game == null || playerId == null || candidate == null
                || !playerId.equals(candidate.getOwner())) {
            return false;
        }
        boolean trenchOnTable = hasOwnedMassassiCardInPlay(
                game, playerId, Filters.Death_Star_Trench);
        PhysicalCard protectedTrench = trenchOnTable
                ? null : preferredMassassiPackageCardSurvivor(
                    game, playerId, Filters.Death_Star_Trench);
        if (candidate == protectedTrench) return true;

        boolean trenchReadyInHand = protectedTrench != null
                && protectedTrench.getZone() == Zone.HAND;
        if (!trenchOnTable && !trenchReadyInHand
                && protectedTrench != null
                && !hasActiveMassassiRebelTechInPlay(
                    game, playerId)
                && candidate == preferredMassassiPackageCardSurvivor(
                    game, playerId, Filters.Rebel_Tech)) {
            return true;
        }

        if (Filters.findFirstFromTopLocationsOnTable(
                    game, Filters.Death_Star_system) == null
                && candidate == preferredMassassiPackageRankSurvivor(
                    game, playerId, 3)) {
            return true;
        }
        if (!hasOwnedMassassiCardInPlay(
                    game, playerId, Filters.Attack_Run)
                && candidate == preferredMassassiPackageRankSurvivor(
                    game, playerId, 2)) {
            return true;
        }

        if (!hasOwnedCompatibleMassassiTorpedoesInPlay(
                game, playerId)) {
            PhysicalCard protectedTorpedoes =
                    preferredMassassiPackageRankSurvivor(
                        game, playerId, 1);
            if (candidate == protectedTorpedoes) return true;
            PhysicalCard protectedCarrier =
                    preferredMassassiAttackRunCarrierSurvivor(
                        game, playerId, protectedTorpedoes);
            if (candidate == protectedCarrier) return true;
        }
        return false;
    }

    private PhysicalCard preferredMassassiPackageRankSurvivor(
            SwccgGame game, String playerId, int rank) {
        PhysicalCard preferred = null;
        int preferredZoneRank = Integer.MAX_VALUE;
        for (PhysicalCard card : objectiveForceLossSurvivors(
                game.getGameState(), playerId)) {
            if (card == null || massassiAttackRunPackageRank(
                    game, playerId, card) != rank) {
                continue;
            }
            int zoneRank = massassiPackageForceLossZoneRank(
                    card.getZone());
            if (preferred == null || zoneRank < preferredZoneRank
                    || zoneRank == preferredZoneRank
                        && card.getPermanentCardId()
                            < preferred.getPermanentCardId()) {
                preferred = card;
                preferredZoneRank = zoneRank;
            }
        }
        return preferred;
    }

    private PhysicalCard preferredMassassiPackageCardSurvivor(
            SwccgGame game, String playerId,
            com.gempukku.swccgo.filters.Filter filter) {
        PhysicalCard preferred = null;
        int preferredZoneRank = Integer.MAX_VALUE;
        for (PhysicalCard card : objectiveForceLossSurvivors(
                game.getGameState(), playerId)) {
            if (card == null || !playerId.equals(card.getOwner())
                    || !filter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), card)) {
                continue;
            }
            int zoneRank = massassiPackageForceLossZoneRank(
                    card.getZone());
            if (preferred == null || zoneRank < preferredZoneRank
                    || zoneRank == preferredZoneRank
                        && card.getPermanentCardId()
                            < preferred.getPermanentCardId()) {
                preferred = card;
                preferredZoneRank = zoneRank;
            }
        }
        return preferred;
    }

    /**
     * Funds the cheapest bodies that can occupy the still-missing physical
     * sites this deploy phase for the two audited three-site objectives.
     */
    public int getCountedObjectivePresenceForceReserve(
            SwccgGame game, String playerId,
            PhysicalCard deployingCandidate) {
        if (isFlipped || game == null || playerId == null
                || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        if (hasCountedOperativeFormationRule()) {
            return getCountedOperativeFormationForceReserve(
                    game, playerId, deployingCandidate);
        }
        if (isISBOperations) {
            return getIsbOnTableAgentForceReserve(
                    game, playerId, deployingCandidate);
        }
        if (!isMassassiBaseOperationsFamily()
                && !isImperialEntanglementsFamily()
                && !isNoMoneyNoPartsObjectiveFamily()) {
            return 0;
        }
        int bestReserve = 0;
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)
                    || isRuleSatisfied(game, playerId, rule)) {
                continue;
            }
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (!isPlainSelfPresenceAlternative(alternative)
                        || alternative.count == null
                        || alternative.count.value == null) {
                    continue;
                }
                int required = expectedCount(
                        game, playerId, alternative.count);
                int qualified = countAlternativeMatches(
                        game, playerId, playerId, alternative);
                int bodiesNeeded = Math.max(0, required - qualified);
                int openDestinations = countOpenCountedObjectiveDestinations(
                        game, playerId, alternative);
                boolean candidateAdvances = deployingCandidate != null
                        && hasLegalPlainPresenceDestinationForAlternative(
                            game, playerId, deployingCandidate,
                            alternative);
                if (candidateAdvances) {
                    bodiesNeeded--;
                    openDestinations--;
                }
                int fundedBodies = Math.min(
                        Math.max(0, bodiesNeeded),
                        Math.max(0, openDestinations));
                if (fundedBodies == 0) continue;

                List<Integer> costs = new ArrayList<>();
                for (PhysicalCard card
                        : game.getGameState().getHand(playerId)) {
                    if (card == null || card == deployingCandidate) {
                        continue;
                    }
                    Integer cost = cheapestPlainPresenceDeployCost(
                            game, playerId, card, alternative);
                    if (cost != null) costs.add(cost);
                }
                Collections.sort(costs);
                int reserve = 0;
                for (int i = 0;
                        i < Math.min(fundedBodies, costs.size()); i++) {
                    reserve += costs.get(i);
                }
                bestReserve = Math.max(bestReserve, reserve);
            }
        }
        return bestReserve;
    }

    public record OldAlliesRouteReserve(
            String ruleId,
            boolean executable,
            boolean candidateUsed,
            int candidatePayment,
            int remainingDeployForce,
            int nextMoveForce,
            int nextBattleForce) {
        public int futureForce() {
            return remainingDeployForce
                    + nextMoveForce + nextBattleForce;
        }
    }

    private static final class OldAlliesRoutePlan {
        private final String ruleId;
        private final Set<Integer> usedCards;
        private final Set<Integer> battleLocations;
        private final boolean candidateUsed;
        private final int candidatePayment;
        private final int deployForce;
        private final int moveForce;
        private final int battleForce;

        private OldAlliesRoutePlan(
                String ruleId, Set<Integer> usedCards,
                Set<Integer> battleLocations,
                boolean candidateUsed, int candidatePayment,
                int deployForce, int moveForce, int battleForce) {
            this.ruleId = ruleId;
            this.usedCards = usedCards;
            this.battleLocations = battleLocations;
            this.candidateUsed = candidateUsed;
            this.candidatePayment = candidatePayment;
            this.deployForce = deployForce;
            this.moveForce = moveForce;
            this.battleForce = battleForce;
        }

        private static OldAlliesRoutePlan empty(String ruleId) {
            return new OldAlliesRoutePlan(
                    ruleId, new HashSet<>(), new HashSet<>(),
                    false, 0, 0, 0, 0);
        }

        private int futureForce() {
            return deployForce + moveForce + battleForce;
        }
    }

    /**
     * Builds each cross-paired Old Allies branch as one executable plan. A
     * physical card and destination may be used once, and deploy, move, and
     * battle payments never leak between the two OR branches.
     */
    public OldAlliesRouteReserve assessOldAlliesFutureRoute(
            SwccgGame game, String playerId,
            PhysicalCard deployingCandidate) {
        if (!isOldAlliesObjectiveFamily() || isFlipped
                || game == null || playerId == null
                || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return new OldAlliesRouteReserve(
                    null, false, false, 0, 0, 0, 0);
        }
        OldAlliesRoutePlan best = findBestOldAlliesRoutePlan(
                game, playerId, deployingCandidate);
        if (best == null) {
            return new OldAlliesRouteReserve(
                    null, false, false, 0, 0, 0, 0);
        }
        return new OldAlliesRouteReserve(
                best.ruleId, true, best.candidateUsed,
                best.candidatePayment, best.deployForce,
                best.moveForce, best.battleForce);
    }

    private OldAlliesRoutePlan findBestOldAlliesRoutePlan(
            SwccgGame game, String playerId,
            PhysicalCard deployingCandidate) {
        if (!isOldAlliesObjectiveFamily() || isFlipped
                || game == null || playerId == null
                || activeFlipLocationRules == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return null;
        }
        List<OldAlliesRoutePlan> completeRoutes = new ArrayList<>();
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)
                    || rule.alternatives == null) {
                continue;
            }
            List<OldAlliesRoutePlan> branch = new ArrayList<>();
            branch.add(OldAlliesRoutePlan.empty(rule.id));
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (!isPlainSelfPresenceAlternative(alternative)
                        || alternative.count == null
                        || alternative.count.value == null) {
                    branch.clear();
                    break;
                }
                List<OldAlliesRoutePlan> alternatives =
                        oldAlliesAlternativePlans(
                            game, playerId, deployingCandidate,
                            rule.id, alternative);
                branch = mergeOldAlliesRoutePlans(
                        branch, alternatives);
                if (branch.isEmpty()) break;
            }
            completeRoutes.addAll(branch);
        }
        List<OldAlliesRoutePlan> candidateRoutes =
                deployingCandidate != null
                    && completeRoutes.stream().anyMatch(
                        plan -> plan.candidateUsed)
                    ? completeRoutes.stream()
                        .filter(plan -> plan.candidateUsed)
                        .toList()
                    : completeRoutes;
        return candidateRoutes.stream()
                .min(oldAlliesPlanComparator())
                .orElse(null);
    }

    private List<OldAlliesRoutePlan> oldAlliesAlternativePlans(
            SwccgGame game, String playerId,
            PhysicalCard deployingCandidate, String ruleId,
            FlipLocationAlternative alternative) {
        int missing = Math.max(0,
                expectedCount(game, playerId, alternative.count)
                - countOldAlliesAlternativeMatches(
                    game, playerId, alternative));
        if (missing == 0) {
            return List.of(OldAlliesRoutePlan.empty(ruleId));
        }
        List<PhysicalCard> destinations = new ArrayList<>();
        Map<Integer, List<OldAlliesRoutePlan>> options = new HashMap<>();
        for (PhysicalCard location
                : game.getGameState().getLocationsInOrder()) {
            if (!locationMatchesAlternative(
                        game.getGameState(), game, playerId,
                        location, alternative)
                    || oldAlliesRelationSatisfiedAt(
                        game, playerId, location, alternative)) {
                continue;
            }
            List<OldAlliesRoutePlan> locationOptions =
                    oldAlliesLocationContributionPlans(
                        game, playerId, deployingCandidate,
                        ruleId, alternative, location);
            if (!locationOptions.isEmpty()) {
                destinations.add(location);
                options.put(location.getPermanentCardId(),
                        locationOptions);
            }
        }
        List<OldAlliesRoutePlan> plans = new ArrayList<>();
        collectOldAlliesAlternativePlans(
                destinations, options, 0, missing,
                OldAlliesRoutePlan.empty(ruleId), plans);
        return trimOldAlliesPlans(plans);
    }

    private List<OldAlliesRoutePlan> oldAlliesLocationContributionPlans(
            SwccgGame game, String playerId,
            PhysicalCard deployingCandidate, String ruleId,
            FlipLocationAlternative alternative,
            PhysicalCard destination) {
        List<OldAlliesRoutePlan> plans = new ArrayList<>();
        String opponent = game.getGameState().getOpponent(playerId);
        boolean selfOccupies = oldAlliesRelationSatisfiedAt(
                game, playerId, destination,
                oldAlliesOccupyAlternative(alternative));
        boolean opponentOccupies = opponent != null
                && game.getModifiersQuerying().occupiesLocation(
                    game.getGameState(), destination, opponent,
                    SpotOverride.INCLUDE_EXCLUDED_FROM_BATTLE);

        if ("control".equals(alternative.relation)
                && selfOccupies && opponentOccupies) {
            Integer battleCost = oldAlliesSafeBattleCostAt(
                    game, playerId, destination);
            if (battleCost != null) {
                plans.add(new OldAlliesRoutePlan(
                        ruleId, new HashSet<>(),
                        new HashSet<>(Set.of(
                            destination.getPermanentCardId())),
                        false, 0, 0, 0, battleCost));
            }
            return plans;
        }

        if ("control".equals(alternative.relation)
                && opponentOccupies) {
            return plans;
        }

        if (Filters.Jakku_system.accepts(
                    game.getGameState(), game.getModifiersQuerying(),
                    destination)
                && hasExecutableOldAlliesFalconDeparture(
                    game, playerId)) {
            addOldAlliesFalconPilotPlans(
                    game, playerId, deployingCandidate,
                    ruleId, destination, plans);
            if (!plans.isEmpty()) {
                return trimOldAlliesPlans(plans);
            }
        }

        if (deployingCandidate != null
                && deployingCandidate.getZone() == Zone.HAND) {
            Integer payment = oldAlliesDirectDeployCostAt(
                    game, playerId, deployingCandidate,
                    destination, alternative);
            if (payment != null) {
                plans.add(oldAlliesCardPlan(
                        ruleId, deployingCandidate,
                        true, payment, 0, 0));
            }
        }
        for (PhysicalCard card : game.getGameState().getHand(playerId)) {
            if (card == null || card == deployingCandidate) continue;
            Integer payment = oldAlliesDirectDeployCostAt(
                    game, playerId, card,
                    destination, alternative);
            if (payment != null) {
                plans.add(oldAlliesCardPlan(
                        ruleId, card, false, 0,
                        payment, 0));
            }
        }

        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents != null) {
            for (PhysicalCard mover : permanents) {
                if (mover == null
                        || !playerId.equals(mover.getOwner())
                        || mover.getZone() == null
                        || !mover.getZone().isInPlay()
                        || !isActiveForSpot(game, mover, true)
                        || !candidateWouldSatisfyAlternativeAt(
                            game, playerId, mover,
                            destination, alternative)) {
                    continue;
                }
                PhysicalCard origin = game.getModifiersQuerying()
                        .getLocationThatCardIsPresentAt(
                            game.getGameState(), mover);
                if (origin == null || samePhysicalLocation(
                            origin, destination)
                        || Filters.Jakku_system.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), destination)
                            && Filters.site.accepts(
                                game.getGameState(),
                                game.getModifiersQuerying(), origin)
                        || isPreFlipPlainPresenceRequirementLocation(
                            game, playerId, origin)
                            && isSolePresenceSourceAtRequiredLocation(
                                game, playerId, mover, origin)
                        || hasExecutableOldAlliesFalconDeparture(
                            game, playerId)
                            && Filters.Niima_Outpost_Shipyard.accepts(
                                game.getGameState(),
                                game.getModifiersQuerying(), origin)
                        || FormationSafety.vetoMoveDestination(
                            game, game.getGameState(), playerId,
                            mover, destination) != null
                        || FormationSafety.vetoMoveOrigin(
                            game, game.getGameState(), playerId,
                            mover, origin) != null) {
                    continue;
                }
                Integer moveCost = oldAlliesMoveCost(
                        game, playerId, mover,
                        origin, destination);
                if (moveCost != null) {
                    plans.add(oldAlliesCardPlan(
                            ruleId, mover, false, 0,
                            0, moveCost));
                }
            }
        }

        return trimOldAlliesPlans(plans);
    }

    private Integer oldAlliesDirectDeployCostAt(
            SwccgGame game, String playerId, PhysicalCard candidate,
            PhysicalCard destination,
            FlipLocationAlternative alternative) {
        if (candidate == null || candidate.getZone() != Zone.HAND
                || !playerId.equals(candidate.getOwner())
                || !candidateWouldSatisfyAlternativeAt(
                    game, playerId, candidate,
                    destination, alternative)) {
            return null;
        }
        try {
            if (!Filters.deployableToLocation(
                    candidate, Filters.sameCardId(destination),
                    true, 0.0f).accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate)) {
                return null;
            }
        } catch (Exception e) {
            return null;
        }
        return requiredCardDeployCostAt(
                game, candidate, destination);
    }

    private OldAlliesRoutePlan oldAlliesCardPlan(
            String ruleId, PhysicalCard card,
            boolean candidateUsed, int candidatePayment,
            int deployForce, int moveForce) {
        return new OldAlliesRoutePlan(
                ruleId,
                new HashSet<>(Set.of(card.getPermanentCardId())),
                new HashSet<>(), candidateUsed,
                candidatePayment, deployForce, moveForce, 0);
    }

    private PhysicalCard findOldAlliesSetupFalcon(
            SwccgGame game, String playerId) {
        if (!isOldAlliesObjectiveFamily() || isFlipped
                || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return null;
        }
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents == null) return null;
        for (PhysicalCard card : permanents) {
            if (card == null || !playerId.equals(card.getOwner())
                    || card.getZone() == null
                    || !card.getZone().isInPlay()
                    || !isActiveForSpot(game, card, false)
                    || !Filters.and(
                        Icon.EPISODE_VII, Filters.Falcon,
                        Filters.starship, Filters.landed)
                        .accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), card)) {
                continue;
            }
            PhysicalCard location = game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                        game.getGameState(), card);
            if (location != null
                    && Filters.Niima_Outpost_Shipyard.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), location)) {
                return card;
            }
        }
        return null;
    }

    private PhysicalCard findOldAlliesJakkuSystem(
            SwccgGame game) {
        if (game == null || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return null;
        }
        for (PhysicalCard location
                : game.getGameState().getLocationsInOrder()) {
            if (Filters.Jakku_system.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), location)) {
                return location;
            }
        }
        return null;
    }

    private boolean oldAlliesSystemOccupied(
            SwccgGame game, String playerId) {
        PhysicalCard system = findOldAlliesJakkuSystem(game);
        return system != null
                && game.getModifiersQuerying().occupiesLocation(
                    game.getGameState(), system, playerId,
                    SpotOverride.INCLUDE_EXCLUDED_FROM_BATTLE);
    }

    private boolean canOldAlliesFalconTakeOffTo(
            SwccgGame game, String playerId,
            PhysicalCard falcon, PhysicalCard system) {
        if (game == null || playerId == null
                || falcon == null || system == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            return Filters.canTakeOffToLocation(
                    playerId, falcon, false,
                    false, 0.0f).accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), system);
        } catch (Exception e) {
            return false;
        }
    }

    private boolean hasExecutableOldAlliesFalconDeparture(
            SwccgGame game, String playerId) {
        PhysicalCard falcon = findOldAlliesSetupFalcon(
                game, playerId);
        PhysicalCard system = findOldAlliesJakkuSystem(game);
        if (falcon == null || system == null) return false;
        PhysicalCard origin = game.getModifiersQuerying()
                .getLocationThatCardIsAt(
                    game.getGameState(), falcon);
        if (origin == null || game.getModifiersQuerying()
                .mayNotTakeOffFromLocationToLocation(
                    game.getGameState(), falcon,
                    origin, system, false)) {
            return false;
        }
        if (canOldAlliesFalconTakeOffTo(
                game, playerId, falcon, system)) {
            return true;
        }
        for (PhysicalCard card
                : game.getGameState().getHand(playerId)) {
            if (isOldAlliesFalconPilotDeployCandidate(
                    game, playerId, card)) {
                return true;
            }
        }
        return false;
    }

    public boolean isOldAlliesFalconPilotDeployCandidate(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (!isOldAlliesObjectiveFamily() || isFlipped
                || game == null || playerId == null
                || candidate == null || candidate.getZone() != Zone.HAND
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        PhysicalCard falcon = findOldAlliesSetupFalcon(
                game, playerId);
        if (falcon == null || canOldAlliesFalconTakeOffTo(
                game, playerId, falcon,
                findOldAlliesJakkuSystem(game))
                || !isLegalProspectivePilotForHost(
                    game, playerId, falcon, candidate)) {
            return false;
        }
        try {
            return Filters.deployableToTarget(
                    candidate, Filters.sameCardId(falcon),
                    true, 0.0f).accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate);
        } catch (Exception e) {
            return false;
        }
    }

    public boolean advancesOldAlliesFalconRouteAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard destination) {
        PhysicalCard falcon = findOldAlliesSetupFalcon(
                game, playerId);
        if (falcon == null || destination != falcon
                || !isOldAlliesFalconPilotDeployCandidate(
                    game, playerId, candidate)) {
            return false;
        }
        OldAlliesRoutePlan route = findBestOldAlliesRoutePlan(
                game, playerId, null);
        return route != null
                && route.usedCards.contains(
                    falcon.getPermanentCardId())
                && route.usedCards.contains(
                    candidate.getPermanentCardId());
    }

    public boolean isOldAlliesFalconTakeOffDestination(
            SwccgGame game, String playerId,
            PhysicalCard mover, PhysicalCard destination) {
        if (!isOldAlliesObjectiveFamily() || isFlipped
                || game == null || playerId == null
                || mover == null || destination == null
                || !playerId.equals(mover.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || !Filters.and(
                        Icon.EPISODE_VII, Filters.Falcon,
                        Filters.starship, Filters.landed)
                    .accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), mover)
                || !Filters.Jakku_system.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), destination)) {
            return false;
        }
        PhysicalCard origin = game.getModifiersQuerying()
                .getLocationThatCardIsAt(
                    game.getGameState(), mover);
        if (origin == null
                || !Filters.Niima_Outpost_Shipyard.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), origin)) {
            return false;
        }
        return isOldAlliesSelectedFalconDeparture(
                game, playerId, mover);
    }

    public boolean isOldAlliesSelectedFalconDeparture(
            SwccgGame game, String playerId,
            PhysicalCard mover) {
        PhysicalCard falcon = findOldAlliesSetupFalcon(
                game, playerId);
        PhysicalCard system = findOldAlliesJakkuSystem(game);
        if (falcon == null || mover != falcon || system == null
                || oldAlliesSystemOccupied(game, playerId)) {
            return false;
        }
        OldAlliesRoutePlan route = findBestOldAlliesRoutePlan(
                game, playerId, null);
        return route != null
                && route.usedCards.contains(
                    mover.getPermanentCardId())
                && canOldAlliesFalconTakeOffTo(
                    game, playerId, mover, system);
    }

    public boolean shouldHoldOldAlliesFalconAtNiima(
            SwccgGame game, String playerId,
            PhysicalCard mover) {
        return isOldAlliesObjectiveFamily() && !isFlipped
                && mover != null
                && mover == findOldAlliesSetupFalcon(
                    game, playerId)
                && !isOldAlliesSelectedFalconDeparture(
                    game, playerId, mover);
    }

    public boolean isOldAlliesRouteDeployCandidate(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (candidate == null || candidate.getZone() != Zone.HAND) {
            return false;
        }
        OldAlliesRoutePlan route = findBestOldAlliesRoutePlan(
                game, playerId, null);
        return route != null && route.usedCards.contains(
                candidate.getPermanentCardId());
    }

    public boolean isOldAlliesGroundRouteDeployCandidate(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (!isOldAlliesObjectiveFamily() || isFlipped
                || game == null || playerId == null
                || candidate == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || activeFlipLocationRules == null) {
            return false;
        }
        if (!isOldAlliesRouteDeployCandidate(
                game, playerId, candidate)) {
            return false;
        }
        if (isOldAlliesFalconPilotDeployCandidate(
                game, playerId, candidate)) {
            return false;
        }
        for (PhysicalCard location
                : game.getGameState().getLocationsInOrder()) {
            if (advancesOldAlliesGroundRouteAt(
                    game, playerId, candidate, location)) {
                return true;
            }
        }
        return false;
    }

    public boolean advancesOldAlliesGroundRouteAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard location) {
        if (!isOldAlliesObjectiveFamily() || isFlipped
                || game == null || playerId == null
                || candidate == null || location == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || activeFlipLocationRules == null
                || !isOldAlliesRouteDeployCandidate(
                    game, playerId, candidate)
                || isOldAlliesFalconPilotDeployCandidate(
                    game, playerId, candidate)) {
            return false;
        }
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (!isActivePreFlipRule(rule)) continue;
            for (FlipLocationAlternative alternative : rule.alternatives) {
                if (!"Jakku_battleground_site".equals(
                            alternative.locationFilterKey)) {
                    continue;
                }
                if (countOldAlliesAlternativeMatches(
                            game, playerId, alternative)
                        >= expectedCount(
                            game, playerId, alternative.count)) {
                    continue;
                }
                if (locationMatchesAlternative(
                            game.getGameState(), game, playerId,
                            location, alternative)
                        && !oldAlliesRelationSatisfiedAt(
                            game, playerId, location, alternative)
                        && candidateWouldSatisfyAlternativeAt(
                            game, playerId, candidate,
                            location, alternative)) {
                    return true;
                }
            }
        }
        return false;
    }

    public boolean isOldAlliesWrongGroundRouteDestination(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard destination) {
        if (!isOldAlliesGroundRouteDeployCandidate(
                    game, playerId, candidate)
                || destination == null
                || destination.getBlueprint() == null) {
            return false;
        }
        CardCategory category = destination.getBlueprint()
                .getCardCategory();
        return category == CardCategory.STARSHIP
                || category == CardCategory.VEHICLE;
    }

    private void addOldAlliesFalconPilotPlans(
            SwccgGame game, String playerId,
            PhysicalCard deployingCandidate, String ruleId,
            PhysicalCard system,
            List<OldAlliesRoutePlan> plans) {
        PhysicalCard falcon = findOldAlliesSetupFalcon(
                game, playerId);
        if (falcon == null) {
            return;
        }
        PhysicalCard falconLocation = game.getModifiersQuerying()
                .getLocationThatCardIsAt(
                    game.getGameState(), falcon);
        if (falconLocation == null
                || !Filters.Niima_Outpost_Shipyard.accepts(
                    game.getGameState(), game.getModifiersQuerying(),
                    falconLocation)
                || game.getModifiersQuerying()
                    .mayNotTakeOffFromLocationToLocation(
                        game.getGameState(), falcon,
                        falconLocation, system, false)) {
            return;
        }
        int takeOffCost;
        try {
            takeOffCost = (int) Math.ceil(Math.max(0.0f,
                    game.getModifiersQuerying().getTakeOffCost(
                        game.getGameState(), falcon,
                        falconLocation, system, false, 0.0f)));
        } catch (Exception e) {
            return;
        }
        if (canOldAlliesFalconTakeOffTo(
                game, playerId, falcon, system)) {
            Set<Integer> routeCards = new HashSet<>();
            routeCards.add(falcon.getPermanentCardId());
            routeCards.addAll(oldAlliesAssignedPilotIds(
                    game, playerId, falcon));
            plans.add(new OldAlliesRoutePlan(
                    ruleId, routeCards, new HashSet<>(),
                    false, 0, 0, takeOffCost, 0));
            return;
        }
        if (deployingCandidate != null
                && isOldAlliesFalconPilotDeployCandidate(
                    game, playerId, deployingCandidate)) {
            Integer payment = requiredCardDeployCostAt(
                    game, deployingCandidate, falcon);
            if (payment != null) {
                Set<Integer> routeCards = new HashSet<>(Set.of(
                        falcon.getPermanentCardId(),
                        deployingCandidate.getPermanentCardId()));
                plans.add(new OldAlliesRoutePlan(
                        ruleId, routeCards,
                        new HashSet<>(), true, payment,
                        0, takeOffCost, 0));
            }
        }
        for (PhysicalCard pilot : game.getGameState().getHand(playerId)) {
            if (pilot == null || pilot == deployingCandidate
                    || !isOldAlliesFalconPilotDeployCandidate(
                        game, playerId, pilot)) {
                continue;
            }
            Integer payment = requiredCardDeployCostAt(
                    game, pilot, falcon);
            if (payment != null) {
                Set<Integer> routeCards = new HashSet<>(Set.of(
                        falcon.getPermanentCardId(),
                        pilot.getPermanentCardId()));
                plans.add(new OldAlliesRoutePlan(
                        ruleId, routeCards,
                        new HashSet<>(), false, 0,
                        payment, takeOffCost, 0));
            }
        }
    }

    private int countOldAlliesAlternativeMatches(
            SwccgGame game, String playerId,
            FlipLocationAlternative alternative) {
        int count = 0;
        for (PhysicalCard location
                : game.getGameState().getLocationsInOrder()) {
            if (locationMatchesAlternative(
                        game.getGameState(), game, playerId,
                        location, alternative)
                    && oldAlliesRelationSatisfiedAt(
                        game, playerId, location, alternative)) {
                count++;
            }
        }
        return count;
    }

    private FlipLocationAlternative oldAlliesOccupyAlternative(
            FlipLocationAlternative source) {
        if (source == null || "occupy".equals(source.relation)) {
            return source;
        }
        FlipLocationAlternative occupy = new FlipLocationAlternative();
        occupy.relation = "occupy";
        occupy.controller = source.controller;
        occupy.locationFilterKey = source.locationFilterKey;
        occupy.locationFragments = source.locationFragments;
        occupy.count = source.count;
        occupy.includeExcludedFromBattle =
                source.includeExcludedFromBattle;
        occupy.spotOverride = source.spotOverride;
        return occupy;
    }

    private boolean oldAlliesRelationSatisfiedAt(
            SwccgGame game, String playerId, PhysicalCard location,
            FlipLocationAlternative alternative) {
        boolean satisfied = relationSatisfiedAt(
                game, playerId, playerId, location,
                alternative.relation,
                alternative.actorFilterKey,
                alternative.includeExcludedFromBattle,
                alternative.spotOverride);
        if (!satisfied
                || !Filters.Niima_Outpost_Shipyard.accepts(
                    game.getGameState(), game.getModifiersQuerying(),
                    location)
                || oldAlliesSystemOccupied(game, playerId)
                || !hasExecutableOldAlliesFalconDeparture(
                    game, playerId)) {
            return satisfied;
        }
        PhysicalCard falcon = findOldAlliesSetupFalcon(
                game, playerId);
        if (falcon == null || !samePhysicalLocation(
                game.getModifiersQuerying().getLocationThatCardIsAt(
                    game.getGameState(), falcon), location)) {
            return satisfied;
        }
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents == null) return false;
        for (PhysicalCard card : permanents) {
            if (card == null || card == falcon
                    || !playerId.equals(card.getOwner())
                    || card.getZone() == null
                    || !card.getZone().isInPlay()
                    || !isActiveForSpot(
                        game, card,
                        alternative.includeExcludedFromBattle)
                    || oldAlliesAttachedToFalcon(card, falcon)
                    || !candidateProvidesPresence(game, card)) {
                continue;
            }
            PhysicalCard cardLocation = game.getModifiersQuerying()
                    .getLocationThatCardIsPresentAt(
                        game.getGameState(), card);
            if (samePhysicalLocation(cardLocation, location)) {
                return true;
            }
        }
        return false;
    }

    private boolean oldAlliesAttachedToFalcon(
            PhysicalCard card, PhysicalCard falcon) {
        PhysicalCard host = card != null ? card.getAttachedTo() : null;
        while (host != null) {
            if (host == falcon) return true;
            host = host.getAttachedTo();
        }
        return false;
    }

    private Set<Integer> oldAlliesAssignedPilotIds(
            SwccgGame game, String playerId, PhysicalCard falcon) {
        Set<Integer> pilotIds = new HashSet<>();
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents == null) return pilotIds;
        for (PhysicalCard card : permanents) {
            if (card != null && playerId.equals(card.getOwner())
                    && game.getModifiersQuerying().getIsPilotOf(
                        game.getGameState(), card) == falcon) {
                pilotIds.add(card.getPermanentCardId());
            }
        }
        return pilotIds;
    }

    private Integer oldAlliesSafeBattleCostAt(
            SwccgGame game, String playerId,
            PhysicalCard location) {
        String opponent = game.getGameState().getOpponent(playerId);
        if (opponent == null
                || FormationSafety.vetoInitiateBattle(
                    game, game.getGameState(), playerId,
                    location) != null) {
            return null;
        }
        float ourPower = game.getModifiersQuerying()
                .getTotalPowerAtLocation(
                    game.getGameState(), location,
                    playerId, false, false);
        float theirPower = game.getModifiersQuerying()
                .getTotalPowerAtLocation(
                    game.getGameState(), location,
                    opponent, false, false);
        if (ourPower <= theirPower) return null;
        try {
            float cost = game.getModifiersQuerying()
                    .getInitiateBattleCost(
                        game.getGameState(), location,
                        playerId, true);
            return (int) Math.ceil(Math.max(0.0f, cost));
        } catch (Exception e) {
            return null;
        }
    }

    private void collectOldAlliesAlternativePlans(
            List<PhysicalCard> destinations,
            Map<Integer, List<OldAlliesRoutePlan>> options,
            int index, int remaining,
            OldAlliesRoutePlan current,
            List<OldAlliesRoutePlan> out) {
        if (remaining == 0) {
            out.add(current);
            return;
        }
        if (index >= destinations.size()
                || destinations.size() - index < remaining) {
            return;
        }
        collectOldAlliesAlternativePlans(
                destinations, options, index + 1,
                remaining, current, out);
        PhysicalCard destination = destinations.get(index);
        for (OldAlliesRoutePlan choice : options.getOrDefault(
                destination.getPermanentCardId(), List.of())) {
            OldAlliesRoutePlan merged = mergeOldAlliesRoutePlan(
                    current, choice);
            if (merged != null) {
                collectOldAlliesAlternativePlans(
                        destinations, options, index + 1,
                        remaining - 1, merged, out);
            }
        }
    }

    private List<OldAlliesRoutePlan> mergeOldAlliesRoutePlans(
            List<OldAlliesRoutePlan> left,
            List<OldAlliesRoutePlan> right) {
        List<OldAlliesRoutePlan> merged = new ArrayList<>();
        for (OldAlliesRoutePlan first : left) {
            for (OldAlliesRoutePlan second : right) {
                OldAlliesRoutePlan plan = mergeOldAlliesRoutePlan(
                        first, second);
                if (plan != null) merged.add(plan);
            }
        }
        return trimOldAlliesPlans(merged);
    }

    private OldAlliesRoutePlan mergeOldAlliesRoutePlan(
            OldAlliesRoutePlan first,
            OldAlliesRoutePlan second) {
        if (!Collections.disjoint(
                    first.usedCards, second.usedCards)
                || !Collections.disjoint(
                    first.battleLocations,
                    second.battleLocations)) {
            return null;
        }
        Set<Integer> usedCards = new HashSet<>(first.usedCards);
        usedCards.addAll(second.usedCards);
        Set<Integer> battleLocations =
                new HashSet<>(first.battleLocations);
        battleLocations.addAll(second.battleLocations);
        return new OldAlliesRoutePlan(
                first.ruleId, usedCards, battleLocations,
                first.candidateUsed || second.candidateUsed,
                first.candidatePayment + second.candidatePayment,
                first.deployForce + second.deployForce,
                first.moveForce + second.moveForce,
                first.battleForce + second.battleForce);
    }

    private List<OldAlliesRoutePlan> trimOldAlliesPlans(
            List<OldAlliesRoutePlan> plans) {
        plans.sort(oldAlliesPlanComparator());
        return plans;
    }

    private Comparator<OldAlliesRoutePlan> oldAlliesPlanComparator() {
        return Comparator
                .comparingInt((OldAlliesRoutePlan plan) ->
                    plan.candidatePayment + plan.futureForce())
                .thenComparingInt(plan -> plan.deployForce)
                .thenComparingInt(plan -> plan.moveForce)
                .thenComparingInt(plan -> plan.battleForce)
                .thenComparing(plan -> plan.ruleId)
                .thenComparing(this::oldAlliesPlanSignature);
    }

    private String oldAlliesPlanSignature(
            OldAlliesRoutePlan plan) {
        List<Integer> cardIds = new ArrayList<>(plan.usedCards);
        List<Integer> battleIds =
                new ArrayList<>(plan.battleLocations);
        Collections.sort(cardIds);
        Collections.sort(battleIds);
        return cardIds + ":" + battleIds;
    }

    public int getOldAlliesFutureRouteForceReserve(
            SwccgGame game, String playerId,
            PhysicalCard deployingCandidate) {
        OldAlliesRouteReserve reserve = assessOldAlliesFutureRoute(
                game, playerId, deployingCandidate);
        return reserve.executable() ? reserve.futureForce() : 0;
    }

    public int getOldAlliesCurrentMoveForceReserve(
            SwccgGame game, String playerId) {
        OldAlliesRouteReserve reserve = assessOldAlliesFutureRoute(
                game, playerId, null);
        return reserve.executable() ? reserve.nextMoveForce() : 0;
    }

    private Integer oldAlliesMoveCost(
            SwccgGame game, String playerId, PhysicalCard mover,
            PhysicalCard origin, PhysicalCard destination) {
        int cheapest = Integer.MAX_VALUE;
        try {
            if (Filters.canMoveToUsingLandspeed(
                    playerId, mover, false, false,
                    false, 0.0f, null).accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), destination)) {
                float cost = game.getModifiersQuerying()
                        .getMoveUsingLandspeedCost(
                            game.getGameState(), mover,
                            origin, destination, false, 0.0f);
                cheapest = Math.min(cheapest,
                        (int) Math.ceil(Math.max(0.0f, cost)));
            }
        } catch (Exception ignored) { }
        try {
            if (Filters.canMoveToUsingHyperspeed(
                    playerId, mover, false,
                    false, 0.0f).accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), destination)) {
                float cost = game.getModifiersQuerying()
                        .getMoveUsingHyperspeedCost(
                            game.getGameState(), mover,
                            origin, destination, false, 0.0f);
                cheapest = Math.min(cheapest,
                        (int) Math.ceil(Math.max(0.0f, cost)));
            }
        } catch (Exception ignored) { }
        try {
            if (Filters.canTakeOffToLocation(
                    playerId, mover, false,
                    false, 0.0f).accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), destination)) {
                float cost = game.getModifiersQuerying().getTakeOffCost(
                        game.getGameState(), mover,
                        origin, destination, false, 0.0f);
                cheapest = Math.min(cheapest,
                        (int) Math.ceil(Math.max(0.0f, cost)));
            }
        } catch (Exception ignored) { }
        return cheapest == Integer.MAX_VALUE ? null : cheapest;
    }

    public int getOldAlliesCurrentBattleForceReserve(
            SwccgGame game, String playerId) {
        OldAlliesRouteReserve reserve = assessOldAlliesFutureRoute(
                game, playerId, null);
        return reserve.executable() ? reserve.nextBattleForce() : 0;
    }

    public int getNoMoneyNoPartsCurrentMoveForceReserve(
            SwccgGame game, String playerId) {
        return getNoMoneyNoPartsCurrentMoveForceReserve(
                game, playerId, null);
    }

    public int getTwinSunsCurrentSiteRouteForceReserve(
            SwccgGame game, String playerId) {
        if (!isTwinSunsObjectiveFamily() || isFlipped
                || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || game.getGameState().getCurrentPhase()
                    != Phase.DEPLOY
                || countTwinSunsUsableRouteSites(
                    game, playerId) >= 2) {
            return 0;
        }
        try {
            PhysicalCard objective = findOurObjective(
                    game.getGameState(), playerId);
            if (objective == null
                    || !"301_4".equals(objective.getBlueprintId(
                        game.getGameState(), false))
                    || game.getModifiersQuerying()
                        .getUntilEndOfTurnLimitCounter(
                            objective, playerId,
                            objective.getCardId(),
                            GameTextActionId
                                .TWIN_SUNS_OF_TATOOINE__DOWNLOAD_TATOOINE_BATTLEGROUND_SITE)
                        .getUsedLimit() >= 1) {
                return 0;
            }
            return hasObjectiveLocationRouteCandidateInReserve(
                    game, playerId, objective) ? 1 : 0;
        } catch (Exception e) {
            LOG.debug("Twin Suns site-route Force reserve failed: {}",
                    e.getMessage());
            return 0;
        }
    }

    private Integer getRalltiirSoleSystemBlockerDeployForceReserve(
            SwccgGame game, String playerId) {
        PhysicalCard blocker = findRalltiirSoleSystemBlocker(
                game, playerId);
        if (blocker == null
                || game.getGameState().getCurrentPhase()
                    != Phase.DEPLOY) {
            return null;
        }
        int cheapest = Integer.MAX_VALUE;
        List<PhysicalCard> hand = game.getGameState().getHand(playerId);
        if (hand == null) return null;
        for (PhysicalCard candidate : hand) {
            PhysicalCard target =
                    findLegalRalltiirSoleSystemBlockerDeployTarget(
                        game, playerId, candidate);
            if (target == null) continue;
            Integer cost = requiredCardDeployCostAt(
                    game, candidate, target);
            if (cost != null) cheapest = Math.min(cheapest, cost);
        }
        return cheapest == Integer.MAX_VALUE ? null : cheapest;
    }

    private Integer getRalltiirSoleSystemBlockerMoveForceReserve(
            SwccgGame game, String playerId) {
        PhysicalCard blocker = findRalltiirSoleSystemBlocker(
                game, playerId);
        if (blocker == null) return null;
        int cheapest = Integer.MAX_VALUE;
        Collection<PhysicalCard> permanents =
                game.getGameState().getAllPermanentCards();
        if (permanents == null) return null;
        for (PhysicalCard candidate : permanents) {
            if (!hasLegalRalltiirSoleSystemBlockerHyperspeedRoute(
                    game, playerId, candidate, blocker)) {
                continue;
            }
            try {
                PhysicalCard origin = presenceContributionLocation(
                        game, candidate);
                float cost = game.getModifiersQuerying()
                        .getMoveUsingHyperspeedCost(
                            game.getGameState(), candidate,
                            origin, blocker, false, 0.0f);
                if (Float.isFinite(cost)) {
                    cheapest = Math.min(cheapest,
                            (int) Math.ceil(Math.max(0.0f, cost)));
                }
            } catch (Exception e) {
                LOG.debug(
                        "Ralltiir system-blocker move reserve failed: {}",
                        e.getMessage());
            }
        }
        return cheapest == Integer.MAX_VALUE ? null : cheapest;
    }

    private int getRalltiirSoleSystemBlockerRouteForceReserve(
            SwccgGame game, String playerId,
            PhysicalCard deployingCandidate) {
        if (deployingCandidate != null
                && hasLegalRalltiirSoleSystemBlockerDeployRoute(
                    game, playerId, deployingCandidate)) {
            return 0;
        }
        Integer deploy = getRalltiirSoleSystemBlockerDeployForceReserve(
                game, playerId);
        Integer move = getRalltiirSoleSystemBlockerMoveForceReserve(
                game, playerId);
        if (deploy == null) return move != null ? move : 0;
        if (move == null) return deploy;
        return Math.min(deploy, move);
    }

    public int getRalltiirCurrentRouteForceReserve(
            SwccgGame game, String playerId) {
        return getRalltiirCurrentRouteForceReserve(
                game, playerId, null);
    }

    /**
     * Preserves only the currently executable payments for the native mixed
     * pull, a safe blocker-clearing battle, and a net-progress Imperial move.
     * All three phases can advance the objective in the same turn, so their
     * exact current-turn costs are additive.
     */
    public int getRalltiirCurrentRouteForceReserve(
            SwccgGame game, String playerId,
            PhysicalCard deployingCandidate) {
        if (!isRalltiirOperationsFamily() || isFlipped
                || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        if (findRalltiirSoleSystemBlocker(game, playerId) != null) {
            return getRalltiirSoleSystemBlockerRouteForceReserve(
                    game, playerId, deployingCandidate);
        }
        if (deployingCandidate != null
                && deployingCandidate.getZone() == Zone.HAND
                && isRalltiirFlipCompletionDeployCandidate(
                    game, playerId, deployingCandidate)) {
            return 0;
        }
        if (deployingCandidate != null
                && deployingCandidate.getZone() == Zone.HAND
                && hasLegalRalltiirProgressDeployDestination(
                    game, playerId, deployingCandidate)) {
            int qualifiedAfterDeploy =
                    countRalltiirQualifiedSites(game, playerId) + 1;
            int remainingNativePull =
                    qualifiedAfterDeploy < 3
                        ? getRalltiirCurrentNativePullForceReserve(
                            game, playerId)
                        : 0;
            int remainingMove = qualifiedAfterDeploy < 3
                    ? getRalltiirCurrentMoveForceReserve(
                        game, playerId)
                    : 0;
            return remainingNativePull
                    + getRalltiirCurrentBattleForceReserve(
                        game, playerId)
                    + remainingMove;
        }
        return getRalltiirCurrentNativePullForceReserve(
                    game, playerId)
                + getRalltiirCurrentBattleForceReserve(
                    game, playerId)
                + getRalltiirCurrentMoveForceReserve(
                    game, playerId);
    }

    private int getRalltiirCurrentNativePullForceReserve(
            SwccgGame game, String playerId) {
        if (game.getGameState().getCurrentPhase() != Phase.DEPLOY) {
            return 0;
        }
        try {
            PhysicalCard objective = findOurObjective(
                    game.getGameState(), playerId);
            if (objective == null
                    || !"7_300".equals(objective.getBlueprintId(
                        game.getGameState(), false))
                    || game.getModifiersQuerying()
                        .getUntilEndOfPhaseLimitCounter(
                            objective, playerId,
                            objective.getCardId(),
                            GameTextActionId
                                .RALLTIIR_OPERATIONS__DOWNLOAD_SITE_OR_NONUNIQUE_IMPERIAL_TO_RALLTIIR,
                            Phase.DEPLOY)
                        .getUsedLimit() >= 1) {
                return 0;
            }
            int cheapest = Integer.MAX_VALUE;
            for (PhysicalCard candidate
                    : game.getGameState().getReserveDeck(playerId)) {
                int priority = getRalltiirFrontPullCandidatePriority(
                        game, playerId, objective, candidate);
                if (priority <= 0) continue;
                Integer cost = priority >= 3
                        ? requiredCardDeployCost(game, candidate)
                        : cheapestRalltiirImperialDeployCost(
                            game, playerId, objective, candidate);
                if (cost != null) cheapest = Math.min(cheapest, cost);
            }
            return cheapest == Integer.MAX_VALUE ? 0 : cheapest;
        } catch (Exception e) {
            LOG.debug("Ralltiir native-route Force reserve failed: {}",
                    e.getMessage());
            return 0;
        }
    }

    public int getRalltiirCurrentMoveForceReserve(
            SwccgGame game, String playerId) {
        if (!isRalltiirOperationsFamily() || isFlipped
                || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        if (findRalltiirSoleSystemBlocker(game, playerId) != null) {
            Integer reserve =
                    getRalltiirSoleSystemBlockerMoveForceReserve(
                        game, playerId);
            return reserve != null ? reserve : 0;
        }
        int cheapest = Integer.MAX_VALUE;
        try {
            Collection<PhysicalCard> permanents =
                    game.getGameState().getAllPermanentCards();
            if (permanents == null) return 0;
            for (PhysicalCard mover : permanents) {
                if (mover == null
                        || !playerId.equals(mover.getOwner())
                        || mover.getZone() == null
                        || !mover.getZone().isInPlay()
                        || !isActiveForSpot(game, mover, true)) {
                    continue;
                }
                PhysicalCard origin = presenceContributionLocation(
                        game, mover);
                if (origin == null) continue;
                for (PhysicalCard destination
                        : game.getGameState().getLocationsInOrder()) {
                    boolean advancesRoute =
                            advancesPreFlipActorAtRuntimeLocation(
                                game, playerId, mover, destination);
                    boolean chasesBlocker = !advancesRoute
                            && qualifiesPreFlipRuntimeActorAtLocation(
                                game, playerId, mover, destination)
                            && isPreFlipGlobalBlockerAt(
                                game, playerId, destination);
                    boolean followsBattleClear = !advancesRoute
                            && !chasesBlocker
                            && qualifiesPreFlipRuntimeActorAtLocation(
                                game, playerId, mover, destination)
                            && !hasMatchingActorAtLocation(
                                game, playerId, destination,
                                "Imperial", true)
                            && isRalltiirCurrentWinnableRouteBattleAt(
                                game, playerId, destination);
                    if ((!advancesRoute
                                && !chasesBlocker
                                && !followsBattleClear)
                            || samePhysicalLocation(origin, destination)
                            || !Filters.canMoveToUsingLandspeed(
                                playerId, mover,
                                false, false, false, 0.0f, null)
                                .accepts(
                                    game.getGameState(),
                                    game.getModifiersQuerying(),
                                    destination)
                            || FormationSafety.vetoMoveDestination(
                                game, game.getGameState(), playerId,
                                mover, destination) != null
                            || FormationSafety.vetoMoveOrigin(
                                game, game.getGameState(), playerId,
                                mover, origin) != null) {
                        continue;
                    }
                    float cost = game.getModifiersQuerying()
                            .getMoveUsingLandspeedCost(
                                game.getGameState(), mover,
                                origin, destination,
                                false, 0.0f);
                    if (Float.isFinite(cost)) {
                        cheapest = Math.min(
                                cheapest,
                                Math.max(0,
                                    (int) Math.ceil(cost)));
                    }
                }
            }
        } catch (Exception e) {
            LOG.debug("Ralltiir move Force reserve failed: {}",
                    e.getMessage());
            return 0;
        }
        return cheapest == Integer.MAX_VALUE ? 0 : cheapest;
    }

    public int getRalltiirCurrentBattleForceReserve(
            SwccgGame game, String playerId) {
        if (!isRalltiirOperationsFamily() || isFlipped
                || game == null || playerId == null
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return 0;
        }
        String opponent = game.getGameState().getOpponent(playerId);
        if (opponent == null) return 0;
        int cheapest = Integer.MAX_VALUE;
        try {
            for (PhysicalCard location
                    : game.getGameState().getLocationsInOrder()) {
                if (!isRalltiirCurrentWinnableRouteBattleAt(
                        game, playerId, location)) {
                    continue;
                }
                float cost = game.getModifiersQuerying()
                        .getInitiateBattleCost(
                            game.getGameState(), location,
                            playerId, true);
                cheapest = Math.min(
                        cheapest,
                        Math.max(0, (int) Math.ceil(cost)));
            }
        } catch (Exception e) {
            LOG.debug("Ralltiir battle Force reserve failed: {}",
                    e.getMessage());
            return 0;
        }
        return cheapest == Integer.MAX_VALUE ? 0 : cheapest;
    }

    private boolean isRalltiirCurrentWinnableRouteBattleAt(
            SwccgGame game, String playerId,
            PhysicalCard location) {
        if (location == null
                || !Filters.Ralltiir_location.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), location)
                || !isMissingPreFlipRequirementAt(
                    game, playerId, location)
                || isPreFlipGlobalBlockerAt(
                    game, playerId, location)
                    && !isPreFlipBattleRemovableGlobalBlockerAt(
                        game, playerId, location)
                || !com.gempukku.swccgo.cards.GameConditions
                    .canInitiateBattleAtLocation(
                        playerId, game, location,
                        false, true)
                || FormationSafety.vetoInitiateBattle(
                    game, game.getGameState(), playerId,
                    location) != null) {
            return false;
        }
        String opponent = game.getGameState().getOpponent(playerId);
        if (opponent == null) return false;
        float ourPower = game.getModifiersQuerying()
                .getTotalPowerAtLocation(
                    game.getGameState(), location,
                    playerId, false, false);
        float opponentPower = game.getModifiersQuerying()
                .getTotalPowerAtLocation(
                    game.getGameState(), location,
                    opponent, false, false);
        return ourPower > opponentPower;
    }

    private boolean hasLegalRalltiirProgressDeployDestination(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        try {
            for (PhysicalCard location
                    : game.getGameState().getLocationsInOrder()) {
                if (advancesPreFlipRequirementAt(
                            game, playerId, candidate, location)
                        && Filters.deployableToLocation(
                            candidate, Filters.sameCardId(location),
                            false, 0.0f).accepts(
                                game.getGameState(),
                                game.getModifiersQuerying(), candidate)) {
                    return true;
                }
            }
        } catch (Exception e) {
            return false;
        }
        return false;
    }

