    /** True when this physical card satisfies the active flip-gate actor filter. */
    public boolean matchesFlipGateActorRequirement(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        if (!analyzed || game == null || playerId == null || candidate == null) {
            return false;
        }

        ActorLocationRule rule = findFlipGateActorRule();
        if (rule == null) return false;

        try {
            GameState gameState = game.getGameState();
            if (gameState == null || game.getModifiersQuerying() == null) return false;
            com.gempukku.swccgo.filters.Filter actorFilter =
                    resolveFilter(rule.actorFilterKey);
            return actorFilter != null && actorFilter.accepts(
                    gameState, game.getModifiersQuerying(), candidate);
        } catch (Exception e) {
            LOG.debug("V297 flip-gate actor-only match failed: {}", e.getMessage());
            return false;
        }
    }

    /**
     * Returns the cheapest typed gate actor a free enabler can upload from
     * Reserve Deck, or null when the card does not provide a proven path.
     */
    public Integer getFlipGateActorEnablerFutureDeployCost(
            SwccgGame game, String playerId, PhysicalCard enabler) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || enabler == null || enabler.getBlueprint() == null
                || findFlipGateActorRule() == null) {
            return null;
        }

        ActorLocationRule rule = findFlipGateActorRule();
        String actorToken = rule.actorFilterKey == null ? null
                : rule.actorFilterKey.replace('_', ' ')
                    .toLowerCase(Locale.ROOT);
        String gameText = enabler.getBlueprint().getGameText();
        if (actorToken == null || gameText == null) return null;
        String gameTextLower = gameText.toLowerCase(Locale.ROOT);
        if (!gameTextLower.contains("[upload]")
                || !gameTextLower.contains(actorToken)
                || gameTextLower.matches(
                    "(?s).*use\\s+\\d+\\s+force[^.]*\\[upload\\].*")) {
            return null;
        }

        try {
            GameState gameState = game.getGameState();
            if (gameState == null) return null;
            for (PhysicalCard location : gameState.getLocationsInOrder()) {
                if (isFlipGateLocation(game, playerId, location)
                        && hasFlipGateActorAtLocation(
                            game, playerId, location)) {
                    return null;
                }
            }

            Integer cheapest = null;
            List<PhysicalCard> reserve = gameState.getReserveDeck(playerId);
            if (reserve == null) return null;
            for (PhysicalCard candidate : reserve) {
                if (candidate == null || candidate.getBlueprint() == null
                        || !matchesFlipGateActorRequirement(
                            game, playerId, candidate)) {
                    continue;
                }
                Float deployCost = candidate.getBlueprint().getDeployCost();
                if (deployCost == null) continue;
                int cost = Math.max(0, deployCost.intValue());
                if (cheapest == null || cost < cheapest) cheapest = cost;
            }
            return cheapest;
        } catch (Exception e) {
            LOG.debug("Objective gate actor enabler assessment failed: {}",
                    e.getMessage());
            return null;
        }
    }

    /**
     * Narrow DPS exception for a free into-hand action that fetches the
     * still-missing typed flip-gate actor.
     */
    public boolean isFlipGateActorUploadIntoHandAction(
            SwccgGame game, String playerId, PhysicalCard sourceCard,
            String actionText) {
        if (actionText == null
                || !actionText.toLowerCase(Locale.ROOT).contains("into hand")) {
            return false;
        }
        return getFlipGateActorEnablerFutureDeployCost(
                game, playerId, sourceCard) != null;
    }

    /** True when this physical location satisfies the active flip-gate location filter. */
    public boolean isFlipGateLocation(
            SwccgGame game, String playerId, PhysicalCard location) {
        if (!analyzed || game == null || playerId == null || location == null) {
            return false;
        }

        ActorLocationRule rule = findFlipGateActorRule();
        if (rule == null) return false;

        try {
            GameState gameState = game.getGameState();
            if (gameState == null || game.getModifiersQuerying() == null) return false;
            com.gempukku.swccgo.filters.Filter locationFilter =
                    resolveLocationFilter(rule.locationFilterKey, playerId);
            return locationFilter != null && locationFilter.accepts(
                    gameState, game.getModifiersQuerying(), location);
        } catch (Exception e) {
            LOG.debug("V297 flip-gate location match failed: {}", e.getMessage());
            return false;
        }
    }

    /** True when the exact card and destination satisfy the active actor-at-gate rule. */
    public boolean matchesFlipGateActorRequirement(
            SwccgGame game, String playerId, PhysicalCard candidate,
            PhysicalCard destination) {
        return matchesFlipGateActorRequirement(game, playerId, candidate)
                && isFlipGateLocation(game, playerId, destination);
    }

    /** Count qualifying friendly actors present at this exact flip gate. */
    public int countFlipGateActorsAtLocation(
            SwccgGame game, String playerId, PhysicalCard destination) {
        if (!isFlipGateLocation(game, playerId, destination)) return 0;
        ActorLocationRule rule = findFlipGateActorRule();
        if (rule == null) return 0;

        int actorsAtGate = 0;
        try {
            GameState gameState = game.getGameState();
            for (PhysicalCard card : gameState.getAllPermanentCards()) {
                if (card == null || !playerId.equals(card.getOwner())
                        || !matchesFlipGateActorRequirement(game, playerId, card)) {
                    continue;
                }
                PhysicalCard actorLocation = "at".equals(rule.relation)
                        ? game.getModifiersQuerying()
                            .getLocationThatCardIsAt(gameState, card)
                        : game.getModifiersQuerying()
                            .getLocationThatCardIsPresentAt(
                                gameState, card);
                if (samePhysicalLocation(actorLocation, destination)) actorsAtGate++;
            }
        } catch (Exception e) {
            LOG.debug("V297 flip-gate actor count failed: {}", e.getMessage());
            return 0;
        }
        return actorsAtGate;
    }

    /** True when a qualifying objective actor is already present at the exact gate. */
    public boolean hasFlipGateActorAtLocation(
            SwccgGame game, String playerId, PhysicalCard destination) {
        return countFlipGateActorsAtLocation(game, playerId, destination) > 0;
    }

    /**
     * Classifies one friendly card by what the active structured objective
     * would lose if that card left play.
     */
    public FlipGateFormationRole classifyGateFormationPieceIfRemoved(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        if (!analyzed || game == null
                || playerId == null || candidate == null
                || !playerId.equals(candidate.getOwner())
                || candidate.isUndercover()
                || candidate.getBlueprint() == null) {
            return FlipGateFormationRole.NONE;
        }

        if (isTerminalObjectiveForfeitActor(
                    game, playerId, candidate)) {
            return FlipGateFormationRole
                    .TERMINAL_OBJECTIVE_ACTOR;
        }
        if (isOnTheVergeHardLossDependency(
                    game, playerId, candidate)) {
            return FlipGateFormationRole
                    .REQUIRED_CARD_RETENTION_DEFENDER;
        }
        if (isSolePresenceSourceAtObjectiveHardLossLocation(
                    game, playerId, candidate)) {
            return FlipGateFormationRole
                    .HARD_LOSS_LOCATION_DEFENDER;
        }
        if (wouldDepartureTriggerRequiredCardRemoval(
                    game, playerId, candidate)
                || isSoleRequiredCardCancelPreventerIfRemoved(
                    game, playerId, candidate)) {
            return FlipGateFormationRole
                    .REQUIRED_CARD_RETENTION_DEFENDER;
        }
        FlipGateFormationRole massassiEnablerRole =
                classifyMassassiAttackRunEnablerIfRemoved(
                    game, playerId, candidate);
        if (massassiEnablerRole != FlipGateFormationRole.NONE) {
            return massassiEnablerRole;
        }

        if (isFlipped) {
            FlipGateFormationRole captureStateRole =
                    CaptureObjectiveFacts.classifyStableBackRemoval(
                        game, playerId, this, candidate);
            if (captureStateRole
                    != FlipGateFormationRole.NONE) {
                return captureStateRole;
            }
            if (wouldRemovalTriggerOnTableFlipBack(
                    game, playerId, candidate)) {
                return matchesRequiredOnTableCardFlipBackAlternative(
                            game, playerId, candidate)
                        ? FlipGateFormationRole.LAST_FLIP_BACK_BLOCKER
                        : FlipGateFormationRole
                            .LAST_REQUIRED_ON_TABLE_ACTOR;
            }
            if (wouldDepartureTriggerStayFlippedFailure(
                    game, playerId, candidate)) {
                return FlipGateFormationRole
                        .LAST_OBJECTIVE_SURVIVAL_ACTOR;
            }
            return wouldDepartureTriggerFlipBack(game, playerId, candidate)
                    ? FlipGateFormationRole.LAST_FLIP_BACK_BLOCKER
                    : FlipGateFormationRole.NONE;
        }

        if (isFirstOrderReignsSolePendingTriggerControlSource(
                    game, playerId, candidate)) {
            return FlipGateFormationRole
                    .LAST_PENDING_TRIGGER_CONTROL_SOURCE;
        }
        FlipGateFormationRole shieldRouteRole =
                classifyShieldMainGeneratorFormationPieceIfRemoved(
                    game, playerId, candidate);
        if (shieldRouteRole != FlipGateFormationRole.NONE) {
            return shieldRouteRole;
        }
        if (isOldAlliesFalconRoutePieceIfRemoved(
                game, playerId, candidate)) {
            return FlipGateFormationRole.LAST_REQUIRED_ACTOR;
        }
        FlipGateFormationRole ralltiirImperialRole =
                classifyRalltiirImperialIfRemoved(
                        game, playerId, candidate);
        if (ralltiirImperialRole != FlipGateFormationRole.NONE) {
            return ralltiirImperialRole;
        }
        FlipGateFormationRole iWantThatMapRole =
                classifyIWantThatMapFormationPieceIfRemoved(
                        game, playerId, candidate);
        if (iWantThatMapRole != FlipGateFormationRole.NONE) {
            return iWantThatMapRole;
        }
        FlipGateFormationRole runtimeActorRole =
                classifyRuntimeActorIfRemoved(
                        game, playerId, candidate);
        if (runtimeActorRole != FlipGateFormationRole.NONE) {
            return runtimeActorRole;
        }
        FlipGateFormationRole plainPresenceRole =
                classifyPlainPresenceIfRemoved(
                        game, playerId, candidate);
        if (plainPresenceRole != FlipGateFormationRole.NONE) {
            return plainPresenceRole;
        }
        FlipGateFormationRole deployEnablerRole =
                classifyRequiredCardDeployEnablerIfRemoved(
                        game, playerId, candidate);
        if (deployEnablerRole != FlipGateFormationRole.NONE) {
            return deployEnablerRole;
        }
        if (hasCountedPreFlipActorRule()) {
            return classifyCountedGatePieceIfRemoved(
                    game, playerId, candidate);
        }
        if (!hasFlipGateActorRequirement()
                || candidate.getBlueprint().getCardCategory()
                    != CardCategory.CHARACTER) {
            return FlipGateFormationRole.NONE;
        }

        try {
            GameState gameState = game.getGameState();
            if (gameState == null || game.getModifiersQuerying() == null) {
                return FlipGateFormationRole.NONE;
            }
            PhysicalCard gate = game.getModifiersQuerying()
                    .getLocationThatCardIsPresentAt(gameState, candidate);
            if (!isFlipGateLocation(game, playerId, gate)) {
                return FlipGateFormationRole.NONE;
            }

            int friendlyCharacters = 0;
            int actorsAtGate = 0;
            boolean candidateSeen = false;
            boolean candidateIsActor = matchesFlipGateActorRequirement(
                    game, playerId, candidate);
            for (PhysicalCard card : gameState.getAllPermanentCards()) {
                if (card == null || !playerId.equals(card.getOwner())
                        || card.isUndercover() || card.getBlueprint() == null
                        || card.getBlueprint().getCardCategory()
                            != CardCategory.CHARACTER) {
                    continue;
                }
                PhysicalCard cardLocation = game.getModifiersQuerying()
                        .getLocationThatCardIsPresentAt(gameState, card);
                if (!samePhysicalLocation(cardLocation, gate)) continue;

                friendlyCharacters++;
                if (card == candidate) candidateSeen = true;
                if (matchesFlipGateActorRequirement(game, playerId, card)) {
                    actorsAtGate++;
                }
            }

            if (!candidateSeen || actorsAtGate < 1) {
                return FlipGateFormationRole.NONE;
            }
            if (candidateIsActor && actorsAtGate == 1) {
                return FlipGateFormationRole.LAST_REQUIRED_ACTOR;
            }

            int remainingCharacters = friendlyCharacters - 1;
            int remainingActors = actorsAtGate - (candidateIsActor ? 1 : 0);
            if (remainingActors >= 1 && remainingCharacters < 2) {
                return FlipGateFormationRole.LAST_REQUIRED_BUDDY;
            }
        } catch (Exception e) {
            LOG.debug("Typed flip-gate casualty classification failed: {}",
                    e.getMessage());
        }
        return FlipGateFormationRole.NONE;
    }

    /**
     * Preserves the sole Imperial in the live battle for the contested third
     * Ralltiir site. Outside that exact two-controlled-plus-one-contested
     * seam, ordinary casualty value decides. A duplicate Imperial at the
     * battle site also makes the candidate replaceable.
     */
    private FlipGateFormationRole classifyRalltiirImperialIfRemoved(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        if (!isRalltiirOperationsFamily() || isFlipped
                || game == null || playerId == null || candidate == null
                || !playerId.equals(candidate.getOwner())
                || game.getGameState() == null
                || game.getModifiersQuerying() == null
                || activeFlipLocationRules == null) {
            return FlipGateFormationRole.NONE;
        }
        try {
            GameState gameState = game.getGameState();
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (!isActivePreFlipRule(rule)) continue;
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if (!isRalltiirControlWithAlternative(alternative)) {
                        continue;
                    }
                    com.gempukku.swccgo.filters.Filter actorFilter =
                            resolveFilter(alternative.actorFilterKey);
                    if (actorFilter == null
                            || !isActiveForSpot(
                                game, candidate,
                                alternative.includeExcludedFromBattle)
                            || !actorFilter.accepts(
                                gameState,
                                game.getModifiersQuerying(), candidate)) {
                        return FlipGateFormationRole.NONE;
                    }
                    PhysicalCard candidateLocation =
                            actorLocationForAlternative(
                                    game, candidate, alternative);
                    PhysicalCard battleLocation =
                            gameState.getBattleState() != null
                                ? gameState.getBattleState()
                                    .getBattleLocation()
                                : null;
                    if (!locationMatchesAlternative(
                                gameState, game, playerId,
                                candidateLocation, alternative)
                            || !samePhysicalLocation(
                                candidateLocation, battleLocation)
                            || !hasOpponentBattleParticipantAt(
                                game, playerId, candidateLocation)
                            || relationSatisfiedAt(
                                game, playerId, playerId,
                                candidateLocation,
                                alternative.relation,
                                alternative.actorFilterKey,
                                alternative.includeExcludedFromBattle,
                                alternative.spotOverride)
                            || hasOtherMatchingActorAtLocation(
                                game, playerId, candidateLocation,
                                alternative, candidate)) {
                        return FlipGateFormationRole.NONE;
                    }
                    int required = expectedCount(
                            game, playerId, alternative.count);
                    int qualified = countAlternativeMatches(
                            game, playerId, playerId, alternative);
                    int supportedSites = 0;
                    for (PhysicalCard location
                            : gameState.getLocationsInOrder()) {
                        if (locationMatchesAlternative(
                                    gameState, game, playerId,
                                    location, alternative)
                                && hasMatchingActorAtLocation(
                                    game, playerId, location,
                                    alternative.actorFilterKey,
                                    alternative
                                        .includeExcludedFromBattle)) {
                            supportedSites++;
                        }
                    }
                    return qualified == required - 1
                            && supportedSites == required
                        ? FlipGateFormationRole.LAST_REQUIRED_ACTOR
                        : FlipGateFormationRole.NONE;
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "Ralltiir Imperial casualty assessment failed: {}",
                    e.getMessage());
        }
        return FlipGateFormationRole.NONE;
    }

    private boolean isOldAlliesFalconRoutePieceIfRemoved(
            SwccgGame game, String playerId,
            PhysicalCard candidate) {
        if (!isOldAlliesObjectiveFamily() || isFlipped
                || game == null || playerId == null
                || candidate == null || candidate.getZone() == null
                || !candidate.getZone().isInPlay()
                || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        PhysicalCard falcon = Filters.and(
                    Icon.EPISODE_VII, Filters.Falcon)
                .accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), candidate)
                    ? candidate
                    : game.getModifiersQuerying().getIsPilotOf(
                        game.getGameState(), candidate);
        if (falcon == null || !playerId.equals(falcon.getOwner())
                || !Filters.and(Icon.EPISODE_VII, Filters.Falcon)
                    .accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), falcon)) {
            return false;
        }
        OldAlliesRoutePlan route = findBestOldAlliesRoutePlan(
                game, playerId, null);
        if (route == null || !route.usedCards.contains(
                falcon.getPermanentCardId())) {
            return false;
        }
        PhysicalCard location = game.getModifiersQuerying()
                .getLocationThatCardIsAt(
                    game.getGameState(), falcon);
        boolean onRoute = location != null
                && (Filters.Niima_Outpost_Shipyard.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), location)
                    || Filters.Jakku_system.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), location));
        if (!onRoute || candidate == falcon) return onRoute;
        if (!route.usedCards.contains(
                candidate.getPermanentCardId())) {
            return false;
        }
        if (game.getModifiersQuerying().hasPermanentPilot(
                game.getGameState(), falcon)) {
            return false;
        }
        Set<Integer> pilotIds = oldAlliesAssignedPilotIds(
                game, playerId, falcon);
        return pilotIds.size() == 1
                && pilotIds.contains(
                    candidate.getPermanentCardId());
    }

    private FlipGateFormationRole
            classifyRequiredCardDeployEnablerIfRemoved(
                    SwccgGame game, String playerId,
                    PhysicalCard candidate) {
        if (activeRequiredCardDeployRules == null
                || game == null || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return FlipGateFormationRole.NONE;
        }
        try {
            GameState gameState = game.getGameState();
            PhysicalCard location = game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                            gameState, candidate);
            if (location == null) return FlipGateFormationRole.NONE;
            for (RequiredCardDeployRule rule
                    : activeRequiredCardDeployRules) {
                FlipLocationAlternative prerequisite =
                        rule != null ? rule.prerequisite : null;
                if (!isRequiredCardDeployRuleActive(
                            game, playerId, rule)
                        || prerequisite == null
                        || prerequisite.actorFilterKey == null
                        || prerequisite.count == null
                        || prerequisite.count.value == null
                        || prerequisite.count.value <= 1
                        || isUpperBound(prerequisite.count)
                        || !locationMatchesAlternative(
                            gameState, game, playerId,
                            location, prerequisite)) {
                    continue;
                }
                int required = expectedCount(
                        game, playerId, prerequisite.count);
                int qualified = countAlternativeMatches(
                        game, playerId, playerId,
                        prerequisite);
                if (qualified <= 0 || qualified > required
                        || !relationSatisfiedAt(
                            game, playerId, playerId, location,
                            prerequisite.relation,
                            prerequisite.actorFilterKey,
                            prerequisite.includeExcludedFromBattle,
                            prerequisite.spotOverride)) {
                    continue;
                }
                com.gempukku.swccgo.filters.Filter actorFilter =
                        resolveFilter(
                                prerequisite.actorFilterKey);
                PhysicalCard pairedActorLost =
                        prospectivePairActorLostWithPilot(
                            game, playerId, candidate,
                            prerequisite, actorFilter);
                if (removedGroupContainsMatchingActor(
                            game, playerId, location,
                            prerequisite, candidate,
                            pairedActorLost, actorFilter)
                        && !hasOtherMatchingActorOutsideRemovedGroup(
                            game, playerId, location,
                            prerequisite, candidate,
                            pairedActorLost)) {
                    return FlipGateFormationRole
                            .LAST_REQUIRED_ACTOR;
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "Required-card deploy enabler casualty assessment failed: {}",
                    e.getMessage());
        }
        return FlipGateFormationRole.NONE;
    }

    private PhysicalCard prospectivePairActorLostWithPilot(
            SwccgGame game, String playerId,
            PhysicalCard candidate,
            FlipLocationAlternative prerequisite,
            com.gempukku.swccgo.filters.Filter actorFilter) {
        ProspectiveActorPair pair =
                prerequisite != null
                        ? prerequisite.prospectiveActorPair : null;
        if (pair == null || actorFilter == null
                || candidate == null || !candidate.isPilotOf()) {
            return null;
        }
        com.gempukku.swccgo.filters.Filter hostFilter =
                resolveFilter(pair.hostFilterKey);
        com.gempukku.swccgo.filters.Filter pilotFilter =
                resolveFilter(pair.pilotFilterKey);
        PhysicalCard host = candidate.getAttachedTo();
        if (host == null || hostFilter == null || pilotFilter == null
                || !playerId.equals(host.getOwner())
                || !pilotFilter.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), candidate)
                || !hostFilter.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), host)
                || !actorFilter.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), host)
                || Filters.hasPermanentPilot.accepts(
                    game.getGameState(),
                    game.getModifiersQuerying(), host)) {
            return null;
        }
        List<PhysicalCard> attached = host.getCardsAttached();
        if (attached != null) {
            for (PhysicalCard card : attached) {
                if (card != null && card != candidate
                        && card.isPilotOf()) {
                    return null;
                }
            }
        }
        return host;
    }

    private FlipGateFormationRole classifyRuntimeActorIfRemoved(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        try {
            GameState gameState = game.getGameState();
            if (gameState == null || game.getModifiersQuerying() == null
                    || activeFlipLocationRules == null) {
                return FlipGateFormationRole.NONE;
            }
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (!isActivePreFlipRule(rule)) continue;
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if (!isActorToRuntimeLocationAlternative(alternative)) {
                        continue;
                    }
                    com.gempukku.swccgo.filters.Filter actorFilter =
                            resolveFilter(alternative.actorFilterKey);
                    String controller = resolveController(
                            gameState, playerId, alternative.controller);
                    if (actorFilter == null
                            || controller != null
                                && !controller.equals(
                                        candidate.getOwner())
                            || !actorFilter.accepts(
                                    gameState,
                                    game.getModifiersQuerying(),
                                    candidate)) {
                        continue;
                    }
                    PhysicalCard location =
                            actorLocationForAlternative(
                                    game, candidate, alternative);
                    if (!locationMatchesAlternative(
                                gameState, game, playerId,
                                location, alternative)
                            || !relationSatisfiedAt(
                                game, playerId, controller, location,
                                alternative.relation,
                                alternative.actorFilterKey,
                                alternative.includeExcludedFromBattle,
                                alternative.spotOverride)) {
                        continue;
                    }

                    int required = expectedCount(
                            game, playerId, alternative.count);
                    int qualified = countAlternativeMatches(
                            game, playerId, controller, alternative);
                    boolean breaksLocation =
                            !hasOtherMatchingActorAtLocation(
                                    game, controller, location,
                                    alternative, candidate);
                    if (!breaksLocation
                            || qualified - 1 >= required) {
                        continue;
                    }
                    if ("anyOf".equals(rule.mode)
                            && hasSatisfiedAlternativeOtherThan(
                                    game, playerId, rule,
                                    alternative)) {
                        continue;
                    }
                    return FlipGateFormationRole.LAST_REQUIRED_ACTOR;
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "Runtime objective actor casualty assessment failed: {}",
                    e.getMessage());
        }
        return FlipGateFormationRole.NONE;
    }

    private FlipGateFormationRole
            classifyIWantThatMapFormationPieceIfRemoved(
                    SwccgGame game, String playerId,
                    PhysicalCard candidate) {
        if (!isIWantThatMapObjectiveFamily() || isFlipped
                || candidate.getZone() == null
                || !candidate.getZone().isInPlay()) {
            return FlipGateFormationRole.NONE;
        }
        int current =
                countIWantThatMapQualifiedBattlegroundsAfterRemoval(
                        game, playerId, null);
        if (current <= 0 || current > 2) {
            return FlipGateFormationRole.NONE;
        }
        int after =
                countIWantThatMapQualifiedBattlegroundsAfterRemoval(
                        game, playerId, candidate);
        if (after >= current) {
            return FlipGateFormationRole.NONE;
        }
        return removedGroupContainsIWantThatMapActor(
                    game, playerId, candidate)
                ? FlipGateFormationRole.LAST_REQUIRED_ACTOR
                : FlipGateFormationRole.LAST_REQUIRED_BUDDY;
    }

    private int countIWantThatMapQualifiedBattlegroundsAfterRemoval(
            SwccgGame game, String playerId,
            PhysicalCard removedRoot) {
        List<PhysicalCard> locations =
                game.getGameState().getLocationsInOrder();
        Collection<PhysicalCard> cards =
                game.getGameState().getAllPermanentCards();
        if (locations == null || cards == null) return 0;

        int qualified = 0;
        for (PhysicalCard location : locations) {
            if (location == null || !Filters.battleground.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), location)
                    || !game.getModifiersQuerying().controlsLocation(
                        game.getGameState(), location, playerId,
                        SpotOverride.INCLUDE_EXCLUDED_FROM_BATTLE)
                    || !hasIWantThatMapPresenceAfterRemovalAt(
                        game, playerId, location, removedRoot)
                    || !hasIWantThatMapActorAfterRemovalAt(
                        game, playerId, location, removedRoot)) {
                continue;
            }
            qualified++;
        }
        return qualified;
    }

    private boolean hasIWantThatMapPresenceAfterRemovalAt(
            SwccgGame game, String playerId, PhysicalCard location,
            PhysicalCard removedRoot) {
        Collection<PhysicalCard> cards =
                game.getGameState().getAllPermanentCards();
        if (cards == null) return false;
        for (PhysicalCard card : cards) {
            if (card == null || !playerId.equals(card.getOwner())
                    || !isActiveForSpot(game, card, true)
                    || !candidateProvidesPresenceOutsideRemovedGroup(
                        game, card, removedRoot, null)) {
                continue;
            }
            if (samePhysicalLocation(
                    iWantThatMapPresenceContributionLocation(
                        game, card), location)) {
                return true;
            }
        }
        return false;
    }

    private PhysicalCard iWantThatMapPresenceContributionLocation(
            SwccgGame game, PhysicalCard candidate) {
        PhysicalCard presentAt = game.getModifiersQuerying()
                .getLocationThatCardIsPresentAt(
                        game.getGameState(), candidate);
        if (presentAt != null) return presentAt;

        SwccgCardBlueprint blueprint = candidate.getBlueprint();
        CardCategory category = blueprint != null
                ? blueprint.getCardCategory() : null;
        if (category == CardCategory.STARSHIP
                || category == CardCategory.VEHICLE) {
            return game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                            game.getGameState(), candidate);
        }
        return null;
    }

    private boolean hasIWantThatMapActorAfterRemovalAt(
            SwccgGame game, String playerId, PhysicalCard location,
            PhysicalCard removedRoot) {
        Collection<PhysicalCard> cards =
                game.getGameState().getAllPermanentCards();
        if (cards == null) return false;
        for (PhysicalCard card : cards) {
            if (card == null || belongsToRemovedGroup(
                        card, removedRoot, null)
                    || !playerId.equals(card.getOwner())
                    || !isActiveForSpot(game, card, true)
                    || !Filters.First_Order_character.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), card)) {
                continue;
            }
            PhysicalCard actorLocation = game.getModifiersQuerying()
                    .getLocationThatCardIsAt(
                            game.getGameState(), card);
            if (samePhysicalLocation(actorLocation, location)) {
                return true;
            }
        }
        return false;
    }

    private boolean removedGroupContainsIWantThatMapActor(
            SwccgGame game, String playerId,
            PhysicalCard removedRoot) {
        Collection<PhysicalCard> cards =
                game.getGameState().getAllPermanentCards();
        if (cards == null) return false;
        for (PhysicalCard card : cards) {
            if (belongsToRemovedGroup(card, removedRoot, null)
                    && playerId.equals(card.getOwner())
                    && isActiveForSpot(game, card, true)
                    && Filters.First_Order_character.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), card)) {
                return true;
            }
        }
        return false;
    }

    private boolean wouldRemovalTriggerOnTableFlipBack(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        return wouldCandidateLossTriggerOnTableFlipBack(
                game, playerId, candidate, false);
    }

    private boolean wouldDepartureTriggerOnTableFlipBack(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        return wouldCandidateLossTriggerOnTableFlipBack(
                game, playerId, candidate, true);
    }

    private boolean wouldCandidateLossTriggerOnTableFlipBack(
            SwccgGame game, String playerId, PhysicalCard candidate,
            boolean departureOnly) {
        try {
            GameState gameState = game.getGameState();
            if (gameState == null || game.getModifiersQuerying() == null
                    || activeFlipLocationRules == null) {
                return false;
            }
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (rule == null || !"postFlip".equals(rule.phase)
                        || !"flipBack".equals(rule.purpose)
                        || rule.alternatives == null
                        || isRuleSatisfied(game, playerId, rule)) {
                    continue;
                }
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if (!"onTable".equals(alternative.relation)
                            || (!"requiredActorMissing".equals(
                                    alternative.scoreRole)
                                && !"requiredOnTableCardMissing".equals(
                                    alternative.scoreRole)
                                && !"stayFlipped".equals(
                                    alternative.scoreRole))
                            || !candidateMatchesOnTableAlternative(
                                    game, playerId, candidate,
                                    alternative)
                            || departureOnly
                                && !isLocationScopedOnTableAlternative(
                                    alternative)) {
                        continue;
                    }
                    String controller = resolveController(
                            gameState, playerId,
                            alternative.controller);
                    int current = countAlternativeMatches(
                            game, playerId, controller, alternative);
                    boolean targetSatisfiedAfter = compareCounts(
                            Math.max(0, current - 1),
                            expectedCount(
                                    game, playerId,
                                    alternative.count),
                            alternative.count != null
                                    ? alternative.count.comparator : null);
                    if (!targetSatisfiedAfter) continue;
                    if ("anyOf".equals(rule.mode)) return true;

                    boolean allSatisfiedAfter = true;
                    for (FlipLocationAlternative other
                            : rule.alternatives) {
                        if (other == alternative) continue;
                        if (!isFlipLocationAlternativeSatisfied(
                                    game, playerId, other)) {
                            allSatisfiedAfter = false;
                            break;
                        }
                    }
                    if (allSatisfiedAfter) return true;
                }
            }
        } catch (Exception e) {
            LOG.debug(
                    "On-table objective actor casualty assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    private boolean isLocationScopedOnTableAlternative(
            FlipLocationAlternative alternative) {
        return alternative != null
                && (alternative.locationFilterKey != null
                    || alternative.locationFragments != null
                        && !alternative.locationFragments.isEmpty());
    }

    private boolean matchesRequiredOnTableCardFlipBackAlternative(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        if (activeFlipLocationRules == null) return false;
        for (FlipLocationRule rule : activeFlipLocationRules) {
            if (rule == null || !"postFlip".equals(rule.phase)
                    || !"flipBack".equals(rule.purpose)
                    || rule.alternatives == null) {
                continue;
            }
            for (FlipLocationAlternative alternative
                    : rule.alternatives) {
                if (alternative != null
                        && "onTable".equals(alternative.relation)
                        && "requiredOnTableCardMissing".equals(
                                alternative.scoreRole)
                        && candidateMatchesOnTableAlternative(
                                game, playerId, candidate,
                                alternative)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean candidateMatchesOnTableAlternative(
            SwccgGame game, String playerId, PhysicalCard candidate,
            FlipLocationAlternative alternative) {
        GameState gameState = game.getGameState();
        String controller = resolveController(
                gameState, playerId, alternative.controller);
        com.gempukku.swccgo.filters.Filter actorFilter =
                resolveFilter(alternative.actorFilterKey);
        if (actorFilter == null
                || controller != null
                    && !controller.equals(candidate.getOwner())
                || !isActiveForSpot(
                        game, candidate,
                        alternative.includeExcludedFromBattle)
                || !actorFilter.accepts(
                        gameState, game.getModifiersQuerying(),
                        candidate)) {
            return false;
        }
        return true;
    }

    private boolean hasSatisfiedAlternativeOtherThan(
            SwccgGame game, String playerId, FlipLocationRule rule,
            FlipLocationAlternative excluded) {
        for (FlipLocationAlternative alternative : rule.alternatives) {
            if (alternative != excluded
                    && isFlipLocationAlternativeSatisfied(
                            game, playerId, alternative)) {
                return true;
            }
        }
        return false;
    }

    private FlipGateFormationRole classifyCountedGatePieceIfRemoved(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        try {
            GameState gameState = game.getGameState();
            if (gameState == null || game.getModifiersQuerying() == null) {
                return FlipGateFormationRole.NONE;
            }
            PhysicalCard location = game.getModifiersQuerying()
                    .getLocationThatCardIsPresentAt(gameState, candidate);

            ruleLoop:
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (!isActivePreFlipRule(rule)) continue;
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if (alternative == null
                            || alternative.actorFilterKey == null
                            || alternative.count == null
                            || alternative.count.value == null
                            || alternative.count.value <= 1
                            || (!"onTable".equals(alternative.relation)
                                && !locationMatchesAlternative(
                                    gameState, game, playerId,
                                    location, alternative))) {
                        continue;
                    }
                    int required = expectedCount(
                            game, playerId, alternative.count);
                    String countedController = "onTable".equals(
                            alternative.relation)
                            ? resolveController(
                                gameState, playerId,
                                alternative.controller)
                            : playerId;
                    int qualified = countAlternativeMatches(
                            game, playerId,
                            countedController, alternative);
                    if (qualified <= 0 || qualified > required
                            || (!"onTable".equals(
                                    alternative.relation)
                                && !relationSatisfiedAt(
                                    game, playerId, playerId, location,
                                    alternative.relation,
                                    alternative.actorFilterKey,
                                    alternative.includeExcludedFromBattle,
                                    alternative.spotOverride))) {
                        continue;
                    }

                    com.gempukku.swccgo.filters.Filter actorFilter =
                            resolveFilter(alternative.actorFilterKey);
                    boolean candidateIsActor = actorFilter != null
                            && actorFilter.accepts(
                                    gameState,
                                    game.getModifiersQuerying(), candidate);
                    if (isCountedOperativeFormationAlternative(
                            alternative)) {
                        if (candidateIsActor
                                && !hasCountedOperativeFormationPieceAtLocation(
                                    game, playerId, location,
                                    candidate, true)) {
                            return FlipGateFormationRole
                                    .LAST_REQUIRED_ACTOR;
                        }
                        if (!candidateIsActor
                                && isCountedOperativeBoardControlCompanion(
                                    game, playerId, candidate)
                                && isSoleCountedOperativeControlCompanionGroupAt(
                                    game, playerId, candidate,
                                    location, alternative)) {
                            return FlipGateFormationRole
                                    .LAST_REQUIRED_BUDDY;
                        }
                        continue;
                    }
                    if (candidateIsActor
                            && ("onTable".equals(alternative.relation)
                                || !hasOtherMatchingActorAtLocation(
                                    game, playerId, location,
                                    alternative, candidate))) {
                        if ("anyOf".equals(rule.mode)
                                && anyCountedAlternativeMeetsThresholdAfterRemoval(
                                    game, playerId, rule,
                                    candidate, location)) {
                            continue ruleLoop;
                        }
                        return FlipGateFormationRole.LAST_REQUIRED_ACTOR;
                    }

                    if (!"onTable".equals(alternative.relation)
                            && !candidateIsActor
                            && hasMatchingActorAtLocation(
                                    game, playerId, location,
                                    alternative.actorFilterKey,
                                    alternative.includeExcludedFromBattle)
                            && isSolePresenceSourceAtLocation(
                                    game, playerId, candidate, location)) {
                        if ("anyOf".equals(rule.mode)
                                && anyCountedAlternativeMeetsThresholdAfterRemoval(
                                    game, playerId, rule,
                                    candidate, location)) {
                            continue ruleLoop;
                        }
                        return FlipGateFormationRole.LAST_REQUIRED_BUDDY;
                    }
                }
            }
        } catch (Exception e) {
            LOG.debug("Counted objective casualty classification failed: {}",
                    e.getMessage());
        }
        return FlipGateFormationRole.NONE;
    }

    private boolean isSoleCountedOperativeControlCompanionGroupAt(
            SwccgGame game, String playerId,
            PhysicalCard candidate, PhysicalCard location,
            FlipLocationAlternative alternative) {
        if (!isCountedOperativeBoardControlCompanion(
                    game, playerId, candidate)
                || !isActiveForSpot(
                    game, candidate,
                    alternative.includeExcludedFromBattle)) {
            return false;
        }
        Collection<PhysicalCard> cards =
                game.getGameState().getAllPermanentCards();
        if (cards == null) return false;
        for (PhysicalCard card : cards) {
            if (belongsToRemovedGroup(card, candidate, null)
                    || card == null
                    || !playerId.equals(card.getOwner())
                    || !isActiveForSpot(
                        game, card,
                        alternative.includeExcludedFromBattle)
                    || matchesCountedOperativeFormationActor(
                        game, playerId, card)
                    || !isCountedOperativeBoardControlCompanion(
                        game, playerId, card)
                    || !candidateProvidesPresenceOutsideRemovedGroup(
                        game, card, candidate, null)) {
                continue;
            }
            PhysicalCard cardLocation = presenceContributionLocation(
                    game, card);
            if (samePhysicalLocation(cardLocation, location)) {
                return false;
            }
        }
        return true;
    }

    private FlipGateFormationRole classifyPlainPresenceIfRemoved(
            SwccgGame game, String playerId, PhysicalCard candidate) {
        try {
            GameState gameState = game.getGameState();
            if (gameState == null || game.getModifiersQuerying() == null
                    || activeFlipLocationRules == null
                    || !candidateProvidesPresence(game, candidate)) {
                return FlipGateFormationRole.NONE;
            }
            PhysicalCard location = presenceContributionLocation(
                    game, candidate);
            if (location == null
                    || !isSolePresenceSourceAtLocation(
                            game, playerId, candidate, location)) {
                return FlipGateFormationRole.NONE;
            }

            ruleLoop:
            for (FlipLocationRule rule : activeFlipLocationRules) {
                if (!isActivePreFlipRule(rule)) continue;
                for (FlipLocationAlternative alternative
                        : rule.alternatives) {
                    if (!isPlainSelfPresenceAlternative(alternative)
                            || !locationMatchesAlternative(
                                gameState, game, playerId,
                                location, alternative)
                            || !relationSatisfiedAt(
                                game, playerId, playerId,
                                location, alternative.relation,
                                null,
                                alternative.includeExcludedFromBattle,
                                alternative.spotOverride)) {
                        continue;
                    }
                    int required = expectedCount(
                            game, playerId, alternative.count);
                    int qualified = countAlternativeMatches(
                            game, playerId, playerId, alternative);
                    if (qualified <= 0 || qualified > required) {
                        continue;
                    }
                    if ("anyOf".equals(rule.mode)
                            && anyCountedAlternativeMeetsThresholdAfterRemoval(
                                game, playerId, rule,
                                candidate, location)) {
                        continue ruleLoop;
                    }
                    return FlipGateFormationRole.LAST_REQUIRED_ACTOR;
                }
            }
        } catch (Exception e) {
            LOG.debug("Plain objective presence casualty assessment failed: {}",
                    e.getMessage());
        }
        return FlipGateFormationRole.NONE;
    }

    private boolean anyCountedAlternativeMeetsThresholdAfterRemoval(
            SwccgGame game, String playerId, FlipLocationRule rule,
            PhysicalCard candidate, PhysicalCard candidateLocation) {
        if (rule == null || rule.alternatives == null) return false;
        for (FlipLocationAlternative alternative : rule.alternatives) {
            if (alternative == null || alternative.count == null
                    || alternative.count.value == null
                    || alternative.actorFilterKey == null
                        && !isPlainSelfPresenceAlternative(alternative)) {
                continue;
            }
            String controller = resolveController(
                    game.getGameState(), playerId,
                    alternative.controller);
            int qualified = countAlternativeMatches(
                    game, playerId, controller, alternative);
            int required = expectedCount(
                    game, playerId, alternative.count);
            if (qualified < required) continue;

            if (isPlainSelfPresenceAlternative(alternative)) {
                if (!locationMatchesAlternative(
                        game.getGameState(), game, playerId,
                        candidateLocation, alternative)
                        || !relationSatisfiedAt(
                            game, playerId, controller,
                            candidateLocation,
                            alternative.relation, null,
                            alternative.includeExcludedFromBattle,
                            alternative.spotOverride)) {
                    return true;
                }
                boolean breaksThisLocation =
                        isSolePresenceSourceAtLocation(
                                game, playerId, candidate,
                                candidateLocation);
                if (qualified - (breaksThisLocation ? 1 : 0)
                        >= required) {
                    return true;
                }
                continue;
            }

            com.gempukku.swccgo.filters.Filter actorFilter =
                    resolveFilter(alternative.actorFilterKey);
            boolean candidateIsActor = actorFilter != null
                    && (controller == null
                        || controller.equals(candidate.getOwner()))
                    && actorFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), candidate);
            if ("onTable".equals(alternative.relation)) {
                if (!candidateIsActor
                        || qualified - 1 >= required) {
                    return true;
                }
                continue;
            }
            if (!locationMatchesAlternative(
                    game.getGameState(), game, playerId,
                    candidateLocation, alternative)
                    || !relationSatisfiedAt(
                        game, playerId, controller, candidateLocation,
                        alternative.relation,
                        alternative.actorFilterKey,
                        alternative.includeExcludedFromBattle,
                        alternative.spotOverride)) {
                return true;
            }

            boolean breaksThisLocation = candidateIsActor
                    ? !hasOtherMatchingActorAtLocation(
                            game, controller, candidateLocation,
                            alternative, candidate)
                    : isSolePresenceSourceAtLocation(
                            game, playerId, candidate,
                            candidateLocation);
            if (qualified - (breaksThisLocation ? 1 : 0) >= required) {
                return true;
            }
        }
        return false;
    }

    private boolean hasOtherMatchingActorAtLocation(
            SwccgGame game, String playerId, PhysicalCard location,
            FlipLocationAlternative alternative, PhysicalCard excluded) {
        com.gempukku.swccgo.filters.Filter actorFilter =
                resolveFilter(alternative.actorFilterKey);
        if (actorFilter == null) return false;
        Collection<PhysicalCard> cards =
                game.getGameState().getAllPermanentCards();
        if (cards == null) return false;
        for (PhysicalCard card : cards) {
            if (card == null || card == excluded
                    || playerId != null
                        && !playerId.equals(card.getOwner())
                    || !isActiveForSpot(
                            game, card,
                            alternative.includeExcludedFromBattle)
                    || !actorFilter.accepts(
                            game.getGameState(),
                            game.getModifiersQuerying(), card)) {
                continue;
            }
            PhysicalCard cardLocation =
                    actorLocationForAlternative(
                            game, card, alternative);
            if (samePhysicalLocation(cardLocation, location)) return true;
        }
        return false;
    }

    private boolean removedGroupContainsMatchingActor(
            SwccgGame game, String playerId, PhysicalCard location,
            FlipLocationAlternative alternative,
            PhysicalCard removedRoot,
            PhysicalCard dependentActor,
            com.gempukku.swccgo.filters.Filter actorFilter) {
        if (actorFilter == null) return false;
        Collection<PhysicalCard> cards =
                game.getGameState().getAllPermanentCards();
        if (cards == null) return false;
        for (PhysicalCard card : cards) {
            if (!belongsToRemovedGroup(
                        card, removedRoot, dependentActor)
                    || playerId != null
                        && !playerId.equals(card.getOwner())
                    || !isActiveForSpot(
                        game, card,
                        alternative.includeExcludedFromBattle)
                    || !actorFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), card)) {
                continue;
            }
            PhysicalCard cardLocation =
                    actorLocationForAlternative(
                            game, card, alternative);
            if (samePhysicalLocation(cardLocation, location)) {
                return true;
            }
        }
        return false;
    }

    private boolean hasOtherMatchingActorOutsideRemovedGroup(
            SwccgGame game, String playerId, PhysicalCard location,
            FlipLocationAlternative alternative,
            PhysicalCard removedRoot,
            PhysicalCard dependentActor) {
        com.gempukku.swccgo.filters.Filter actorFilter =
                resolveFilter(alternative.actorFilterKey);
        if (actorFilter == null) return false;
        Collection<PhysicalCard> cards =
                game.getGameState().getAllPermanentCards();
        if (cards == null) return false;
        for (PhysicalCard card : cards) {
            if (belongsToRemovedGroup(
                        card, removedRoot, dependentActor)
                    || playerId != null
                        && !playerId.equals(card.getOwner())
                    || !isActiveForSpot(
                        game, card,
                        alternative.includeExcludedFromBattle)
                    || !actorFilter.accepts(
                        game.getGameState(),
                        game.getModifiersQuerying(), card)) {
                continue;
            }
            PhysicalCard cardLocation =
                    actorLocationForAlternative(
                            game, card, alternative);
            if (samePhysicalLocation(cardLocation, location)) {
                return true;
            }
        }
        return false;
    }

    private static boolean belongsToRemovedGroup(
            PhysicalCard card, PhysicalCard removedRoot,
            PhysicalCard dependentActor) {
        return card != null
                && (card == removedRoot
                    || card == dependentActor
                    || removedRoot != null
                        && attachedToOrAboard(
                            card, removedRoot));
    }

    private boolean isSolePresenceSourceAtLocation(
            SwccgGame game, String playerId, PhysicalCard candidate,
            PhysicalCard location) {
        if (!candidateProvidesPresence(game, candidate)) {
            return false;
        }
        Collection<PhysicalCard> cards =
                game.getGameState().getAllPermanentCards();
        if (cards == null) return false;
        for (PhysicalCard card : cards) {
            if (card == null
                    || !playerId.equals(card.getOwner())
                    || card.isUndercover()
                    || !candidateProvidesPresenceOutsideRemovedGroup(
                        game, card, candidate, null)) {
                continue;
            }
            PhysicalCard cardLocation = presenceContributionLocation(
                    game, card);
            if (samePhysicalLocation(cardLocation, location)) return false;
        }
        return true;
    }

    /**
     * V276: true only when this exact candidate can fill an active pre-flip actor-at-site gate
     * and no qualifying actor is already present there. The data lives in the objective profile;
     * deploy evaluators only consume this fact. Unknown filters or board reads fail closed.
     */
    public boolean advancesUnfilledFlipGateActorRequirement(
            SwccgGame game, String playerId, PhysicalCard candidate,
            PhysicalCard destination) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || candidate == null || destination == null) return false;

        ActorLocationRule rule = findFlipGateActorRule();
        if (rule == null) return false;

        try {
            GameState gameState = game.getGameState();
            if (gameState == null || game.getModifiersQuerying() == null) return false;
            if (!matchesFlipGateActorRequirement(
                            game, playerId, candidate, destination)) {
                return false;
            }
            int actorsAtGate = countFlipGateActorsAtLocation(
                    game, playerId, destination);
            int required = rule.count != null && rule.count.value != null
                    ? rule.count.value : 1;
            return actorsAtGate < Math.max(1, required);
        } catch (Exception e) {
            LOG.debug("V276 flip-gate actor assessment failed: {}", e.getMessage());
            return false;
        }
    }

    /**
     * True when a typed gate actor can legally be staged at one of the
     * objective's exact setup sites with a known site path to the gate.
     */
    public boolean stagesPreFlipActorRoute(
            SwccgGame game,
            String playerId,
            PhysicalCard actor,
            PhysicalCard destination) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || actor == null || destination == null
                || !playerId.equals(actor.getOwner())) {
            return false;
        }
        ActorLocationRule rule = findFlipGateActorRule();
        if (rule == null || rule.count == null
                || rule.count.value == null
                || rule.count.value != 1
                || !matchesFlipGateActorRequirement(
                        game, playerId, actor)
                || !matchesStartingLocation(destination)) {
            return false;
        }

        try {
            GameState gameState = game.getGameState();
            if (gameState == null || game.getModifiersQuerying() == null) {
                return false;
            }
            com.gempukku.swccgo.filters.Filter actorFilter =
                    resolveFilter(rule.actorFilterKey);
            if (actorFilter == null
                    || hasOtherMatchingActorOnPreFlipRoute(
                            game, playerId, actor, actorFilter, false)) {
                return false;
            }

            List<PhysicalCard> locations = gameState.getLocationsInOrder();
            if (locations == null) return false;
            for (PhysicalCard gate : locations) {
                if (gate == null
                        || !isFlipGateLocation(game, playerId, gate)
                        || samePhysicalLocation(gate, destination)
                        || countFlipGateActorsAtLocation(
                                game, playerId, gate) >= 1) {
                    continue;
                }
                Integer distance = game.getModifiersQuerying()
                        .getDistanceBetweenSites(
                                gameState, destination, gate);
                if (distance != null && distance > 0) return true;
            }
        } catch (Exception e) {
            LOG.debug("Objective actor staging assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    /**
     * Parent deploy-action fact. Unlike the child destination fact, this must
     * prove that at least one route stage is currently legal and affordable.
     */
    public boolean hasLegalPreFlipActorRouteStage(
            SwccgGame game,
            String playerId,
            PhysicalCard actor) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || actor == null || game.getGameState() == null
                || game.getModifiersQuerying() == null) {
            return false;
        }
        try {
            GameState gameState = game.getGameState();
            List<PhysicalCard> locations = gameState.getLocationsInOrder();
            if (locations == null) return false;
            for (PhysicalCard location : locations) {
                if (!stagesPreFlipActorRoute(
                        game, playerId, actor, location)) {
                    continue;
                }
                if (Filters.deployableToLocation(
                        actor, Filters.sameCardId(location),
                        false, 0.0f).accepts(
                                gameState, game.getModifiersQuerying(),
                                actor)) {
                    return true;
                }
            }
        } catch (Exception e) {
            LOG.debug("Objective legal actor staging assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

    private boolean matchesStartingLocation(PhysicalCard destination) {
        try {
            String blueprintId = destination.getBlueprintId(true);
            if (blueprintId != null
                    && startingLocationIds.contains(blueprintId)) {
                return true;
            }
            String title = destination.getTitle();
            if (title == null) return false;
            String titleLower = title.toLowerCase(Locale.ROOT);
            for (String fragment : startingLocationFragments) {
                if (fragment != null && !fragment.isEmpty()
                        && titleLower.equals(fragment)) {
                    return true;
                }
            }
        } catch (Exception e) {
            return false;
        }
        return false;
    }

    /**
     * True only when this exact typed gate actor moves along the engine's
     * toward relation to its still-unfilled pre-flip gate.
     */
    public boolean advancesPreFlipActorRoute(
            SwccgGame game,
            String playerId,
            PhysicalCard actor,
            PhysicalCard destination) {
        if (!analyzed || isFlipped || game == null || playerId == null
                || actor == null || destination == null
                || !playerId.equals(actor.getOwner())) {
            return false;
        }

        if (CaptureObjectiveFacts
                .advancesCaptureApproachByLandspeed(
                    game, playerId, this,
                    actor, destination)) {
            return true;
        }

        ActorLocationRule rule = findFlipGateActorRule();
        if (rule == null || rule.count == null
                || rule.count.value == null
                || rule.count.value != 1
                || !matchesFlipGateActorRequirement(
                        game, playerId, actor)) {
            return false;
        }

        try {
            GameState gameState = game.getGameState();
            if (gameState == null || game.getModifiersQuerying() == null) {
                return false;
            }
            PhysicalCard origin = game.getModifiersQuerying()
                    .getLocationThatCardIsPresentAt(gameState, actor);
            if (origin == null || samePhysicalLocation(origin, destination)) {
                return false;
            }

            List<PhysicalCard> locations = gameState.getLocationsInOrder();
            if (locations == null) return false;
            for (PhysicalCard gate : locations) {
                if (gate == null
                        || !isFlipGateLocation(game, playerId, gate)
                        || countFlipGateActorsAtLocation(
                                game, playerId, gate) >= 1) {
                    continue;
                }
                if (Filters.toward(origin, gate).accepts(
                        gameState, game.getModifiersQuerying(),
                        destination)) {
                    return true;
                }
            }
        } catch (Exception e) {
            LOG.debug("Objective actor-route assessment failed: {}",
                    e.getMessage());
        }
        return false;
    }

